/* =========================================================
   EXZY Intern Handbook — Modern, Corporate, Trustworthy
   Palette: cyan #66C5C5 → navy #004081 (accents),
            #004081 (key text), #707070 (muted), #F8F9FA (bg)
   ========================================================= */

/* ===== LOCAL FONTS (offline fallback) ===== */
@font-face {
  font-family: "Noto Sans Thai Local";
  src: url("./static/NotoSansThai-Regular.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
  ascent-override: 120%;
  descent-override: 35%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Noto Sans Thai Local";
  src: url("./static/NotoSansThai-SemiBold.ttf") format("truetype");
  font-weight: 600;
  font-style: normal;
  font-display: swap;
  ascent-override: 120%;
  descent-override: 35%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Noto Sans Thai Local";
  src: url("./static/NotoSansThai-Bold.ttf") format("truetype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
  ascent-override: 120%;
  descent-override: 35%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Noto Sans Thai Local";
  src: url("./static/NotoSansThai-ExtraBold.ttf") format("truetype");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
  ascent-override: 120%;
  descent-override: 35%;
  line-gap-override: 0%;
}

:root {
  /* EXZY CI palette */
  --ci-bluegray: #929EB4;
  --ci-muted: #707070;
  --ci-slate: #586782;
  --ci-line: #D0D6DF;
  --ci-success: #82C566;
  --ci-body: #505050;
  --ci-error: #F3554F;
  --ci-teal: #66C5C5;
  --ci-warning: #FFCC00;
  --ci-bg: #F8F9FA;
  --ci-ink: #001122;
  --ci-navy: #004080;

  --cyan: #66C5C5;
  --navy: #004080;
  --ink: #004081;
  --muted: #707070;
  --body: #505050;
  --slate: #586782;
  --bluegray: #929EB4;
  --bg: #F8F9FA;
  --surface: #F8F9FA;
  --surface-2: #D0D6DF;
  --mist: #D0D6DF;
  --success: #82C566;
  --warning: #FFCC00;
  --error: #F3554F;
  --on-dark: #F8F9FA;
  --cyan-soft: rgba(102,197,197,0.14);
  --navy-soft: rgba(0,64,129,0.10);
  --success-soft: rgba(130,197,102,0.16);
  --warning-soft: rgba(255,204,0,0.18);
  --error-soft: rgba(243,85,79,0.12);
  /* Easing tokens */
  --ease-out-quart: cubic-bezier(0.25, 1, 0.5, 1);
  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out-expo:  cubic-bezier(0.16, 1, 0.3, 1);
  --line: #D0D6DF;
  --line-soft: rgba(208,214,223,0.72);
  --shadow-sm: 0 1px 2px rgba(0,64,129, 0.04), 0 1px 1px rgba(0,17,34,0.02);
  --shadow-md: 0 4px 14px rgba(0,64,129, 0.07);
  --shadow-lg: 0 16px 34px rgba(0,64,129, 0.10);
  --grad: linear-gradient(135deg, #66C5C5 0%, #004080 100%);
  --grad-soft: linear-gradient(135deg, rgba(102,197,197,0.12), rgba(0,64,129,0.07));
  --radius-sm: 8px;
  --radius: 14px;
  --radius-lg: 22px;
  --thai: "Noto Sans Thai Local", "Noto Sans Thai", "Sora", system-ui, sans-serif;
  --display: "Noto Sans Thai Local", "Sora", "Noto Sans Thai", system-ui, sans-serif;
  --nav-h: 72px;
  --maxw: 1240px;
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }
html { scroll-behavior: smooth; }

body {
  font-family: var(--thai);
  color: #001122;
  background: var(--bg);
  font-weight: 400;
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-feature-settings: "kern" 1;
}

img { max-width: 100%; display: block; }
a { color: var(--ink); text-decoration: none; }
button { font: inherit; }

/* ===== NAVBAR ===== */
.navbar {
  position: sticky; top: 0; z-index: 100;
  background: rgba(248,249,250,0.92);
  backdrop-filter: saturate(1.4) blur(14px);
  -webkit-backdrop-filter: saturate(1.4) blur(14px);
  border-bottom: 1px solid var(--line-soft);
  transition: box-shadow .25s ease, border-color .25s ease;
}
.navbar.scrolled {
  box-shadow: 0 1px 0 rgba(0,64,129,0.05), 0 4px 20px rgba(0,64,129,0.04);
  border-bottom-color: transparent;
}
.nav-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  height: var(--nav-h);
  padding: 0 clamp(22px, 3vw, 36px);
  display: flex;
  align-items: center;
  gap: clamp(12px, 1.8vw, 22px);
}
.nav-logo {
  height: 38px;
  display: flex;
  align-items: center;
  margin-right: 8px;
  flex-shrink: 0;
}
.nav-logo img { height: 100%; width: auto; object-fit: contain; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
}
.nav-right {
  display: flex;
  align-items: center;
  margin-left: auto;
  padding-left: 14px;
  border-left: 1px solid rgba(208,214,223,0.78);
}

.nav-item {
  font-family: var(--thai);
  font-weight: 500;
  font-size: 14px;
  color: #3A4757;
  background: transparent;
  border: none;
  min-height: 42px;
  padding: 10px 15px;
  border-radius: 12px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  position: relative;
  transition: color .18s ease;
  letter-spacing: 0;
}
.nav-item:hover { color: var(--ci-navy); background: transparent; }
.nav-item.is-active {
  color: var(--ci-navy);
  background: transparent;
}
.nav-home { margin-right: 0; }
.nav-day1 {
  color: var(--ci-navy);
  background: transparent;
  border: 0;
  font-weight: 500;
}
.nav-day1:hover,
.nav-day1.is-active {
  background: transparent;
  box-shadow: none;
}

.nav-group { position: relative; }
.nav-toggle svg { transition: transform .2s ease; opacity: 0.6; }
.nav-group.open .nav-toggle svg { transform: rotate(180deg); }
.nav-group.open .nav-toggle { color: var(--ci-navy); background: transparent; }

.nav-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  min-width: 240px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 8px;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity .18s ease, transform .18s ease, visibility 0s linear .18s;
}
.nav-menu-right { left: auto; right: 0; }
.nav-group.open .nav-menu {
  opacity: 1; visibility: visible; transform: translateY(0);
  transition: opacity .18s ease, transform .18s ease, visibility 0s;
}
.nav-menu a {
  display: block;
  padding: 9px 12px;
  border-radius: 8px;
  font-size: 14px;
  color: #505050;
  font-weight: 400;
}
.nav-menu a:hover { background: var(--surface-2); color: var(--ink); }
.nav-menu a.is-active { color: var(--ink); font-weight: 600; background: rgba(102,197,197,0.10); }
.nav-sub {
  border-top: 1px solid var(--line-soft);
  margin-top: 6px;
  padding-top: 6px;
}
.nav-sub:first-child { border-top: none; margin-top: 0; padding-top: 0; }
.nav-sub-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  padding: 8px 12px 4px;
  font-weight: 600;
}

.nav-burger {
  display: none;
  background: none;
  border: none;
  width: 40px; height: 40px;
  cursor: pointer;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  align-items: center;
}
.nav-burger span {
  width: 22px; height: 2px; background: var(--ink); border-radius: 2px;
  transition: transform .25s ease, opacity .25s ease;
}

/* ===== HERO ===== */
.hero {
  position: relative;
  overflow: hidden;
  padding: 100px 0 110px;
  background: linear-gradient(180deg, #F8F9FA 0%, #F8F9FA 42%, #F8F9FA 100%);
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 12% 16%, rgba(102,197,197,0.18), transparent 24%),
    radial-gradient(circle at 86% 28%, rgba(102,197,197,0.14), transparent 20%),
    radial-gradient(circle at 52% 80%, rgba(255,204,0,0.12), transparent 18%);
  opacity: 0.95;
  pointer-events: none;
}
.hero::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 40%, rgba(248,249,250,0.35), transparent 32%),
              radial-gradient(circle at 75% 18%, rgba(102,197,197,0.16), transparent 24%);
  opacity: 0.9;
  animation: hero-glow 8s ease-in-out infinite;
  pointer-events: none;
}
.hero-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 28px;
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 60px;
  align-items: center;
  position: relative;
  z-index: 1;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink);
  padding: 7px 14px;
  border: 1px solid rgba(0,64,129,0.18);
  border-radius: 999px;
  background: rgba(248,249,250,0.7);
  margin-bottom: 22px;
}
.hero-eyebrow .dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--ci-navy);
  box-shadow: 0 0 0 4px rgba(102,197,197,0.18);
}
.hero h1 {
  font-family: var(--thai);
  font-size: clamp(34px, 4.8vw, 56px);
  line-height: 1.6;
  letter-spacing: -0.01em;
  margin: 0 0 22px;
  color: #001122;
  font-weight: 700;
  padding-top: 4px;
}
.hero h1 .accent {
  color: var(--ci-navy);
  display: inline-block;
  padding-top: 4px;
  overflow: visible;
}
.hero p.lead {
  font-size: 17px;
  color: #505050;
  max-width: 540px;
  margin: 0 0 36px;
  line-height: 1.7;
}
.hero-ctas {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}
.hero-feature-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 20px;
}
.hero-feature-pill {
  display: inline-flex;
  align-items: center;
  padding: 12px 16px;
  border-radius: 999px;
  background: rgba(102,197,197,0.14);
  color: var(--ink);
  font-size: 13px;
  font-weight: 600;
  border: 1px solid rgba(102,197,197,0.22);
  box-shadow: 0 10px 24px rgba(102,197,197,0.08);
  animation: hero-pill-float 5s ease-in-out infinite alternate;
}
.hero-feature-pill:nth-child(2) {
  animation-delay: 140ms;
}
.hero-feature-pill:nth-child(3) {
  animation-delay: 280ms;
}
@keyframes hero-glow {
  0%, 100% { transform: scale(1) translateY(0); }
  50% { transform: scale(1.02) translateY(-6px); }
}
@keyframes hero-pill-float {
  0% { transform: translateY(0); }
  100% { transform: translateY(-5px); }
}
.btn {
  font-family: var(--thai);
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 24px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  transition: transform .15s ease, box-shadow .2s ease, filter .2s ease;
  border: none;
  text-decoration: none;
  white-space: nowrap;
}
.btn-primary {
  background: var(--grad);
  color: #F8F9FA;
  box-shadow: 0 8px 24px rgba(0,64,129,0.22), inset 0 1px 0 rgba(248,249,250,0.2);
}
.btn-primary:hover { transform: translateY(-1px); box-shadow: 0 12px 30px rgba(0,64,129,0.28), inset 0 1px 0 rgba(248,249,250,0.2); filter: brightness(1.04); }
.btn-primary:active { transform: translateY(0); }
.btn-primary .arrow {
  transition: transform .2s ease;
}
.btn-primary:hover .arrow { transform: translateX(3px); }

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border: 1px solid rgba(0,64,129,0.22);
}
.btn-ghost:hover { background: rgba(102,197,197,0.10); border-color: var(--cyan); }

.btn-hero {
  animation: glow-cta 4.2s ease-in-out infinite;
}

@keyframes glow-cta {
  0%, 100% { box-shadow: 0 14px 24px rgba(102,197,197,0.16); }
  50% { box-shadow: 0 20px 36px rgba(102,197,197,0.24); }
}

.reference-section {
  padding: 90px 0 76px;
  background: var(--surface);
  border-top: 1px solid var(--line-soft);
}
.reference-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 28px;
}
.reference-header {
  max-width: 720px;
  margin-bottom: 36px;
}
.reference-title {
  font-family: var(--display);
  font-size: clamp(30px, 3.5vw, 42px);
  line-height: 1.2;
  margin: 0 0 14px;
}
.reference-sub {
  margin: 0;
  font-size: 16px;
  color: var(--muted);
  line-height: 1.75;
}
.reference-grid {
  display: grid;
  gap: 22px;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  grid-auto-flow: dense;
}
.reference-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.reference-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  border-color: rgba(102,197,197,0.45);
}
.reference-card-feature {
  border-color: rgba(102,197,197,0.45);
  box-shadow: 0 22px 50px rgba(102,197,197,0.08);
}
.reference-card-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 9px 14px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cyan);
  background: rgba(102,197,197,0.12);
  width: fit-content;
}
.reference-card h3 {
  margin: 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.35;
}
.reference-card p {
  margin: 0;
  color: #505050;
  font-size: 14.7px;
  line-height: 1.75;
}
.reference-card ul {
  padding-left: 18px;
  margin: 0;
  color: #505050;
  font-size: 14.2px;
  line-height: 1.75;
}
.reference-card li {
  margin-bottom: 10px;
}

.hb-section {
  padding: 90px 0 100px;
  background: #F8F9FA;
}
.hb-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 28px;
}
.hb-header {
  margin-bottom: 32px;
}
.hb-title {
  font-family: var(--display);
  font-size: clamp(30px, 4vw, 40px);
  margin: 0 0 14px;
  letter-spacing: -0.02em;
}
.hb-sub {
  margin: 0;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.75;
}
.hb-groups {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 20px;
  grid-auto-flow: dense;
}
.hb-group {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.hb-group-label {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
  font-size: 12.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.hb-group-dot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
}
.hb-dot-cyan { background: var(--cyan); }
.hb-dot-amber { background: #FFCC00; }
.hb-dot-navy { background: var(--navy); }
.hb-links {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.hb-link {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  align-items: center;
  padding: 16px 18px;
  border-radius: 18px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  transition: transform .22s ease, border-color .22s ease, box-shadow .22s ease;
}
.hb-link:hover {
  transform: translateY(-2px);
  border-color: rgba(102,197,197,0.45);
  box-shadow: var(--shadow-sm);
}
.hb-link-icon {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: var(--surface);
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.hb-link-body {
  min-width: 0;
}
.hb-link-title {
  display: block;
  font-size: 15px;
  font-weight: 700;
  color: var(--ink);
}
.hb-link-desc {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 13.5px;
  line-height: 1.5;
}
.hb-link-arrow {
  color: var(--cyan);
  display: inline-flex;
  align-items: center;
}

.hb-discover {
  position: relative;
  margin-top: 36px;
  overflow: hidden;
  padding: 28px 30px;
  border-radius: var(--radius-lg);
  border: 1px solid rgba(102,197,197,0.18);
  background: linear-gradient(135deg, rgba(102,197,197,0.12), rgba(0,64,129,0.04));
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 24px;
  align-items: center;
}
.hb-discover::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 120% -20%, rgba(248,249,250,0.45), transparent 40%), radial-gradient(circle at 10% 120%, rgba(102,197,197,0.18), transparent 28%);
  pointer-events: none;
}
.hb-discover-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 18% 25%, rgba(248,249,250,0.65), transparent 24%), radial-gradient(circle at 90% 10%, rgba(248,249,250,0.35), transparent 20%);
  pointer-events: none;
}
.hb-discover-content {
  position: relative;
  z-index: 1;
}
.hb-discover-copy {
  margin: 12px 0 0;
  max-width: 540px;
  color: var(--ink);
  font-size: 15px;
  line-height: 1.75;
  opacity: 0.92;
}
.hb-discover-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--navy);
  margin-bottom: 10px;
}
.hb-discover-title {
  font-family: var(--display);
  font-size: clamp(28px, 3.4vw, 36px);
  margin: 0 0 14px;
  color: var(--ink);
}
.hb-discover-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 12px;
}
.hb-dis-chip {
  display: inline-flex;
  align-items: center;
  padding: 10px 14px;
  border-radius: 999px;
  background: rgba(248,249,250,0.85);
  color: var(--ink);
  font-size: 13px;
  font-weight: 600;
}
.hb-discover-cta {
  position: relative;
  z-index: 1;
  justify-self: center;
}

.journey-section {
  padding: 90px 0 100px;
  background: var(--surface);
  border-top: 1px solid var(--line-soft);
}
.journey-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 28px;
}
.journey-header {
  max-width: 720px;
  margin-bottom: 38px;
}
.journey-title {
  font-family: var(--display);
  font-size: clamp(30px, 4vw, 44px);
  margin: 0 0 14px;
  color: #001122;
  line-height: 1.2;
}
.journey-sub {
  margin: 0;
  color: var(--muted);
  font-size: 16px;
  line-height: 1.75;
}
.journey-grid {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}
.journey-card {
  position: relative;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(248,249,250,0.97) 0%, rgba(248,249,250,0.95) 100%);
  border: 1px solid rgba(102,197,197,0.20);
  border-radius: 28px;
  padding: 30px 28px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-height: 280px;
  transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease, background 0.3s ease;
}
.journey-card::before {
  content: "";
  position: absolute;
  inset: -20% 55% auto auto;
  width: 180px;
  height: 180px;
  background: radial-gradient(circle, rgba(102,197,197,0.18), transparent 60%);
  filter: blur(20px);
  pointer-events: none;
}
.journey-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 18px 40px rgba(0,64,129, 0.09);
  border-color: rgba(102,197,197,0.45);
  background: linear-gradient(180deg, rgba(248,249,250,1) 0%, rgba(248,249,250,0.95) 100%);
}
.journey-card-feature {
  border-color: rgba(0,64,129, 0.18);
}
.journey-card-feature .journey-card-badge {
  background: rgba(0,64,129,0.1);
  color: var(--navy);
}
.journey-card-badge {
  display: inline-flex;
  align-items: center;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cyan);
  background: rgba(102,197,197,0.12);
  border-radius: 999px;
  padding: 9px 14px;
  font-size: 12px;
  font-weight: 700;
}
.journey-card-badge-feature {
  background: rgba(0,64,129,0.1);
  color: var(--navy);
}
.journey-card h3 {
  margin: 0;
  font-size: 20px;
  line-height: 1.4;
  color: #001122;
}
.journey-card p {
  margin: 0;
  color: #505050;
  line-height: 1.8;
}
.journey-card .card-link {
  margin-top: auto;
}
.journey-note {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 18px;
  margin-top: 28px;
  padding: 22px 24px;
  border-radius: 20px;
  border: 1px solid rgba(102,197,197,0.18);
  background: rgba(102,197,197,0.07);
}
.journey-note-icon {
  width: 44px;
  height: 44px;
  border-radius: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--cyan);
  background: rgba(248,249,250,0.9);
}
.journey-note strong {
  display: block;
  margin-bottom: 6px;
  color: #001122;
}
.journey-note div {
  color: var(--ink);
  line-height: 1.7;
}
.journey-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  margin-top: 22px;
  padding: 20px 22px;
  border-radius: 20px;
  background: linear-gradient(135deg, rgba(102,197,197,0.12), rgba(248,249,250,0.94));
  border: 1px solid rgba(102,197,197,0.22);
}
.journey-actions-text {
  flex: 1 1 100%;
  color: #001122;
  font-weight: 700;
  line-height: 1.5;
}
.journey-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.link-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 18px;
  border-radius: 999px;
  border: 1px solid rgba(0,64,129,0.12);
  background: #F8F9FA;
  color: var(--ink);
  font-weight: 700;
  text-decoration: none;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.link-pill:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
  border-color: rgba(102,197,197,0.45);
  background: rgba(102,197,197,0.08);
}

@media (max-width: 780px) {
  .journey-actions { flex-direction: column; align-items: stretch; }
  .journey-actions-text { flex: 1 1 auto; }
}

@media (max-width: 980px) {
  .hero {
    padding: 80px 0 90px;
  }
  .hero-feature-row {
    justify-content: center;
  }
  .hb-discover {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 850px) {
  .reference-grid,
  .hb-groups {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 620px) {
  .hb-discover { padding: 24px; }
} 

/* hero card stack */
/* .hero-visual base moved to Journey Card section below */
.hero-visual::before {
  content: '';
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 340px; height: 340px;
  background: radial-gradient(ellipse, rgba(102,197,197,0.18) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
  z-index: 0;
}
.hv-card {
  position: absolute;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-top: 3px solid var(--cyan);
  border-radius: var(--radius-lg);
  padding: 22px;
  box-shadow: 0 8px 32px rgba(0,64,129,0.12), 0 2px 8px rgba(0,17,34,0.06);
  transition: transform .3s ease, box-shadow .3s ease;
  z-index: 2;
}
.hv-card:hover {
  box-shadow: 0 16px 48px rgba(0,64,129,0.18), 0 4px 12px rgba(0,17,34,0.08);
}
.hv-card-1 {
  top: 0; left: 0;
  width: 62%;
  transform: rotate(-3deg);
  z-index: 3;
}
.hv-card-1:hover { transform: rotate(-3deg) translateY(-6px); }
.hv-card-2 {
  bottom: 30px; right: 0;
  width: 58%;
  transform: rotate(4deg);
  z-index: 2;
}
.hv-card-2:hover { transform: rotate(4deg) translateY(-6px); }
.hv-card-3 {
  bottom: 0; left: 8%;
  width: 50%;
  transform: rotate(-1deg);
  z-index: 1;
}
.hv-card-3:hover { transform: rotate(-1deg) translateY(-6px); }
.hv-card h4 {
  margin: 0 0 6px;
  font-size: 14px;
  color: var(--ink);
  font-weight: 700;
  display: flex; align-items: center; gap: 8px;
}
.hv-card .ico {
  width: 28px; height: 28px;
  border-radius: 8px;
  background: var(--grad-soft);
  display: inline-flex;
  align-items: center; justify-content: center;
  color: var(--ink);
}
.hv-card p {
  margin: 0;
  font-size: 13px;
  color: var(--muted);
  line-height: 1.55;
}
.hv-card .row {
  display: flex; gap: 6px; margin-top: 12px;
}
.hv-card .pill {
  font-size: 11px;
  background: var(--surface-2);
  padding: 4px 10px;
  border-radius: 999px;
  color: var(--ink);
  font-weight: 500;
}

/* ===== FLOW CUE (scroll invitation between sections) ===== */
.flow-cue {
  display: flex;
  justify-content: center;
  margin-top: 52px;
  color: var(--ink);
  opacity: 0.18;
  animation: flow-bounce 2.2s ease-in-out infinite;
}
.flow-cue svg { width: 22px; height: 22px; }
.story-section-dark .flow-cue { color: #F8F9FA; opacity: 0.22; }
@keyframes flow-bounce {
  0%, 100% { transform: translateY(0);   opacity: 0.18; }
  50%       { transform: translateY(6px); opacity: 0.35; }
}

/* ===== HERO STAT PILLS ===== */
.hero-stat-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 24px;
  margin-bottom: 8px;
}
.hero-stat-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  font-weight: 500;
  color: #505050;
  padding: 6px 13px;
  background: rgba(248,249,250,0.75);
  border: 1px solid rgba(102,197,197,0.30);
  border-radius: 999px;
  backdrop-filter: blur(4px);
  transition: border-color .2s, background .2s;
}
.hero-stat-pill:hover {
  border-color: var(--cyan);
  background: rgba(102,197,197,0.08);
}
.hsp-ico {
  display: inline-flex;
  align-items: center;
  color: var(--cyan);
  flex-shrink: 0;
}
.hsp-ico svg { width: 14px; height: 14px; }

/* ===== HERO VISUAL — JOURNEY CARD ===== */
.hero-visual {
  position: relative;
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 28px 24px;
}
.hv-journey-card {
  width: 100%;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-top: 3px solid var(--cyan);
  border-radius: var(--radius-lg);
  padding: 24px 22px 20px;
  box-shadow: 0 16px 48px rgba(0,64,129,0.14), 0 3px 10px rgba(0,17,34,0.06);
  position: relative;
  z-index: 2;
}
.hv-journey-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
}
.hv-journey-tag {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--cyan);
  background: rgba(102,197,197,0.12);
  padding: 4px 11px;
  border-radius: 999px;
}
.hv-journey-dots {
  display: flex;
  gap: 5px;
}
.hv-journey-dots span {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--line);
}
.hv-journey-dots span:first-child { background: var(--cyan); }
.hv-journey-dots span:nth-child(2) { background: rgba(102,197,197,0.45); }

/* Journey steps */
.hv-journey-steps {
  display: flex;
  flex-direction: column;
  position: relative;
}
.hv-journey-steps::before {
  content: '';
  position: absolute;
  left: 17px;
  top: 36px;
  bottom: 36px;
  width: 2px;
  background: linear-gradient(to bottom, rgba(102,197,197,0.6) 0%, rgba(102,197,197,0.08) 100%);
  border-radius: 2px;
}
.hv-step {
  display: grid;
  grid-template-columns: 34px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid rgba(0,64,129,0.055);
}
.hv-step-last { border-bottom: none; }
.hv-step-num {
  width: 34px; height: 34px;
  border-radius: 9px;
  background: #F8F9FA;
  border: 1.5px solid rgba(102,197,197,0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--navy);
  flex-shrink: 0;
  position: relative;
  z-index: 1;
  box-shadow: 0 2px 6px rgba(102,197,197,0.15);
}
.hv-step-body { min-width: 0; }
.hv-step-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
  white-space: nowrap;
  overflow: visible;
  text-overflow: clip;
  padding-top: 3px;
}
.hv-step-desc {
  font-size: 11.5px;
  color: var(--muted);
  line-height: 1.45;
  margin-top: 2px;
}
.hv-step-pill {
  font-size: 10.5px;
  font-weight: 600;
  color: #586782;
  background: var(--surface-2);
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
  flex-shrink: 0;
}
.hv-step-pill-grad {
  background: var(--ci-navy);
  color: #F8F9FA;
}
.hv-step-ico {
  width: 30px; height: 30px;
  border-radius: 8px;
  background: rgba(102,197,197,0.08);
  border: 1px solid rgba(102,197,197,0.2);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--cyan);
  flex-shrink: 0;
}
.hv-step-ico svg { width: 15px; height: 15px; }
.hv-step-ico-accent {
  background: rgba(0,64,129,0.06);
  border-color: rgba(0,64,129,0.15);
  color: var(--navy);
}

/* Floating badges (CTA links) */
.hv-float {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 15px 9px 10px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ink);
  box-shadow: 0 6px 22px rgba(0,64,129,0.12), 0 1px 4px rgba(0,17,34,0.05);
  z-index: 4;
  white-space: nowrap;
}
.hv-float-ico {
  width: 24px; height: 24px;
  background: rgba(102,197,197,0.12);
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--cyan);
  flex-shrink: 0;
}
.hv-float-ico svg { width: 14px; height: 14px; }
.hv-float-arr { color: var(--cyan); display: inline-flex; align-items: center; opacity: 0.75; }
.hv-float-1 {
  top: 4px;
  right: 4px;
  animation: hv-float-a 3s ease-in-out infinite;
}
.hv-float-2 {
  bottom: 4px;
  left: 4px;
  animation: hv-float-b 3.6s ease-in-out infinite;
}
@keyframes hv-float-a {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-7px); }
}
@keyframes hv-float-b {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(6px); }
}

/* ===== SECTIONS ===== */
.section { padding: 90px 0; }
.section-inner { max-width: var(--maxw); margin: 0 auto; padding: 0 28px; }
.section-sm { padding: 60px 0; }

.eyebrow {
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 12px;
  display: inline-block;
}
h2.section-title {
  font-family: var(--display);
  font-size: clamp(28px, 3.6vw, 42px);
  letter-spacing: -0.015em;
  color: #001122;
  margin: 0 0 14px;
  font-weight: 700;
  line-height: 1.6;
  padding-top: 4px;
}
.section-sub {
  font-size: 16px;
  color: var(--muted);
  max-width: 620px;
  margin: 0 0 48px;
  padding-top: 8px;
  line-height: 1.85;
}

.section-head-row {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 32px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}
.section-head-row .section-sub { margin-bottom: 0; }

/* page header (sub-pages) */
.page-header {
  padding: 60px 0 36px;
  border-bottom: 1px solid var(--line-soft);
  position: relative;
}
.page-header .crumb {
  font-size: 13px;
  color: var(--muted);
  margin-bottom: 12px;
}
.page-header .crumb a { color: var(--muted); }
.page-header .crumb a:hover { color: var(--ink); }
.page-header h1 {
  font-family: var(--display);
  font-size: clamp(32px, 4.2vw, 46px);
  margin: 0 0 12px;
  letter-spacing: -0.015em;
  color: #001122;
  font-weight: 700;
  line-height: 1.55;
  padding-top: 4px;
}
.page-header .page-lead {
  font-size: 16.5px;
  color: var(--muted);
  max-width: 720px;
  margin: 0;
  padding-top: 8px;
  line-height: 1.85;
}

/* ===== CARDS GRID ===== */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 22px;
}
.card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 28px 26px;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
  display: flex;
  flex-direction: column;
}
.card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: rgba(102,197,197,0.5);
}
.card.is-link { cursor: pointer; }
.card .icon-wrap {
  width: 48px; height: 48px;
  border-radius: 12px;
  background: var(--grad-soft);
  display: inline-flex;
  align-items: center; justify-content: center;
  color: var(--ink);
  margin-bottom: 18px;
  position: relative;
  overflow: hidden;
}
.card .icon-wrap::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--ci-navy);
  opacity: 0;
  transition: opacity .25s ease;
}
.card:hover .icon-wrap { color: #F8F9FA; }
.card:hover .icon-wrap::after { opacity: 1; }
.card .icon-wrap svg { position: relative; z-index: 1; }
.card h3 {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.005em;
}
.card p {
  margin: 0;
  color: var(--muted);
  font-size: 14.5px;
  line-height: 1.65;
  flex: 1;
}
.card .card-link {
  margin-top: 18px;
  font-size: 14px;
  color: var(--ink);
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.card .card-link svg { transition: transform .2s ease; }
.card:hover .card-link svg { transform: translateX(3px); }

/* Featured card with gradient */
.card-feature {
  position: relative;
  background: var(--ci-navy);
  color: #F8F9FA;
  border: none;
  overflow: hidden;
}
.card-feature::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 100% 0%, rgba(248,249,250,0.18), transparent 60%);
  pointer-events: none;
}
.card-feature h3, .card-feature p { color: #F8F9FA; }
.card-feature .icon-wrap { background: rgba(248,249,250,0.15); color: #F8F9FA; }
.card-feature:hover .icon-wrap { color: #F8F9FA; }
.card-feature:hover .icon-wrap::after { display: none; }
.card-feature .card-link { color: #F8F9FA; }

/* ===== HOME QUICK ACCESS ===== */
.quick {
  background: var(--surface);
  padding: 90px 0;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
}

/* ===== STAT / TRUST STRIP ===== */
.trust {
  padding: 50px 0;
}
.trust-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 28px 28px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
}
.trust-item {
  text-align: center;
  padding: 18px 16px;
  position: relative;
}
.trust-item + .trust-item::before {
  content: "";
  position: absolute;
  left: 0; top: 22%; height: 56%;
  width: 1px;
  background: var(--line);
}
.trust-num {
  font-family: var(--display);
  font-size: 30px;
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.02em;
  line-height: 1;
  margin-bottom: 6px;
}
.trust-label {
  font-size: 13px;
  color: var(--muted);
  font-weight: 500;
}

/* ===== JOURNEY (process) ===== */
.journey {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: 12px;
  position: relative;
}
.journey-step {
  position: relative;
  padding: 24px 22px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  transition: transform .25s ease, box-shadow .25s ease;
}
.journey-step:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.journey-num {
  font-family: var(--display);
  font-size: 13px;
  font-weight: 700;
  color: var(--cyan);
  letter-spacing: 0.06em;
}
.journey-step h4 {
  font-size: 16px;
  color: var(--ink);
  margin: 6px 0 8px;
  font-weight: 700;
}
.journey-step p {
  margin: 0;
  font-size: 13.5px;
  color: var(--muted);
}
.journey-step::after {
  content: "→";
  position: absolute;
  right: -14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--cyan);
  font-weight: 700;
  z-index: 1;
  background: var(--bg);
  width: 22px;
  text-align: center;
}
.journey-step:last-child::after { display: none; }

/* ===== CONTENT BLOCKS (sub-page bodies) ===== */
.content-grid {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 48px;
}
.content-sticky {
  position: sticky;
  top: calc(var(--nav-h) + 24px);
  align-self: start;
}
.toc {
  font-size: 14px;
}
.toc-title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 14px;
}
.toc a {
  display: block;
  padding: 8px 12px;
  margin-bottom: 2px;
  border-left: 2px solid transparent;
  color: #505050;
  border-radius: 0 8px 8px 0;
  font-size: 14px;
}
.toc a:hover { background: var(--surface-2); color: var(--ink); }
.toc a.is-active { border-left-color: var(--cyan); color: var(--ink); font-weight: 600; background: var(--surface-2); }

.prose h2 {
  font-family: var(--display);
  font-size: 26px;
  color: var(--ink);
  margin: 42px 0 14px;
  letter-spacing: -0.01em;
  font-weight: 700;
  line-height: 1.55;
  scroll-margin-top: calc(var(--nav-h) + 16px);
}
.prose h2:first-child { margin-top: 0; }
.prose h3 {
  font-family: var(--display);
  font-size: 19px;
  color: var(--ink);
  margin: 28px 0 10px;
  font-weight: 600;
  line-height: 1.55;
}
.prose p { color: #505050; font-size: 15.5px; line-height: 1.85; margin: 0 0 14px; }
.prose ul { padding-left: 22px; margin: 0 0 18px; }
.prose ul li { color: #505050; font-size: 15.5px; margin-bottom: 8px; line-height: 1.65; }
.prose ul li::marker { color: var(--cyan); }
.prose strong { color: var(--ink); font-weight: 600; }

/* Inline callout / info card */
.callout {
  background: linear-gradient(135deg, rgba(102,197,197,0.10), rgba(0,64,129,0.04));
  border: 1px solid rgba(102,197,197,0.30);
  border-radius: var(--radius);
  padding: 20px 22px;
  margin: 22px 0;
  display: flex;
  gap: 14px;
  align-items: flex-start;
}
.callout .ic {
  flex-shrink: 0;
  width: 32px; height: 32px;
  border-radius: 8px;
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
}
.callout .ic svg { width: 16px; height: 16px; }
.callout h4 { margin: 0 0 4px; color: var(--ink); font-size: 15px; font-weight: 700; }
.callout p { margin: 0; color: #505050; font-size: 14.5px; line-height: 1.6; }
/* note-style callout: icon + single line → vertically centered */
.callout-note { align-items: center; }
.callout-note .ic { flex-shrink: 0; }

/* Info cards (key-value style) */
.info-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 28px;
  margin: 22px 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 22px;
}
.info-item .label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 6px;
}
.info-item .value {
  font-family: var(--display);
  font-size: 18px;
  color: var(--ink);
  font-weight: 600;
  letter-spacing: -0.005em;
  word-break: break-all;
}
.info-item .value.mono {
  font-family: "JetBrains Mono", "SF Mono", Consolas, monospace;
  font-size: 16px;
  background: var(--surface-2);
  padding: 6px 10px;
  border-radius: 6px;
  display: inline-block;
}

/* ===== ACCORDION ===== */
.accordion { display: flex; flex-direction: column; gap: 10px; }
.acc-item {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
  transition: border-color .2s ease, box-shadow .2s ease;
}
.acc-item.open { border-color: rgba(102,197,197,0.6); box-shadow: 0 4px 12px rgba(0,64,129,0.05); }
.acc-trigger {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 18px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  font-size: 15.5px;
  font-weight: 600;
  color: var(--ink);
  font-family: var(--thai);
}
.acc-trigger:hover { background: var(--surface); }
.acc-trigger .acc-icon {
  width: 26px; height: 26px;
  border-radius: 50%;
  border: 1px solid var(--line);
  display: flex; align-items: center; justify-content: center;
  color: var(--ink);
  transition: transform .25s ease, background .25s ease, border-color .25s ease;
  flex-shrink: 0;
}
.acc-item.open .acc-trigger .acc-icon {
  transform: rotate(45deg);
  background: var(--ci-navy);
  border-color: transparent;
  color: #F8F9FA;
}
.acc-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height .35s ease;
}
.acc-body-inner {
  padding: 0 22px 22px;
  color: #505050;
  font-size: 14.5px;
  line-height: 1.7;
}
.acc-body-inner ul { padding-left: 20px; margin: 8px 0; }
.acc-body-inner li::marker { color: var(--cyan); }

/* ===== ORG CHART ===== */
.org {
  padding: 28px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow-x: auto;
}
.org-tree {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 760px;
}
.org-row { display: flex; gap: 14px; justify-content: center; position: relative; }
.org-row + .org-row { margin-top: 36px; }
.org-row + .org-row::before {
  content: "";
  position: absolute;
  top: -22px;
  width: 70%;
  height: 1px;
  background: var(--line);
}
.org-row + .org-row::after {
  content: "";
  position: absolute;
  top: -22px;
  width: 1px; height: 22px;
  background: var(--line);
}
.org-node {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px 18px;
  text-align: center;
  min-width: 140px;
  box-shadow: var(--shadow-sm);
  position: relative;
}
.org-node.lead {
  background: var(--ci-navy);
  color: #F8F9FA;
  border: none;
}
.org-node .role {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--cyan);
  font-weight: 600;
}
.org-node.lead .role { color: rgba(248,249,250,0.85); }
.org-node .name {
  font-family: var(--display);
  font-weight: 700;
  font-size: 15px;
  color: var(--ink);
  margin-top: 4px;
}
.org-node.lead .name { color: #F8F9FA; }

/* ===== TEAM CHIPS ===== */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 18px;
}
.team-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 24px;
  transition: transform .2s ease, box-shadow .2s ease;
}
.team-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.team-card .team-head {
  display: flex; align-items: center; gap: 12px;
  margin-bottom: 14px;
}
.team-badge {
  width: 42px; height: 42px;
  border-radius: 10px;
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--display);
  font-weight: 700;
  font-size: 16px;
  letter-spacing: -0.02em;
}
.team-card h4 {
  margin: 0;
  font-size: 16px;
  color: var(--ink);
  font-weight: 700;
}
.team-card .team-sub {
  font-size: 12px;
  color: var(--muted);
}
.team-roles {
  display: flex; flex-wrap: wrap; gap: 6px;
}
.team-roles span {
  font-size: 12px;
  padding: 4px 10px;
  background: var(--surface-2);
  color: var(--ink);
  border-radius: 999px;
  font-weight: 500;
}

/* ===== EMBED ===== */
.embed-wrap {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.embed-bar {
  padding: 12px 18px;
  border-bottom: 1px solid var(--line-soft);
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--surface);
  font-size: 13.5px;
  color: var(--muted);
}
.embed-bar .dot { width: 9px; height: 9px; border-radius: 50%; background: var(--cyan); }
.embed-bar .name { color: var(--ink); font-weight: 600; }
.embed-bar .right { margin-left: auto; }
.embed-bar .right a {
  font-size: 13px;
  color: var(--ink);
  font-weight: 600;
}

/* ===== SHOWCASE ===== */
.tabs {
  display: inline-flex;
  background: var(--surface);
  padding: 4px;
  border-radius: 999px;
  border: 1px solid var(--line);
  margin-bottom: 36px;
}
.tab {
  padding: 9px 18px;
  font-size: 14px;
  border-radius: 999px;
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-family: var(--thai);
  font-weight: 500;
  transition: color .18s ease, background .18s ease;
}
.tab:hover { color: var(--ink); }
.tab.is-active { background: var(--ci-navy); color: #F8F9FA; box-shadow: 0 4px 10px rgba(0,64,129,0.18); }

.showcase-real-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 22px;
}
.show-real-card {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #F8F9FA;
  overflow: hidden;
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.show-real-card:hover {
  transform: translateY(-4px);
  border-color: rgba(102,197,197,0.4);
  box-shadow: var(--shadow-md);
}

.show-real-media {
  border-bottom: 1px solid var(--line-soft);
  background: linear-gradient(135deg, #F8F9FA 0%, #F8F9FA 100%);
}
.show-real-media-video {
  aspect-ratio: 9 / 14;
  min-height: 420px;
}
.show-real-media-video iframe {
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}
.show-real-media-link {
  min-height: 186px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
}
.show-real-preview {
  width: 100%;
  border: 1px dashed rgba(0,64,129,0.22);
  border-radius: 14px;
  background: rgba(248,249,250,0.85);
  padding: 14px 16px;
}
.show-real-preview-head {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 7px;
}
.show-real-preview p {
  margin: 0;
  font-size: 13.5px;
  line-height: 1.55;
  color: #505050;
}

.show-real-body {
  padding: 18px 20px 20px;
}
.show-real-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}
.show-real-badge {
  display: inline-flex;
  align-items: center;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 4px 9px;
  border-radius: 999px;
  background: rgba(0,64,129,0.08);
  color: var(--navy);
  border: 1px solid rgba(0,64,129,0.15);
}
.show-real-track {
  font-size: 12px;
  font-weight: 700;
  color: #586782;
  background: rgba(102,197,197,0.13);
  border: 1px solid rgba(102,197,197,0.3);
  border-radius: 999px;
  padding: 4px 10px;
}
.show-real-card h4 {
  margin: 0 0 8px;
  font-size: 17px;
  line-height: 1.45;
  color: var(--ink);
}
.show-real-summary {
  margin: 0;
  font-size: 13.5px;
  line-height: 1.6;
  color: var(--muted);
}
.show-real-actions {
  margin-top: 14px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
}
.show-real-link,
.show-real-canonical {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13.5px;
  font-weight: 700;
  color: var(--ink);
  text-decoration: none;
}
.show-real-link:hover,
.show-real-canonical:hover {
  color: #586782;
}
.show-real-empty {
  margin: 8px 0 18px;
  font-size: 14px;
  color: var(--muted);
  background: var(--surface);
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  padding: 14px 16px;
}
@media (max-width: 700px) {
  .showcase-real-grid { grid-template-columns: 1fr; }
  .show-real-media-video { min-height: 360px; }
  .show-real-body { padding: 16px 16px 18px; }
}

/* ===== CTA BAND ===== */
.cta-band {
  margin: 70px 0;
}
.cta-card {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 60px 56px;
  border-radius: var(--radius-lg);
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex;
  align-items: center;
  gap: 40px;
  justify-content: space-between;
  position: relative;
  overflow: hidden;
}
.cta-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 90% 0%, rgba(248,249,250,0.18), transparent 50%),
    radial-gradient(circle at 0% 100%, rgba(0,17,34,0.10), transparent 50%);
  pointer-events: none;
}
.cta-card h3 {
  font-family: var(--display);
  font-size: clamp(22px, 2.6vw, 30px);
  margin: 0 0 6px;
  font-weight: 700;
  letter-spacing: -0.01em;
  position: relative;
}
.cta-card p { margin: 0; opacity: 0.9; font-size: 15px; max-width: 520px; position: relative; }
.cta-card .btn {
  background: #F8F9FA;
  color: var(--ink);
  position: relative;
}
.cta-card .btn:hover {
  background: #F8F9FA;
  filter: brightness(0.95);
}

/* ===== FOOTER ===== */
.footer {
  background: #001122;
  color: #D0D6DF;
  margin-top: 80px;
}
.footer-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 64px 28px 36px;
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 48px;
}
.footer-logo {
  height: 32px;
  width: auto;
  margin-bottom: 16px;
  filter: brightness(1.1);
}
.footer-tag {
  margin: 0;
  font-size: 14px;
  color: #929EB4;
  line-height: 1.7;
  max-width: 380px;
}
.footer-col h4 {
  margin: 0 0 16px;
  font-size: 13px;
  color: #F8F9FA;
  font-weight: 600;
  letter-spacing: 0.04em;
}
.footer-col a {
  display: block;
  color: #929EB4;
  font-size: 14px;
  padding: 4px 0;
  transition: color .15s ease;
}
.footer-col a:hover { color: #F8F9FA; }
.footer-bottom {
  border-top: 1px solid rgba(248,249,250,0.06);
  padding: 22px 28px;
  max-width: var(--maxw);
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12.5px;
  color: #707070;
  flex-wrap: wrap;
  gap: 8px;
}

/* ===== TIMESHEET PAGE ===== */
.timesheet-hero {
  background: var(--ci-navy);
  color: #F8F9FA;
  border-radius: var(--radius-lg);
  padding: 44px 44px;
  position: relative;
  overflow: hidden;
  margin-bottom: 36px;
}
.timesheet-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 100% 0, rgba(248,249,250,0.18), transparent 60%);
}
.timesheet-hero h2 { color: #F8F9FA; font-family: var(--display); font-size: 28px; margin: 0 0 8px; font-weight: 700; position: relative; }
.timesheet-hero p { margin: 0 0 22px; opacity: 0.9; max-width: 520px; position: relative; }
.timesheet-hero .btn { background: #F8F9FA; color: var(--ink); position: relative; }

.howto {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 18px;
  margin: 24px 0 0;
}
.howto-step {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 22px;
}
.howto-step .num {
  width: 32px; height: 32px;
  border-radius: 8px;
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
  font-weight: 700;
  font-family: var(--display);
  margin-bottom: 14px;
}
.howto-step h4 { margin: 0 0 6px; color: var(--ink); font-size: 16px; font-weight: 700; }
.howto-step p { margin: 0; color: var(--muted); font-size: 14px; line-height: 1.6; }

/* ===== TABLE-LIKE LIST ===== */
.kv-list {
  display: flex; flex-direction: column;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  background: #F8F9FA;
}
.kv-row {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 24px;
  padding: 16px 24px;
  align-items: baseline;
  border-bottom: 1px solid var(--line-soft);
  font-size: 14.5px;
}
.kv-row:last-child { border-bottom: none; }
.kv-row .k {
  color: var(--muted);
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.02em;
}
.kv-row .v { color: #505050; }
.kv-row .v strong { color: var(--ink); }

/* ===== UTIL ===== */
.flex { display: flex; }
.gap-md { gap: 16px; }
.row-wrap { flex-wrap: wrap; }
.center { align-items: center; }

/* fade-in animation */
/* === Scroll-triggered animation system === */
.fade-up,
.anim-up   { opacity: 0; transform: translateY(28px); }
.anim-down { opacity: 0; transform: translateY(-28px); }
.anim-left { opacity: 0; transform: translateX(-28px); }
.anim-right{ opacity: 0; transform: translateX(28px); }
.anim-scale{ opacity: 0; transform: scale(0.93); }

.fade-up, .anim-up, .anim-down, .anim-left, .anim-right, .anim-scale {
  transition: opacity 0.6s cubic-bezier(0.16, 1, 0.3, 1), transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: opacity, transform;
}
.fade-up.is-visible,
.anim-up.is-visible,
.anim-down.is-visible,
.anim-left.is-visible,
.anim-right.is-visible,
.anim-scale.is-visible {
  opacity: 1;
  transform: none;
}
@keyframes fadeUp { to { opacity: 1; transform: translateY(0); } }

/* ============================================================
   PAGE TRANSITION SYSTEM
   ============================================================ */
.page-exiting {
  opacity: 0;
  transform: translateY(-10px) scale(0.99);
  pointer-events: none;
  transition: opacity 0.11s ease, transform 0.11s ease;
}
.page-entering {
  animation: pageEnterAnim 0.52s cubic-bezier(0.25, 1, 0.5, 1) forwards;
}
@keyframes pageEnterAnim {
  from { opacity: 0; transform: translateY(22px) scale(0.99); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* ============================================================
   GLOBAL WOW — PROSE SECTION HEADINGS
   Enhanced h2/h3 inside .prose content areas
   ============================================================ */
.prose {
  counter-reset: section-h2;
}
.prose h2 {
  position: relative;
  padding-left: 20px;
  counter-increment: section-h2;
  font-size: 22px !important;
  font-weight: 800 !important;
  letter-spacing: -0.02em;
  color: #001122 !important;
}
.prose h2::before {
  content: "";
  position: absolute;
  left: 0; top: 6px; bottom: 6px;
  width: 4px;
  background: var(--ci-teal);
  border-radius: 999px;
}
/* h3 upgrades */
.prose h3 {
  font-size: 17px !important;
  font-weight: 700 !important;
  color: #001122 !important;
  padding-left: 14px;
  position: relative;
}
.prose h3::before {
  content: "";
  position: absolute;
  left: 0; top: 5px; bottom: 5px;
  width: 3px;
  background: rgba(102,197,197,0.55);
  border-radius: 999px;
}
/* h4 upgrades */
.prose h4 {
  font-weight: 700 !important;
  color: #001122 !important;
}

/* ============================================================
   CALLOUT — enhanced bold style
   ============================================================ */
.callout {
  transition: box-shadow 0.22s ease, transform 0.22s ease;
}
.callout:hover {
  box-shadow: 0 12px 32px rgba(0,64,129,0.10);
  transform: translateY(-2px);
}
.callout-warn {
  border-left-color: #FFCC00;
  background: rgba(255,204,0,0.06);
}
.callout-warn h4 { color: #707070; }

/* ============================================================
   STAT PILL — for embedding big numbers in prose
   ============================================================ */
.stat-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--ci-navy);
  color: #F8F9FA;
  font-family: var(--display);
  font-weight: 800;
  font-size: 13px;
  padding: 4px 12px;
  border-radius: 999px;
  letter-spacing: 0.01em;
  vertical-align: middle;
}
.stat-big {
  font-family: var(--display);
  font-size: clamp(36px, 5vw, 54px);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--ci-navy);
}

/* ============================================================
   PAGE HERO BAND — shown at top of every inner page
   ============================================================ */
.page-hero-band {
  position: relative;
  overflow: hidden;
  padding: 28px 0 26px;
  margin-bottom: 0;
  background: linear-gradient(135deg,
    rgba(102,197,197,0.06) 0%,
    rgba(0,64,129,0.03) 60%,
    rgba(88,103,130,0.04) 100%);
  border-bottom: 1px solid var(--line-soft);
}
.page-hero-band::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 80% at 90% -20%, rgba(102,197,197,0.14) 0%, transparent 70%);
  pointer-events: none;
}
.page-hero-band::after {
  content: "";
  position: absolute;
  bottom: -1px; left: 0; right: 0;
  height: 3px;
  background: var(--ci-teal);
  opacity: 0.55;
}
.phb-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 clamp(16px, 4vw, 48px);
  position: relative;
  z-index: 1;
}
.phb-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--cyan);
  background: rgba(102,197,197,0.12);
  border: 1px solid rgba(102,197,197,0.22);
  padding: 5px 12px;
  border-radius: 999px;
  margin-bottom: 16px;
}
.phb-title {
  font-family: var(--display);
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 900;
  letter-spacing: -0.03em;
  color: var(--ink);
  margin: 0 0 14px;
  line-height: 1.1;
}
.phb-title .phb-grad {
  color: var(--ci-navy);
}
.phb-lead {
  font-size: clamp(15px, 1.8vw, 17px);
  line-height: 1.75;
  color: #505050;
  max-width: 620px;
  margin: 0;
}
.phb-deco-num {
  position: absolute;
  right: clamp(16px, 5vw, 80px);
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--display);
  font-size: clamp(80px, 12vw, 160px);
  font-weight: 900;
  letter-spacing: -0.06em;
  line-height: 1;
  color: var(--ci-navy);
  opacity: 0.07;
  pointer-events: none;
  user-select: none;
}

/* ============================================================
   JOURNEY CTA STRIP — "Next Chapter" style
   ============================================================ */
.page-cta-strip {
  position: relative;
  overflow: hidden;
  margin-top: 64px;
  padding: 36px 40px;
  background: linear-gradient(135deg,
    rgba(102,197,197,0.07) 0%,
    rgba(0,64,129,0.04) 100%);
  border: 1px solid rgba(102,197,197,0.18);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  flex-wrap: wrap;
}
.page-cta-strip::before {
  content: "";
  position: absolute;
  left: 0; right: 0; top: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--ci-teal) 0%, transparent 100%);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}
.page-cta-strip::after {
  content: "";
  position: absolute;
  right: -40px; top: -40px;
  width: 160px; height: 160px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(102,197,197,0.10) 0%, transparent 70%);
  pointer-events: none;
}
.page-cta-strip h4 {
  font-family: var(--display);
  font-size: 18px;
  font-weight: 800;
  color: var(--ink);
  margin: 0 0 6px;
}
.page-cta-strip p {
  font-size: 14px;
  color: var(--muted);
  margin: 0;
  line-height: 1.6;
}

/* ============================================================
   HOWTO STEP — enhanced with gradient number
   ============================================================ */
.howto-step {
  transition: transform 0.22s ease, box-shadow 0.22s ease;
}
.howto-step:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 28px rgba(0,64,129,0.10);
}
.howto .num {
  background: var(--ci-navy) !important;
  color: #F8F9FA !important;
  font-family: var(--display);
  font-weight: 900;
  width: 38px; height: 38px;
  border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px;
  flex-shrink: 0;
  box-shadow: 0 6px 16px rgba(0,64,129,0.18);
}

/* ============================================================
   RULE CARDS — hover glow
   ============================================================ */
.rule-card {
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.rule-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 14px 32px rgba(0,64,129,0.10);
  border-color: rgba(102,197,197,0.35);
}

/* ============================================================
   BUTTON SHINE EFFECT
   ============================================================ */
.btn-primary {
  position: relative;
  overflow: hidden;
}
.btn-primary::after {
  content: "";
  position: absolute;
  top: 0; left: -100%;
  width: 60%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(248,249,250,0.18), transparent);
  transform: skewX(-20deg);
  transition: left 0.55s ease;
}
.btn-primary:hover::after {
  left: 160%;
}

/* ============================================================
   CARD HOVER GLOW (global upgrade)
   ============================================================ */
.hb-card,
.dress-card,
.howto-step,
.ts-col,
.faq-item,
.mr-book-card,
.oct-dept-card {
  transition: transform 0.24s cubic-bezier(0.22, 1, 0.36, 1),
              box-shadow 0.24s ease,
              border-color 0.24s ease;
}
.hb-card:hover,
.dress-card:hover,
.ts-col:hover,
.mr-book-card:hover {
  transform: translateY(-5px) scale(1.01);
  box-shadow: 0 16px 36px rgba(0,64,129,0.12);
  border-color: rgba(102,197,197,0.30);
}

/* ============================================================
   BREADCRUMB JOURNEY DOTS
   ============================================================ */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 13px;
  padding: 16px 0 0;
}
.breadcrumb a {
  color: var(--cyan);
  text-decoration: none;
  font-weight: 600;
  transition: opacity 0.15s ease;
}
.breadcrumb a:hover { opacity: 0.75; }
.breadcrumb-sep {
  color: var(--muted);
  opacity: 0.5;
  font-size: 11px;
}
.breadcrumb-cur {
  color: var(--ink);
  font-weight: 700;
}

/* hero-orb styles are defined in the HERO HOME section below */

/* ============================================================
   ACCENT DOT GRID — subtle background texture
   ============================================================ */
.dot-grid-bg {
  background-image: radial-gradient(rgba(0,64,129,0.055) 1px, transparent 1px);
  background-size: 24px 24px;
}

/* ============================================================
   EYEBROW LABEL STYLE (reusable)
   ============================================================ */
.section-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 12px;
}
.section-eyebrow::before {
  content: "";
  display: inline-block;
  width: 18px; height: 2px;
  background: var(--ci-teal);
  border-radius: 999px;
}

/* ===== WIFI PAGE ===== */
.wifi-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
  margin: 8px 0 28px;
}
.wifi-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 30px 28px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  transition: box-shadow .25s ease, transform .25s ease;
}
.wifi-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.wifi-staff {
  border: none;
  position: relative;
}
.wifi-staff::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: var(--ci-teal);
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}
.wifi-staff { border: 1px solid var(--line); padding-top: 34px; }
.wifi-card-head { display: flex; align-items: center; gap: 14px; }
.wifi-icon {
  width: 52px; height: 52px;
  border-radius: 14px;
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.wifi-guest .wifi-icon { background: var(--surface-2); color: var(--ink); }
.wifi-label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 2px;
}
.wifi-card h3 {
  margin: 0;
  font-family: var(--display);
  font-size: 22px;
  color: var(--ink);
  font-weight: 700;
  letter-spacing: -0.01em;
}
.wifi-info {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px 18px;
  background: var(--surface);
  border-radius: 12px;
  border: 1px solid var(--line-soft);
}
.wifi-row {
  display: grid;
  grid-template-columns: 90px 1fr;
  gap: 14px;
  align-items: center;
}
.wifi-k {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}
.wifi-v {
  font-family: var(--display);
  font-size: 17px;
  color: var(--ink);
  font-weight: 600;
  letter-spacing: -0.005em;
}
.wifi-pw { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.wifi-pw code {
  font-family: "JetBrains Mono", "SF Mono", Consolas, monospace;
  font-size: 15px;
  background: #F8F9FA;
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid var(--line);
  color: var(--ink);
  font-weight: 600;
  letter-spacing: 0.04em;
}
.wifi-copy {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 8px;
  width: 32px; height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--ink);
  transition: background .18s ease, color .18s ease, border-color .18s ease;
}
.wifi-copy:hover { background: var(--ink); color: #F8F9FA; border-color: var(--ink); }
.wifi-copy.is-copied { background: #586782; color: #F8F9FA; border-color: #586782; }
.wifi-qr {
  background: #F8F9FA;
  border: 1px dashed var(--line);
  border-radius: 12px;
  padding: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.wifi-qr svg { max-width: 180px; width: 100%; height: auto; }
.wifi-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.wifi-actions .btn { padding: 11px 18px; font-size: 14px; }
.wifi-hint { margin: 0; font-size: 13px; color: var(--muted); line-height: 1.6; }

/* ===== EMPLOYEE DIRECTORY ===== */

/* ── Password Gate ── */
.dir-gate {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 0 48px;
}
.dir-gate-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 44px 40px 40px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 40px rgba(0,64,129,.08);
}
.dir-gate-icon {
  width: 64px;
  height: 64px;
  border-radius: 16px;
  background: rgba(0,64,129,.08);
  color: var(--navy);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}
.dir-gate-title {
  font-family: var(--display);
  font-size: 20px;
  font-weight: 800;
  color: var(--ink);
  margin: 0 0 10px;
}
.dir-gate-desc {
  font-size: 14px;
  color: var(--muted);
  line-height: 1.65;
  margin: 0 0 24px;
}
.dir-gate-form {
  display: flex;
  gap: 10px;
  margin-bottom: 12px;
}
.dir-pw-input {
  flex: 1;
  height: 44px;
  border: 1.5px solid var(--line);
  border-radius: 10px;
  padding: 0 14px;
  font-size: 14px;
  font-family: var(--body);
  color: var(--ink);
  background: var(--surface);
  outline: none;
  transition: border-color .2s;
}
.dir-pw-input:focus { border-color: var(--cyan); }
.dir-pw-input.is-error {
  border-color: #F3554F;
  animation: dir-shake .35s ease;
}
@keyframes dir-shake {
  0%,100% { transform: translateX(0); }
  20%      { transform: translateX(-6px); }
  40%      { transform: translateX(6px); }
  60%      { transform: translateX(-4px); }
  80%      { transform: translateX(4px); }
}
.dir-pw-btn {
  height: 44px;
  padding: 0 18px;
  background: var(--ci-navy);
  color: #F8F9FA;
  border: none;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 700;
  font-family: var(--body);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
  transition: opacity .2s;
}
.dir-pw-btn:hover { opacity: .9; }
.dir-gate-err:not([hidden]) {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 12.5px;
  color: #F3554F;
  margin-bottom: 16px;
  background: rgba(243,85,79,.07);
  border-radius: 8px;
  padding: 8px 12px;
}
.dir-gate-hint {
  font-size: 13px;
  color: var(--muted);
}

/* ── Top bar (toggle + lock) ── */
.dir-topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.dir-view-toggle {
  display: flex;
  gap: 4px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 3px;
}
.dir-view-btn {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 14px;
  border: none;
  border-radius: 7px;
  background: none;
  font-size: 13px;
  font-weight: 600;
  font-family: var(--body);
  color: var(--muted);
  cursor: pointer;
  transition: background .18s, color .18s;
}
.dir-view-btn.is-active {
  background: #F8F9FA;
  color: var(--navy);
  box-shadow: 0 1px 6px rgba(0,64,129,.1);
}
.dir-mode-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  background: rgba(102,197,197,.12);
  color: #004081;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  border: 1px solid rgba(102,197,197,.25);
}
.dir-lock-btn {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: none;
  font-size: 12.5px;
  font-weight: 600;
  font-family: var(--body);
  color: var(--muted);
  cursor: pointer;
  transition: background .2s, color .2s;
}
.dir-lock-btn:hover { background: var(--surface); color: var(--ink); }

/* ── View containers ── */
.dir-view { }
.dir-view-hidden { display: none; }

/* ── Department view v2 — org-chart grouped cards ── */
.dir-dept2-wrap {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 20px;
  padding: 4px 0 8px;
}

/* Base card */
.dir-dept2-card {
  border-radius: 20px;
  overflow: hidden;
  border: 1.5px solid transparent;
  box-shadow: 0 4px 24px rgba(0,64,129,.07);
  transition: box-shadow .25s, transform .2s;
}
.dir-dept2-card:hover {
  box-shadow: 0 10px 36px rgba(0,64,129,.13);
  transform: translateY(-2px);
}

/* ── Color variants matching org chart ── */
.ddc-bd  { background: linear-gradient(160deg, #F8F9FA 0%, #F8F9FA 100%); border-color: rgba(255,204,0,.2); }
.ddc-hr  { background: linear-gradient(160deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(102,197,197,.22); }
.ddc-dev { background: linear-gradient(160deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(88,103,130,.18); }
.ddc-des { background: linear-gradient(160deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(146,158,180,.2); }
.ddc-sal { background: linear-gradient(160deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(130,197,102,.2); }
.ddc-oth { background: linear-gradient(160deg, #F8F9FA 0%, #F8F9FA 100%); border-color: rgba(88,103,130,.18); }

/* Card header */
.dir-dept2-hd {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 20px 14px;
}
.dir-dept2-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.ddc-bd  .dir-dept2-icon { background: rgba(255,204,0,.14); color: #F3554F; }
.ddc-hr  .dir-dept2-icon { background: rgba(102,197,197,.18); color: #004081; }
.ddc-dev .dir-dept2-icon { background: rgba(88,103,130,.14);  color: #004081; }
.ddc-des .dir-dept2-icon { background: rgba(146,158,180,.14);  color: #586782; }
.ddc-sal .dir-dept2-icon { background: rgba(130,197,102,.14);   color: #505050; }
.ddc-oth .dir-dept2-icon { background: rgba(88,103,130,.14); color: #586782; }

.dir-dept2-hd-text { flex: 1; min-width: 0; }
.dir-dept2-name {
  font-family: var(--display);
  font-size: 14.5px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -.01em;
  line-height: 1.2;
}
.dir-dept2-meta {
  font-size: 11.5px;
  color: var(--muted);
  margin-top: 2px;
}
.dir-dept2-pill {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .01em;
  padding: 3px 10px;
  border-radius: 20px;
  white-space: nowrap;
  flex-shrink: 0;
}
.ddc-bd  .dir-dept2-pill { background: rgba(255,204,0,.15); color: #505050; }
.ddc-hr  .dir-dept2-pill { background: rgba(102,197,197,.2);  color: #004081; }
.ddc-dev .dir-dept2-pill { background: rgba(88,103,130,.13);  color: #004081; }
.ddc-des .dir-dept2-pill { background: rgba(146,158,180,.14);  color: #586782; }
.ddc-sal .dir-dept2-pill { background: rgba(130,197,102,.14);   color: #505050; }
.ddc-oth .dir-dept2-pill { background: rgba(88,103,130,.13); color: #505050; }

/* Card body */
.dir-dept2-body {
  padding: 0 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Team block within department */
.dir-dept2-team {
  background: rgba(248,249,250,.65);
  backdrop-filter: blur(4px);
  border-radius: 12px;
  padding: 10px 12px;
  border: 1px solid rgba(248,249,250,.8);
}
.dir-dept2-team-hd {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}
.dir-dept2-team-label {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .05em;
}
.dir-dept2-team-n {
  font-size: 10.5px;
  font-weight: 800;
  color: var(--muted);
  background: rgba(0,64,129,.07);
  border-radius: 20px;
  padding: 1px 7px;
}

/* Member avatars */
.dir-dept2-members {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.dir-d2-member {
  display: flex;
  align-items: center;
  gap: 5px;
  background: rgba(248,249,250,.85);
  border: 1px solid rgba(0,64,129,.09);
  border-radius: 20px;
  padding: 3px 8px 3px 4px;
  cursor: default;
  transition: background .15s, border-color .15s;
}
.dir-d2-member:hover { background: #F8F9FA; border-color: rgba(0,64,129,.2); }
.dir-d2-av {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--ci-navy);
  color: #F8F9FA;
  font-size: 10px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  line-height: 1;
}
.dir-d2-nm {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
  white-space: nowrap;
}
.dir-d2-mail {
  width: 18px;
  height: 18px;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted);
  margin-left: 1px;
  transition: color .15s;
}
.dir-d2-mail:hover { color: var(--navy); }

/* Keep old member classes for backward compat (no longer rendered) */
.dir-dept-grid { display: none; }

/* ── Existing toolbar below ── */
.dir-toolbar {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 18px;
  flex-wrap: wrap;
}
.dir-search {
  flex: 1;
  min-width: 240px;
  position: relative;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0 14px 0 42px;
  transition: border-color .2s ease, box-shadow .2s ease;
}
.dir-search:focus-within {
  border-color: var(--cyan);
  box-shadow: 0 0 0 4px rgba(102,197,197,0.16);
}
.dir-search-ico {
  position: absolute;
  left: 14px; top: 50%;
  transform: translateY(-50%);
  color: var(--muted);
  display: flex;
}
#dir-q {
  width: 100%;
  border: none;
  outline: none;
  padding: 13px 0;
  font-family: var(--thai);
  font-size: 15px;
  background: transparent;
  color: var(--ink);
}
#dir-team {
  padding: 13px 16px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #F8F9FA;
  font-family: var(--thai);
  font-size: 14.5px;
  color: var(--ink);
  cursor: pointer;
  min-width: 180px;
}
.dir-count {
  font-size: 13px;
  color: var(--muted);
  font-weight: 500;
  white-space: nowrap;
}
.dir-table-wrap {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.dir-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14.5px;
}
.dir-table thead th {
  text-align: left;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  background: var(--surface);
  padding: 14px 20px;
  border-bottom: 1px solid var(--line);
}
.dir-table tbody td {
  padding: 13px 20px;
  border-bottom: 1px solid var(--line-soft);
  color: #505050;
}
.dir-table tbody tr:hover td { background: var(--surface); }
.dir-table tbody tr:last-child td { border-bottom: none; }
.dir-table a { color: var(--ink); font-weight: 500; }
.dir-table a:hover { text-decoration: underline; }
.dir-tag {
  display: inline-block;
  font-size: 12px;
  padding: 3px 10px;
  background: var(--grad-soft);
  color: var(--ink);
  border-radius: 999px;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.dir-muted { color: var(--muted); }
.dir-email { color: var(--cyan); font-size: 13px; word-break: break-all; }
.dir-empty {
  padding: 50px 20px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
}

/* ===== CORE VALUES PAGE ===== */
.values-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-areas:
    "v1 v1"
    "v2 v3"
    "v4 v5";
  gap: 22px;
  margin-top: 8px;
}
.value-card-1 { grid-area: v1; }
.value-card-2 { grid-area: v2; }
.value-card-3 { grid-area: v3; }
.value-card-4 { grid-area: v4; }
.value-card-5 { grid-area: v5; }
.value-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 30px 28px 28px 34px;
  position: relative;
  overflow: hidden;
  transition: transform .25s ease, box-shadow .25s ease;
}
.value-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.value-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0;
  width: 6px; height: 100%;
}
.value-1::before { background: linear-gradient(180deg, #FFCC00, #F3554F); }
.value-2::before { background: linear-gradient(180deg, #66C5C5, #004081); }
.value-3::before { background: linear-gradient(180deg, #66C5C5, #586782); }
.value-4::before { background: linear-gradient(180deg, #F3554F, #F3554F); }
.value-5::before { background: linear-gradient(180deg, #929EB4, #586782); }

.value-num {
  font-family: var(--display);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  margin-bottom: 4px;
}
.value-1 .value-num { color: #F3554F; }
.value-2 .value-num { color: #004081; }
.value-3 .value-num { color: #586782; }
.value-4 .value-num { color: #F3554F; }
.value-5 .value-num { color: #586782; }

.value-card h3 {
  font-family: var(--display);
  font-size: 22px;
  color: var(--ink);
  font-weight: 700;
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}
.value-sub {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.55;
  margin: 0 0 18px;
}
.value-tags {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.value-tags li {
  display: flex;
  gap: 12px;
  align-items: baseline;
  font-size: 13.5px;
  line-height: 1.55;
  color: #505050;
}
.vt {
  display: inline-block;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  padding: 3px 9px;
  border-radius: 6px;
  color: #F8F9FA;
  flex-shrink: 0;
  align-self: flex-start;
  white-space: nowrap;
  text-transform: uppercase;
}
.vt-1 { background: linear-gradient(135deg, #FFCC00, #F3554F); }
.vt-2 { background: linear-gradient(135deg, #66C5C5, #004081); }
.vt-3 { background: linear-gradient(135deg, #66C5C5, #586782); }
.vt-4 { background: linear-gradient(135deg, #F3554F, #F3554F); }
.vt-5 { background: linear-gradient(135deg, #929EB4, #586782); }

/* ===== ORG CHART (wide row support) ===== */
.org-row-wide {
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  max-width: 100%;
}
.org-row-wide .org-node { min-width: 130px; }

/* ===== ADMIN MODE ===== */
.admin-bar {
  background: linear-gradient(90deg, #001122 0%, #004081 100%);
  color: #F8F9FA;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
}
.admin-bar[hidden] { display: none !important; }
.admin-dot {
  position: relative;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: #66C5C5;
  box-shadow: 0 0 0 4px rgba(102,197,197,0.30);
}
.admin-dot::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid rgba(102,197,197,.45);
  animation: pulse 1.6s ease-out infinite;
  pointer-events: none;
}
@keyframes pulse {
  0% { transform: scale(.7); opacity: .8; }
  100% { transform: scale(1.5); opacity: 0; }
}
.admin-label { font-weight: 600; letter-spacing: 0.02em; }
.admin-btn {
  background: rgba(248,249,250,0.16);
  border: 1px solid rgba(248,249,250,0.22);
  color: #F8F9FA;
  padding: 5px 12px;
  border-radius: 999px;
  font-family: var(--thai);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background .18s ease;
}
.admin-btn:hover { background: rgba(248,249,250,0.26); }
.admin-btn-ghost { background: transparent; }

/* Admin modal */
.admin-modal {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.admin-modal[hidden] { display: none !important; }
.admin-modal-bd {
  position: absolute;
  inset: 0;
  background: rgba(0,17,34,0.55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.admin-modal-card {
  position: relative;
  background: #F8F9FA;
  border-radius: var(--radius-lg);
  max-width: 720px;
  width: 100%;
  max-height: calc(100vh - 48px);
  display: flex;
  flex-direction: column;
  box-shadow: 0 30px 60px rgba(0,17,34,0.25);
  overflow: hidden;
  animation: modalIn .22s ease;
}
.admin-modal-card-sm { max-width: 440px; }
@keyframes modalIn {
  from { opacity: 0; transform: translateY(10px) scale(.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.admin-modal-head {
  padding: 24px 28px 18px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid var(--line-soft);
  gap: 16px;
}
.admin-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 4px;
}
.admin-modal-head h3 {
  margin: 0;
  font-family: var(--display);
  font-size: 22px;
  color: var(--ink);
  font-weight: 700;
  letter-spacing: -0.01em;
}
.admin-x {
  background: var(--surface-2);
  border: none;
  width: 32px; height: 32px;
  border-radius: 8px;
  cursor: pointer;
  color: var(--muted);
  font-size: 16px;
  flex-shrink: 0;
}
.admin-x:hover { background: var(--ink); color: #F8F9FA; }
.admin-modal-body {
  padding: 22px 28px;
  overflow-y: auto;
  flex: 1;
}
.admin-modal-foot {
  padding: 16px 28px;
  border-top: 1px solid var(--line-soft);
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  background: var(--surface);
}
.admin-section { margin-bottom: 22px; }
.admin-section:last-child { margin-bottom: 0; }
.admin-section-title {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line-soft);
}
.admin-field { margin-bottom: 14px; }
.admin-field label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  margin-bottom: 6px;
}
.admin-field .hint {
  font-size: 12px;
  color: var(--muted);
  margin-top: 4px;
}
.admin-input {
  width: 100%;
  padding: 11px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  font-family: var(--thai);
  font-size: 14.5px;
  color: var(--ink);
  background: #F8F9FA;
  transition: border-color .18s ease, box-shadow .18s ease;
  outline: none;
}
.admin-input:focus {
  border-color: var(--cyan);
  box-shadow: 0 0 0 4px rgba(102,197,197,0.16);
}
.admin-input.mono {
  font-family: "JetBrains Mono", Consolas, monospace;
  font-size: 14px;
  letter-spacing: 0.02em;
}
.admin-err {
  color: #F3554F;
  font-size: 13px;
  margin: 8px 0 0;
  font-weight: 500;
}
.admin-tabs {
  display: flex;
  gap: 4px;
  background: var(--surface);
  padding: 4px;
  border-radius: 10px;
  margin-bottom: 18px;
  border: 1px solid var(--line);
}
.admin-tab {
  flex: 1;
  padding: 8px 12px;
  background: none;
  border: none;
  border-radius: 7px;
  font-family: var(--thai);
  font-size: 13px;
  font-weight: 500;
  color: var(--muted);
  cursor: pointer;
  transition: background .18s ease, color .18s ease;
}
.admin-tab:hover { color: var(--ink); }
.admin-tab.is-active {
  background: #F8F9FA;
  color: var(--ink);
  font-weight: 600;
  box-shadow: 0 1px 3px rgba(0,64,129,0.08);
}

/* ===== Admin showcase sub-tabs ===== */
.admin-sc-tabs {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.admin-sc-tab {
  font: inherit;
  font-size: 12.5px;
  font-weight: 500;
  padding: 5px 14px;
  border-radius: 99px;
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
  transition: all .15s;
}
.admin-sc-tab:hover { border-color: var(--cyan); color: var(--ink); }
.admin-sc-tab.is-active { background: var(--ink); color: #F8F9FA; border-color: var(--ink); font-weight: 600; }

/* showcase item row in admin */
.sc-admin-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  margin-bottom: 8px;
  background: var(--surface);
  transition: border-color .15s;
}
.sc-admin-item:hover { border-color: rgba(102,197,197,0.5); }
.sc-admin-info {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
  flex-wrap: wrap;
}
.sc-admin-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--ink);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sc-admin-meta {
  font-size: 12px;
  color: var(--muted);
  flex-shrink: 0;
}
.sc-admin-link {
  display: flex;
  align-items: center;
  color: var(--cyan);
  flex-shrink: 0;
}
.sc-del-btn {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: #F8F9FA;
  color: #F3554F;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .15s, border-color .15s;
}
.sc-del-btn:hover { background: #F8F9FA; border-color: #F3554F; }
.sc-del-btn svg { width: 13px; height: 13px; }

/* toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: #F8F9FA;
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: 0 12px 28px rgba(0,17,34,0.18);
  z-index: 300;
  opacity: 0;
  transition: opacity .2s ease, transform .25s ease;
  pointer-events: none;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ===== STORY SECTIONS (Homepage) ===== */
.story-section {
  padding: 90px 0;
  position: relative;
}
.story-section-light { background: var(--surface); }
.story-section-dark {
  background: linear-gradient(135deg, #001122 0%, #004081 50%, #004081 100%);
  color: #F8F9FA;
  position: relative;
  overflow: hidden;
}
.story-section-dark::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 25% 30%, rgba(102,197,197,0.15), transparent 50%),
    radial-gradient(circle at 80% 75%, rgba(102,197,197,0.10), transparent 50%);
  pointer-events: none;
}
.story-section-cta { background: var(--surface); padding-bottom: 60px; }
.story-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 28px;
  position: relative;
}
.story-title {
  font-family: var(--display);
  font-size: clamp(32px, 4vw, 44px);
  font-weight: 800;
  color: var(--ink);
  letter-spacing: -0.02em;
  line-height: 1.6;
  margin: 8px 0 16px;
  padding-top: 4px;
}
.story-title-light { color: #F8F9FA; }
.story-lead {
  font-size: 17px;
  line-height: 1.9;
  color: var(--muted);
  max-width: 680px;
  margin: 0 0 50px;
  padding-top: 10px;
}
.story-lead-light { color: rgba(248,249,250,0.78); }
.story-lead em { font-style: normal; color: var(--cyan); font-weight: 600; }
.eyebrow-light { color: rgba(248,249,250,0.85); }
.story-content {
  max-width: 760px;
  font-size: 16px;
  line-height: 1.8;
  color: #505050;
}
.story-content p { margin: 0 0 16px; }
.story-sub {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 700;
  color: var(--ink);
  margin: 50px 0 24px;
  letter-spacing: -0.01em;
}

/* Journey on home — bigger cards with icons */
.story-journey {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  position: relative;
}
.story-journey::before {
  content: "";
  position: absolute;
  top: 60px;
  left: 60px; right: 60px;
  height: 2px;
  background: linear-gradient(90deg, var(--cyan) 0%, var(--cyan) 50%, var(--navy) 100%);
  opacity: 0.25;
  z-index: 0;
}
.sj-step {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 30px 26px;
  position: relative;
  z-index: 1;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.sj-step:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--cyan);
}
.sj-num {
  font-family: var(--display);
  font-size: 13px;
  font-weight: 800;
  color: var(--cyan);
  letter-spacing: 0.10em;
  margin-bottom: 12px;
}
.sj-icon {
  width: 48px; height: 48px;
  border-radius: 14px;
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 18px;
}
.sj-step h3 {
  font-family: var(--display);
  font-size: 19px;
  color: var(--ink);
  font-weight: 700;
  margin: 0 0 8px;
}
.sj-step p {
  font-size: 14px;
  line-height: 1.6;
  color: var(--muted);
  margin: 0 0 18px;
  min-height: 44px;
}
.sj-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--ink);
  text-decoration: none;
  transition: gap .2s ease, color .2s ease;
}
.sj-link:hover { gap: 10px; color: var(--cyan); }

/* Values preview (dark section) */
.values-preview {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 18px;
  margin-top: 8px;
}
.vp-card {
  display: block;
  background: rgba(248,249,250,0.06);
  border: 1px solid rgba(248,249,250,0.12);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  border-radius: 18px;
  padding: 26px 22px;
  text-decoration: none;
  transition: transform .25s ease, background .25s ease, border-color .25s ease;
}
.vp-card:hover {
  transform: translateY(-4px);
  background: rgba(248,249,250,0.12);
  border-color: rgba(102,197,197,0.4);
}
.vp-num {
  font-family: var(--display);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.10em;
  color: var(--cyan);
  margin-bottom: 14px;
}
.vp-card h4 {
  font-family: var(--display);
  font-size: 17px;
  color: #F8F9FA;
  font-weight: 700;
  margin: 0 0 8px;
  letter-spacing: -0.005em;
}
.vp-card p {
  font-size: 12.5px;
  color: rgba(248,249,250,0.65);
  margin: 0;
  line-height: 1.5;
  letter-spacing: 0.01em;
}

/* Fact grid (Quick Facts) */
.fact-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.fact-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 28px 26px;
  transition: transform .25s ease, box-shadow .25s ease;
}
.fact-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.fact-icon {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: var(--grad-soft);
  color: var(--ink);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 18px;
}
.fact-num {
  font-family: var(--display);
  font-size: 26px;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: -0.02em;
  margin-bottom: 4px;
  word-break: break-word;
  overflow-wrap: break-word;
}
.fact-card:nth-child(3) .fact-num {
  font-size: 17px;
  letter-spacing: 0;
  font-weight: 700;
}
.fact-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 12px;
}
.fact-card p {
  font-size: 13.5px;
  line-height: 1.6;
  color: var(--muted);
  margin: 0;
}

/* Duty grid (Roles & Duties) */
.duty-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
  margin-bottom: 8px;
}
.duty-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  position: relative;
}
.duty-num {
  font-family: var(--display);
  font-size: 36px;
  font-weight: 800;
  color: var(--cyan);
  opacity: 0.5;
  line-height: 1;
  margin-bottom: 16px;
}
.duty-card h3 {
  font-family: var(--display);
  font-size: 20px;
  color: var(--ink);
  font-weight: 700;
  margin: 0 0 10px;
  letter-spacing: -0.01em;
}
.duty-card p {
  font-size: 14.5px;
  line-height: 1.65;
  color: var(--muted);
  margin: 0;
}

/* Project types */
.project-types {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 760px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 28px;
}
.pt-item {
  display: flex;
  gap: 18px;
  align-items: flex-start;
}
.pt-num {
  flex-shrink: 0;
  width: 32px; height: 32px;
  border-radius: 50%;
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--display);
  font-weight: 700;
  font-size: 14px;
}
.pt-item h4 {
  margin: 4px 0 4px;
  font-family: var(--display);
  font-size: 16px;
  color: var(--ink);
  font-weight: 700;
}
.pt-item p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.55;
}

/* ===== COMPANY STRUCTURE PAGE ===== */
.ceo-card {
  background: var(--ci-navy);
  border-radius: var(--radius-lg);
  padding: 32px 36px;
  color: #F8F9FA;
  text-align: center;
  margin-bottom: 32px;
  position: relative;
  overflow: hidden;
}
.ceo-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 20% 30%, rgba(248,249,250,0.15), transparent 50%),
    radial-gradient(circle at 80% 70%, rgba(248,249,250,0.10), transparent 50%);
  pointer-events: none;
}
.ceo-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
