  display: block;
  margin: 0 auto;
  border-bottom: 1px solid var(--line-soft);
}
.ts-figure figcaption {
  padding: 12px 22px;
  font-size: 13px;
  color: var(--muted);
  background: var(--surface);
  text-align: center;
}

.ts-cols {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-top: 12px;
}
.ts-col {
  display: flex;
  align-items: center;
  gap: 14px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px 18px;
}
.ts-col-num {
  width: 30px; height: 30px;
  border-radius: 50%;
  background: var(--cyan);
  color: #F8F9FA;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--display);
  font-weight: 700;
  font-size: 13px;
  flex-shrink: 0;
}
.ts-col > div { display: flex; flex-direction: column; }
.ts-col strong {
  font-family: var(--display);
  font-size: 14.5px;
  color: var(--ink);
  font-weight: 700;
}
.ts-col span {
  font-size: 12.5px;
  color: var(--muted);
}

/* ===== FAQ SECTIONS ===== */
.faq-section {
  margin-bottom: 40px;
}
.faq-section:last-child { margin-bottom: 0; }
.faq-section-title {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--display);
  font-size: 19px;
  font-weight: 700;
  color: var(--ink);
  margin: 0 0 18px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--cyan);
  letter-spacing: -0.005em;
}
.faq-section-ico {
  display: inline-flex;
  width: 36px; height: 36px;
  border-radius: 10px;
  background: var(--ci-navy);
  color: #F8F9FA;
  align-items: center;
  justify-content: center;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 980px) {
  .hero-inner { grid-template-columns: 1fr; gap: 40px; }
  .hero-visual { min-height: unset; padding: 20px 16px 40px; }
  .hv-float-1 { top: -10px; right: 8px; }
  .hv-float-2 { bottom: -10px; left: 8px; }
  .hero-stat-pills { gap: 6px; }
  .journey { grid-template-columns: repeat(2, 1fr); }
  .journey-step::after { display: none; }
  .content-grid { grid-template-columns: 1fr; }
  .content-sticky { position: static; }
  .footer-inner { grid-template-columns: 1fr 1fr; gap: 32px; }
  .cta-card { flex-direction: column; align-items: flex-start; padding: 40px 30px; }
  .trust-inner { grid-template-columns: repeat(2, 1fr); }
  .trust-item + .trust-item::before { display: none; }

  .story-section { padding: 70px 0; }
  .story-journey { grid-template-columns: repeat(2, 1fr); }
  .story-journey::before { display: none; }
  .values-preview { grid-template-columns: repeat(2, 1fr); }
  .fact-grid { grid-template-columns: repeat(2, 1fr); }
  .duty-grid { grid-template-columns: 1fr; }
  .dept-grid { grid-template-columns: 1fr; }
  .cycle-grid { grid-template-columns: 1fr; }
  .values-grid {
    grid-template-columns: 1fr;
    grid-template-areas: "v1" "v2" "v3" "v4" "v5";
  }
  .wifi-panel-grid { grid-template-columns: 1fr; }
  .wifi-steps { grid-template-columns: 1fr; }
  .org-level-2 { grid-template-columns: repeat(2, 1fr); }
  /* .hours-hero grid override removed — now flex */
  .rule-grid { grid-template-columns: 1fr; }
  .dress-hero { grid-template-columns: 1fr; padding: 30px; }
  .dress-image img { width: 200px; }
  .dress-grid { grid-template-columns: 1fr; }
  .dress-dont { grid-template-columns: repeat(2, 1fr); }
  .ts-cols { grid-template-columns: 1fr; }
  .day-timeline { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .nav-links, .nav-right { display: none; }
  .nav-burger { display: flex; margin-left: auto; }
  .nav-logo { margin-right: 0; }

  /* Mobile drawer: one unified panel beneath the navbar */
  .navbar.mobile-open .nav-links {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 4px;
    position: absolute;
    top: var(--nav-h);
    left: 0; right: 0;
    background: #F8F9FA;
    padding: 14px 16px 18px;
    border-top: 1px solid var(--line-soft);
    box-shadow: 0 12px 28px rgba(0,64,129,0.10);
    z-index: 5;
    max-height: calc(100vh - var(--nav-h));
    overflow-y: auto;
  }
  .navbar.mobile-open .nav-links .nav-promoted-mobile,
  .navbar.mobile-open .nav-links .nav-showcase-mobile {
    margin-top: 8px;
    padding-top: 12px;
    border-top: 1px dashed var(--line);
  }
  .navbar.mobile-open .nav-menu {
    position: static;
    box-shadow: none;
    border: none;
    border-top: 1px solid var(--line-soft);
    border-radius: 0;
    opacity: 1;
    visibility: visible;
    transform: none;
    transition: none;
    display: none;
    padding-left: 14px;
  }
  .navbar.mobile-open .nav-group.open .nav-menu { display: block; }
  .navbar.mobile-open .nav-group { width: 100%; }
  .navbar.mobile-open .nav-item { width: 100%; justify-content: space-between; }

  .section { padding: 60px 0; }
  .hero { padding: 60px 0 70px; }
  .kv-row { grid-template-columns: 1fr; gap: 4px; }
  .footer-inner { grid-template-columns: 1fr; gap: 32px; }
  .trust-inner { grid-template-columns: 1fr 1fr; }
  .timesheet-hero { padding: 30px 24px; }
  .cta-card { padding: 32px 24px; }

  .story-section { padding: 60px 0; }
  .story-journey { grid-template-columns: 1fr; }
  .values-preview { grid-template-columns: 1fr; }
  .fact-grid { grid-template-columns: 1fr; }
  .ceo-card { padding: 28px 24px; }
  .ceo-card h3 { font-size: 24px; }
  .wifi-panel-grid { padding: 22px; gap: 22px; }
  .org-level-2 { grid-template-columns: 1fr; }
  .org-box { min-width: 0; }
  /* old hours-hero mobile overrides removed — handled by new block */
  .dress-dont { grid-template-columns: 1fr; }
  .faq-section-title { font-size: 17px; }
  .org-dept { padding: 18px 16px; }
}

/* About products grid */
.about-products {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 10px;
  margin-top: 20px;
}
.about-product-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 14px;
  color: var(--ink);
  line-height: 1.5;
  padding: 10px 14px;
  background: var(--surface);
  border-radius: 10px;
  border: 1px solid var(--border);
}
.ap-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  min-width: 8px;
  border-radius: 50%;
  background: var(--cyan);
  margin-top: 4px;
}

/* ============================================================
   ORIENTATION — project cards, next-steps, slides embed
   ============================================================ */

/* Project cards */
.proj-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
  margin-top: 20px;
}
.proj-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 22px 20px;
  position: relative;
  overflow: hidden;
  transition: box-shadow .2s, transform .2s;
}
.proj-card:hover { box-shadow: 0 6px 24px rgba(0,17,34,.08); transform: translateY(-2px); }
.proj-num {
  font-size: 36px;
  font-weight: 800;
  line-height: 1;
  color: var(--cyan);
  opacity: .18;
  margin-bottom: 10px;
  font-family: var(--display);
}
.proj-card h4 { margin: 0 0 6px; font-size: 15px; font-weight: 700; color: var(--ink); }
.proj-card p  { margin: 0; font-size: 13.5px; color: var(--muted); line-height: 1.55; }

/* Next-steps grid */
.next-steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 12px;
  margin-top: 20px;
}
.next-step-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  text-decoration: none;
  color: var(--ink);
  transition: border-color .2s, box-shadow .2s, transform .2s;
}
.next-step-card:hover {
  border-color: var(--cyan);
  box-shadow: 0 4px 18px rgba(102,197,197,.15);
  transform: translateY(-2px);
}
.ns-icon { flex-shrink: 0; color: var(--cyan); }
.ns-icon svg { width: 20px; height: 20px; }
.next-step-card h4 { margin: 0 0 2px; font-size: 14px; font-weight: 700; }
.next-step-card p  { margin: 0; font-size: 12.5px; color: var(--muted); line-height: 1.4; }
.ns-arrow { margin-left: auto; flex-shrink: 0; color: var(--muted); opacity: .5; }

/* Slides full embed */
.slides-full-embed {
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  background: var(--surface);
  margin-top: 16px;
}
.slides-embed-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}
.slides-embed-header .slides-icon { color: var(--cyan); flex-shrink: 0; }
.slides-embed-header .slides-title { font-size: 14px; font-weight: 600; color: var(--ink); flex: 1; }
.slides-embed-actions { display: flex; gap: 8px; flex-shrink: 0; }
.btn-sm { padding: 6px 14px; font-size: 12.5px; gap: 5px; }
.slides-embed-body { position: relative; }
.slides-embed-body iframe {
  width: 100%;
  aspect-ratio: 16 / 9;
  border: 0;
  display: block;
  min-height: 420px;
}
.slides-embed-placeholder { position: relative; }
.slides-embed-preview-img { width: 100%; display: block; aspect-ratio: 16/9; object-fit: cover; }
.slides-embed-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0,17,34,.65);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
}
.slides-embed-cta { text-align: center; color: #F8F9FA; padding: 24px; max-width: 380px; }
.slides-embed-cta h4 { margin: 12px 0 8px; font-size: 18px; }
.slides-embed-cta p  { margin: 0; opacity: .75; font-size: 14px; line-height: 1.55; }

/* ============================================================
   UX — inline page-bottom CTAs (used across multiple pages)
   ============================================================ */
.page-cta-strip {
  margin-top: 56px;
  padding: 28px 32px;
  background: linear-gradient(135deg, rgba(102,197,197,.08) 0%, rgba(0,64,129,.06) 100%);
  border: 1px solid rgba(102,197,197,.25);
  border-radius: 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
.page-cta-strip h4 { margin: 0 0 4px; font-size: 16px; font-weight: 700; color: var(--ink); }
.page-cta-strip p  { margin: 0; font-size: 13.5px; color: var(--muted); }
.page-cta-strip .cta-btns { display: flex; gap: 10px; flex-shrink: 0; flex-wrap: wrap; }

@media (max-width: 600px) {
  .proj-cards { grid-template-columns: 1fr; }
  .next-steps-grid { grid-template-columns: 1fr; }
  .slides-embed-header { flex-direction: column; align-items: flex-start; }
  .page-cta-strip { flex-direction: column; text-align: center; }
  .page-cta-strip .cta-btns { justify-content: center; }
}

/* Hero accent word — ensure Thai tone marks render fully */
.hero-accent-word {
  display: inline-block;
  white-space: nowrap;
  padding-top: 8px;
  padding-bottom: 4px;
  overflow: visible;
  line-height: 1.5;
}

/* ============================================================
   HERO — scroll hint + chevron animation
   ============================================================ */
.hero-scroll-hint {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 32px;
  opacity: .55;
  transition: opacity .2s;
}
.hero-scroll-hint:hover { opacity: .85; }
.hero-scroll-label {
  font-size: 12px;
  letter-spacing: .06em;
  color: var(--ink);
}
.hero-scroll-chevron {
  animation: bounce-down 1.6s ease-in-out infinite;
  color: var(--ink);
  display: flex;
}
@keyframes bounce-down {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(5px); }
}

/* ============================================================
   CYCLE GRID — fix bullet alignment
   ============================================================ */
.cycle-list {
  list-style: none;
  padding: 0;
  margin: 12px 0 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cycle-list li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--ink);
}
.cycle-list li::before {
  content: '';
  display: inline-block;
  width: 6px;
  height: 6px;
  min-width: 6px;
  border-radius: 50%;
  background: var(--cyan);
  margin-top: 6px;
}

/* ============================================================
   WIFI — password masking toggle + tab enhancements
   ============================================================ */
.wifi-pass-wrap {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
}
.wifi-pass-val { flex: 1; }
.wifi-pass-toggle {
  background: none;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 8px;
  cursor: pointer;
  color: var(--muted);
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: border-color .2s, color .2s;
  white-space: nowrap;
  flex-shrink: 0;
}
.wifi-pass-toggle:hover { border-color: var(--cyan); color: var(--ink); }

.wifi-tabs {
  display: flex;
  gap: 0;
  background: var(--surface);
  border: 1.5px solid var(--border);
  border-radius: 12px;
  padding: 4px;
  margin-bottom: 28px;
  width: fit-content;
}
.wifi-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  border: none;
  border-radius: 9px;
  background: transparent;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: var(--muted);
  transition: background .2s, color .2s, box-shadow .2s;
}
.wifi-tab .ic { opacity: .5; transition: opacity .2s; }
.wifi-tab.is-active {
  background: var(--ci-navy);
  color: #F8F9FA;
  font-weight: 600;
  box-shadow: 0 2px 10px rgba(0,64,129,.18);
}
.wifi-tab.is-active .ic { opacity: 1; }
.wifi-tab:hover:not(.is-active) { background: var(--border); color: var(--ink); }

/* ============================================================
   PROJ-NUM — make more visible on orientation cards
   ============================================================ */
.proj-num {
  font-size: 30px;
  font-weight: 800;
  line-height: 1.2;
  color: var(--ci-navy);
  opacity: 1;
  margin-bottom: 10px;
  font-family: var(--display);
  display: inline-block;
}

/* Inline text links (underlined, visually distinct) */
.inline-link {
  color: var(--navy);
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-thickness: 1.5px;
  font-weight: 500;
  transition: color .15s;
}
.inline-link:hover { color: var(--cyan); }

/* ============================================================
   INTERNSHIP POLICY — compact hours hero + new timeline
   ============================================================ */
/* ============================================================
   HOURS HERO — redesigned clean white card
   ============================================================ */
.hours-hero {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 32px 36px;
  background: #F8F9FA;
  border: 1.5px solid var(--line);
  border-radius: 20px;
  flex-wrap: wrap;
  position: relative;
  overflow: hidden;
}
.hours-hero::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 5px;
  background: var(--ci-teal);
  border-radius: 999px 0 0 999px;
}
.hours-main {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 180px;
}
.hours-time-badge {
  font-size: clamp(26px, 4vw, 38px);
  font-weight: 800;
  color: var(--ink);
  font-family: var(--display);
  letter-spacing: -0.03em;
  line-height: 1;
}
.hours-subtitle {
  font-size: 12.5px;
  color: var(--muted);
  letter-spacing: .02em;
}
.hours-divider {
  width: 1px;
  height: 52px;
  background: var(--line);
  flex-shrink: 0;
}
.hours-stats {
  display: flex;
  gap: 28px;
  flex-wrap: wrap;
}
.hours-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.hours-stat-num {
  font-size: 28px;
  font-weight: 800;
  color: var(--cyan);
  font-family: var(--display);
  line-height: 1;
}
.hours-stat-label { font-size: 11.5px; color: var(--muted); text-align: center; }
.hours-stat-detail { font-size: 10.5px; color: var(--muted); opacity: .65; }

/* ============================================================
   DAY TIMELINE — proportional linear bar
   ============================================================ */
.day-timeline {
  margin-top: 16px;
}
.day-tl-track {
  display: flex;
  height: 44px;
  border-radius: 12px;
  overflow: hidden;
  position: relative;
}
.day-tl-seg {
  display: flex;
  align-items: flex-end;
  padding: 0 0 6px 10px;
  position: relative;
}
.day-tl-morning {
  background: linear-gradient(135deg, #F8F9FA, #D0D6DF);
}
.day-tl-lunch {
  background: linear-gradient(135deg, #F8F9FA, #D0D6DF);
}
.day-tl-afternoon {
  background: linear-gradient(135deg, #D0D6DF, #D0D6DF);
}
.day-tl-ts {
  font-size: 11px;
  font-weight: 700;
  color: var(--ink);
  font-family: var(--display);
  opacity: .7;
  white-space: nowrap;
}
.day-tl-end {
  position: absolute;
  right: 10px;
  bottom: 6px;
}
.day-tl-labels {
  display: flex;
  margin-top: 8px;
  gap: 2px;
}
.day-tl-lbl {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 0 4px;
}
.day-tl-name {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ink);
}
.day-tl-dur {
  font-size: 11.5px;
  color: var(--muted);
}

@media (max-width: 600px) {
  .day-tl-track { height: 36px; }
  .hours-hero { flex-direction: column; text-align: center; padding: 24px 20px; }
  .hours-divider { width: 60px; height: 1px; }
  .hours-hero::before { width: 100%; height: 4px; bottom: auto; right: 0; border-radius: 20px 20px 0 0; }
}

/* ============================================================
   SHOWCASE NAV — special badge style
   ============================================================ */
.nav-showcase-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 9px 2px 5px;
  background: linear-gradient(90deg, #66C5C5, #586782);
  color: #F8F9FA !important;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: .01em;
}
.nav-showcase-badge svg { width: 12px; height: 12px; }
.nav-showcase .nav-showcase-badge { color: #F8F9FA !important; }

/* PDF inline embed */
.slides-pdf-inline { width: 100%; }
.slides-pdf-frame {
  width: 100%;
  height: 520px;
  border: 0;
  display: block;
}
@media (max-width: 760px) { .slides-pdf-frame { height: 340px; } }

/* Value points — cleaner than pill-tag list */
.value-points {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 9px;
}
.value-points li {
  font-size: 13.5px;
  line-height: 1.55;
  color: #505050;
  padding-left: 14px;
  position: relative;
}
.value-points li::before {
  content: '–';
  position: absolute;
  left: 0;
  color: var(--muted);
}
.value-points li strong { color: var(--ink); }

/* Right nav highlight */
.nav-support-highlight,
.nav-showcase-highlight {
  position: relative;
}
.support-nav-label,
.showcase-nav-label {
  color: var(--ci-teal);
  font-weight: 700;
  letter-spacing: .01em;
}
/* ใหม่ badge removed */

/* ============================================================
   HERO SCROLL HINT — mouse wheel animation (replaces chevron)
   ============================================================ */
.hero-scroll-hint {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  margin-top: 36px;
  cursor: pointer;
  width: fit-content;
  opacity: .45;
  transition: opacity .3s;
  text-decoration: none;
}
.hero-scroll-hint:hover { opacity: .75; }
.hero-scroll-mouse {
  width: 22px;
  height: 34px;
  border: 2px solid currentColor;
  border-radius: 11px;
  position: relative;
  color: var(--ink);
}
.hero-scroll-wheel {
  position: absolute;
  top: 5px;
  left: 50%;
  transform: translateX(-50%);
  width: 3px;
  height: 6px;
  background: var(--ink);
  border-radius: 999px;
  animation: scroll-wheel 1.8s ease-in-out infinite;
}
@keyframes scroll-wheel {
  0%   { transform: translateX(-50%) translateY(0); opacity: 1; }
  60%  { transform: translateX(-50%) translateY(10px); opacity: 0; }
  61%  { transform: translateX(-50%) translateY(0); opacity: 0; }
  100% { transform: translateX(-50%) translateY(0); opacity: 1; }
}
.hero-scroll-label {
  font-size: 10px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--ink);
}

/* ============================================================
   CYCLE LIST — precise bullet alignment
   ============================================================ */
.cycle-list {
  list-style: none;
  padding: 0;
  margin: 14px 0 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.cycle-list li {
  display: grid;
  grid-template-columns: 8px 1fr;
  gap: 10px;
  font-size: 13.5px;
  line-height: 1.55;
  color: var(--ink);
  align-items: start;
}
.cycle-list li::before {
  content: '';
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  margin-top: 7px;
  grid-column: 1;
}

/* ============================================================
   ALSO EXPLORE — chip row at bottom of Orientation page
   ============================================================ */
.also-explore {
  margin-top: 44px;
  padding: 22px 24px;
  background: linear-gradient(135deg, rgba(102,197,197,0.07) 0%, rgba(0,64,129,0.04) 100%);
  border: 1.5px solid rgba(102,197,197,0.3);
  border-radius: var(--radius-lg);
}
.ae-label {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--cyan);
  letter-spacing: 0.01em;
  margin-bottom: 14px;
  display: block;
}
.ae-links {
  display: flex;
  gap: 9px;
  flex-wrap: wrap;
}
.ae-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border: 1.5px solid rgba(102,197,197,0.35);
  border-radius: 999px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--ink);
  text-decoration: none;
  background: #F8F9FA;
  transition: border-color .2s, background .2s, color .2s, box-shadow .2s;
  box-shadow: 0 1px 4px rgba(0,64,129,0.06);
}
.ae-chip svg { width: 14px; height: 14px; opacity: .65; flex-shrink: 0; }
.ae-chip:hover {
  border-color: var(--cyan);
  color: var(--navy);
  background: rgba(102,197,197,.08);
  box-shadow: 0 3px 10px rgba(102,197,197,.2);
}

/* ============================================================
   CYCLE LIST — final override (fix: ::before was position:absolute
   from old block, pulling it out of grid flow so text collapsed to 8px col)
   ============================================================ */
.cycle-list {
  list-style: none;
  padding: 0;
  margin: 14px 0 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cycle-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 13.5px;
  line-height: 1.6;
  color: var(--ink);
  padding-left: 0;
  position: static;
}
.cycle-list li::before {
  content: '';
  display: block;
  width: 6px;
  height: 6px;
  min-width: 6px;
  border-radius: 50%;
  background: var(--cyan);
  margin-top: 7px;
  flex-shrink: 0;
  position: static;
}

/* ============================================================
   MEETING ROOMS PAGE
   ============================================================ */

/* Floor section wrapper */
.floor-section {
  margin-bottom: 44px;
}

/* Floor header: pill + rule line */
.floor-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 22px;
}
.floor-header::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--line);
}
.floor-pill {
  display: inline-flex;
  align-items: center;
  background: var(--ci-navy);
  color: #F8F9FA;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 16px;
  border-radius: 999px;
  flex-shrink: 0;
}

/* Room card grid */
.room-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}

/* Individual room card */
.room-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 26px 24px 22px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.25s ease, transform 0.25s ease;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.room-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}
.room-card-featured {
  border-color: rgba(102,197,197, 0.35);
  background: linear-gradient(160deg, rgba(102,197,197,0.04) 0%, #F8F9FA 60%);
}

/* Room name row */
.room-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}
.room-name-wrap {
  font-family: var(--display);
  font-size: 21px;
  font-weight: 800;
  line-height: 1.25;
  color: var(--ink);
  display: flex;
  align-items: baseline;
  letter-spacing: -0.02em;
}
.room-name-x {
  display: inline-block;
  color: var(--ci-navy);
  -webkit-text-fill-color: transparent;
}
.room-name-rest {
  color: var(--ink);
}

/* Capacity badge */
.room-cap-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  background: var(--surface-2);
  border: 1px solid var(--line-soft);
  border-radius: 999px;
  padding: 4px 12px;
  white-space: nowrap;
  flex-shrink: 0;
}
.room-cap-badge svg { width: 13px; height: 13px; opacity: 0.7; }

/* Status badges */
.room-status-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}
.room-type-badge {
  display: inline-block;
  font-size: 11.5px;
  font-weight: 600;
  padding: 3px 12px;
  border-radius: 999px;
}
.room-type-closed {
  background: rgba(102,197,197, 0.12);
  color: #586782;
  border: 1px solid rgba(102,197,197, 0.3);
}
.room-type-open {
  background: rgba(255,204,0, 0.12);
  color: #707070;
  border: 1px solid rgba(255,204,0, 0.3);
}

/* Short description */
.room-desc {
  font-size: 13.5px;
  line-height: 1.6;
  color: var(--muted);
  margin: 0 0 14px;
}

/* Usage chips */
.room-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: auto;
}
.room-tag {
  display: inline-block;
  font-size: 12px;
  font-weight: 500;
  color: var(--ink);
  background: var(--surface-2);
  border: 1px solid var(--line-soft);
  border-radius: 999px;
  padding: 3px 11px;
}

/* ---- Booking methods grid ---- */
.booking-methods {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  margin-top: 8px;
}
.booking-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 28px 22px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0;
  transition: box-shadow 0.25s ease, transform 0.25s ease, border-color 0.25s ease;
}
.booking-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
  border-color: rgba(102,197,197, 0.4);
}
.booking-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 16px;
  background: var(--ci-navy);
  color: #F8F9FA;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  flex-shrink: 0;
}
.booking-card h4 {
  font-family: var(--display);
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
  margin: 0 0 8px;
  letter-spacing: -0.01em;
}
.booking-hint {
  font-size: 13px;
  line-height: 1.6;
  color: var(--muted);
  margin: 0;
}
.booking-card p { margin: 0 0 4px; font-size: 13px; color: var(--muted); }
.booking-card p:last-child { margin: 0; }

/* Responsive */
@media (max-width: 860px) {
  .booking-methods { grid-template-columns: 1fr; gap: 12px; }
  .booking-card { flex-direction: row; align-items: flex-start; text-align: left; gap: 16px; padding: 20px 20px; }
  .booking-card-icon { width: 44px; height: 44px; border-radius: 12px; margin-bottom: 0; flex-shrink: 0; }
}
@media (max-width: 600px) {
  .room-grid { grid-template-columns: 1fr; }
}

/* ===== HOMEPAGE REDESIGN v2 — PRIORITY-FIRST ===== */

/* --- Hero compact variant --- */
.hero {
  min-height: calc(100vh - var(--nav-h));
  padding: 0;
  display: flex;
  align-items: center;
  position: relative;
}
.hero .hero-shape {
  position: absolute;
  pointer-events: none;
  will-change: transform, opacity;
  opacity: 0.9;
}
.hero .hero-shape.shape-a { width: 360px; height: 360px; right: -80px; top: 6%; background: radial-gradient(circle at 30% 30%, rgba(102,197,197,0.18), transparent 30%); border-radius: 48%; filter: blur(28px); transform: translateZ(0); }
.hero .hero-shape.shape-b { width: 220px; height: 220px; left: -40px; bottom: 6%; background: radial-gradient(circle at 60% 40%, rgba(88,103,130,0.12), transparent 30%); border-radius: 48%; filter: blur(24px); }
.hero .hero-shape.shape-c { width: 120px; height: 120px; left: 8%; top: 20%; background: radial-gradient(circle at 40% 40%, rgba(255,204,0,0.14), transparent 30%); border-radius: 999px; }
.hero-compact { padding: 0; }
.hero-compact-inner {
  max-width: 920px;
  margin: 0 auto;
  padding: 100px 28px 94px;
  display: grid;
  align-items: center;
  min-height: calc(100vh - var(--nav-h));
}
.hero-compact-inner h1 { font-size: clamp(34px, 5vw, 56px); }
.hero-compact .hero-ctas { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 28px; }
.hero-compact .btn-hero { min-width: 210px; }
.hero-feature-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
.hero-feature-pill { padding: 12px 16px; font-size: 13px; }

/* Hero micro-animations */
.btn-hero { animation: btn-pulse 3.6s ease-in-out infinite; }
@keyframes btn-pulse { 0% { box-shadow: 0 6px 20px rgba(0,64,129,0.06); } 50% { box-shadow: 0 16px 40px rgba(0,64,129,0.09); transform: translateY(-2px); } 100% { box-shadow: 0 6px 20px rgba(0,64,129,0.06); } }

/* hb-link tilt interaction (JS controlled but provide smooth backface) */
.hb-link { transform-style: preserve-3d; transition: transform .18s ease, box-shadow .18s ease; }
.hb-link:hover { box-shadow: 0 18px 40px rgba(0,64,129,0.06); }

/* make hover lift clearer */
.hb-link:hover { transform: translateY(-8px); }

/* ensure anim classes are smooth and visible */
.fade-up, .anim-up, .anim-down, .anim-left, .anim-right, .anim-scale { backface-visibility: hidden; }

/* Ripple for CTA */
.btn-ripple {
  position: absolute;
  width: 12px; height: 12px;
  background: rgba(248,249,250,0.45);
  border-radius: 999px;
  transform: translate(-50%, -50%) scale(0);
  animation: ripple-anim 0.7s ease-out forwards;
  pointer-events: none;
}
@keyframes ripple-anim { to { transform: translate(-50%, -50%) scale(14); opacity: 0; } }

/* cursor follower removed per user preference */

/* --- Priority Section --- */
.priority-section {
  background: var(--surface);
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
  padding: 72px 0 80px;
}
.priority-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 28px;
}
.priority-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 36px;
}
.priority-overline {
  display: inline-block;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 8px;
}
.priority-title {
  font-family: var(--display);
  font-size: clamp(22px, 2.8vw, 32px);
  font-weight: 800;
  letter-spacing: -0.02em;
