  line-height: 1.2;
}

/* --- Priority Cards Grid --- */
.priority-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}

/* --- Individual Priority Card --- */
.ptask-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 32px 30px 28px;
