}

.ptask-card-top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 22px;
}
.ptask-num-badge {
  font-family: var(--display);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.10em;
  color: var(--muted);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 3px 9px;
}
.ptask-state-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  padding: 4px 11px;
