}
.ptask-state-waiting {
  background: rgba(255,204,0,0.12);
  color: #707070;
  border: 1px solid rgba(255,204,0,0.35);
}
.ptask-state-action {
  background: rgba(102,197,197,0.13);
  color: #586782;
  border: 1px solid rgba(102,197,197,0.35);
}

.ptask-icon-wrap {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  flex-shrink: 0;
}
.ptask-icon-amber {
  background: rgba(255,204,0,0.13);
