}

.ptask-title {
  font-family: var(--display);
  font-size: 20px;
  font-weight: 700;
  color: #001122;
  margin: 0 0 12px;
  letter-spacing: -0.015em;
  line-height: 1.3;
}
.ptask-desc {
  font-size: 14px;
  color: #505050;
  line-height: 1.75;
  margin: 0 0 24px;
}

/* --- Calendar Invite Flow --- */
.cal-flow {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--surface);
  border: 1px solid var(--line-soft);
  border-radius: var(--radius);
  padding: 18px 16px;
  margin-bottom: 16px;
}
.ptask-action-box {
  height: 154px;
  min-height: 154px;
  flex-shrink: 0;
}
.cal-flow-step {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
