/* --- Timesheet info row --- */
.ptask-info-row {
  flex: 1;
  display: flex;
  align-items: stretch;
  gap: 0;
  background: var(--surface);
  border: 1px solid var(--line-soft);
  border-radius: var(--radius);
  margin-bottom: 22px;
  overflow: hidden;
  min-height: 154px;
}
.ptask-info-item {
