  grid-template-columns: 52px 1fr;
  gap: 0 20px;
  padding: 24px 22px 22px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 24px;
  box-shadow: var(--shadow-sm);
}
.day1-step-last { padding-bottom: 22px; }

/* Left aside: number + connecting line */
.day1-step-aside {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}
.day1-step-num {
  width: 40px; height: 40px;
  border-radius: 12px;
  background: var(--surface-2);
  border: 1.5px solid var(--line);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--display);
  font-size: 13px; font-weight: 800;
  color: var(--muted);
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}
.day1-step-num-accent {
  background: var(--ci-navy);
  color: #F8F9FA;
  border-color: transparent;
  box-shadow: 0 4px 14px rgba(0,64,129,0.18);
}
.day1-step-line {
  flex: 1;
  width: 2px;
  background: linear-gradient(to bottom, var(--line), rgba(248,249,250,0.4));
  margin: 8px auto 0;
}

/* Right body */
.day1-step-body { padding-top: 4px; }
.day1-step-time {
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 10px;
}
.day1-step-icon-wrap {
  width: 42px; height: 42px;
  border-radius: 14px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 12px;
}
.day1-icon-cyan  { background: rgba(102,197,197,0.13); color: #586782; }
.day1-icon-amber { background: rgba(255,204,0,0.12);  color: #707070; }
.day1-icon-navy  { background: rgba(0,64,129,0.09);    color: var(--navy); }
.day1-icon-accent{ background: var(--ci-navy); color: #F8F9FA; box-shadow: 0 4px 14px rgba(0,64,129,0.18); }

.day1-step-title {
  font-family: var(--display);
  font-size: 18px; font-weight: 700;
  letter-spacing: -0.015em;
  color: #001122;
  margin: 0 0 10px;
}
.day1-step-desc {
  font-size: 14px; color: #505050;
  line-height: 1.75; margin: 0 0 14px;
}
.day1-step-tags {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin-bottom: 14px;
}
.day1-tag {
  font-size: 12px; font-weight: 600;
  color: var(--muted);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 5px 12px;
}
.day1-tag-accent {
  background: rgba(0,64,129,0.08);
  color: var(--ink);
  border-color: rgba(0,64,129,0.18);
}
.day1-step-link {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 13.5px; font-weight: 600;
  color: var(--ink); text-decoration: none;
  transition: gap 0.18s ease;
}
.day1-step-link:hover { gap: 11px; }

/* Responsive */
@media (max-width: 900px) {
  .day1-step { gap: 0 16px; padding: 20px 18px 18px; }
}
@media (max-width: 600px) {
  .day1-section { padding: 48px 0 56px; }
  .day1-header { margin-bottom: 32px; }
  .day1-step { grid-template-columns: 36px 1fr; gap: 0 14px; padding: 18px 16px 16px; }
  .day1-step-num { width: 34px; height: 34px; font-size: 11px; border-radius: 9px; }
  .day1-step-icon-wrap { width: 38px; height: 38px; }
  .day1-step-title { font-size: 16px; }
}

/* ===== ANIMATION ENHANCEMENTS & MICRO-INTERACTIONS ===== */

/* Page header entrance — stagger crumb → h1 → lead */
.page-header .crumb.anim-up        { transition-delay: 0ms; }
.page-header h1.anim-up            { transition-delay: 70ms; }
.page-header .page-lead.anim-up    { transition-delay: 140ms; }

/* Inner-page content — stagger callouts and step cards */
.prose .callout.anim-up           { transition-duration: 0.5s; }
.prose .howto-step.anim-up        { transition-duration: 0.55s; }
.prose .proj-card.anim-up         { transition-duration: 0.5s; }
.prose .ts-col.anim-up            { transition-duration: 0.45s; }

/* Hover lift on interactive cards */
.card.is-link,
.ptask-card,
.info-chip,
.room-card,
.team-card,
.booking-card {
  transition: box-shadow 0.22s ease, transform 0.22s ease;
}
.card.is-link:hover,
.team-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

/* Day 1 step — slide line draw animation */
.day1-step-line {
  transform-origin: top;
  transform: scaleY(0);
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}
.day1-step.is-visible .day1-step-line {
  transform: scaleY(1);
}

/* Day 1 step number pop */
.day1-step-num {
  transition: background 0.35s ease, color 0.35s ease, box-shadow 0.35s ease;
}
.day1-step.is-visible .day1-step-num {
  background: rgba(102,197,197,0.14);
  color: #586782;
  border-color: rgba(102,197,197,0.35);
}
.day1-step.is-visible .day1-step-num-accent {
  background: var(--ci-navy);
  color: #F8F9FA;
  border-color: transparent;
}

/* Priority card accent-line grow */
.ptask-card::before {
  transform-origin: left;
  transform: scaleX(0);
  transition: transform 0.55s cubic-bezier(0.16, 1, 0.3, 1);
}
.ptask-card.is-visible::before {
  transform: scaleX(1);
}

/* Cal-flow steps stagger */
.cal-flow-step {
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.4s ease, transform 0.4s ease;
}
.ptask-card.is-visible .cal-flow-step:nth-child(1) { opacity: 1; transform: none; transition-delay: 300ms; }
.ptask-card.is-visible .cal-flow-step:nth-child(3) { opacity: 1; transform: none; transition-delay: 480ms; }
.ptask-card.is-visible .cal-flow-step:nth-child(5) { opacity: 1; transform: none; transition-delay: 650ms; }
.ptask-card.is-visible .cal-flow-arrow             { opacity: 1; transition-delay: 390ms; }
.cal-flow-arrow { opacity: 0; transition: opacity 0.3s ease; }

/* Info-chip hover */
.info-chip {
  transition: border-color 0.18s, box-shadow 0.18s, transform 0.18s;
}
.info-chip:hover {
  border-color: rgba(102,197,197,0.4);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

/* Handbook card-grid stagger (qCard) */
.card-grid .card.fade-up:nth-child(1) { --d: 0ms; }
.card-grid .card.fade-up:nth-child(2) { --d: 70ms; }
.card-grid .card.fade-up:nth-child(3) { --d: 140ms; }
.card-grid .card.fade-up:nth-child(4) { --d: 210ms; }
.card-grid .card.fade-up:nth-child(5) { --d: 70ms; }
.card-grid .card.fade-up:nth-child(6) { --d: 140ms; }
.card-grid .card.fade-up:nth-child(7) { --d: 210ms; }
.card-grid .card.fade-up:nth-child(8) { --d: 280ms; }
.card-grid .card.fade-up { transition-delay: var(--d, 0ms); }

/* Smooth link arrow nudge on hover */
.day1-step-link svg,
.card-link svg,
.htask-action-btn svg,
.ptask-cta svg {
  transition: transform 0.18s ease;
  display: inline-block;
}
.day1-step-link:hover svg,
.card.is-link:hover .card-link svg,
.htask-action-btn:hover svg,
.ptask-cta:hover svg {
  transform: translateX(4px);
}

/* Button pulse on primary CTA */
.btn-primary {
  position: relative;
  overflow: hidden;
}
.btn-primary::after {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(248,249,250,0.12);
  opacity: 0;
  transition: opacity 0.2s;
}
.btn-primary:hover::after { opacity: 1; }
.btn-primary:active::after { opacity: 0.25; }

/* Reduce motion for accessibility */
@media (prefers-reduced-motion: reduce) {
  .fade-up, .anim-up, .anim-left, .anim-right, .anim-scale {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
  .day1-step-line { transform: scaleY(1) !important; }
  .ptask-card::before { transform: scaleX(1) !important; }
  .cal-flow-step, .cal-flow-arrow { opacity: 1 !important; transform: none !important; }
}

/* ============================================================
   HERO HOME v3 — 2-column with animated visual
   ============================================================ */
.hero-home {
