  overflow: hidden;
}
.hero-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0;
  animation: orbFloat 8s ease-in-out infinite;
}
.hero-orb-1 {
  width: 440px; height: 440px;
  background: radial-gradient(circle, rgba(102,197,197,0.22), transparent 70%);
  top: -10%; left: -8%;
