  z-index: 1;
  width: 100%;
}

/* Left text */
.hero-home-left { }
.hero-cta-wrap {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 32px;
}

/* Primary hero CTA — shiny gradient button */
.btn-cta-hero {
  position: relative;
  overflow: hidden;
  background: var(--grad);
  color: #F8F9FA;
  padding: 16px 32px;
  border-radius: 16px;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.01em;
  gap: 10px;
  box-shadow: 0 8px 28px rgba(0,64,129,0.26), 0 2px 8px rgba(0,64,129,0.14), inset 0 1px 0 rgba(248,249,250,0.18);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  border: none;
}
.btn-cta-hero:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 36px rgba(0,64,129,0.32), 0 4px 12px rgba(0,64,129,0.16), inset 0 1px 0 rgba(248,249,250,0.2);
}
.btn-cta-hero:active { transform: translateY(-1px); }
.btn-cta-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px; height: 26px;
  background: rgba(248,249,250,0.22);
  border-radius: 8px;
  flex-shrink: 0;
  transition: background 0.2s;
}
.btn-cta-hero:hover .btn-cta-icon { background: rgba(248,249,250,0.30); }
.btn-shine {
  position: absolute;
  top: 0; left: 0;
  width: 55%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(248,249,250,0.22), transparent);
  transform: translateX(-160%) skewX(-18deg);
