/* Rewritten: was animating `left` (layout) — now uses transform (composited) */
@keyframes btnShine {
  0%   { transform: translateX(-160%) skewX(-18deg); }
  40%  { transform: translateX(280%)  skewX(-18deg); }
  100% { transform: translateX(280%)  skewX(-18deg); }
}
.btn-cta-hero .arrow { transition: transform 0.2s ease; }
.btn-cta-hero:hover .arrow { transform: translateX(4px); }

/* Ghost btn v2 */
