/* ============================================================
   INTERACTIVE DAY 1 TIMELINE
   ============================================================ */
.d1-scroll-story {
  --d1-progress: 0;
  --d1-step-count: 4;
  position: relative;
  min-height: calc(var(--d1-step-count) * 72vh);
}
.d1-sticky-shell {
  position: sticky;
  top: calc(var(--nav-h) + 108px);
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 44px;
  align-items: start;
  min-height: calc(100vh - var(--nav-h) - 124px);
  z-index: 2;
}
.d1-scroll-track {
  position: relative;
  z-index: 1;
}
.d1-scroll-slice {
  height: 70vh;
  pointer-events: none;
}

.d1-wheel-col {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.d1-wheel-wrap {
  display: flex;
  justify-content: center;
}
.d1-wheel {
  width: 208px;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  position: relative;
  background:
    radial-gradient(circle at center, #F8F9FA 42%, transparent 43%),
    conic-gradient(from -90deg, var(--cyan) calc(var(--d1-progress) * 1turn), rgba(0,64,129,0.12) 0);
  border: 1px solid var(--line);
  box-shadow: 0 14px 30px rgba(0,64,129,0.11);
}
.d1-wheel::before {
  content: "";
  position: absolute;
  inset: 15px;
  border: 1px dashed rgba(0,64,129,0.18);
  border-radius: 50%;
}
.d1-wheel-core {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  z-index: 2;
}
.d1-wheel-core-step {
  font-family: var(--display);
  font-size: 30px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -0.02em;
  line-height: 1;
}
.d1-wheel-core-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--muted);
}
.d1-wheel-dot {
  position: absolute;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid var(--line);
  background: #F8F9FA;
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
  transform: translate(-50%, -50%);
  transition: transform 0.22s ease, color 0.22s ease, border-color 0.22s ease, background 0.22s ease;
  z-index: 3;
}
.d1-wheel-dot.is-active {
  color: #F8F9FA;
  background: var(--navy);
  border-color: var(--navy);
  transform: translate(-50%, -50%) scale(1.08);
}
.d1-wheel-dot.is-done {
  color: #586782;
  background: rgba(102,197,197,0.16);
  border-color: rgba(102,197,197,0.55);
}
.d1-wheel-dot-1 { left: 50%; top: 8%; }
.d1-wheel-dot-2 { left: 92%; top: 50%; }
.d1-wheel-dot-3 { left: 50%; top: 92%; }
.d1-wheel-dot-4 { left: 8%; top: 50%; }

.d1-step-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.d1-step-btn {
  border: 1px solid var(--line);
  background: #F8F9FA;
  border-radius: 12px;
  padding: 11px 13px;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 2px;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.d1-step-btn:hover {
  border-color: rgba(102,197,197,0.45);
}
.d1-step-btn.is-active {
  border-color: rgba(102,197,197,0.55);
  background: rgba(102,197,197,0.08);
}
.d1-step-btn.is-done .d1-btn-name {
  color: #586782;
}
.d1-btn-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}
.d1-btn-name {
  font-size: 14px;
  font-weight: 700;
  color: #001122;
}
.d1-scroll-note {
  margin: 0;
  font-size: 12.5px;
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.d1-panels-col {
  position: relative;
  min-height: 520px;
}
.d1-panel {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transform: translateX(42px);
  transition: opacity 0.42s ease, transform 0.46s cubic-bezier(0.22, 1, 0.36, 1);
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 34px 34px 30px;
  box-shadow: 0 10px 30px rgba(0,64,129,0.08);
}
.d1-panel.is-before { transform: translateX(-34px); }
.d1-panel.is-after  { transform: translateX(42px); }
.d1-panel.is-active {
  position: relative;
  opacity: 1;
  transform: translateX(0);
  pointer-events: auto;
}

.d1-panel-icon {
  width: 52px; height: 52px;
  border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 18px;
}
.d1-icon-cyan  { background: rgba(102,197,197,0.13); color: #586782; }
.d1-icon-amber { background: rgba(255,204,0,0.12); color: #707070; }
.d1-icon-navy  { background: rgba(0,64,129,0.10); color: var(--navy); }
.d1-icon-accent{ background: var(--ci-navy); color: #F8F9FA; box-shadow: 0 4px 16px rgba(0,64,129,0.22); }

.d1-panel-eyebrow {
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 8px;
}
.d1-panel-title {
  font-family: var(--display);
  font-size: 26px;
  font-weight: 800;
  color: #001122;
  letter-spacing: -0.02em;
  margin: 0 0 14px;
  line-height: 1.3;
}
.d1-panel-desc {
  font-size: 15px;
  line-height: 1.8;
  color: #505050;
  margin: 0 0 20px;
}

.d1-panel-facts {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  margin-bottom: 20px;
  padding: 16px 20px;
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--line-soft);
}
.d1-fact {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.d1-fact-k {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.d1-fact-v {
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
}
.d1-panel-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}
.d1-panel-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  color: var(--ink);
  text-decoration: none;
  padding: 10px 18px;
  background: var(--surface);
  border: 1.5px solid var(--line);
  border-radius: 999px;
  transition: border-color 0.2s, background 0.2s, gap 0.2s;
}
.d1-panel-link:hover {
  border-color: var(--cyan);
  background: rgba(102,197,197,0.08);
  gap: 12px;
}

@media (max-width: 980px) {
  .day1-header {
    position: static;
    margin-bottom: 18px;
    gap: 8px;
  }
  .day1-header-stick {
    position: static;
    margin: 0;
    padding: 0;
    background: transparent;
    backdrop-filter: none;
    border-radius: 0;
  }
  .day1-header-lead {
    margin-bottom: 10px;
  }
  .d1-sticky-shell {
    grid-template-columns: 1fr;
    gap: 20px;
    position: static;
    min-height: 0;
  }
  .d1-scroll-story {
    min-height: 0;
  }
  .d1-scroll-track {
    display: none;
  }
  .d1-wheel-wrap {
    justify-content: flex-start;
  }
  .d1-wheel {
    width: 162px;
  }
  .d1-panels-col {
    min-height: 0;
  }
  .d1-panel {
    position: static;
    opacity: 1;
    transform: none;
    pointer-events: auto;
    display: none;
    padding: 24px;
  }
  .d1-panel.is-active {
    display: block;
  }
  .d1-panel-title {
    font-size: 22px;
  }
}

/* Final task-card fit: keep emoji flow readable on desktop */
.ex-day-tasks .ex-task-stage {
  max-width: 1080px !important;
  grid-template-columns: 1fr !important;
}

.ex-day-tasks .ex-task-slip {
  grid-template-columns: minmax(170px, .26fr) minmax(0, 1fr) !important;
  min-height: 300px !important;
}

.ex-day-tasks .ex-task-visual svg {
  max-width: 210px !important;
}

.ex-day-tasks .ex-mini-flow-emoji {
  grid-template-columns: minmax(130px, 1fr) auto minmax(130px, 1fr) auto minmax(130px, 1fr) !important;
}

@media (max-width: 760px) {
  .ex-day-tasks .ex-task-slip {
    grid-template-columns: 1fr !important;
  }

  .ex-day-tasks .ex-mini-flow-emoji {
    grid-template-columns: 1fr !important;
  }
}
@media (max-width: 600px) {
  .d1-wheel-col {
    gap: 14px;
  }
  .d1-wheel {
    width: 142px;
  }
  .d1-wheel-dot {
    width: 30px;
    height: 30px;
    font-size: 10px;
  }
  .d1-step-list {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }
  .d1-step-btn {
    min-height: 72px;
  }
  .d1-btn-label {
    font-size: 9px;
  }
}

/* ============================================================
   HB-EXPLORE (replaces hb-discover)
   ============================================================ */
.hb-explore {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-top: 24px;
  margin-bottom: 20px;
}
.hb-explore-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #001122 0%, #001122 45%, #004081 100%);
}
.hbe-orb {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}
.hbe-orb-1 {
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(102,197,197,0.18), transparent 70%);
  top: -100px; right: -80px;
  filter: blur(40px);
}
.hbe-orb-2 {
  width: 280px; height: 280px;
  background: radial-gradient(circle, rgba(0,64,129,0.3), transparent 70%);
  bottom: -60px; left: 10%;
  filter: blur(36px);
}
.hbe-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(248,249,250,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(248,249,250,0.04) 1px, transparent 1px);
  background-size: 48px 48px;
}
.hb-explore-content {
  position: relative;
  z-index: 1;
  padding: 44px 44px 40px;
}
.hbe-head {
  margin-bottom: 32px;
}
.hbe-eyebrow {
  display: inline-block;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 10px;
}
.hbe-title {
  font-family: var(--display);
  font-size: clamp(22px, 2.8vw, 32px);
  font-weight: 800;
  color: #F8F9FA;
  letter-spacing: -0.02em;
  margin: 0 0 10px;
}
.hbe-sub {
  font-size: 14.5px;
  color: rgba(248,249,250,0.62);
  margin: 0;
  line-height: 1.6;
}
.hbe-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.hbe-card {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(248,249,250,0.07);
  border: 1px solid rgba(248,249,250,0.12);
  border-radius: var(--radius);
  padding: 16px 18px;
  text-decoration: none;
  transition: background 0.2s, border-color 0.2s, transform 0.2s;
}
.hbe-card:hover {
  background: rgba(248,249,250,0.13);
  border-color: rgba(102,197,197,0.4);
  transform: translateY(-3px);
}
.hbe-card-icon {
  width: 36px; height: 36px;
  border-radius: 10px;
  background: rgba(102,197,197,0.18);
  color: var(--cyan);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.hbe-card-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.hbe-card-title {
  font-size: 13.5px;
  font-weight: 700;
  color: #F8F9FA;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hbe-card-sub {
  font-size: 11.5px;
  color: rgba(248,249,250,0.5);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hbe-card-arr {
  color: rgba(248,249,250,0.4);
  flex-shrink: 0;
  transition: transform 0.2s, color 0.2s;
}
.hbe-card:hover .hbe-card-arr { color: var(--cyan); transform: translateX(3px); }

@media (max-width: 900px) {
  .hbe-cards { grid-template-columns: repeat(2, 1fr); }
  .hb-explore-content { padding: 32px 28px; }
}
@media (max-width: 560px) {
  .hbe-cards { grid-template-columns: 1fr; gap: 8px; }
  .hb-explore-content { padding: 24px 20px; }
  .hbe-title { font-size: 20px; }
}

/* ============================================================
   GLOBAL BACKGROUND MOTION — floating dots on dark sections
   ============================================================ */
@keyframes floatDot {
  0%, 100% { transform: translateY(0) rotate(0deg); opacity: 0.5; }
  50%       { transform: translateY(-20px) rotate(180deg); opacity: 0.9; }
}

/* Enhanced button entrance animations */
.btn-primary, .btn-ghost, .btn-ghost-2, .btn-cta-hero {
  position: relative;
}

/* Smooth page section transitions */
.hero-home, .priority-section, .day1-section, .hb-section {
  transition: background 0.3s ease;
}

/* ============================================================
   REDUCED MOTION — ensure accessibility for new elements
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  .hero-orb, .heroCardFloat, .heroCardFloat *, .hero-tasks-card,
  .hero-float-pill, .btn-shine, .htc-footer-arr,
  .d1-wheel, .d1-wheel-dot, .d1-panel, .hbe-orb-1, .hbe-orb-2,
  .hero-word, .hero-p, .hero-mesh {
    animation: none !important;
    transition: none !important;
  }
  .hero-word { opacity: 1 !important; transform: none !important; }
  .d1-panel { transform: none !important; }
}

/* ============================================================
   MEETING ROOMS v2
   ============================================================ */
.mr-overview {
  display: flex;
  align-items: center;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 24px 36px;
  margin-bottom: 40px;
  box-shadow: 0 2px 12px rgba(0,64,129,0.06);
}
.mr-ov-item {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 14px;
}
.mr-ov-icon-wrap {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: var(--grad-soft);
  color: var(--cyan);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.mr-ov-num {
  display: block;
  font-family: var(--display);
  font-size: 30px; font-weight: 800;
  color: var(--ink); line-height: 1;
  letter-spacing: -0.03em;
}
.mr-ov-lbl {
  display: block;
  font-size: 12px; color: var(--muted);
  margin-top: 3px; font-weight: 500;
}
.mr-ov-sep {
  width: 1px; height: 44px;
  background: var(--line);
  margin: 0 28px;
  flex-shrink: 0;
}
.mr-floor-sec { margin-bottom: 40px; }
.mr-floor-hd {
  display: flex; align-items: center;
  gap: 12px; margin-bottom: 20px;
}
.mr-floor-pill {
  display: inline-flex; align-items: center;
  font-family: var(--display);
  font-size: 13px; font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--ink);
  background: var(--grad-soft);
  padding: 5px 16px; border-radius: 999px;
  border: 1px solid rgba(102,197,197,0.3);
  white-space: nowrap;
}
.mr-floor-line {
  flex: 1; height: 1px;
  background: linear-gradient(90deg, var(--line) 0%, transparent 100%);
}
.mr-floor-count {
  font-size: 12.5px; color: var(--muted);
  font-weight: 500; white-space: nowrap;
}

/* Featured room card */
.mr-feat-card {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 36px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 36px;
  box-shadow: 0 4px 20px rgba(0,64,129,0.07);
  transition: box-shadow .25s ease;
}
.mr-feat-card:hover { box-shadow: 0 8px 32px rgba(0,64,129,0.12); }
.mr-feat-vis {
  position: relative;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  background: linear-gradient(135deg,#F8F9FA 0%,#F8F9FA 100%);
  border-radius: var(--radius);
  padding: 24px 16px 16px;
  gap: 12px; overflow: hidden;
}
.mr-room-plan { width: 100%; max-width: 260px; display: block; }
.mr-vis-cap {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 13px; font-weight: 600; color: var(--ink);
  background: #F8F9FA; border: 1px solid var(--line);
  border-radius: 999px; padding: 5px 14px;
}
.mr-vis-cap svg { opacity: 0.55; }
.mr-feat-info {
  display: flex; flex-direction: column;
  gap: 14px; justify-content: center;
}
.mr-feat-title-row {
  display: flex; align-items: center;
  gap: 12px; flex-wrap: wrap;
}
.mr-feat-name {
  font-family: var(--display);
  font-size: 30px; font-weight: 800;
  color: var(--ink); letter-spacing: -0.025em; line-height: 1.1;
}
.mr-x-accent { color: var(--cyan); font-style: italic; }
.mr-room-badge {
  display: inline-flex; align-items: center;
  font-size: 12px; font-weight: 600;
  padding: 4px 12px; border-radius: 999px;
}
.mr-room-closed {
  background: rgba(0,64,129,0.07); color: var(--navy);
  border: 1px solid rgba(0,64,129,0.15);
}
.mr-room-open {
  background: rgba(102,197,197,0.12); color: #004081;
  border: 1px solid rgba(102,197,197,0.3);
}
.mr-feat-desc {
  font-size: 15px; line-height: 1.7;
  color: var(--muted); margin: 0;
}
.mr-feat-meta {
  display: flex; flex-direction: column; gap: 10px;
  background: var(--surface); border-radius: var(--radius);
  padding: 16px 20px;
}
.mr-meta-row {
  display: flex; align-items: center; gap: 14px;
}
.mr-meta-lbl {
  font-size: 11.5px; font-weight: 700; color: var(--muted);
  text-transform: uppercase; letter-spacing: 0.06em;
  min-width: 60px; flex-shrink: 0;
}
.mr-cap-dots { display: flex; align-items: center; gap: 4px; }
.mr-cap-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: rgba(0,64,129,0.1); border: 1.5px solid rgba(0,64,129,0.12);
}
.mr-cap-dot.active { background: var(--cyan); border-color: var(--cyan); }
.mr-cap-txt {
  font-size: 13px; font-weight: 600; color: var(--ink); margin-left: 8px;
}
.mr-feat-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.mr-use-tag {
  font-size: 12px; font-weight: 500; color: var(--ink);
  background: var(--grad-soft); padding: 3px 11px;
  border-radius: 999px; border: 1px solid rgba(102,197,197,0.25);
}

/* 3-column room grid */
.mr-rooms-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}
.mr-room-card {
  background: #F8F9FA; border: 1px solid var(--line);
  border-radius: var(--radius-lg); overflow: hidden;
  transition: transform .2s ease, box-shadow .2s ease;
}
.mr-room-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(0,64,129,0.1);
}
.mr-room-plan-sm {
  background: linear-gradient(135deg,#F8F9FA 0%,#F8F9FA 100%);
  padding: 18px 14px 10px;
  display: flex; align-items: center; justify-content: center;
}
.mr-room-plan-sm svg { width: 100%; max-width: 200px; display: block; }
.mr-room-body {
  padding: 18px 20px;
  display: flex; flex-direction: column; gap: 7px;
}
.mr-room-hdr {
  display: flex; align-items: center;
  gap: 8px; flex-wrap: wrap;
}
.mr-room-nm {
  font-family: var(--display);
  font-size: 17px; font-weight: 800;
  color: var(--ink); line-height: 1.2;
}
.mr-x-sm { color: var(--cyan); font-style: italic; }
.mr-room-cap {
  display: flex; align-items: center; gap: 6px;
  font-size: 13px; color: var(--muted); font-weight: 500;
}
.mr-room-cap svg { opacity: 0.5; }
.mr-room-desc {
  font-size: 13px; line-height: 1.65;
  color: var(--muted); margin: 0;
}
.mr-room-tags {
  display: flex; flex-wrap: wrap; gap: 5px; margin-top: 4px;
}
.mr-room-tags span {
  font-size: 11.5px; font-weight: 500; color: var(--ink);
  background: var(--surface); padding: 3px 9px;
  border-radius: 999px; border: 1px solid var(--line);
}

/* Booking section */
.mr-book-section { margin-top: 48px; }
.mr-book-section h2 { margin-top: 0; }
.mr-book-lead {
  font-size: 15px; color: var(--muted);
  margin: -8px 0 24px; line-height: 1.6;
}
.mr-book-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px;
}
.mr-book-card {
  background: #F8F9FA; border: 1px solid var(--line);
  border-radius: var(--radius-lg); padding: 28px 24px;
  display: flex; flex-direction: column; gap: 8px;
  transition: transform .2s ease, box-shadow .2s ease;
}
.mr-book-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(0,64,129,0.09);
}
.mr-book-num {
  font-size: 11px; font-weight: 700;
  letter-spacing: 0.1em; color: var(--cyan);
  text-transform: uppercase;
}
.mr-book-icon {
  width: 50px; height: 50px; border-radius: var(--radius);
  background: var(--grad-soft); color: var(--cyan);
  display: flex; align-items: center; justify-content: center;
  margin: 4px 0 6px;
}
.mr-book-card h4 {
  font-family: var(--display); font-size: 17px;
  font-weight: 700; color: var(--ink); margin: 0;
}
.mr-book-card p { font-size: 13.5px; line-height: 1.65; color: var(--muted); margin: 0; }
.mr-book-hint { font-size: 13px !important; }

/* ============================================================
   ORG CHART v3
   ============================================================ */
.oc-exec-wrap {
  position: relative; display: flex;
  justify-content: center; margin-bottom: 0;
}
.oc-exec-bg {
  position: absolute; inset: 0;
  border-radius: var(--radius-lg); overflow: hidden;
  pointer-events: none;
}
.oc-exec-orb {
  position: absolute; border-radius: 50%; filter: blur(50px);
}
.oc-orb-1 {
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(102,197,197,0.35), transparent 70%);
  top: -80%; left: 5%;
  animation: orbFloat 7s ease-in-out infinite;
}
.oc-orb-2 {
  width: 260px; height: 260px;
  background: radial-gradient(circle, rgba(0,64,129,0.2), transparent 70%);
  bottom: -80%; right: 5%;
  animation: orbFloat 9s ease-in-out infinite 2s reverse;
}
.oc-exec-card {
  position: relative;
  background: linear-gradient(135deg, var(--navy) 0%, #004081 55%, #004081 100%);
  border-radius: var(--radius-lg);
  padding: 40px 60px;
  text-align: center; width: 100%; max-width: 600px;
  box-shadow: 0 16px 52px rgba(0,64,129,0.3), inset 0 1px 0 rgba(248,249,250,0.1);
}
.oc-exec-eyebrow {
  display: inline-block;
  font-size: 11px; font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase;
  color: rgba(102,197,197,0.85); margin-bottom: 10px;
}
.oc-exec-name {
  font-family: var(--display);
  font-size: 24px; font-weight: 800;
  color: #F8F9FA; letter-spacing: -0.02em;
  line-height: 1.15; margin-bottom: 8px;
}
.oc-exec-role {
  font-size: 14px; color: rgba(248,249,250,0.55); font-weight: 400;
}
.oc-tree-conn {
  display: flex; flex-direction: column;
  align-items: center; margin: 0 auto;
}
.oc-tc-stem {
  width: 2px; height: 28px;
  background: linear-gradient(180deg, var(--cyan), rgba(102,197,197,0.2));
