/* ============================================================
   CORE VALUES v2 — animated card stack
   ============================================================ */

/* ── Intro strip ── */
.cv2-intro {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  padding: 24px 28px;
  background: var(--ci-navy);
  border-radius: 20px;
  margin-bottom: 28px;
  color: #F8F9FA;
}
.cv2-intro-inner { flex: 1; }
.cv2-intro-label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
  opacity: .65;
  display: block;
  margin-bottom: 6px;
}
.cv2-intro-text {
  font-size: 14.5px;
  line-height: 1.7;
  opacity: .88;
  margin: 0;
}
.cv2-dots {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding-top: 6px;
  align-items: center;
}
.cv2-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(248,249,250,.28);
  cursor: pointer;
  transition: background .2s, transform .2s;
  flex-shrink: 0;
}
.cv2-dot.is-active { background: #F8F9FA; transform: scale(1.4); }
.cv2-dot:hover     { background: rgba(248,249,250,.65); }

/* ── Card stack ── */
.cv2-stack {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* Base card */
.cv2-card {
  position: relative;
  border-radius: 22px;
  padding: 30px 32px 28px;
  border: 1.5px solid transparent;
  overflow: hidden;
  cursor: default;
  box-shadow: 0 4px 20px rgba(0,64,129,.05);
  transition: box-shadow .3s, transform .3s;
}
.cv2-card:hover {
  box-shadow: 0 14px 44px rgba(0,64,129,.12);
  transform: translateY(-3px);
}

/* Color variants */
.cv2-c1 { background: linear-gradient(140deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(0,64,129,.11); }
.cv2-c2 { background: linear-gradient(140deg, #F8F9FA 0%, #F8F9FA 100%); border-color: rgba(255,204,0,.2); }
.cv2-c3 { background: linear-gradient(140deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(130,197,102,.18); }
.cv2-c4 { background: linear-gradient(140deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(146,158,180,.18); }
.cv2-c5 { background: linear-gradient(140deg, #F8F9FA 0%, #D0D6DF 100%); border-color: rgba(243,85,79,.17); }

/* Large decorative number */
.cv2-card-num {
  position: absolute;
  top: -8px;
  right: 22px;
  font-family: var(--display);
  font-size: 100px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.04em;
  pointer-events: none;
  user-select: none;
  transition: opacity .35s;
}
.cv2-c1 .cv2-card-num { color: rgba(0,64,129,.06); }
.cv2-c2 .cv2-card-num { color: rgba(243,85,79,.09); }
.cv2-c3 .cv2-card-num { color: rgba(130,197,102,.08); }
.cv2-c4 .cv2-card-num { color: rgba(146,158,180,.09); }
.cv2-c5 .cv2-card-num { color: rgba(243,85,79,.09); }
.cv2-card:hover .cv2-card-num { opacity: .32; }

/* Card top row: icon + title */
.cv2-card-top {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 22px;
  position: relative;
}
.cv2-card-icon {
  width: 52px;
  height: 52px;
  border-radius: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform .25s;
}
.cv2-card:hover .cv2-card-icon { transform: scale(1.07) rotate(-3deg); }
.cv2-c1 .cv2-card-icon { background: rgba(0,64,129,.09);    color: var(--navy); }
.cv2-c2 .cv2-card-icon { background: rgba(255,204,0,.15);  color: #707070; }
.cv2-c3 .cv2-card-icon { background: rgba(130,197,102,.14);   color: #505050; }
.cv2-c4 .cv2-card-icon { background: rgba(146,158,180,.14);  color: #586782; }
.cv2-c5 .cv2-card-icon { background: rgba(243,85,79,.12);   color: #505050; }

.cv2-name {
  font-family: var(--display);
  font-size: 21px;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--navy);
  margin: 0 0 5px;
  line-height: 1.2;
}
.cv2-sub {
  font-size: 13.5px;
  color: var(--muted);
  line-height: 1.65;
  margin: 0;
}

/* Key points — stagger-animated on scroll reveal */
.cv2-pts {
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
}
.cv2-pt {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 9px 14px;
  border-radius: 11px;
  background: rgba(248,249,250,.5);
  border: 1px solid rgba(248,249,250,.85);
  opacity: 0;
  transform: translateX(-10px);
  transition: opacity .35s, transform .35s, background .18s;
}
.cv2-card.cv2-pts-visible .cv2-pt {
  opacity: 1;
  transform: none;
}
.cv2-card:hover .cv2-pt { background: rgba(248,249,250,.8); }
.cv2-pt-k {
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
  padding: 2px 8px;
  border-radius: 6px;
  flex-shrink: 0;
  line-height: 1.7;
}
.cv2-c1 .cv2-pt-k { background: rgba(0,64,129,.09);    color: #004081; }
.cv2-c2 .cv2-pt-k { background: rgba(243,85,79,.13);   color: #505050; }
.cv2-c3 .cv2-pt-k { background: rgba(130,197,102,.14);   color: #505050; }
.cv2-c4 .cv2-pt-k { background: rgba(146,158,180,.14);  color: #586782; }
.cv2-c5 .cv2-pt-k { background: rgba(243,85,79,.12);   color: #505050; }
.cv2-pt-v {
  font-size: 13.5px;
  color: var(--ink);
  line-height: 1.6;
  flex: 1;
}

