  flex-direction: column;
  align-items: center;
  padding-top: 28px;
  position: relative;
  min-width: 120px;
}
/* Vertical tick from bar to card */
.voc-dept-col::before {
  content: '';
  position: absolute;
  top: 0;
  width: 2px;
  height: 28px;
  background: rgba(0,64,129,.15);
}

/* ── Department node — colored card ── */
.voc-dept-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  border-radius: 20px;
  padding: 22px 14px 18px;
  width: calc(100% - 16px);
  max-width: 148px;
  transition: transform .22s ease, box-shadow .22s ease;
  cursor: default;
  text-align: center;
  position: relative;
  z-index: 1;
  border-top: 4px solid transparent;
}
.voc-dept-node:hover {
  transform: translateY(-6px);
}

.voc-dept-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.voc-dept-name {
  font-family: var(--display);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.45;
  letter-spacing: -.1px;
}

/* ── Department color themes — solid backgrounds ── */
.voc-d-bd {
  background: linear-gradient(160deg, #F8F9FA, #F8F9FA);
  border-top-color: #FFCC00;
  box-shadow: 0 12px 32px rgba(255,204,0,.15);
}
.voc-d-bd:hover { box-shadow: 0 18px 44px rgba(255,204,0,.25); }
.voc-d-bd .voc-dept-icon { background: rgba(255,204,0,.15); color: #F3554F; }
.voc-d-bd .voc-dept-name { color: #505050; }

.voc-d-hr {
  background: linear-gradient(160deg, #F8F9FA, #D0D6DF);
  border-top-color: #66C5C5;
  box-shadow: 0 12px 32px rgba(102,197,197,.18);
}
.voc-d-hr:hover { box-shadow: 0 18px 44px rgba(102,197,197,.3); }
.voc-d-hr .voc-dept-icon { background: rgba(102,197,197,.2); color: #586782; }
.voc-d-hr .voc-dept-name { color: #004081; }

.voc-d-dev {
  background: linear-gradient(160deg, #F8F9FA, #D0D6DF);
  border-top-color: #586782;
  box-shadow: 0 12px 32px rgba(0,64,129,.12);
}
.voc-d-dev:hover { box-shadow: 0 18px 44px rgba(0,64,129,.22); }
.voc-d-dev .voc-dept-icon { background: rgba(0,64,129,.12); color: #004081; }
.voc-d-dev .voc-dept-name { color: #004081; }

.voc-d-des {
  background: linear-gradient(160deg, #F8F9FA, #D0D6DF);
  border-top-color: #929EB4;
  box-shadow: 0 12px 32px rgba(146,158,180,.14);
}
.voc-d-des:hover { box-shadow: 0 18px 44px rgba(146,158,180,.24); }
.voc-d-des .voc-dept-icon { background: rgba(146,158,180,.12); color: #586782; }
.voc-d-des .voc-dept-name { color: #586782; }

.voc-d-sal {
  background: linear-gradient(160deg, #F8F9FA, #D0D6DF);
  border-top-color: #82C566;
  box-shadow: 0 12px 32px rgba(130,197,102,.14);
}
.voc-d-sal:hover { box-shadow: 0 18px 44px rgba(130,197,102,.24); }
.voc-d-sal .voc-dept-icon { background: rgba(130,197,102,.12); color: #505050; }
.voc-d-sal .voc-dept-name { color: #505050; }

/* ── Sub-dept connector stem ── */
.voc-sub-stem {
  width: 2px;
  height: 18px;
  background: rgba(0,17,34,.12);
  flex-shrink: 0;
}

/* ── Sub-department pill ── */
.voc-sub-node {
  display: flex;
  align-items: center;
  gap: 6px;
  border-radius: 10px;
  padding: 6px 13px;
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
  border: 1px solid transparent;
}
.voc-sub-node svg { opacity: .55; }

.voc-s-bd  { background: #F8F9FA; border-color: rgba(255,204,0,.35); color: #505050; }
.voc-s-hr  { background: #F8F9FA; border-color: rgba(102,197,197,.4);  color: #004081; }
.voc-s-dev { background: #D0D6DF; border-color: rgba(0,64,129,.22);     color: #004081; }
.voc-s-des { background: #D0D6DF; border-color: rgba(146,158,180,.3);    color: #586782; }

/* No sub-dept spacer */
.voc-dept-col-nosub .voc-dept-node { margin-bottom: 0; }

/* ── Responsive ── */
@media (max-width: 860px) {
  .voc-l1-row::before { left: 6%; right: 6%; }
  .voc-dept-node { max-width: 120px; padding: 16px 10px 14px; }
  .voc-dept-icon { width: 40px; height: 40px; }
  .voc-dept-name { font-size: 12px; }
}
@media (max-width: 640px) {
  .voc-l1-row { flex-wrap: wrap; justify-content: center; gap: 14px; }
  .voc-l1-row::before { display: none; }
  .voc-dept-col { padding-top: 0; min-width: 0; flex: 0 1 calc(50% - 8px); }
  .voc-dept-col::before { display: none; }
  .voc-dept-node { max-width: 100%; width: 100%; }
  .voc-root-stem { display: none; }
  .voc-root-node { padding: 18px 24px; }
  .voc-root-name { font-size: 17px; }
}

/* ============================================================
   WOW FACTOR ENHANCEMENTS — Global polish pass
   ============================================================ */

/* ── hb-link cards: richer hover ── */
.hb-link {
  transition: background 0.2s ease, transform 0.22s cubic-bezier(0.22, 1, 0.36, 1),
              box-shadow 0.22s ease, border-color 0.22s ease !important;
}
.hb-link:hover {
  background: linear-gradient(135deg, rgba(102,197,197,0.10), rgba(0,64,129,0.04)) !important;
  transform: translateX(6px) !important;
  border-color: rgba(102,197,197,0.35) !important;
  box-shadow: 0 6px 20px rgba(0,64,129,0.09) !important;
}
.hb-link:hover .hb-link-arrow {
  transform: translateX(4px);
  color: var(--cyan);
}
.hb-link-arrow {
  transition: transform 0.2s ease, color 0.2s ease;
}

/* ── Priority card hover lift ── */
.ptask-card:hover {
  transform: translateY(-6px) scale(1.005) !important;
  box-shadow: 0 24px 48px rgba(0,64,129,0.13) !important;
}

/* ── Homepage section heading style (non-prose) ── */
.priority-title,
.hb-title,
.story-title {
  letter-spacing: -0.03em !important;
}

/* ── Eyebrow pill style (homepage labels) ── */
.priority-overline,
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 11px !important;
  font-weight: 800 !important;
  letter-spacing: 0.13em !important;
  text-transform: uppercase !important;
  color: var(--cyan) !important;
  background: rgba(102,197,197,0.11) !important;
  border: 1px solid rgba(102,197,197,0.20) !important;
  padding: 4px 12px !important;
  border-radius: 999px !important;
  margin-bottom: 12px !important;
}

/* ── Skeleton shimmer for loading states ── */
@keyframes shimmer {
  0% { background-position: -400px 0; }
  100% { background-position: 400px 0; }
}

/* ── Pulse dot (nav badge, status indicators) ── */
@keyframes pulse-ring {
  0%   { transform: scale(0.8); opacity: 0.8; }
  70%  { transform: scale(1.6); opacity: 0; }
  100% { transform: scale(0.8); opacity: 0; }
}
.dot {
  position: relative;
}
.dot::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: var(--cyan);
  animation: pulse-ring 2s ease-out infinite;
}

/* ── Callout icon upgrade ── */
.callout .ic {
  background: var(--ci-navy) !important;
  box-shadow: 0 4px 12px rgba(0,64,129,0.20);
}

/* ── Inline link underline animation ── */
.inline-link {
  position: relative;
  text-decoration: none !important;
  color: var(--cyan) !important;
  font-weight: 600;
}
.inline-link::after {
  content: "";
  position: absolute;
  bottom: -1px; left: 0;
  width: 0; height: 1.5px;
  background: var(--ci-teal);
  border-radius: 999px;
  transition: width 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
.inline-link:hover::after { width: 100%; }

/* ── Accordion hover ── */
.acc-trigger:hover {
  background: linear-gradient(135deg, rgba(102,197,197,0.08), rgba(0,64,129,0.03)) !important;
}

/* ── Tag/pill hover ── */
.day1-tag:hover,
.oct-team-pill:hover,
.mr-use-tag:hover {
  background: rgba(102,197,197,0.14) !important;
  border-color: rgba(102,197,197,0.40) !important;
  color: #586782 !important;
  transition: all 0.18s ease;
}

/* ── Howto step number — gradient circle ── */
.howto-step .num {
  background: var(--ci-navy) !important;
  color: #F8F9FA !important;
  box-shadow: 0 4px 14px rgba(0,64,129,0.22) !important;
  font-weight: 900 !important;
  font-family: var(--display) !important;
  border: none !important;
}

/* ── Rule card icon upgrade ── */
.rule-icon {
  background: linear-gradient(135deg, rgba(102,197,197,0.15), rgba(0,64,129,0.08)) !important;
  border: 1px solid rgba(102,197,197,0.22) !important;
  transition: transform 0.22s ease, box-shadow 0.22s ease;
}
.rule-card:hover .rule-icon {
  transform: scale(1.08) rotate(-3deg);
  box-shadow: 0 6px 16px rgba(0,64,129,0.12);
}

/* ── Day 1 panel card hover ── */
.d1-panel.is-active {
  box-shadow: 0 18px 44px rgba(0,64,129,0.12) !important;
}

/* ── Nav link active indicator ── */
.nav-link.is-active {
  position: relative;
}
.nav-link.is-active::after {
  content: "";
  position: absolute;
  bottom: -2px; left: 12px; right: 12px;
  height: 2px;
  background: var(--ci-teal);
  border-radius: 999px;
}

/* ── Page section "stripe" decoration (alternating sections) ── */
.section:nth-child(even) {
  background: linear-gradient(180deg, #F8F9FA 0%, #F8F9FA 100%);
}

/* ── Smooth scroll behavior ── */
html { scroll-behavior: smooth; }

/* ── Focus rings (accessibility upgrade) ── */
:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
  border-radius: 6px;
}

/* ── Responsive page hero band ── */
@media (max-width: 768px) {
  .page-hero-band { padding: 36px 0 32px; }
  .phb-title { font-size: clamp(24px, 6vw, 34px) !important; }
  .phb-deco-num { display: none; }
  .page-cta-strip { padding: 24px 24px; flex-direction: column; align-items: flex-start; }
}
@media (max-width: 480px) {
  .page-hero-band { padding: 28px 0 24px; }
  .phb-eyebrow { font-size: 10px; }
}

/* ================================================================
   HOMEPAGE WOW UPGRADE — Particles, Word-reveal, Stats, Sections
   ================================================================ */

/* ── Floating particles layer ── */
.hero-particles {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}
.hero-p {
  position: absolute;
  border-radius: 50%;
  background: var(--cyan);
  opacity: 0;
  animation: particleDrift var(--dur, 9s) ease-in-out var(--delay, 0s) infinite;
}
@keyframes particleDrift {
  0%   { opacity: 0; transform: translateY(0) scale(1); }
  15%  { opacity: var(--op, 0.35); }
  80%  { opacity: var(--op, 0.35); }
  100% { opacity: 0; transform: translateY(-80px) scale(0.6); }
}
.hero-p:nth-child(1)  { width:6px; height:6px; left:8%;  top:72%;  --dur:10s; --delay:0s;   --op:0.4; }
.hero-p:nth-child(2)  { width:4px; height:4px; left:18%; top:30%;  --dur:8s;  --delay:1.5s; --op:0.28; }
.hero-p:nth-child(3)  { width:8px; height:8px; left:82%; top:60%;  --dur:12s; --delay:0.8s; --op:0.22; background: #004081; }
.hero-p:nth-child(4)  { width:5px; height:5px; left:65%; top:20%;  --dur:9s;  --delay:3s;   --op:0.32; }
.hero-p:nth-child(5)  { width:3px; height:3px; left:44%; top:80%;  --dur:7s;  --delay:2s;   --op:0.45; }
.hero-p:nth-child(6)  { width:6px; height:6px; left:91%; top:40%;  --dur:11s; --delay:4s;   --op:0.2;  background: #586782; }
.hero-p:nth-child(7)  { width:4px; height:4px; left:30%; top:55%;  --dur:9.5s; --delay:1s;  --op:0.3; }
.hero-p:nth-child(8)  { width:7px; height:7px; left:55%; top:15%;  --dur:13s; --delay:5s;   --op:0.18; background: #004081; }
.hero-p:nth-child(9)  { width:3px; height:3px; left:76%; top:85%;  --dur:8s;  --delay:2.5s; --op:0.38; }
.hero-p:nth-child(10) { width:5px; height:5px; left:12%; top:45%;  --dur:10s; --delay:3.5s; --op:0.25; }

/* Grid mesh overlay (very subtle) */
.hero-mesh {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image:
    linear-gradient(rgba(102,197,197,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(102,197,197,0.04) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse 80% 60% at 50% 50%, black 30%, transparent 80%);
}

/* ── Hero h1 word-by-word reveal ── */
.hero-word {
  display: inline-block; /* overridden to block for block-level elements */
  animation: wordUp 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
}
p.hero-word, div.hero-word { display: block; }
@keyframes wordUp {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}
/* Delays set inline via style="--wi:N"; base 0.25s lets parent fade-in start first */
.hero-word { animation-delay: calc(0.25s + 0.09s * var(--wi, 0)); }

/* ── Stats Strip ── */
.hero-stats-strip {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 36px;
  padding-top: 28px;
  border-top: 1px solid rgba(102,197,197,0.18);
}
.hss-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.hss-num {
  font-family: var(--display);
  font-size: 28px;
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1;
  color: var(--ci-navy);
}
.hss-label {
  font-size: 11.5px;
  color: var(--muted);
  font-weight: 500;
  line-height: 1.3;
}
.hss-div {
  width: 1px;
  height: 36px;
  background: var(--line);
  flex-shrink: 0;
  margin: 0 10px;
}

/* ── Priority section upgrade: gradient top accent on cards ── */
.ptask-card {
  position: relative;
}
.ptask-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  background: var(--ci-teal);
  opacity: 0;
  transition: opacity 0.3s ease;
}
.ptask-card:hover::before { opacity: 1; }
.ptask-card-action::before { opacity: 0.5; }

/* ── Floating number badge on priority cards ── */
.ptask-num-badge {
  font-size: 13px !important;
  font-weight: 900 !important;
  letter-spacing: 0 !important;
  font-family: var(--display) !important;
}

/* ── Section separator with progress feel ── */
.section-journey-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 0 0 52px;
}
.sjb-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--cyan);
  opacity: 0.35;
  transition: opacity 0.3s ease;
}
.sjb-dot.is-active { opacity: 1; background: var(--ci-navy); }
.sjb-line {
  width: 48px; height: 2px;
  background: linear-gradient(90deg, rgba(102,197,197,0.3), rgba(0,64,129,0.15));
  border-radius: 999px;
}

/* ── HB group enhanced headers ── */
.hb-group-label {
  letter-spacing: 0.06em !important;
  font-weight: 800 !important;
}

/* ── HBE cards hover glow ── */
.hbe-card {
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease !important;
}
.hbe-card:hover {
  transform: translateY(-4px) !important;
  box-shadow: 0 12px 32px rgba(0,64,129,0.10), 0 2px 8px rgba(102,197,197,0.12) !important;
  background: linear-gradient(135deg, rgba(102,197,197,0.07), rgba(0,64,129,0.03)) !important;
}
.hbe-card:hover .hbe-card-icon {
  background: var(--ci-navy) !important;
  color: #F8F9FA !important;
  box-shadow: 0 6px 16px rgba(0,64,129,0.20) !important;
  transform: scale(1.08) rotate(-3deg) !important;
  transition: all 0.22s ease;
}
.hbe-card-icon { transition: all 0.22s ease; }

/* ── HB link group hover glow ── */
.hb-link {
  transition: transform 0.18s ease, background 0.18s ease, box-shadow 0.18s ease !important;
}
.hb-link:hover {
  background: linear-gradient(135deg, rgba(102,197,197,0.08), rgba(0,64,129,0.03)) !important;
  transform: translateX(5px) !important;
  box-shadow: 0 4px 16px rgba(0,64,129,0.07) !important;
}
.hb-link:hover .hb-link-icon {
  background: var(--ci-navy) !important;
  color: #F8F9FA !important;
  transition: all 0.2s ease;
}
.hb-link-icon { transition: all 0.2s ease; }

/* ── Day 1 step buttons hover ── */
.d1-step-btn:not(.is-active):hover {
  background: rgba(102,197,197,0.08) !important;
  border-left-color: rgba(102,197,197,0.4) !important;
  transform: translateX(3px);
  transition: all 0.18s ease;
}

/* ── Priority section overline + title upgrade ── */
.priority-title {
  font-size: clamp(22px, 3.2vw, 32px) !important;
  letter-spacing: -0.03em !important;
  font-weight: 900 !important;
  line-height: 1.25 !important;
}

/* ── Explore section: neon border on hover ── */
.hb-explore {
  border: 1px solid rgba(102,197,197,0.15) !important;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
.hb-explore:hover {
  border-color: rgba(102,197,197,0.32) !important;
  box-shadow: 0 20px 60px rgba(0,64,129,0.08), 0 0 0 1px rgba(102,197,197,0.15) !important;
}

@media (max-width: 640px) {
  .hero-stats-strip { gap: 0; }
  .hss-num { font-size: 22px; }
  .hss-div { margin: 0 6px; }
  .hero-mesh { display: none; }
}

/* ================================================================
   NEW DAY 1 TIMELINE — Tab + Card Design
   ================================================================ */
.tl-section {
  padding: 80px 0 96px;
  background: linear-gradient(180deg, #F8F9FA 0%, #F8F9FA 100%);
  position: relative;
  overflow: hidden;
}
.tl-section::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1px;
  background: var(--line-soft);
}
.tl-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 clamp(20px, 4vw, 48px);
}

/* Header */
.tl-header { text-align: center; margin-bottom: 52px; }
.tl-heading {
  font-family: var(--display);
  font-size: clamp(26px, 3.5vw, 40px);
  font-weight: 900;
  letter-spacing: -0.035em;
  color: #001122;
  line-height: 1.18;
  margin: 12px 0 14px;
}
.tl-sub {
  font-size: 15px;
  color: var(--muted);
  max-width: 480px;
  margin: 0 auto;
  line-height: 1.65;
}

/* Tab nav */
.tl-nav {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 28px;
}
/* Progress track behind tabs */
.tl-track {
  display: none; /* hidden — progress shown via tab states */
}

/* Individual tabs */
.tl-tab {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 18px 12px 16px;
  background: #F8F9FA;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  cursor: pointer;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease, transform 0.18s ease;
  overflow: hidden;
}
.tl-tab::after {
  content: "";
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 3px;
  background: var(--ci-teal);
  border-radius: 0 0 var(--radius) var(--radius);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
.tl-tab:hover {
  border-color: rgba(102,197,197,0.4);
  box-shadow: 0 4px 16px rgba(0,64,129,0.06);
  transform: translateY(-2px);
}
.tl-tab.is-active {
  border-color: var(--cyan);
  background: linear-gradient(160deg, rgba(102,197,197,0.06) 0%, rgba(0,64,129,0.02) 100%);
  box-shadow: 0 6px 24px rgba(102,197,197,0.14), 0 2px 8px rgba(0,64,129,0.06);
}
.tl-tab.is-active::after { transform: scaleX(1); }
.tl-tab-num {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1;
  color: var(--ci-navy);
}
.tl-tab-time {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.tl-tab-name {
  font-size: 14px;
  font-weight: 700;
  color: #001122;
  line-height: 1.3;
  text-align: center;
}
.tl-tab.is-active .tl-tab-name { color: var(--ink); }

/* Content panels */
.tl-panels { position: relative; min-height: 280px; }
.tl-panel {
  display: none;
  grid-template-columns: 200px 1fr;
  gap: 40px;
  align-items: flex-start;
  background: #F8F9FA;
  border: 1.5px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 40px 44px;
  box-shadow: var(--shadow-md);
  animation: tlPanelIn 0.38s cubic-bezier(0.25, 1, 0.5, 1) forwards;
}
.tl-panel.is-active { display: grid; }
@keyframes tlPanelIn {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Left column */
.tl-panel-left {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
  padding-right: 24px;
  border-right: 1px solid var(--line-soft);
}
.tl-big-num {
  font-family: var(--display);
  font-size: 72px;
  font-weight: 900;
  letter-spacing: -0.05em;
  line-height: 1;
  color: var(--ci-navy);
  opacity: 0.18;
}
.tl-icon-wrap {
  width: 56px; height: 56px;
  border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
}
.tl-icon-cyan  { background: rgba(102,197,197,0.14); color: #004081; }
.tl-icon-amber { background: rgba(255,204,0,0.12);  color: #707070; }
.tl-icon-navy  { background: rgba(0,64,129,0.10);    color: var(--navy); }
.tl-icon-accent { background: linear-gradient(135deg, rgba(102,197,197,0.15), rgba(0,64,129,0.10)); color: var(--ink); }
.tl-icon-wrap svg { width: 26px; height: 26px; }

.tl-time-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  background: var(--surface-2);
  border: 1px solid var(--line);
  padding: 5px 10px;
  border-radius: 999px;
}
.tl-chip-accent {
  background: rgba(255,204,0,0.10) !important;
  border-color: rgba(255,204,0,0.25) !important;
  color: #F3554F !important;
}

/* Right column body */
.tl-panel-body { display: flex; flex-direction: column; gap: 14px; }
.tl-panel-title {
  font-family: var(--display);
  font-size: clamp(20px, 2.5vw, 26px);
  font-weight: 900;
  letter-spacing: -0.03em;
  color: #001122;
  margin: 0;
  line-height: 1.2;
}
.tl-panel-desc {
  font-size: 15px;
  color: #505050;
  line-height: 1.7;
  margin: 0;
}
.tl-facts {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.tl-fact {
  display: flex;
  flex-direction: column;
  gap: 2px;
  background: var(--surface);
  border: 1px solid var(--line-soft);
  border-radius: 10px;
  padding: 10px 16px;
  min-width: 100px;
}
.tl-fact-k {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--cyan);
}
.tl-fact-v {
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
}
.tl-tags {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
}
.tl-tag {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
  background: rgba(0,64,129,0.05);
  border: 1px solid rgba(0,64,129,0.10);
  padding: 4px 11px;
  border-radius: 999px;
}
.tl-tag-hot {
  background: rgba(255,204,0,0.12) !important;
  border-color: rgba(255,204,0,0.28) !important;
  color: #505050 !important;
}
.tl-cta {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 700;
  color: var(--ink);
  background: transparent;
  border: none;
  padding: 0;
  cursor: pointer;
  margin-top: 4px;
  transition: gap 0.18s ease, color 0.18s ease;
  text-decoration: none;
}
.tl-cta:hover { color: var(--cyan); gap: 11px; }
.tl-cta svg { transition: transform 0.18s ease; }
.tl-cta:hover svg { transform: translateX(2px); }

/* Mobile stacked */
@media (max-width: 840px) {
  .tl-panel { grid-template-columns: 1fr; gap: 24px; padding: 28px 24px; }
  .tl-panel-left { flex-direction: row; align-items: center; padding-right: 0; border-right: none; border-bottom: 1px solid var(--line-soft); padding-bottom: 20px; gap: 14px; }
  .tl-big-num { font-size: 44px; }
}
@media (max-width: 620px) {
  .tl-nav { grid-template-columns: repeat(2, 1fr); }
  .tl-tab { padding: 14px 10px 12px; }
  .tl-tab-name { font-size: 13px; }
}

/* ============================================================
   WOW REDESIGN — Scroll Interactions & Animations
   ============================================================ */

/* ---- SCROLL PROGRESS BAR ---- */
#scroll-progress {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  width: 0%;
  background: linear-gradient(90deg, #66C5C5, #586782, #004081);
  z-index: 9999;
  border-radius: 0 2px 2px 0;
  box-shadow: 0 0 12px rgba(102,197,197,0.55), 0 0 4px rgba(102,197,197,0.3);
  pointer-events: none;
  transition: width 0.08s linear;
}
#scroll-progress::after {
  content: "";
  position: absolute;
  right: -1px;
  top: -2px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #66C5C5;
  box-shadow: 0 0 8px rgba(102,197,197,0.9);
}

/* ---- ENHANCED BASE ANIMATION STATES (override, last wins) ---- */
.anim-up {
  opacity: 0;
  transform: translateY(48px);
  transition: opacity 0.78s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.78s cubic-bezier(0.22, 1, 0.36, 1);
}
.anim-up.is-visible { opacity: 1; transform: none; }

.anim-left {
  opacity: 0;
  transform: translateX(-48px);
  transition: opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.75s cubic-bezier(0.22, 1, 0.36, 1);
}
.anim-left.is-visible { opacity: 1; transform: none; }

.anim-right {
  opacity: 0;
  transform: translateX(48px);
  transition: opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.75s cubic-bezier(0.22, 1, 0.36, 1);
}
.anim-right.is-visible { opacity: 1; transform: none; }

.anim-down {
  opacity: 0;
  transform: translateY(-48px);
  transition: opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1),
              transform 0.75s cubic-bezier(0.22, 1, 0.36, 1);
}
.anim-down.is-visible { opacity: 1; transform: none; }

.anim-scale {
  opacity: 0;
  transform: scale(0.85) translateY(24px);
  transition: opacity 0.72s cubic-bezier(0.25, 1, 0.5, 1),
              transform 0.72s cubic-bezier(0.25, 1, 0.5, 1);
}
.anim-scale.is-visible { opacity: 1; transform: none; }

/* ---- NEW: POP (spring bounce) ---- */
.anim-pop {
  opacity: 0;
  transform: scale(0.78) translateY(20px);
  transition: opacity 0.55s cubic-bezier(0.25, 1, 0.5, 1),
              transform 0.55s cubic-bezier(0.25, 1, 0.5, 1);
  will-change: opacity, transform;
}
.anim-pop.is-visible { opacity: 1; transform: none; }

/* ---- NEW: BLUR FADE IN ---- */
.anim-blur {
  opacity: 0;
  filter: blur(10px);
  transform: scale(1.03);
  transition: opacity 0.9s ease, filter 0.9s ease, transform 0.9s ease;
  will-change: opacity, filter;
}
.anim-blur.is-visible { opacity: 1; filter: blur(0px); transform: none; }

/* ---- CURSOR GLOW SPOTLIGHT ---- */
#cursor-glow {
  pointer-events: none;
  position: fixed;
  width: 420px;
  height: 420px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(102,197,197,0.07) 0%, transparent 70%);
  transform: translate(-50%, -50%);
  z-index: 0;
  left: -999px;
  top: -999px;
  transition: opacity 0.3s ease;
  mix-blend-mode: normal;
}

/* ---- SCROLL WAYPOINTS (right side) ---- */
#scroll-waypoints {
  position: fixed;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 11px;
  z-index: 50;
  opacity: 0;
  transition: opacity 0.4s ease;
}
#scroll-waypoints.is-visible { opacity: 1; }
.swp-item {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  cursor: pointer;
  position: relative;
}
.swp-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(0,64,129,0.18);
  transition: transform 0.25s cubic-bezier(0.25, 1, 0.5, 1),
              background 0.25s ease, width 0.25s ease, height 0.25s ease,
              box-shadow 0.25s ease;
  display: block;
  flex-shrink: 0;
}
.swp-label {
  position: absolute;
  right: 18px;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 700;
  color: var(--ink);
  background: #F8F9FA;
  padding: 5px 11px;
  border-radius: 999px;
  box-shadow: 0 2px 12px rgba(0,64,129,0.12);
  opacity: 0;
  transform: translateX(6px);
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: none;
  border: 1px solid var(--line-soft);
}
.swp-item:hover .swp-label { opacity: 1; transform: translateX(0); }
.swp-item:hover .swp-dot { transform: scale(1.7); background: var(--cyan); }
.swp-item.is-active .swp-dot {
  width: 9px;
  height: 9px;
  background: var(--cyan);
  box-shadow: 0 0 0 3px rgba(102,197,197,0.3);
  transform: scale(1.2);
}
@media (max-width: 1100px) { #scroll-waypoints { display: none; } }

/* ---- SECTION EYEBROW ANIMATED LINE ---- */
.section-eyebrow-line::before {
  content: "";
  display: inline-block;
  width: 0;
  height: 2px;
  background: var(--ci-teal);
  border-radius: 999px;
  vertical-align: middle;
  margin-right: 0;
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
.section-eyebrow-line.is-visible::before { width: 22px; margin-right: 8px; }

/* ---- STAGGER CHILDREN (parent becomes visible, children stagger in) ---- */
.stagger-in > * {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.stagger-in.is-visible > *:nth-child(1) { opacity:1; transform:none; transition-delay: 0ms; }
.stagger-in.is-visible > *:nth-child(2) { opacity:1; transform:none; transition-delay: 80ms; }
.stagger-in.is-visible > *:nth-child(3) { opacity:1; transform:none; transition-delay: 160ms; }
.stagger-in.is-visible > *:nth-child(4) { opacity:1; transform:none; transition-delay: 240ms; }
.stagger-in.is-visible > *:nth-child(5) { opacity:1; transform:none; transition-delay: 320ms; }
.stagger-in.is-visible > *:nth-child(6) { opacity:1; transform:none; transition-delay: 400ms; }
.stagger-in.is-visible > *:nth-child(7) { opacity:1; transform:none; transition-delay: 480ms; }
.stagger-in.is-visible > *:nth-child(8) { opacity:1; transform:none; transition-delay: 560ms; }

/* ---- PULSE RING (for stat numbers) ---- */
.pulse-dot {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.pulse-dot::before {
  content: "";
  position: absolute;
  inset: -6px;
  border-radius: inherit;
  border: 2px solid rgba(102,197,197,0.45);
  animation: pulseRingWow 2.5s ease-out infinite;
}
@keyframes pulseRingWow {
  0% { transform: scale(0.88); opacity: 0.8; }
  100% { transform: scale(1.5); opacity: 0; }
}

/* ---- ANIMATED GRADIENT BORDER ---- */
@keyframes gradientBorderSpin {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
.grad-border-anim {
  position: relative;
  isolation: isolate;
}
.grad-border-anim::before {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: inherit;
  background: linear-gradient(270deg, #66C5C5, #004081, #66C5C5);
  background-size: 300% 300%;
  animation: gradientBorderSpin 4s ease infinite;
  z-index: -1;
  opacity: 0;
  transition: opacity 0.3s ease;
}
.grad-border-anim:hover::before { opacity: 1; }

/* ---- SPARKLE BUTTON EFFECT ---- */
.btn-sparkle {
  position: relative;
  overflow: visible;
}
@keyframes sparkleFloat {
  0% { opacity: 1; transform: translate(-50%,-50%) scale(1); }
  100% { opacity: 0; transform: translate(calc(-50% + var(--sx)), calc(-50% + var(--sy))) scale(0); }
}
.btn-sparkle-particle {
  position: absolute;
  width: 5px; height: 5px;
  border-radius: 50%;
  background: var(--cyan);
  pointer-events: none;
  animation: sparkleFloat 0.7s ease forwards;
}

/* ---- SECTION SEPARATOR GRADIENT ---- */
.section-sep {
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, rgba(102,197,197,0.35) 35%, rgba(0,64,129,0.2) 65%, transparent 100%);
  margin: 0;
  border: none;
}

/* ---- ENHANCED INNER PAGE SECTION BACKGROUNDS ---- */
.page-hero-band {
  background: linear-gradient(135deg,
    rgba(102,197,197,0.07) 0%,
    rgba(0,64,129,0.04) 60%,
    rgba(88,103,130,0.05) 100%) !important;
}

/* Inner page hero band orb animation */
.phb-orb {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(50px);
  animation: orbPulse 6s ease-in-out infinite;
}
.phb-orb-1 {
  width: 200px; height: 200px;
  background: rgba(102,197,197,0.12);
  top: -40px; right: 10%;
  animation-delay: 0s;
}
.phb-orb-2 {
  width: 140px; height: 140px;
  background: rgba(0,64,129,0.06);
  bottom: -20px; right: 30%;
  animation-delay: -3s;
}
@keyframes orbPulse {
  0%, 100% { transform: scale(1) translate(0, 0); opacity: 0.8; }
  50% { transform: scale(1.15) translate(10px, -10px); opacity: 1; }
}

/* ---- CALLOUT ENHANCED HOVER ---- */
.callout {
  position: relative;
  overflow: hidden;
}
.callout::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(102,197,197,0.05), transparent 60%);
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}
.callout:hover::after { opacity: 1; }

/* ---- HOVERABLE PROSE LIST ---- */
.prose ul li,
.prose ol li {
  transition: transform 0.2s ease, color 0.2s ease, padding-left 0.2s ease;
  cursor: default;
}
.prose ul li:hover {
  transform: translateX(5px);
  color: var(--ink);
}

/* ---- BTN RIPPLE EFFECT ---- */
.btn-ripple-wow {
  position: absolute;
  border-radius: 50%;
  transform: scale(0);
  background: rgba(248,249,250,0.3);
  pointer-events: none;
  animation: rippleExpand 0.7s linear;
}
@keyframes rippleExpand {
  to { transform: scale(4); opacity: 0; }
}

/* ---- SCROLL-TRIGGERED NUMBER COUNT GLOW ---- */
[data-count-to] {
  display: inline-block;
  transition: text-shadow 0.5s ease;
}
.count-active {
  text-shadow: 0 0 20px rgba(102,197,197,0.5);
}

/* ---- CARD REVEAL SEQUENCE ---- */
.card-grid.stagger-in > .card,
.card-grid.stagger-in > * { transition-delay: calc(var(--card-i, 0) * 90ms); }

/* ---- INNER PAGE: ANIMATED SECTION NUMBERS ---- */
.prose h2 {
  overflow: hidden;
}
.prose h2.anim-up.is-visible { animation: h2SlideIn 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
@keyframes h2SlideIn {
  from { opacity: 0; transform: translateX(-16px); }
  to { opacity: 1; transform: none; }
}

/* ---- PAGE TRANSITION ENHANCED ---- */
.page-entering {
  animation: pageEnterWow 0.55s cubic-bezier(0.25, 1, 0.5, 1) forwards;
}
@keyframes pageEnterWow {
  from { opacity: 0; transform: translateY(28px) scale(0.985); filter: blur(4px); }
  to { opacity: 1; transform: none; filter: blur(0); }
}

/* ---- MOBILE-FRIENDLY: disable cursor glow on touch ---- */
@media (hover: none) {
  #cursor-glow { display: none; }
}

/* ============================================================
   BENTO GRID REDESIGN — Hero + Cards
   ============================================================ */

/* ===== HERO BENTO GRID ===== */
.hero-bento-grid {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.hbg-header-card {
  background: linear-gradient(135deg, #001122 0%, #001122 55%, #001122 100%);
  border-radius: 24px;
  padding: 26px 28px;
  box-shadow: 0 24px 56px rgba(0,17,34,0.26), 0 4px 16px rgba(0,17,34,0.16);
  position: relative;
  overflow: hidden;
}
.hbg-header-card::before {
  content: "";
  position: absolute;
  top: -40%; right: -10%;
  width: 260px; height: 260px;
  background: radial-gradient(circle, rgba(102,197,197,0.12), transparent 65%);
  pointer-events: none;
}

.hbg-header-inner {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.hbg-header-left { flex: 1; }

.hbg-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--cyan);
  background: rgba(102,197,197,0.13);
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid rgba(102,197,197,0.22);
  margin-bottom: 14px;
}

.hbg-header-title {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 800;
  color: #F8F9FA;
  letter-spacing: -0.02em;
  line-height: 1.25;
  margin-bottom: 16px;
}

.hbg-task-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}
.hbg-task {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13px;
  font-weight: 500;
  color: rgba(248,249,250,0.78);
}
.hbg-task-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.hbg-dot-amber {
  background: #FFCC00;
  box-shadow: 0 0 0 3px rgba(255,204,0,0.22);
}
.hbg-dot-cyan {
  background: var(--cyan);
  box-shadow: 0 0 0 3px rgba(102,197,197,0.22);
}

.hbg-header-num {
  font-family: var(--display);
  font-size: 80px;
  font-weight: 800;
  color: rgba(248,249,250,0.05);
  line-height: 1;
  letter-spacing: -0.05em;
  flex-shrink: 0;
  user-select: none;
  align-self: center;
}

/* Stat cards row */
.hbg-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.hbg-stat-card {
  border-radius: 20px;
  padding: 20px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
  overflow: hidden;
  transition: transform 0.22s cubic-bezier(0.25, 1, 0.5, 1), box-shadow 0.22s ease;
}
.hbg-stat-card:hover { transform: translateY(-4px) scale(1.02); }

.hbg-stat-cyan {
  background: linear-gradient(145deg, #66C5C5, #66C5C5);
  box-shadow: 0 10px 28px rgba(102,197,197,0.30);
}
.hbg-stat-navy {
  background: linear-gradient(145deg, #004081, #004081);
  box-shadow: 0 10px 28px rgba(0,64,129,0.28);
}
.hbg-stat-light {
  background: #F8F9FA;
  border: 1px solid var(--line);
  box-shadow: var(--shadow-md);
}

.hbg-big-num {
  font-family: var(--display);
  font-size: 38px;
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1;
}
.hbg-stat-cyan .hbg-big-num,
.hbg-stat-navy .hbg-big-num { color: #F8F9FA; }
.hbg-stat-light .hbg-big-num { color: var(--navy); }

.hbg-stat-label {
  font-size: 11px;
  font-weight: 600;
  line-height: 1.45;
}
.hbg-stat-cyan .hbg-stat-label,
.hbg-stat-navy .hbg-stat-label { color: rgba(248,249,250,0.82); }
.hbg-stat-light .hbg-stat-label { color: var(--muted); }

@media (max-width: 820px) {
  .hero-bento-grid { display: none; }
}

/* ===== PRIORITY TASKS — BENTO BOLD ===== */
.pb-headline {
  font-size: clamp(28px, 4vw, 46px) !important;
  letter-spacing: -0.03em !important;
  line-height: 1.15 !important;
}

.pb-bento {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.pb-card {
  position: relative;
  overflow: hidden;
}

.pb-card-num-bg {
  position: absolute;
  bottom: -18px;
  right: 14px;
  font-family: var(--display);
  font-size: 130px;
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 1;
  pointer-events: none;
  user-select: none;
  z-index: 0;
  transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
}
.pb-card:hover .pb-card-num-bg { transform: translateY(-8px) scale(1.04); }

.pb-card-cal { background: linear-gradient(145deg, #F8F9FA, #F8F9FA) !important; }
.pb-card-cal .pb-card-num-bg { color: rgba(255,204,0,0.09); }

.pb-card-ts { background: linear-gradient(145deg, #F8F9FA, #F8F9FA) !important; }
.pb-card-ts .pb-card-num-bg { color: rgba(0,64,129,0.07); }

/* Ensure card inner content sits above the ghost number */
.pb-card > *:not(.pb-card-num-bg) { position: relative; z-index: 1; }

@media (max-width: 680px) {
  .pb-bento { grid-template-columns: 1fr; }
  .pb-card-num-bg { font-size: 90px; }
}

/* ===== HANDBOOK GROUPS — CATEGORY NUMBERS ===== */
.hb-group-bento {
  position: relative;
  overflow: hidden;
}

.hbg-category-num {
  font-family: var(--display);
  font-size: 52px;
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 1;
  margin-bottom: -6px;
  user-select: none;
  transition: transform 0.35s cubic-bezier(0.25, 1, 0.5, 1), opacity 0.35s ease;
}
.hb-group-bento:hover .hbg-category-num {
  transform: translateX(4px);
}

.hb-group-bento:nth-child(1) .hbg-category-num { color: rgba(102,197,197,0.20); }
.hb-group-bento:nth-child(2) .hbg-category-num { color: rgba(255,204,0,0.16); }
.hb-group-bento:nth-child(3) .hbg-category-num { color: rgba(0,64,129,0.10); }

/* Lift the entire bento group card on hover */
.hb-group-bento {
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}
.hb-group-bento:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: rgba(102,197,197,0.35);
}

/* ===== HERO HEADLINE — BIGGER & BOLDER ===== */
.hero-home .hero h1,
.hero-home h1 {
  font-size: clamp(38px, 5.2vw, 62px) !important;
  font-weight: 800 !important;
  letter-spacing: -0.025em !important;
  line-height: 1.15 !important;
}

/* ============================================================
   DARK HERO v2
