}

/* ===== HERO DASHBOARD CARD ===== */
.hero-dashboard-card {
  background: #F8F9FA;
  border-radius: 22px;
  overflow: hidden;
  box-shadow: 0 32px 80px rgba(0,17,34,0.32), 0 8px 24px rgba(0,17,34,0.18);
}
.hdc-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 18px;
  background: #F8F9FA;
  border-bottom: 1px solid #D0D6DF;
}
.hdc-window-dots { display: flex; gap: 6px; align-items: center; }
.hdc-wd {
  width: 11px; height: 11px;
  border-radius: 50%;
  flex-shrink: 0;
}
.hdc-wd-r { background: #F3554F; }
.hdc-wd-y { background: #FFCC00; }
.hdc-wd-g { background: #82C566; }
.hdc-win-title {
  flex: 1;
  font-size: 12px;
  font-weight: 600;
  color: #929EB4;
  letter-spacing: 0.01em;
}
.hdc-task-count {
  font-size: 11px;
  font-weight: 700;
  color: var(--cyan);
  background: rgba(102,197,197,0.12);
  padding: 3px 9px;
  border-radius: 999px;
}
.hdc-body {
  padding: 18px 18px 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.hdc-task {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 13px 14px;
  border-radius: 14px;
}
.hdc-task-wait {
  background: linear-gradient(135deg, rgba(255,204,0,0.09), rgba(255,204,0,0.04));
  border: 1px solid rgba(255,204,0,0.20);
}
.hdc-task-go {
  background: linear-gradient(135deg, rgba(102,197,197,0.09), rgba(102,197,197,0.04));
