}
.hdc-task-icon-wrap {
  width: 36px; height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.hdc-tw-amber { background: rgba(255,204,0,0.15); color: #707070; }
.hdc-tw-cyan { background: rgba(102,197,197,0.15); color: #586782; }
.hdc-task-info { min-width: 0; }
.hdc-task-name {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: #001122;
  line-height: 1.3;
}
.hdc-task-sub {
  display: block;
  font-size: 11.5px;
  color: var(--muted);
  margin-top: 2px;
}
.hdc-chip {
  font-size: 10.5px;
  font-weight: 700;
  padding: 4px 9px;
  border-radius: 999px;
  white-space: nowrap;
  flex-shrink: 0;
}
.hdc-chip-amber { background: rgba(255,204,0,0.14); color: #707070; border: 1px solid rgba(255,204,0,0.28); }
.hdc-chip-cyan  { background: rgba(102,197,197,0.14); color: #586782; border: 1px solid rgba(102,197,197,0.28); }
.hdc-footer {
  padding: 14px 18px 16px;
  border-top: 1px solid #F8F9FA;
  background: #F8F9FA;
}
.hdc-stats-row {
  display: flex;
  align-items: center;
  justify-content: space-around;
}
.hdc-stat { text-align: center; }
.hdc-stat-n {
  display: block;
  font-family: var(--display);
  font-size: 22px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -0.03em;
  line-height: 1;
}
.hdc-stat-l {
  display: block;
  font-size: 11px;
  color: var(--muted);
  margin-top: 3px;
  font-weight: 500;
}
.hdc-stat-sep {
  width: 1px;
  height: 30px;
  background: #F8F9FA;
}

/* ============================================================
   VERTICAL SCROLL-REVEAL STEPS (Day 1)
   ============================================================ */
.steps-reveal-section {
  padding: 80px 0 100px;
  background: var(--surface);
  border-top: 1px solid var(--line-soft);
}
.srs-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 28px;
}
.srs-header {
  text-align: center;
  margin-bottom: 64px;
}
.srs-steps {
  display: flex;
  flex-direction: column;
  max-width: 860px;
  margin: 0 auto;
}
.srs-step {
  display: grid;
  grid-template-columns: 72px 1fr;
  gap: 28px;
  align-items: flex-start;
}
.srs-step-aside {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 4px;
}
.srs-step-badge {
  width: 52px; height: 52px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  flex-shrink: 0;
  box-shadow: 0 8px 22px rgba(0,17,34,0.14);
  transition: transform 0.3s cubic-bezier(0.25, 1, 0.5, 1);
}
.srs-step:hover .srs-step-badge { transform: scale(1.08); }
.srs-step-badge svg { width: 20px; height: 20px; }
.srs-badge-num {
  position: absolute;
  top: -7px; right: -7px;
  background: #F8F9FA;
  color: var(--ink);
  font-family: var(--display);
  font-size: 9.5px;
  font-weight: 800;
  width: 20px; height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 6px rgba(0,17,34,0.14);
}
.srs-badge-cyan   { background: linear-gradient(135deg, #66C5C5, #66C5C5); color: #F8F9FA; }
.srs-badge-amber  { background: linear-gradient(135deg, #FFCC00, #FFCC00); color: #F8F9FA; }
.srs-badge-navy   { background: linear-gradient(135deg, #004081, #004081); color: #F8F9FA; }
.srs-badge-accent { background: linear-gradient(135deg, #586782, #66C5C5); color: #F8F9FA; }

.srs-step-spine {
  width: 2px;
  flex: 1;
  min-height: 52px;
  background: linear-gradient(to bottom, rgba(102,197,197,0.45), rgba(102,197,197,0.06));
  border-radius: 2px;
  margin-top: 10px;
}

.srs-step-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 28px 32px 26px;
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}
.srs-step-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: rgba(102,197,197,0.40);
}
.srs-step-card-last { margin-bottom: 0; }

.srs-step-meta { margin-bottom: 8px; }
.srs-step-time {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}
.srs-time-urgent { color: #F3554F; }

.srs-step-title {
  font-family: var(--display);
  font-size: clamp(18px, 2.2vw, 22px);
  font-weight: 800;
  color: #001122;
  margin: 4px 0 10px;
  letter-spacing: -0.015em;
  line-height: 1.25;
}
.srs-step-desc {
  font-size: 15px;
  color: #505050;
  line-height: 1.72;
  margin: 0 0 18px;
}
.srs-facts {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  margin-bottom: 16px;
  padding: 12px 16px;
  background: var(--surface-2);
  border-radius: 12px;
}
.srs-fact { display: flex; align-items: baseline; gap: 7px; font-size: 13.5px; }
.srs-fact-k { color: var(--muted); }
.srs-fact-v { color: var(--ink); font-weight: 700; }

.srs-tags {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}
.srs-tag {
  font-size: 12px;
  font-weight: 600;
  padding: 5px 13px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--ink);
  border: 1px solid var(--line);
}
.srs-tag-hot {
  background: rgba(255,204,0,0.12);
  color: #707070;
  border-color: rgba(255,204,0,0.28);
}
.srs-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  color: var(--ink);
  text-decoration: none;
  padding: 10px 20px;
  border-radius: 999px;
  background: #F8F9FA;
  border: 1px solid var(--line);
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.2s ease, box-shadow 0.2s ease;
}
.srs-cta:hover {
  background: rgba(102,197,197,0.08);
  border-color: var(--cyan);
  transform: translateX(4px);
  box-shadow: var(--shadow-sm);
}
@media (max-width: 620px) {
  .srs-step { grid-template-columns: 48px 1fr; gap: 16px; }
  .srs-step-badge { width: 42px; height: 42px; border-radius: 13px; }
  .srs-step-card { padding: 22px 18px; border-radius: 18px; }
  .steps-reveal-section { padding: 56px 0 72px; }
}

