/* ============================================================
   HERO V3 — Clean Split Design
   ============================================================ */
.hero-v3 {
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  min-height: 100vh;
  background: linear-gradient(180deg, #F8F9FA 0%, #F8F9FA 52%, #F8F9FA 100%);
  padding: 24px 0 48px;
}

.hero-v3::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 14% 18%, rgba(102,197,197,0.18), transparent 24%),
    radial-gradient(circle at 82% 14%, rgba(88,103,130,0.14), transparent 22%),
    radial-gradient(circle at 52% 80%, rgba(255,204,0,0.12), transparent 18%);
  opacity: 0.95;
  pointer-events: none;
  z-index: 0;
}

.hero-v3::after {
  content: '';
  position: absolute;
  top: 18%;
  left: -8%;
  width: 260px;
  height: 260px;
  border-radius: 50%;
  background: rgba(248,249,250,0.72);
  filter: blur(18px);
  pointer-events: none;
  z-index: 0;
}

.hero-v3-blob {
  position: absolute;
  top: -80px;
  right: -80px;
  width: 640px;
  height: 640px;
  border-radius: 50%;
  background: radial-gradient(circle at 42% 42%, rgba(102,197,197,0.22) 0%, rgba(0,64,129,0.08) 50%, transparent 74%);
  pointer-events: none;
  z-index: 0;
}

.hero-v3-inner {
  position: relative;
  z-index: 1;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
  box-sizing: border-box;
  padding: 90px 48px 56px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: 64px;
  flex: 1;
}

