  position: absolute;
  inset: 0;
  background: linear-gradient(145deg, rgba(102,197,197,0.16) 0%, rgba(248,249,250,0.85) 100%);
  border-radius: 34px;
  z-index: 0;
}

/* Extra decorative ring inside right panel */
.hero-v3-right::after {
  content: '';
  position: absolute;
  bottom: -44px;
  right: -44px;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  border: 2px dashed rgba(102,197,197,0.30);
  z-index: 0;
  pointer-events: none;
}

.hero-v3-right .hero-dashboard-card {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 420px;
}

/* ——— BOTTOM STRIPE DIVIDER ——— */
.hero-v3-stripe {
  height: 8px;
  background: linear-gradient(90deg, #66C5C5 0%, #586782 48%, #004081 100%);
  flex-shrink: 0;
  width: 100%;
  align-self: stretch;
}

/* ——— RESPONSIVE ——— */
@media (max-width: 900px) {
  .hero-v3-inner {
    grid-template-columns: 1fr;
    padding: 110px 28px 56px;
    gap: 40px;
  }
  .hero-v3-right {
    padding: 28px 20px;
  }
  .hero-v3-stats {
    width: 100%;
    justify-content: space-between;
  }
  .hero-v3-stat { padding: 0 16px; }
}

@media (max-width: 520px) {
  .hero-v3-inner { padding: 96px 18px 48px; gap: 32px; }
  .hero-v3-h1 { font-size: clamp(32px, 10vw, 42px); }
  .hero-v3-stat-n { font-size: 26px; }
  .hero-v3-stat { padding: 0 10px; }
  .hero-v3-lead { font-size: 15px; }
}

/* ============================================================
   HERO-V3 DOT — force inline-flex so div.hero-word doesn't
   break the pill layout (div.hero-word sets display:block)
   ============================================================ */
.hero-v3-eyebrow { display: inline-flex !important; }
.hero-v3-dot { display: inline-block; flex-shrink: 0; }

/* ============================================================
   HTP — Clean hero task panel header (no Mac window dots)
   ============================================================ */
.htp-header {
  background: rgba(0,64,129,0.03) !important;
  border-bottom: 1px solid var(--line-soft) !important;
}
.htp-label-wrap {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 700;
  color: var(--ink);
  flex: 1;
  letter-spacing: 0.02em;
}
.htp-label-wrap svg { color: var(--cyan); flex-shrink: 0; }

/* ============================================================
   PRIORITY BENTO — equal card heights via grid stretch
   ============================================================ */
.pb-bento { align-items: stretch; }
.ptask-card { box-sizing: border-box; }

/* ============================================================
   ORG CHART V2 — base oc-dept-card + c6–c9 color variants
   ============================================================ */
.oc-dept-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.oc-dept-icon {
  width: 40px; height: 40px;
  border-radius: 11px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.oc-c1 .oc-dept-icon { background: rgba(102,197,197,0.14); color: #586782; }
.oc-c2 .oc-dept-icon { background: rgba(88,103,130,0.12);  color: #586782; }
.oc-c3 .oc-dept-icon { background: rgba(243,85,79,0.12);   color: #F3554F; }
.oc-c4 .oc-dept-icon { background: rgba(88,103,130,0.12);  color: #004081; }
.oc-c5 .oc-dept-icon { background: rgba(0,64,129,0.10);    color: var(--navy); }
.oc-c6 .oc-dept-icon { background: rgba(146,158,180,0.12); color: #586782; }
.oc-c7 .oc-dept-icon { background: rgba(243,85,79,0.12); color: #F3554F; }
.oc-c8 .oc-dept-icon { background: rgba(102,197,197,0.12);  color: #004081; }
.oc-c9 .oc-dept-icon { background: rgba(102,197,197,0.12);  color: #505050; }
.oc-c6::before { background: linear-gradient(90deg, #929EB4, #586782); }
.oc-c7::before { background: linear-gradient(90deg, #F3554F, #F3554F); }
.oc-c8::before { background: linear-gradient(90deg, #66C5C5, #004081); }
.oc-c9::before { background: linear-gradient(90deg, #66C5C5, #586782); }

/* ============================================================
   SHIFT ROW — Internship Policy schedule (replaces timelines)
   ============================================================ */
.shift-row {
  display: flex;
  align-items: stretch;
  gap: 12px;
  margin: 20px 0 32px;
}
.shift-item {
  flex: 1;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.shift-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.shift-time {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -0.02em;
  line-height: 1.2;
}
.shift-noon {
  font-size: 12px;
  color: var(--muted);
}
.shift-divider {
  display: flex;
  align-items: center;
  font-size: 12px;
  font-weight: 700;
  color: var(--muted);
  flex-shrink: 0;
}
@media (max-width: 480px) {
  .shift-row { flex-direction: column; }
  .shift-divider { justify-content: center; }
}

/* ============================================================
   SHOWCASE — platform link card (slc-*)
   ============================================================ */
.showcase-real-grid { align-items: start; }
.show-real-media-link {
  min-height: 0 !important;
  padding: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  background: transparent !important;
}
.slc-header-facebook { background: linear-gradient(135deg, #586782 0%, #004081 100%); }
.slc-header-medium   { background: linear-gradient(135deg, #001122 0%, #586782 100%); }
.slc-header-default  { background: var(--ci-navy); }
.slc-platform-row {
  position: absolute;
  top: 0;
  left: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: auto;
  min-width: 34px;
  height: 22px;
  padding: 0 8px;
  border: 1px solid rgba(248,249,250,.18);
  border-top: 0;
  border-left: 0;
  border-radius: 0 0 9px 0;
  background: rgba(0,17,34,.58);
  box-shadow: 0 7px 18px rgba(0,17,34,.18);
  backdrop-filter: blur(8px) saturate(1.05);
  -webkit-backdrop-filter: blur(8px) saturate(1.05);
  z-index: 2;
}
.slc-platform-label {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  line-height: 1;
  color: rgba(248,249,250,0.96);
  text-shadow: 0 1px 3px rgba(0,17,34,.45);
}
.slc-headline {
  font-size: 14.5px;
  font-weight: 700;
  line-height: 1.45;
  color: #F8F9FA;
  margin: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.slc-preview-strip {
  padding: 13px 20px 15px;
  background: var(--surface);
  border-bottom: 1px solid var(--line-soft);
}
.slc-preview-strip p {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--muted);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* showcase card — photo cover variant */
.slc-photo {
  position: relative;
  height: 200px;
  overflow: hidden;
  flex-shrink: 0;
  /* fallback bg shown when image fails or not set */
  background: linear-gradient(135deg, #0d2540 0%, #004081 100%);
  isolation: isolate;
}
.slc-photo-empty {
  background:
    radial-gradient(circle at 78% 20%, rgba(102,197,197,.14), transparent 34%),
    linear-gradient(135deg, #004081 0%, #002a56 58%, #001122 100%);
}
.show-real-media-medium .slc-photo {
  background: linear-gradient(135deg, #0d1826 0%, #1a2a40 100%);
}
.slc-photo-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
  display: block;
  filter: saturate(0.94) contrast(1.04) brightness(0.98);
  transition: transform .55s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
@media (prefers-reduced-motion: reduce) {
  .slc-photo-img { transition: none; }
}
.show-real-card:hover .slc-photo-img {
  transform: scale(1.07);
}
.slc-photo-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 14px 16px 15px;
  /* stronger bottom fade for text readability */
  background:
    radial-gradient(circle at 18% 6%, rgba(255,255,255,.30), transparent 32%),
    linear-gradient(to bottom,
      rgba(0,10,26,.46) 0%,
      rgba(0,10,26,.08) 32%,
      rgba(0,10,26,.0)  50%,
      rgba(0,10,26,.55) 72%,
      rgba(0,10,26,.88) 100%);
  z-index: 1;
}
.slc-overlay-facebook {
  background:
    radial-gradient(circle at 14% 8%, rgba(102,197,197,.26), transparent 34%),
    linear-gradient(to bottom,
      rgba(0,30,72,.54) 0%,
      rgba(0,30,72,.12) 30%,
      rgba(0,30,72,.0)  48%,
      rgba(0,50,100,.60) 72%,
      rgba(0,64,129,.90) 100%);
}
.slc-overlay-medium {
  background:
    radial-gradient(circle at 14% 8%, rgba(102,197,197,.18), transparent 34%),
    linear-gradient(to bottom,
      rgba(0,0,0,.48) 0%,
      rgba(0,0,0,.12) 30%,
      rgba(0,0,0,.0)  48%,
      rgba(0,10,24,.62) 72%,
      rgba(0,10,24,.92) 100%);
}
.slc-photo-overlay .slc-platform-label {
  text-shadow: 0 1px 3px rgba(0,0,0,.5);
}
/* headline at bottom of photo */
.slc-photo-overlay .slc-headline {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.4;
  color: #fff;
  text-shadow: 0 1px 6px rgba(0,0,0,.6);
  margin: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* =========================================================
   NEW HOME PAGE — Handbook Landing
   ========================================================= */

/* ----- Hero ----- */
.hm-hero {
  position: relative;
  overflow: hidden;
  padding: calc(var(--nav-h) + 72px) 0 80px;
  background: var(--bg);
}
.hm-hero-blob {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 55% at 65% 30%, rgba(102,197,197,0.13) 0%, transparent 70%),
              radial-gradient(ellipse 40% 40% at 20% 70%, rgba(0,64,129,0.06) 0%, transparent 60%);
  pointer-events: none;
}
.hm-hero-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 32px;
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 56px;
  align-items: center;
}
.hm-hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 20px;
}
.hm-hero-h1 {
  font-family: var(--display);
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  font-weight: 800;
  line-height: 1.18;
  color: var(--ink);
  margin: 0 0 20px;
  display: flex;
  flex-direction: column;
}
.hm-hero-accent {
  color: var(--ci-navy);
}
.hm-hero-lead {
  font-size: 16px;
  line-height: 1.75;
  color: var(--muted);
  max-width: 480px;
  margin: 0 0 32px;
}
.hm-hero-cta {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  align-items: center;
  margin-bottom: 28px;
}

/* Handbook overview card */
.hm-overview-card {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}
.hm-ov-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 20px;
  background: var(--surface-2);
  border-bottom: 1px solid var(--line);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--navy);
}
.hm-ov-list {
  padding: 8px 0;
}
.hm-ov-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 20px;
  font-size: 14px;
  color: var(--ink);
  border-bottom: 1px solid var(--line-soft);
  transition: background .15s;
}
.hm-ov-item:last-child { border-bottom: none; }
.hm-ov-item-day1 { background: rgba(102,197,197,0.06); }
.hm-ov-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.hm-ov-dot-cyan   { background: var(--cyan); }
.hm-ov-dot-amber  { background: #FFCC00; }
.hm-ov-dot-navy   { background: var(--navy); }
.hm-ov-dot-accent { background: #929EB4; }
.hm-ov-label { flex: 1; }
.hm-ov-badge {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 20px;
}
.hm-ov-badge-new {
  background: rgba(102,197,197,0.18);
  color: #586782;
}

/* ----- Day 1 Banner ----- */
.hm-day1-banner {
  background: linear-gradient(90deg, rgba(102,197,197,0.10) 0%, rgba(0,64,129,0.07) 100%);
  border-top: 1px solid rgba(102,197,197,0.25);
  border-bottom: 1px solid rgba(102,197,197,0.25);
}
.hm-day1-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 18px 32px;
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.hm-day1-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--cyan);
  color: #F8F9FA;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.hm-day1-text {
  flex: 1;
  min-width: 200px;
  font-size: 14px;
  color: var(--ink);
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  align-items: center;
}
.hm-day1-text strong { font-weight: 700; color: var(--navy); }
.hm-day1-text span { color: var(--muted); }
.hm-day1-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  background: var(--navy);
  color: #F8F9FA;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
  transition: opacity .15s, transform .15s;
}
.hm-day1-btn:hover { opacity: .88; transform: translateX(2px); }

/* ----- Sections Grid ----- */
.hm-sections {
  padding: 88px 0 80px;
  background: var(--surface);
}
.hm-sections-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 32px;
}
.hm-sections-header {
  text-align: center;
  margin-bottom: 52px;
}
.hm-sections-title {
  font-family: var(--display);
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  font-weight: 800;
  color: var(--ink);
  margin: 8px 0 12px;
}
.hm-sections-sub {
  font-size: 15px;
  color: var(--muted);
  margin: 0;
}

.hm-cat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.hm-cat-card {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 24px;
  position: relative;
  text-decoration: none;
  color: inherit;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: box-shadow .2s, transform .2s, border-color .2s;
}
.hm-cat-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
  border-color: var(--cyan);
}
.hm-cat-num {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .12em;
  color: var(--muted);
  opacity: .6;
}
.hm-cat-icon-wrap {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hm-ci-cyan   { background: rgba(102,197,197,0.15); color: #586782; }
.hm-ci-amber  { background: rgba(255,204,0,0.15);  color: #707070; }
.hm-ci-navy   { background: rgba(0,64,129,0.10);    color: var(--navy); }
.hm-ci-accent { background: rgba(146,158,180,0.12);  color: #586782; }

.hm-cat-body { display: flex; flex-direction: column; gap: 4px; }
.hm-cat-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--ink);
}
.hm-cat-desc {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.55;
}
.hm-cat-links {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 4px;
}
.hm-cat-links a {
  font-size: 13px;
  font-weight: 600;
  color: var(--navy);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 0;
  border-top: 1px solid var(--line-soft);
  transition: color .15s, gap .15s;
}
.hm-cat-links a:hover { color: var(--cyan); gap: 8px; }
.hm-cat-links a svg { opacity: .7; }

/* Day 1 card special style */
.hm-cat-day1 {
  border-color: rgba(102,197,197,0.4);
  background: linear-gradient(135deg, rgba(102,197,197,0.05) 0%, rgba(0,64,129,0.04) 100%);
}
.hm-cat-day1:hover { border-color: var(--cyan); }

.hm-cat-tag {
  position: absolute;
  top: 16px;
  right: 16px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
  padding: 3px 9px;
  border-radius: 20px;
}
.hm-cat-tag-hot {
  background: var(--cyan);
  color: #F8F9FA;
}
.hm-cat-arr {
  margin-top: auto;
  color: var(--cyan);
  display: flex;
  align-items: center;
}

/* ----- About section ----- */
.hm-about {
  padding: 88px 0;
  background: var(--bg);
}
.hm-about-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 32px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: start;
}
.hm-about-title {
  font-family: var(--display);
  font-size: clamp(1.6rem, 2.5vw, 2.2rem);
  font-weight: 800;
  color: var(--ink);
  margin: 10px 0 16px;
  line-height: 1.2;
}
.hm-about-body {
  font-size: 15px;
  color: var(--muted);
  line-height: 1.75;
  margin: 0 0 32px;
}
.hm-about-facts {
  display: flex;
  gap: 32px;
}
.hm-about-fact {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.hm-af-num {
  font-family: var(--display);
  font-size: 2rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1;
}
.hm-af-label {
  font-size: 12px;
  color: var(--muted);
  font-weight: 500;
}

/* Quick links */
.hm-quicklinks {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.hm-ql-head {
  padding: 14px 20px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--muted);
  background: var(--surface-2);
  border-bottom: 1px solid var(--line);
}
.hm-ql-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  text-decoration: none;
  color: var(--ink);
  font-size: 14px;
  border-bottom: 1px solid var(--line-soft);
  transition: background .15s, padding-left .15s;
}
.hm-ql-item:last-child { border-bottom: none; }
.hm-ql-item:hover { background: rgba(102,197,197,0.06); padding-left: 24px; }
.hm-ql-icon { color: var(--cyan); flex-shrink: 0; display: flex; }
.hm-ql-item span:nth-child(2) { flex: 1; }
.hm-ql-arr { color: var(--muted); opacity: .5; transition: opacity .15s, transform .15s; }
.hm-ql-item:hover .hm-ql-arr { opacity: 1; transform: translateX(3px); }

/* ----- First Day → Handbook bridge section ----- */
.fd-next-section {
  padding: 72px 0;
  background: var(--surface);
}
.fd-next-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 32px;
  text-align: center;
}
.fd-next-content { display: inline-flex; flex-direction: column; align-items: center; gap: 12px; }
.fd-next-title {
  font-family: var(--display);
  font-size: clamp(1.6rem, 2.5vw, 2.2rem);
  font-weight: 800;
  color: var(--ink);
  margin: 8px 0;
}
.fd-next-sub {
  font-size: 15px;
  color: var(--muted);
  margin: 0 0 12px;
