/* ================================================================
   DESIGN SYSTEM V2 — Premium UX Upgrade
   Per-page unique identities + glassmorphism + micro-interactions
   ================================================================ */

/* ── Section accent colour theming ── */
:root {
  --sec: #66C5C5;
  --sec-soft: rgba(102,197,197,0.10);
  --sec-mid: rgba(102,197,197,0.30);
}
[data-section="getting-started"] { --sec:#66C5C5; --sec-soft:rgba(102,197,197,.10); --sec-mid:rgba(102,197,197,.30); }
[data-section="first-day"]       { --sec:#66C5C5; --sec-soft:rgba(102,197,197,.10); --sec-mid:rgba(102,197,197,.30); }
[data-section="company"]         { --sec:#FFCC00; --sec-soft:rgba(255,204,0,.10);  --sec-mid:rgba(255,204,0,.30); }
[data-section="policy"]          { --sec:#66C5C5; --sec-soft:rgba(102,197,197,.10);  --sec-mid:rgba(102,197,197,.30); }
[data-section="resources"]       { --sec:#929EB4; --sec-soft:rgba(146,158,180,.10);  --sec-mid:rgba(146,158,180,.30); }
[data-section="showcase"]        { --sec:#F3554F; --sec-soft:rgba(243,85,79,.10);  --sec-mid:rgba(243,85,79,.30); }

/* ── Redesigned page hero band ── */
.page-hero-band {
  position: relative;
  overflow: hidden;
  padding: calc(var(--nav-h) + 18px) 0 22px;
  background: var(--bg);
  border-bottom: 1px solid var(--line);
  isolation: isolate;
}
.page-hero-band::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 55% 80% at 92% 50%, var(--sec-soft) 0%, transparent 70%),
    radial-gradient(ellipse 30% 50% at 10% 80%, rgba(0,64,129,.04) 0%, transparent 60%);
  pointer-events: none;
  z-index: 0;
}
/* Grid dot pattern overlay */
.page-hero-band::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(0,64,129,0.06) 1px, transparent 1px);
  background-size: 28px 28px;
  pointer-events: none;
  z-index: 0;
  mask-image: radial-gradient(ellipse 80% 60% at 80% 50%, black 0%, transparent 70%);
  -webkit-mask-image: radial-gradient(ellipse 80% 60% at 80% 50%, black 0%, transparent 70%);
}
.phb-inner { position: relative; z-index: 1; max-width: var(--maxw); margin: 0 auto; padding: 0 32px; }
.phb-deco-num {
  position: absolute;
  right: -24px;
  top: 50%;
  transform: translateY(-50%);
  font-size: clamp(100px,14vw,200px);
  font-weight: 900;
  font-family: var(--display);
  letter-spacing: -0.05em;
  line-height: 1;
  color: var(--ci-navy);
  opacity: 0.06;
  pointer-events: none;
  user-select: none;
  z-index: 0;
}
.phb-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--sec);
  background: var(--sec-soft);
  border: 1px solid var(--sec-mid);
  padding: 3px 11px;
  border-radius: 20px;
  margin-bottom: 10px;
}
.phb-eyebrow svg { color: var(--sec); }
.phb-title {
  font-family: var(--display);
  font-size: clamp(1.5rem,3.5vw,2.4rem);
  font-weight: 800;
  color: var(--ink);
  line-height: 1.15;
  margin: 0 0 10px;
  max-width: 760px;
  position: relative;
}
.phb-title::after {
  content: '';
  display: block;
  width: 40px;
  height: 3px;
  background: linear-gradient(90deg, var(--sec), transparent);
  border-radius: 2px;
  margin-top: 10px;
}
.phb-lead {
  font-size: 14.5px;
  line-height: 1.7;
  color: var(--muted);
  max-width: 620px;
  margin: 0;
}

/* ── Redesigned breadcrumb ── */
.breadcrumb { font-size: 12.5px; color: var(--muted); display: flex; align-items: center; flex-wrap: wrap; gap: 2px; }
.breadcrumb a { color: var(--sec); text-decoration: none; font-weight: 600; transition: opacity .15s; white-space: nowrap; }
.breadcrumb a:hover { opacity: .75; }
.breadcrumb-sep { color: var(--line); padding: 0 4px; white-space: nowrap; }
.breadcrumb-cur { color: var(--ink); font-weight: 600; white-space: nowrap; }
.breadcrumb > span { white-space: nowrap; }

/* ── Enhanced prose ── */
.prose h2 {
  font-family: var(--display);
  font-size: clamp(1.25rem,2.2vw,1.7rem);
  font-weight: 800;
  color: var(--ink);
  margin: 52px 0 16px;
  padding-bottom: 0;
  line-height: 1.25;
  position: relative;
}
.prose h2::after {
  content: none;
}
.prose h2:first-child { margin-top: 0; }
.prose h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--ink);
  margin: 28px 0 10px;
}
.prose p { font-size: 15px; line-height: 1.8; color: #505050; margin: 0 0 16px; }
.prose ul { padding-left: 0; margin: 0 0 20px; list-style: none; }
.prose ul li {
  padding: 6px 0 6px 24px;
  position: relative;
  font-size: 15px;
  line-height: 1.7;
