}
.prose ul li:last-child { border-bottom: none; }
.prose ul li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 14px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--sec);
  opacity: .7;
}
.inline-link { color: var(--sec); font-weight: 600; text-decoration: none; border-bottom: 1px solid var(--sec-mid); transition: border-color .15s; }
.inline-link:hover { border-color: var(--sec); }

/* ── Callout V2 ── */
.callout {
  display: flex;
  gap: 14px;
  padding: 18px 20px;
  border-radius: var(--radius);
  background: var(--sec-soft);
  border: 1px solid var(--line);
  margin: 24px 0;
  align-items: flex-start;
}
.callout .ic { color: var(--sec); flex-shrink: 0; margin-top: 1px; }
.callout h4 { font-size: 14px; font-weight: 700; color: var(--ink); margin: 0 0 4px; }
.callout p  { font-size: 14px; color: var(--muted); margin: 0; line-height: 1.65; }
.callout-warn { background: rgba(255,204,0,0.10); }
.callout-warn .ic { color: #FFCC00; }
.callout-note { background: var(--sec-soft); }
.callout-note .ic { color: #66C5C5; }

/* ── Glass card ── */
.glass-card {
  background: rgba(248,249,250,0.75);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid rgba(248,249,250,0.9);
  box-shadow: 0 8px 32px rgba(0,64,129,0.08), 0 2px 8px rgba(0,17,34,0.04);
  border-radius: var(--radius-lg);
}

/* ── Gradient border card ── */
.grad-border-card {
  position: relative;
  border-radius: var(--radius);
  background: var(--bg);
}
.grad-border-card::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: calc(var(--radius) + 1px);
  background: var(--ci-teal);
  z-index: -1;
  opacity: 0;
  transition: opacity .25s;
}
.grad-border-card:hover::before { opacity: 1; }

/* ── Accent pill (small colored tag) ── */
.accent-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 20px;
  background: var(--sec-soft);
  color: var(--sec);
  border: 1px solid var(--sec-mid);
}

/* ── Stat row ── */
.stat-row {
  display: flex;
  gap: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg);
  margin: 32px 0;
}
.stat-row-item {
  flex: 1;
  padding: 24px 20px;
  text-align: center;
  border-right: 1px solid var(--line);
  position: relative;
  transition: background .2s;
}
.stat-row-item:last-child { border-right: none; }
.stat-row-item:hover { background: var(--sec-soft); }
.stat-num {
  font-family: var(--display);
  font-size: clamp(2rem,3.5vw,2.8rem);
  font-weight: 900;
  color: var(--sec);
  display: block;
  line-height: 1;
  margin-bottom: 6px;
}
.stat-label { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .1em; }

/* ── Section label chip ── */
.section-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 100px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  background: var(--sec-soft);
  color: var(--sec);
  border: 1px solid var(--sec-mid);
  margin-bottom: 12px;
}

/* ─────────────── HOME V2 ─────────────── */
.hm-hero {
  position: relative;
