.fd-btn-primary { padding:12px 28px; border-radius:var(--radius-sm); background:var(--cyan); color:#F8F9FA; font-size:14px; font-weight:700; text-decoration:none; display:inline-flex; align-items:center; gap:8px; transition:transform .15s, box-shadow .15s; box-shadow:0 4px 16px rgba(102,197,197,0.4); }
