.fd-prog-bar-wrap { height: 6px; background: rgba(248,249,250,0.15); border-radius: 3px; overflow: hidden; margin-bottom: 12px; }
.fd-prog-bar { height: 100%; background: linear-gradient(90deg, var(--cyan), #586782); border-radius: 3px; transition: width 1s ease; }
.fd-prog-tasks { display: flex; flex-direction: column; gap: 10px; margin-top: 16px; }
.fd-prog-task { display: flex; align-items: center; gap: 10px; font-size: 13px; color: rgba(248,249,250,.8); }
.fd-prog-check { width: 20px; height: 20px; border-radius: 50%; border: 2px solid rgba(248,249,250,.3); flex-shrink: 0; display: flex; align-items: center; justify-content: center; transition: all .3s; }
.fd-prog-check.done { background: var(--cyan); border-color: var(--cyan); }
.fd-prog-check.done svg { display: block; }
