}
.fd-cc-body { flex: 1; }
.fd-cc-num { font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-bottom: 6px; }
.fd-cc-title { font-size: 17px; font-weight: 700; color: var(--ink); margin: 0 0 8px; line-height: 1.3; }
.fd-cc-desc { font-size: 14px; color: var(--muted); line-height: 1.65; margin: 0; }

/* Celebration state */
