}
.fd-all-done.visible { display: block; }
.fd-all-done-emoji { font-size: 3rem; margin-bottom: 12px; }
.fd-all-done h3 { font-size: 1.5rem; font-weight: 800; color: var(--ink); margin: 0 0 8px; }
.fd-all-done p { color: var(--muted); font-size: 15px; margin: 0; }

/* Day 1 Timeline V2 */
.fd-timeline { display: flex; flex-direction: column; gap: 0; margin: 40px 0; }
.fd-tl-item { display: flex; gap: 0; }
.fd-tl-aside { display: flex; flex-direction: column; align-items: center; width: 64px; flex-shrink: 0; }
.fd-tl-node {
  width: 48px; height: 48px;
  border-radius: 50%;
