}
.fd-tl-card:hover { box-shadow: var(--shadow-md); transform: translateX(3px); }
.fd-tl-time { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; display: flex; align-items: center; gap: 5px; }
.fd-tl-time.urgent { color: #F3554F; }
.fd-tl-title { font-size: 18px; font-weight: 700; color: var(--ink); margin: 0 0 8px; }
.fd-tl-desc { font-size: 14px; color: var(--muted); line-height: 1.65; margin: 0 0 12px; }
.fd-tl-facts { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 10px; }
.fd-tl-fact { font-size: 12.5px; color: var(--muted); display: flex; gap: 4px; }
.fd-tl-fact strong { color: var(--ink); }
.fd-tl-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.fd-tl-tag { font-size: 11px; font-weight: 600; padding: 2px 9px; border-radius: 20px; background: var(--surface-2); color: var(--muted); }
