  isolation: isolate;
}
.wifi-glass-wrap::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 80% 50%, rgba(102,197,197,0.15) 0%, transparent 60%),
    radial-gradient(ellipse 40% 60% at 20% 30%, rgba(0,64,129,0.3) 0%, transparent 60%);
