}
@keyframes spin-ring { to { transform: rotate(360deg); } }
.wifi-qr-ring-inner { width: 100%; height: 100%; background: rgba(248,249,250,0.95); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; overflow: hidden; position: relative; z-index: 1; }
.wifi-qr-ring-inner .wifi-qr { width: 100%; height: 100%; }
.wifi-qr-cap { font-size: 11px; color: rgba(248,249,250,.6); text-align: center; font-weight: 600; letter-spacing: .06em; }
.wifi-details { color: #F8F9FA; }
.wifi-detail-row { margin-bottom: 18px; }
.wifi-dl { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: rgba(248,249,250,.5); margin-bottom: 6px; }
.wifi-dv { font-size: 17px; font-weight: 700; color: #F8F9FA; display: flex; align-items: center; gap: 10px; }
.wifi-pass-dots { font-size: 22px; letter-spacing: .2em; color: rgba(248,249,250,.6); }
.wifi-action-row { display: flex; gap: 10px; margin-top: 24px; flex-wrap: wrap; }
.wifi-copy-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 10px 18px;
  border-radius: var(--radius-sm);
  background: rgba(248,249,250,0.1);
  border: 1px solid rgba(248,249,250,0.2);
  color: #F8F9FA;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s;
}
.wifi-copy-btn:hover { background: rgba(248,249,250,0.18); }
.wifi-copy-btn.is-copied { background: rgba(102,197,197,0.3); border-color: var(--cyan); }
.wifi-cta-btn { padding: 10px 22px; border-radius: var(--radius-sm); background: var(--cyan); color: #F8F9FA; font-size: 13px; font-weight: 700; cursor: pointer; border: none; display: inline-flex; align-items: center; gap: 7px; transition: opacity .15s; }
.wifi-cta-btn:hover { opacity: .85; }

/* ─────────────── CORE VALUES V2 ─────────────── */
.cv-wrap { display: flex; flex-direction: column; gap: 24px; }

/* ── Card shell ──────────────────────────────────────────────── */
.cv-card {
  border-radius: var(--radius);
  border: 1px solid color-mix(in srgb, var(--cv-head, #004081) 20%, var(--line));
  background: color-mix(in srgb, var(--cv-head, #004081) 3%, var(--bg));
  overflow: hidden;
  transition: box-shadow .25s, transform .25s;
}
.cv-card:hover {
  box-shadow: 0 12px 36px color-mix(in srgb, var(--cv-head, #004081) 18%, transparent);
  transform: translateY(-3px);
}

/* ── Card head — solid dark band, white text ─────────────────── */
.cv-card-head {
  padding: 22px 32px 20px;
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 24px;
  background: var(--cv-head, #004081);
}

/* ── Number column ───────────────────────────────────────────── */
.cv-card-num-col {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 76px;
  height: 68px;
  border-radius: 14px;
  background: rgba(102,197,197,0.18);
  border: 1px solid rgba(102,197,197,0.32);
  flex-shrink: 0;
}
.cv-card-big-num {
  font-family: var(--display);
  font-size: 2.6rem;
  font-weight: 900;
  line-height: 1;
  color: #66C5C5;
  letter-spacing: -0.04em;
}

/* ── Text in head — always white on dark bg ──────────────────── */
.cv-card-text-col { flex: 1; }
.cv-card-name {
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  font-weight: 800;
  color: #ffffff;
  margin: 0 0 5px;
  letter-spacing: -0.01em;
}
.cv-card-tagline {
  font-size: 13.5px;
  color: rgba(255,255,255,0.68) !important;
  line-height: 1.65;
  margin: 0;
}

/* ── Body grid ───────────────────────────────────────────────── */
.cv-card-body {
  padding: 20px 32px 24px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

/* ── Points ──────────────────────────────────────────────────── */
.cv-point {
  background: color-mix(in srgb, var(--cv-head, #004081) 5%, var(--bg));
  border: 1px solid color-mix(in srgb, var(--cv-head, #004081) 16%, var(--line));
  border-radius: var(--radius-sm);
  padding: 14px 14px 13px;
}
.cv-point-k {
  display: block;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .07em;
  text-transform: uppercase;
  margin-bottom: 5px;
  color: var(--cv-head, #004081);
}
.cv-point-v { font-size: 13px; color: var(--body); line-height: 1.55; opacity: .82; }

/* ── Per-card dark head colors (all navy/slate, all ≥ 6:1 on white) ── */
.cv-c1 { --cv-head: #004081; }   /* Brand navy */
.cv-c2 { --cv-head: #1C3A5C; }   /* Midnight blue */
.cv-c3 { --cv-head: #2E3D54; }   /* Dark blue-slate */
.cv-c4 { --cv-head: #3A5270; }   /* Slate-blue */
.cv-c5 { --cv-head: #001122; }   /* Deep navy */

/* ─────────────── TIMESHEET VISUAL ─────────────── */
.ts-hero-banner {
  background: linear-gradient(135deg, #001122 0%, #001122 55%, #004081 100%);
