.mr-v2-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.mr-v2-tag { font-size: 11.5px; font-weight: 600; padding: 3px 10px; border-radius: 6px; background: var(--surface-2); color: var(--muted); }
.mr-v2-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.mr-v2-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: box-shadow .2s, transform .2s;
}
.mr-v2-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.mr-v2-card-vis { background: linear-gradient(135deg, #F8F9FA, #F8F9FA); padding: 16px; }
.mr-room-photo {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  object-position: center;
  border-radius: 10px;
}
.mr-room-photo-sm {
  min-height: 180px;
}
.mr-room-gallery {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: thin;
  scrollbar-color: rgba(102, 197, 197, .75) transparent;
  padding-bottom: 4px;
}
.mr-room-gallery::-webkit-scrollbar {
  height: 6px;
}
.mr-room-gallery::-webkit-scrollbar-track {
  background: transparent;
}
.mr-room-gallery::-webkit-scrollbar-thumb {
  background: rgba(102, 197, 197, .75);
  border-radius: 999px;
}
.mr-room-gallery .mr-room-photo {
  flex: 0 0 100%;
  scroll-snap-align: center;
}
.mr-room-gallery-dots {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-top: 8px;
}
.mr-room-gallery-dots span {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: rgba(0, 64, 128, .22);
}
.mr-room-gallery-dots span:first-child {
  background: var(--cyan);
}
.mr-v2-card-body { padding: 16px 18px; }
.mr-v2-card-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; gap: 8px; flex-wrap: wrap; }
.mr-v2-card-name { font-size: 14px; font-weight: 700; color: var(--ink); }
.mr-v2-card-name span { color: var(--cyan); }
.mr-v2-cap { font-size: 12.5px; color: var(--muted); display: flex; align-items: center; gap: 4px; margin-bottom: 6px; }
.mr-v2-card-desc { font-size: 12.5px; color: var(--muted); line-height: 1.55; margin-bottom: 8px; }

/* ─────────────── ORG CHART V2 ─────────────── */
.oc-company-card {
  background: linear-gradient(135deg, var(--navy) 0%, #004081 100%);
  border-radius: var(--radius-lg);
  padding: 36px;
  color: #F8F9FA;
  text-align: center;
  position: relative;
  overflow: hidden;
  margin-bottom: 0;
}
.oc-company-card-sm {
  max-width: 480px;
  margin: 0 auto;
  padding: 24px 32px;
  border-radius: 14px;
}
.oc-company-card-sm .oc-company-name { font-size: clamp(1.2rem,2.5vw,1.7rem); margin-bottom: 6px; }
.oc-company-card-sm .oc-company-tagline { font-size: 12.5px; }
.oc-company-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 80% at 50% 120%, rgba(102,197,197,0.2) 0%, transparent 60%);
  pointer-events: none;
}
.oc-company-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .15em; text-transform: uppercase; color: rgba(248,249,250,.55); margin-bottom: 8px; }
.oc-company-name { font-family: var(--display); font-size: clamp(1.6rem,3vw,2.4rem); font-weight: 900; margin-bottom: 8px; }
.oc-company-tagline { font-size: 14px; color: rgba(248,249,250,.65); font-style: italic; }
.oc-connector { display: flex; flex-direction: column; align-items: center; gap: 0; padding: 16px 0 0; }
.oc-connector-stem { width: 2px; height: 32px; background: linear-gradient(to bottom, var(--navy), var(--line)); }
.oc-connector-branch { width: 80%; height: 2px; background: var(--line); }
.oc-dept-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; padding-top: 16px; }
.oc-dept-v2 {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: box-shadow .2s, transform .2s, border-color .2s;
  position: relative;
  overflow: hidden;
}
.oc-dept-v2::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--dv-color, var(--cyan)); }
.oc-dept-v2:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); border-color: var(--dv-color, var(--cyan)); }
.oc-dept-v2-icon { width: 40px; height: 40px; border-radius: 10px; display: flex; align-items: center; justify-content: center; background: rgba(var(--dv-rgb,102,197,197),.1); color: var(--dv-color, var(--cyan)); }
.oc-dept-v2-abbr { font-size: 9.5px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--dv-color, var(--cyan)); }
.oc-dept-v2-name { font-size: 14px; font-weight: 700; color: var(--ink); line-height: 1.3; }
.oc-dept-v2-desc { font-size: 12px; color: var(--muted); line-height: 1.55; }

/* ─────────────── DRESS CODE V2 ─────────────── */
.dress-hero-v2 {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 40px;
  align-items: center;
  background: linear-gradient(135deg, #F8F9FA 0%, #F8F9FA 100%);
  border-radius: var(--radius-lg);
  padding: 36px 40px;
  margin-bottom: 40px;
  border: 1px solid rgba(146,158,180,.15);
}
.dress-tag-v2 { display: inline-block; font-size: 10.5px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: #586782; background: rgba(146,158,180,.1); border: 1px solid rgba(146,158,180,.2); padding: 3px 12px; border-radius: 100px; margin-bottom: 14px; }
.dress-hero-v2 h3 { font-size: 1.5rem; font-weight: 800; color: var(--ink); margin: 0 0 10px; }
.dress-hero-v2 p { font-size: 14.5px; color: var(--muted); line-height: 1.7; margin: 0; }
.dress-hero-img { border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-lg); }
.dress-hero-img img { width: 100%; display: block; }

.dress-grid-v2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; margin: 28px 0; max-width: 680px; }
.dress-card-v2 {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 24px;
  transition: box-shadow .2s, transform .2s;
}
.dress-card-v2:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.dress-card-v2-icon { width: 48px; height: 48px; border-radius: 12px; display: flex; align-items: center; justify-content: center; margin-bottom: 14px; }
.dress-card-v2-style { font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; margin-bottom: 8px; }
.dress-card-v2 h4 { font-size: 15px; font-weight: 700; color: var(--ink); margin: 0 0 12px; }
.dress-card-v2 ul { padding: 0; margin: 0; list-style: none; }
.dress-card-v2 ul li { font-size: 13px; color: var(--muted); padding: 5px 0 5px 18px; position: relative; border-bottom: 1px solid var(--line-soft); line-height: 1.5; }
.dress-card-v2 ul li:last-child { border-bottom: none; }
.dress-card-v2 ul li::before { content: '✓'; position: absolute; left: 0; color: #66C5C5; font-size: 11px; font-weight: 800; top: 6px; }

.dress-dont-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin: 20px 0; }
.dress-dont-item { display: flex; align-items: center; gap: 10px; padding: 12px 16px; background: rgba(243,85,79,.04); border: 1px solid rgba(243,85,79,.12); border-radius: var(--radius-sm); font-size: 14px; color: var(--ink); }
.dress-dont-x { width: 22px; height: 22px; border-radius: 50%; background: rgba(243,85,79,.12); color: #F3554F; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 800; flex-shrink: 0; }

/* ─────────────── LEAVE V2 ─────────────── */
.leave-process { display: flex; flex-direction: column; gap: 0; margin: 32px 0; }
.leave-step {
  display: grid;
  grid-template-columns: 52px 1fr;
  gap: 20px;
  position: relative;
}
.leave-step::after { content: ''; position: absolute; left: 25px; top: 52px; width: 2px; height: calc(100% - 16px); background: linear-gradient(to bottom, var(--line), transparent); }
.leave-step:last-child::after { display: none; }
.leave-step-node { width: 52px; height: 52px; border-radius: 50%; background: #66C5C5; color: #004080; display: flex; align-items: center; justify-content: center; font-size: 15px; font-weight: 800; flex-shrink: 0; box-shadow: 0 4px 12px rgba(0,64,128,.16); }
.leave-step-card { padding: 14px 0 32px; }
.leave-step-card h4 { font-size: 15px; font-weight: 700; color: var(--ink); margin: 0 0 6px; }
.leave-step-card p { font-size: 14px; color: var(--muted); line-height: 1.65; margin: 0; }

.leave-deadline-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin: 28px 0; }
.leave-dl-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 22px;
  position: relative;
  overflow: hidden;
}
.leave-dl-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px; }
.leave-dl-sick::before { background: rgba(243,85,79,1); }
.leave-dl-biz::before { background: #FFCC00; }
.leave-dl-type { font-size: 10.5px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
.leave-dl-time { font-family: var(--display); font-size: 1.4rem; font-weight: 900; color: var(--ink); margin-bottom: 4px; }
.leave-dl-note { font-size: 13px; color: var(--muted); }

/* ─────────────── BOOKING STEPS V2 ─────────────── */
.book-method-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin: 28px 0; }
.book-method-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 24px;
  text-align: center;
  transition: box-shadow .2s, transform .2s;
}
.book-method-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.book-method-num { font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-bottom: 12px; }
.book-method-icon { width: 56px; height: 56px; border-radius: 14px; display: flex; align-items: center; justify-content: center; margin: 0 auto 14px; background: rgba(0,64,129,.07); color: var(--navy); }
.book-method-card h4 { font-size: 14.5px; font-weight: 700; color: var(--ink); margin: 0 0 8px; }
.book-method-card p { font-size: 13px; color: var(--muted); line-height: 1.55; margin: 0; }

/* ─────────────── POLICY HERO CARD ─────────────── */
.policy-time-hero {
  background: linear-gradient(135deg, #001122 0%, #004081 60%, #004081 100%);
  border-radius: var(--radius-lg);
  padding: 44px 48px;
  color: #F8F9FA;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 40px;
  align-items: center;
  margin-bottom: 48px;
  position: relative;
  overflow: hidden;
}
.policy-time-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 50% 80% at 100% 50%, rgba(102,197,197,.15) 0%, transparent 60%);
  pointer-events: none;
}
.policy-time-main h2 { font-family:var(--display); font-size:clamp(1.6rem,3vw,2.4rem); font-weight:900; margin:0 0 8px; color:#F8F9FA !important; letter-spacing:-.02em; }
.policy-time-main p { font-size:14.5px; color:rgba(248,249,250,.7); margin:0; }
.policy-time-stats { display: flex; gap: 32px; flex-shrink: 0; }
.pts-item { text-align: center; }
.pts-num { font-family:var(--display); font-size:2.4rem; font-weight:900; color:var(--cyan); display:block; line-height:1; }
.pts-label { font-size:11px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; color:rgba(248,249,250,.55); margin-top:4px; }

/* ─────────────── PAGE-LEVEL NAV ENHANCEMENTS ─────────────── */
.nav-menu-highlight { color: #004081 !important; font-weight: 700 !important; border-radius: 4px; }

/* ─────────────── RESPONSIVE ADDITIONS ─────────────── */
@media (max-width: 900px) {
  .hm-hero-inner { grid-template-columns: 1fr; }
  .hm-hero-right, .fd-hero-right { display: none; }
  .hm-grid { grid-template-columns: 1fr 1fr; }
  .cv-card-body { grid-template-columns: 1fr; }
  .cv-card-head { grid-template-columns: auto 1fr; padding: 20px 20px 16px; }
  .cv-card-num-col { width: 60px; height: 56px; }
  .cv-card-big-num { font-size: 2rem; }
  .cv-card-body { padding: 0 20px 20px; }
  .ts-steps-visual { grid-template-columns: repeat(2, 1fr); gap: 20px; }
  .ts-steps-visual::before { display: none; }
  .mr-v2-main { grid-template-columns: 1fr; }
  .dress-hero-v2 { grid-template-columns: 1fr; }
  .policy-time-hero { grid-template-columns: 1fr; }
  .leave-deadline-row { grid-template-columns: 1fr; }
  .wifi-glass-card { grid-template-columns: 1fr; }
  .oc-dept-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .hm-grid { grid-template-columns: 1fr; }
  .hm-stats { flex-direction: column; }
  .hm-stat { border-right: none; border-bottom: 1px solid var(--line); }
  .hm-stat:last-child { border-bottom: none; }
  .dress-grid-v2 { grid-template-columns: 1fr; }
  .dress-dont-grid { grid-template-columns: 1fr; }
  .ts-col-grid { grid-template-columns: 1fr; }
  .book-method-grid { grid-template-columns: 1fr; }
  .oc-dept-grid { grid-template-columns: 1fr; }
  .mr-v2-grid { grid-template-columns: 1fr; }
}

/* ═══════════════════════════════════════════════════════════════
   HOME V3 — BENTO EDITORIAL  (classes: hmv3-*)
   ═══════════════════════════════════════════════════════════════ */

/* ── Hero ── */
.hmv3-hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #001122 0%, #004081 55%, #004081 100%);
  padding: calc(var(--nav-h) + 80px) 0 88px;
  isolation: isolate;
}
.hmv3-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 55% 70% at 100% 50%, rgba(102,197,197,.12) 0%, transparent 65%),
    radial-gradient(ellipse 35% 40% at 0% 85%, rgba(0,64,129,.25) 0%, transparent 60%);
  pointer-events: none;
}
.hmv3-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(248,249,250,.045) 1px, transparent 1px);
  background-size: 32px 32px;
  pointer-events: none;
  mask-image: radial-gradient(ellipse 80% 100% at 80% 40%, black 0%, transparent 70%);
  -webkit-mask-image: radial-gradient(ellipse 80% 100% at 80% 40%, black 0%, transparent 70%);
}
.hmv3-inner {
  position: relative;
  z-index: 1;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 40px;
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 60px;
  align-items: center;
}
.hmv3-inner > div { min-width: 0; }

/* ── Hero visual (right column) ── */
.hmv3-hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 320px;
}
.hmv3-hero-orb {
  position: absolute;
  width: 400px; height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(102,197,197,0.09) 0%, transparent 70%);
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}
.hmv3-hero-svg {
  width: 280px; height: 280px;
  position: relative; z-index: 1;
}
.hmv3-hero-orbit {
  position: absolute;
  border-radius: 50%;
  top: 50%; left: 50%;
  pointer-events: none;
}
.hmv3-hero-orbit-1 {
  width: 296px; height: 296px;
  margin: -148px 0 0 -148px;
  animation: hmv3OrbitSpin 18s linear infinite;
}
.hmv3-hero-orbit-2 {
  width: 220px; height: 220px;
  margin: -110px 0 0 -110px;
  animation: hmv3OrbitSpin 12s linear infinite reverse;
}
@keyframes hmv3OrbitSpin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
.hmv3-hero-dot {
  position: absolute;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--cyan);
  opacity: 0.75;
  top: -4px; left: 50%;
  transform: translateX(-50%);
}
.hmv3-hero-dot-sm {
  width: 5px; height: 5px;
  top: -2.5px;
  opacity: 0.45;
}
@media (prefers-reduced-motion: reduce) {
  .hmv3-hero-orbit-1, .hmv3-hero-orbit-2 { animation: none; }
}

/* ── Scrapbook scene (replaces orbital SVG) ── */
.hmv3-scene {
  position: relative;
  width: 100%; height: 340px;
  display: flex; align-items: center; justify-content: center;
}

/* All scene cards */
.hmv3-sn {
  position: absolute;
  border-radius: 6px;
  user-select: none;
}

/* Quote sticky note */
.hmv3-sn-quote {
  background: #F8F9FA;
  padding: 18px 18px 22px;
  width: 200px;
  top: 28px; right: 48px;
  transform: rotate(-3.5deg);
  box-shadow: 4px 6px 24px rgba(0,17,34,.32), 0 1px 3px rgba(0,17,34,.14);
  animation: hmv3Float1 5s ease-in-out infinite;
}
.hmv3-sn-pin {
  width: 13px; height: 13px;
  border-radius: 50%;
  background: #66C5C5;
  position: absolute; top: -6px; left: 50%;
  transform: translateX(-50%);
  box-shadow: 0 0 8px rgba(102,197,197,.65), 0 2px 4px rgba(0,17,34,.2);
}
.hmv3-sn-text {
  font-size: 12.5px; font-style: italic;
  color: #505050; line-height: 1.72;
  margin: 4px 0 10px;
}
.hmv3-sn-by {
  font-size: 10.5px; font-weight: 700; font-style: normal;
  color: #707070; letter-spacing: .02em;
}

/* Calendar badge */
.hmv3-sn-cal {
  background: #004081;
  color: #F8F9FA;
  padding: 14px 16px 16px;
  width: 88px; text-align: center;
  top: 18px; left: 28px;
  transform: rotate(2.5deg);
  border-radius: 14px;
  box-shadow: 3px 5px 20px rgba(0,17,34,.38);
  animation: hmv3Float2 6s ease-in-out 0.8s infinite;
}
.hmv3-sn-cal-header {
  font-size: 9px; font-weight: 800;
  letter-spacing: .22em; text-transform: uppercase;
  color: #66C5C5; margin-bottom: 3px;
}
.hmv3-sn-cal-num {
  font-size: 46px; font-weight: 900; line-height: 1;
  letter-spacing: -.05em; color: #F8F9FA;
}
.hmv3-sn-cal-sub {
  font-size: 10px; font-weight: 600;
  color: rgba(102,197,197,.75); margin-top: 5px;
}

/* Goals checklist note */
.hmv3-sn-goals {
  background: #F8F9FA;
  padding: 15px 16px 17px;
  width: 172px;
  bottom: 24px; right: 32px;
  transform: rotate(1.8deg);
  box-shadow: 3px 5px 18px rgba(0,17,34,.24), 0 1px 3px rgba(0,17,34,.1);
  animation: hmv3Float3 7s ease-in-out 1.5s infinite;
}
.hmv3-sn-goals-top {
  font-size: 10.5px; font-weight: 800;
  letter-spacing: .06em; text-transform: uppercase;
  color: #004081; margin-bottom: 9px;
}
.hmv3-sn-goal {
  font-size: 12px; color: #505050; line-height: 1.65;
  padding: 1px 0;
}

/* Coffee decorative emoji */
.hmv3-sn-coffee {
  position: absolute;
  font-size: 30px;
  bottom: 34px; left: 36px;
  opacity: .82;
  filter: drop-shadow(2px 3px 5px rgba(0,17,34,.22));
  animation: hmv3Float1 4s ease-in-out 0.4s infinite;
}

@keyframes hmv3Float1 {
  0%, 100% { transform: rotate(-3.5deg) translateY(0); }
  50%       { transform: rotate(-3.5deg) translateY(-5px); }
}
@keyframes hmv3Float2 {
  0%, 100% { transform: rotate(2.5deg) translateY(0); }
  50%       { transform: rotate(2.5deg) translateY(-7px); }
}
@keyframes hmv3Float3 {
  0%, 100% { transform: rotate(1.8deg) translateY(0); }
  50%       { transform: rotate(1.8deg) translateY(-4px); }
}
@media (prefers-reduced-motion: reduce) {
  .hmv3-sn-quote, .hmv3-sn-cal, .hmv3-sn-goals, .hmv3-sn-coffee { animation: none !important; }
}

.hmv3-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--cyan);
  margin-bottom: 22px;
}
.hmv3-kicker-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  animation: hmv3-pulse 0.6s ease-out both;
}
@keyframes hmv3-pulse {
  from { box-shadow: 0 0 0 var(--cyan); transform: scale(0.6); opacity: 0; }
  to   { box-shadow: 0 0 8px var(--cyan); transform: scale(1); opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .hmv3-kicker-dot { animation: none; }
}
.hmv3-h1 {
  font-family: var(--display);
  font-size: clamp(2.6rem, 5vw, 4rem);
  font-weight: 900;
  color: #F8F9FA;
  line-height: 1.5;
  letter-spacing: -.02em;
  margin: 0 0 24px;
  text-wrap: balance;
}
.hmv3-h1-accent {
  display: block;
  padding-top: 6px;
  color: var(--cyan);
}
.hmv3-sub {
  font-size: 15.5px;
  line-height: 1.8;
  color: rgba(248,249,250,.62);
  max-width: 500px;
  margin: 0 0 36px;
  text-wrap: pretty;
}
.hmv3-actions {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 32px;
}
.hmv3-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 13px 28px;
  background: var(--cyan);
  color: #F8F9FA;
  font-size: 14px;
  font-weight: 700;
  border-radius: var(--radius-sm);
  text-decoration: none;
  box-shadow: 0 4px 20px rgba(102,197,197,.4);
  transition: transform .18s, box-shadow .18s;
  position: relative;
  overflow: hidden;
}
.hmv3-btn-primary::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(248,249,250,.18) 50%, transparent 100%);
  transform: translateX(-100%);
  transition: transform .55s ease;
}
.hmv3-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(102,197,197,.55); }
.hmv3-btn-primary:hover::after { transform: translateX(100%); }
.hmv3-btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 22px;
  background: rgba(248,249,250,.08);
  border: 1px solid rgba(248,249,250,.18);
  color: rgba(248,249,250,.85);
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-sm);
  text-decoration: none;
  transition: background .18s, border-color .18s;
}
.hmv3-btn-ghost:hover { background: rgba(248,249,250,.15); border-color: rgba(248,249,250,.35); }
.hmv3-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.hmv3-pill {
  font-size: 11.5px;
  font-weight: 700;
  padding: 5px 14px;
  border-radius: 20px;
  background: rgba(248,249,250,.07);
  border: 1px solid rgba(248,249,250,.13);
  color: rgba(248,249,250,.6);
  letter-spacing: .04em;
}

/* ── Handbook Index Card (right side of hero) ── */
.hmv3-index {
  background: rgba(248,249,250,.06);
  backdrop-filter: blur(20px) saturate(160%);
  -webkit-backdrop-filter: blur(20px) saturate(160%);
  border: 1px solid rgba(248,249,250,.14);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 24px 60px rgba(0,17,34,.35);
}
.hmv3-index-header {
  padding: 14px 20px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: rgba(248,249,250,.45);
  border-bottom: 1px solid rgba(248,249,250,.08);
  display: flex;
  align-items: center;
  gap: 8px;
}
.hmv3-index-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 20px;
  border-bottom: 1px solid rgba(248,249,250,.06);
  cursor: pointer;
  text-decoration: none;
  color: rgba(248,249,250,.75);
  font-size: 14px;
  font-weight: 500;
  transition: background .15s, color .15s, padding-left .2s;
}
.hmv3-index-item:last-child { border-bottom: none; }
.hmv3-index-item:hover { background: rgba(248,249,250,.07); color: #F8F9FA; padding-left: 24px; }
.hmv3-index-num {
  font-size: 10px;
  font-weight: 800;
  font-family: var(--display);
  color: rgba(248,249,250,.3);
  min-width: 20px;
}
.hmv3-index-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.hmv3-index-lbl { flex: 1; }
.hmv3-index-badge {
  font-size: 10px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: 20px;
  background: rgba(102,197,197,.25);
  color: var(--cyan);
  letter-spacing: .05em;
  text-transform: uppercase;
}
.hmv3-index-arr {
  color: rgba(248,249,250,.25);
  transition: color .15s, transform .15s;
  flex-shrink: 0;
}
.hmv3-index-item:hover .hmv3-index-arr { color: var(--cyan); transform: translateX(3px); }


/* ── Global focus-visible ring for all new interactive elements ── */
.hmv3-btn-primary:focus-visible,
.hmv3-btn-ghost:focus-visible,
.hmv3-chapter-item:focus-visible,
.hmv3-ql-item:focus-visible,
.fd3-more-entry:focus-visible,
.fd3-task-link:focus-visible,
.fd3-tl-cta:focus-visible,
.fd3-more-home-btn:focus-visible,
.hb-link:focus-visible,
.reference-card:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

/* ── Chapter bar (below hero) ── */
.hmv3-chapters {
  background: var(--bg);
  border-bottom: 1px solid var(--line);
}
.hmv3-chapters-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 40px;
  display: flex;
}
.hmv3-chapter-item {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 14px 20px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--ink);
  text-decoration: none;
  flex: 1;
  min-width: 0;
  position: relative;
  transition: background .15s, color .15s;
}
.hmv3-chapter-item + .hmv3-chapter-item::before {
  content: '';
  position: absolute;
  left: 0; top: 12px; bottom: 12px;
  width: 1px;
  background: var(--line);
}
.hmv3-chapter-item:hover { background: var(--surface-2); }
.hmv3-chapter-item { cursor: pointer; }
.hmv3-chapter-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.hmv3-chapter-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hmv3-chapter-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(102,197,197,.12);
  color: var(--cyan);
  flex-shrink: 0;
  white-space: nowrap;
}

/* ── Bento grid ── */
.hmv3-bento-wrap {
  padding: 60px 0 72px;
  background: var(--surface);
}
.hmv3-bento-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 40px;
}
.hmv3-bento-header {
  margin-bottom: 44px;
}
.hmv3-bento-title {
  font-family: var(--display);
  font-size: clamp(1.7rem, 2.8vw, 2.4rem);
  font-weight: 800;
  color: var(--ink);
  margin: 0;
  line-height: 1.3;
  text-wrap: balance;
}
.hmv3-bento-grid {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 3.5fr) minmax(0, 3.5fr);
  grid-template-rows: auto auto;
  gap: 18px;
}

/* ── Base cell ── */
.hmv3-cell {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 0;
  position: relative;
  overflow: hidden;
  transition: box-shadow .25s ease, transform .25s ease, border-color .25s ease;
  text-decoration: none;
  color: inherit;
}
.hmv3-cell::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  background: var(--cell-accent, var(--cyan));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .3s ease;
}
.hmv3-cell:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); border-color: rgba(102,197,197,.4); }
.hmv3-cell:hover::before { transform: scaleX(1); }

/* Day 1 featured cell */
.hmv3-cell--day1 {
  grid-column: 1;
  grid-row: 1 / span 2;
  background: linear-gradient(145deg, #001122 0%, #004081 50%, #004081 100%);
  border-color: rgba(102,197,197,.2);
  padding: 36px;
}
.hmv3-cell--day1::before { background: var(--cyan); }
.hmv3-cell--day1:hover { border-color: var(--cyan); box-shadow: 0 20px 60px rgba(0,17,34,.4); }

.hmv3-day1-num {
  font-family: var(--display);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: rgba(248,249,250,.35);
  margin-bottom: 24px;
}
.hmv3-day1-icon {
  width: 52px; height: 52px;
  border-radius: 16px;
  background: rgba(102,197,197,.2);
  color: var(--cyan);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.hmv3-day1-title {
  font-family: var(--display);
  font-size: clamp(1.6rem, 2.5vw, 2.1rem);
  font-weight: 800;
  color: #F8F9FA;
  line-height: 1.2;
  margin: 0 0 10px;
  letter-spacing: -.02em;
}
.hmv3-day1-sub {
  font-size: 14px;
  line-height: 1.7;
  color: rgba(248,249,250,.55);
  margin: 0 0 28px;
}
.hmv3-day1-checklist {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 32px;
  flex: 1;
}
.hmv3-day1-check {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 16px;
  background: rgba(248,249,250,.06);
  border: 1px solid rgba(248,249,250,.09);
  border-radius: var(--radius-sm);
  transition: background .15s;
}
.hmv3-day1-check:hover { background: rgba(102,197,197,.1); }
.hmv3-day1-check-dot {
  width: 20px; height: 20px;
  border-radius: 50%;
  border: 2px solid rgba(102,197,197,.5);
  flex-shrink: 0;
  margin-top: 1px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hmv3-day1-check-dot svg { display: none; }
.hmv3-day1-check-text {
  font-size: 13.5px;
  color: rgba(248,249,250,.8);
  line-height: 1.4;
}
.hmv3-day1-check-label {
  font-weight: 600;
  color: #F8F9FA;
  display: block;
  margin-bottom: 2px;
}
.hmv3-day1-check-note {
  font-size: 12px;
  color: rgba(248,249,250,.45);
}
.hmv3-day1-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 24px;
  background: var(--cyan);
  color: #F8F9FA;
  font-size: 14px;
  font-weight: 700;
  border-radius: var(--radius-sm);
  text-decoration: none;
  box-shadow: 0 4px 20px rgba(102,197,197,.35);
  transition: transform .18s, box-shadow .18s;
  margin-top: auto;
}
.hmv3-day1-cta:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(102,197,197,.5); }
.hmv3-day1-cta svg { transition: transform .18s; }
.hmv3-day1-cta:hover svg { transform: translateX(3px); }

/* Section cells */
.hmv3-cell-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
}
.hmv3-cell-num {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .14em;
  color: var(--muted);
  opacity: .5;
  font-family: var(--display);
}
.hmv3-cell-icon {
  width: 40px; height: 40px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.hmv3-cell-title {
  font-family: var(--display);
  font-size: 15.5px;
  font-weight: 800;
  color: var(--ink);
  margin: 0 0 6px;
  line-height: 1.25;
}
.hmv3-cell-desc {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.6;
  margin: 0 0 16px;
  flex: 1;
}
.hmv3-cell-links {
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid var(--line-soft);
  padding-top: 12px;
}
.hmv3-cell-link {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--navy);
  text-decoration: none;
  border-bottom: 1px solid var(--line-soft);
  transition: color .15s, gap .18s, padding-left .18s;
}
.hmv3-cell-link:last-child { border-bottom: none; }
.hmv3-cell-link:hover { color: var(--cyan); gap: 10px; padding-left: 4px; }
.hmv3-cell-link svg { opacity: .6; transition: opacity .15s; flex-shrink: 0; }
.hmv3-cell-link:hover svg { opacity: 1; }

/* Showcase cell — full width */
.hmv3-showcase-wrap {
  grid-column: 1 / -1;
  background: linear-gradient(135deg, #001122 0%, #001122 40%, #001122 100%);
  border: 1px solid rgba(146,158,180,.25);
  border-radius: var(--radius-lg);
  padding: 32px 36px;
  position: relative;
  overflow: hidden;
}
.hmv3-showcase-wrap::before {
  content: '';
  position: absolute;
  right: -100px; top: -100px;
  width: 360px; height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(146,158,180,.18) 0%, transparent 70%);
  pointer-events: none;
}
.hmv3-showcase-top {
  margin-bottom: 24px;
  position: relative;
}
.hmv3-showcase-eyebrow {
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: rgba(208,214,223,.6);
  margin-bottom: 8px;
}
.hmv3-showcase-title {
  font-family: var(--display);
  font-size: clamp(1.2rem, 2vw, 1.55rem);
  font-weight: 800;
  color: #F8F9FA;
  margin: 0 0 6px;
  letter-spacing: -0.01em;
}
.hmv3-showcase-sub {
  font-size: 13.5px;
  color: rgba(248,249,250,.65);
  margin: 0;
  line-height: 1.65;
  max-width: 520px;
}
.hmv3-showcase-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  position: relative;
}
.hmv3-sc-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: rgba(248,249,250,.06);
  border: 1px solid rgba(248,249,250,.1);
  border-radius: var(--radius-sm);
  text-decoration: none;
  transition: background .18s, border-color .18s;
}
.hmv3-sc-card:hover { background: rgba(248,249,250,.12); border-color: rgba(208,214,223,.35); }
.hmv3-sc-card-icon {
  width: 36px; height: 36px;
  border-radius: 9px;
  background: rgba(146,158,180,.25);
  color: #D0D6DF;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.hmv3-sc-card-body { flex: 1; }
.hmv3-sc-card-title { font-size: 13.5px; font-weight: 700; color: #F8F9FA; margin-bottom: 2px; }
.hmv3-sc-card-desc { font-size: 12px; color: rgba(248,249,250,.48); line-height: 1.4; }
.hmv3-sc-card-arr { color: rgba(248,249,250,.3); flex-shrink: 0; transition: transform .15s, color .15s; }
.hmv3-sc-card:hover .hmv3-sc-card-arr { color: #D0D6DF; transform: translateX(3px); }

/* ── Quick links bottom section ── */
.hmv3-ql-wrap {
  background: var(--bg);
  border-top: 1px solid var(--line);
  padding: 56px 0 72px;
}
.hmv3-ql-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 40px;
}
.hmv3-ql-header {
  margin-bottom: 28px;
}
.hmv3-ql-label {
  font-family: var(--display);
  font-size: clamp(1.2rem, 2vw, 1.5rem);
  font-weight: 800;
  color: var(--ink);
  margin: 0 0 4px;
  line-height: 1.3;
  letter-spacing: -0.01em;
}
.hmv3-ql-sub {
  font-size: 13.5px;
  color: var(--muted);
  margin: 0;
}
.hmv3-ql-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
}
.hmv3-ql-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--bg);
  text-decoration: none;
  color: var(--ink);
  transition: border-color .18s, box-shadow .18s, transform .18s;
}
.hmv3-ql-item:hover {
  border-color: var(--cyan);
  box-shadow: 0 4px 16px rgba(102,197,197,.12);
  transform: translateY(-2px);
}
.hmv3-ql-num {
  font-family: var(--display);
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--line);
  flex-shrink: 0;
  line-height: 1;
  letter-spacing: -0.04em;
  min-width: 36px;
  transition: color .18s;
}
.hmv3-ql-item:hover .hmv3-ql-num { color: var(--cyan); }
.hmv3-ql-text { flex: 1; }
.hmv3-ql-name { font-weight: 700; color: var(--ink); display: block; font-size: 14px; }
.hmv3-ql-hint { font-size: 12px; color: var(--muted); }
.hmv3-ql-arr {
  color: var(--muted);
  opacity: .55;
  transition: opacity .15s, transform .2s, color .15s;
  flex-shrink: 0;
}
.hmv3-ql-item:hover .hmv3-ql-arr { opacity: 1; color: var(--cyan); transform: translateX(3px); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .hmv3-bento-grid { grid-template-columns: 5fr 5fr; }
  .hmv3-cell--day1 { grid-column: 1 / -1; grid-row: 1; }
  .hmv3-ql-grid { grid-template-columns: repeat(2, 1fr); }
  .hmv3-showcase-cards { grid-template-columns: 1fr; }
  .hmv3-chapters-inner { padding: 0 28px; }
  .hmv3-chapter-item { padding: 13px 16px; font-size: 12.5px; }
}
@media (max-width: 768px) {
  .hmv3-chapters-inner {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    padding: 0;
  }
  .hmv3-chapter-item {
    padding: 12px 14px;
    font-size: 12px;
    border-bottom: 1px solid var(--line);
    border-right: 1px solid var(--line);
  }
  .hmv3-chapter-item + .hmv3-chapter-item::before { display: none; }
  .hmv3-chapter-item:nth-child(3n) { border-right: none; }
  .hmv3-chapter-item:nth-child(4),
  .hmv3-chapter-item:nth-child(5),
  .hmv3-chapter-item:nth-child(6) { border-bottom: none; }
}
@media (max-width: 760px) {
  .hmv3-bento-grid { grid-template-columns: 1fr; }
  .hmv3-ql-grid { grid-template-columns: 1fr; }
  .hmv3-inner { grid-template-columns: 1fr; padding: 0 24px; }
  .hmv3-hero-visual { display: none; }
  .hmv3-hero { padding: calc(var(--nav-h) + 52px) 0 64px; }
  .hmv3-chapters-inner { grid-template-columns: repeat(2, 1fr); }
  .hmv3-chapter-item:nth-child(3n) { border-right: 1px solid var(--line); }
  .hmv3-chapter-item:nth-child(even) { border-right: none; }
  .hmv3-chapter-item:nth-child(4),
  .hmv3-chapter-item:nth-child(5),
  .hmv3-chapter-item:nth-child(6) { border-bottom: 1px solid var(--line); }
  .hmv3-chapter-item:nth-child(5),
  .hmv3-chapter-item:nth-child(6) { border-bottom: none; }
  .hmv3-chapter-badge { display: none; }
}

/* ═══════════════════════════════════════════════════════════════
   FIRST DAY V3 — MISSION CONTROL  (fdx-*)
   ═══════════════════════════════════════════════════════════════ */

.fdx-hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(140deg, #001122 0%, #001122 55%, #004081 100%);
  padding: calc(var(--nav-h) + 72px) 0 80px;
  isolation: isolate;
}
.fdx-hero::before {
  content: '';
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 60% 80% at 95% 50%, rgba(102,197,197,.14) 0%, transparent 65%),
    radial-gradient(ellipse 40% 50% at 5% 90%, rgba(0,64,129,.2) 0%, transparent 60%);
  pointer-events: none;
}
.fdx-hero::after {
  content: '';
  position: absolute; inset: 0;
  background-image: radial-gradient(circle, rgba(248,249,250,.04) 1px, transparent 1px);
  background-size: 30px 30px;
  pointer-events: none;
  mask-image: radial-gradient(ellipse 70% 100% at 85% 40%, black 0%, transparent 70%);
  -webkit-mask-image: radial-gradient(ellipse 70% 100% at 85% 40%, black 0%, transparent 70%);
}
.fdx-inner {
  position: relative; z-index: 1;
  max-width: var(--maxw); margin: 0 auto; padding: 0 40px;
  display: grid; grid-template-columns: 1fr 380px; gap: 52px; align-items: center;
}
.fdx-badge {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 11px; font-weight: 800; letter-spacing: .15em; text-transform: uppercase;
  color: var(--cyan); margin-bottom: 20px;
}
.fdx-badge-dot {
  width: 6px; height: 6px; border-radius: 50%; background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  animation: hmv3-pulse 2.4s ease-in-out infinite;
}
.fdx-h1 {
  font-family: var(--display);
  font-size: clamp(2.4rem, 4.5vw, 3.6rem);
  font-weight: 900; color: #F8F9FA; line-height: 1.1;
  letter-spacing: -.025em; margin: 0 0 18px;
}
.fdx-h1 em { font-style: normal; color: var(--cyan); }
.fdx-sub {
  font-size: 15px; line-height: 1.8; color: rgba(248,249,250,.6);
  max-width: 460px; margin: 0 0 32px;
}
.fdx-ctas { display: flex; gap: 12px; flex-wrap: wrap; }
.fdx-btn-p {
  display: inline-flex; align-items: center; gap: 9px;
  padding: 13px 26px; background: var(--cyan); color: #F8F9FA;
  font-size: 14px; font-weight: 700; border-radius: var(--radius-sm);
  text-decoration: none; box-shadow: 0 4px 20px rgba(102,197,197,.4);
  transition: transform .18s, box-shadow .18s;
}
.fdx-btn-p:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(102,197,197,.55); }
.fdx-btn-g {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 22px; background: rgba(248,249,250,.08);
  border: 1px solid rgba(248,249,250,.18); color: rgba(248,249,250,.85);
  font-size: 14px; font-weight: 600; border-radius: var(--radius-sm);
  text-decoration: none; transition: background .18s;
}
.fdx-btn-g:hover { background: rgba(248,249,250,.15); }

/* Progress card */
.fdx-prog-card {
  background: rgba(248,249,250,.07);
  backdrop-filter: blur(18px) saturate(150%);
  -webkit-backdrop-filter: blur(18px) saturate(150%);
  border: 1px solid rgba(248,249,250,.13);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: 0 20px 50px rgba(0,17,34,.3);
}
.fdx-prog-title {
  font-size: 10.5px; font-weight: 800; letter-spacing: .14em;
  text-transform: uppercase; color: rgba(248,249,250,.4); margin-bottom: 18px;
}
.fdx-prog-track {
  height: 6px; background: rgba(248,249,250,.12);
  border-radius: 3px; overflow: hidden; margin-bottom: 20px;
}
.fdx-prog-fill {
  height: 100%; width: 0%;
  background: linear-gradient(90deg, var(--cyan), #66C5C5);
  border-radius: 3px; transition: width .8s cubic-bezier(0.16, 1, 0.3, 1);
}
.fdx-prog-items { display: flex; flex-direction: column; gap: 12px; }
.fdx-prog-item {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 14px; border-radius: var(--radius-sm);
  background: rgba(248,249,250,.05); border: 1px solid rgba(248,249,250,.08);
  cursor: pointer; transition: background .15s, border-color .15s;
  user-select: none;
}
.fdx-prog-item:hover { background: rgba(102,197,197,.1); border-color: rgba(102,197,197,.25); }
.fdx-prog-item.done { background: rgba(102,197,197,.12); border-color: rgba(102,197,197,.3); }
.fdx-prog-check {
  width: 22px; height: 22px; border-radius: 50%;
  border: 2px solid rgba(248,249,250,.25); flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  transition: all .3s ease;
}
.fdx-prog-item.done .fdx-prog-check {
  background: var(--cyan); border-color: var(--cyan);
}
.fdx-prog-check-icon { display: none; color: #F8F9FA; }
.fdx-prog-item.done .fdx-prog-check-icon { display: block; }
.fdx-prog-text { flex: 1; }
.fdx-prog-label {
  font-size: 13px; font-weight: 600; color: rgba(248,249,250,.85); display: block;
}
.fdx-prog-item.done .fdx-prog-label { text-decoration: line-through; opacity: .6; }
.fdx-prog-hint { font-size: 11.5px; color: rgba(248,249,250,.38); }
.fdx-prog-pct {
  font-family: var(--display); font-size: 11px; font-weight: 800;
  color: var(--cyan); white-space: nowrap;
}

/* ── Mission section ── */
.fdx-mission {
  padding: 64px 0 72px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}
.fdx-mission-inner { max-width: var(--maxw); margin: 0 auto; padding: 0 40px; }
.fdx-mission-hd { margin-bottom: 36px; }
.fdx-mission-overline {
  font-size: 11px; font-weight: 800; letter-spacing: .14em;
  text-transform: uppercase; color: var(--cyan); margin-bottom: 8px;
}
.fdx-mission-title {
  font-family: var(--display);
  font-size: clamp(1.6rem, 2.8vw, 2.2rem); font-weight: 800;
  color: var(--ink); margin: 0; line-height: 1.2;
}
.fdx-task-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 20px;
}
.fdx-task {
  background: var(--bg); border: 1px solid var(--line);
  border-radius: var(--radius-lg); padding: 32px;
  display: flex; flex-direction: column; gap: 0;
  position: relative; overflow: hidden;
  transition: box-shadow .25s, transform .25s, border-color .25s;
}
.fdx-task::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0; height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  background: var(--task-accent, var(--cyan));
}
.fdx-task:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); border-color: rgba(102,197,197,.35); }
.fdx-task-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 24px; }
.fdx-task-num {
  font-size: 11px; font-weight: 800; letter-spacing: .1em;
  color: var(--muted); font-family: var(--display);
  background: var(--surface-2); border: 1px solid var(--line);
  border-radius: 6px; padding: 3px 9px;
}
.fdx-task-status {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11.5px; font-weight: 700; letter-spacing: .03em;
  padding: 5px 12px; border-radius: 99px;
}
.fdx-status-wait { background: rgba(255,204,0,.1); color: #505050; border: 1px solid rgba(255,204,0,.3); }
.fdx-status-now  { background: rgba(102,197,197,.12); color: #004081; border: 1px solid rgba(102,197,197,.3); }
.fdx-task-icon {
  width: 52px; height: 52px; border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 18px; flex-shrink: 0;
}
.fdx-icon-amber { background: rgba(255,204,0,.12); color: #505050; }
.fdx-icon-cyan  { background: rgba(102,197,197,.14); color: #004081; }
.fdx-task-title {
  font-family: var(--display); font-size: 1.25rem; font-weight: 800;
  color: var(--ink); margin: 0 0 10px; line-height: 1.3; letter-spacing: -.01em;
}
.fdx-task-desc {
  font-size: 14px; color: var(--muted); line-height: 1.75; margin: 0 0 24px;
}
.fdx-task-visual {
  flex: 1; background: var(--surface); border: 1px solid var(--line-soft);
  border-radius: var(--radius); padding: 20px; margin-bottom: 20px;
  min-height: 120px; display: flex; align-items: center; justify-content: center;
}
.fdx-flow { display: flex; align-items: center; gap: 8px; width: 100%; }
.fdx-flow-step {
  flex: 1; display: flex; flex-direction: column; align-items: center;
  text-align: center; gap: 8px;
}
.fdx-flow-icon {
  width: 40px; height: 40px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.fdx-flow-icon-a { background: rgba(0,64,129,.08); color: var(--navy); }
.fdx-flow-icon-b { background: rgba(255,204,0,.12); color: #505050; }
.fdx-flow-icon-c { background: rgba(102,197,197,.14); color: #004081; }
.fdx-flow-lbl { font-size: 11.5px; color: var(--muted); line-height: 1.4; }
.fdx-flow-arr { color: var(--muted); opacity: .4; flex-shrink: 0; }
.fdx-info-row {
  display: flex; gap: 0; width: 100%;
  border-radius: var(--radius-sm); overflow: hidden;
}
.fdx-info-item {
  flex: 1; display: flex; flex-direction: column; align-items: center;
  justify-content: center; padding: 14px 10px; gap: 3px;
}
.fdx-info-item + .fdx-info-item { border-left: 1px solid var(--line-soft); }
.fdx-info-lbl { font-size: 10.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); }
.fdx-info-val { font-size: 14px; font-weight: 800; color: var(--ink); }
.fdx-task-cta {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 13.5px; font-weight: 700; color: var(--ink);
  background: var(--surface-2); border: 1px solid var(--line);
  border-radius: var(--radius-sm); padding: 11px 20px;
  text-decoration: none; transition: background .18s, border-color .18s, color .18s;
  align-self: flex-start; margin-top: auto;
}
.fdx-task-cta:hover { background: rgba(102,197,197,.1); border-color: rgba(102,197,197,.4); color: #004081; }
.fdx-task-note { font-size: 12.5px; color: var(--muted); margin-top: 10px; }

/* ── Timeline section ── */
.fdx-tl-section {
  padding: 64px 0 72px; background: var(--bg);
}
.fdx-tl-inner { max-width: var(--maxw); margin: 0 auto; padding: 0 40px; }
.fdx-tl-hd { text-align: center; margin-bottom: 52px; }
.fdx-tl-eyebrow {
  font-size: 11px; font-weight: 800; letter-spacing: .14em;
  text-transform: uppercase; color: var(--cyan); margin-bottom: 10px;
}
.fdx-tl-title {
  font-family: var(--display);
  font-size: clamp(1.7rem, 2.8vw, 2.4rem); font-weight: 800;
  color: var(--ink); margin: 0 0 10px; line-height: 1.2;
}
.fdx-tl-sub { font-size: 15px; color: var(--muted); margin: 0; }

/* Horizontal step flow */
.fdx-steps {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 2px; position: relative;
}
.fdx-steps::before {
  content: '';
  position: absolute; top: 28px; left: 14%; right: 14%;
  height: 2px;
  background: linear-gradient(90deg, var(--cyan) 0%, #66C5C5 50%, #F3554F 100%);
  z-index: 0; opacity: .3;
}
.fdx-step {
  display: flex; flex-direction: column; align-items: center;
  padding: 0 12px; position: relative; z-index: 1;
  gap: 0;
}
.fdx-step-node {
  width: 56px; height: 56px; border-radius: 50%;
  border: 3px solid var(--step-color, var(--cyan));
  background: var(--bg);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--display); font-size: 14px; font-weight: 900;
  color: var(--step-color, var(--cyan));
  margin-bottom: 20px; flex-shrink: 0; position: relative; z-index: 1;
  box-shadow: 0 0 0 4px var(--bg);
  transition: background .25s, color .25s, box-shadow .25s;
}
.fdx-step:hover .fdx-step-node {
  background: var(--step-color, var(--cyan));
  color: #F8F9FA;
  box-shadow: 0 0 0 4px var(--bg), 0 8px 24px rgba(0,17,34,.15);
}
.fdx-step-card {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 20px; width: 100%;
  transition: box-shadow .2s, transform .2s, border-color .2s;
  text-align: left;
}
.fdx-step:hover .fdx-step-card {
  box-shadow: var(--shadow-md); transform: translateY(-3px);
  border-color: var(--step-color, var(--cyan));
}
.fdx-step-time {
  font-size: 10.5px; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: var(--muted); margin-bottom: 8px;
}
.fdx-step-name {
  font-family: var(--display); font-size: 15px; font-weight: 800;
  color: var(--ink); margin: 0 0 8px; line-height: 1.3;
}
.fdx-step-desc {
  font-size: 12.5px; color: var(--muted); line-height: 1.6; margin: 0 0 12px;
}
.fdx-step-tags { display: flex; flex-wrap: wrap; gap: 5px; }
.fdx-step-tag {
  font-size: 11px; font-weight: 600; color: var(--muted);
  background: var(--bg); border: 1px solid var(--line);
  border-radius: 99px; padding: 3px 9px;
}
.fdx-step-link {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 12.5px; font-weight: 700; color: var(--step-color, var(--cyan));
  text-decoration: none; margin-top: 10px;
  transition: gap .15s;
}
.fdx-step-link:hover { gap: 8px; }
.fdx-urgent { color: #F3554F; }

/* Responsive */
@media (max-width: 960px) {
  .fdx-inner { grid-template-columns: 1fr; }
  .fdx-prog-card { display: none; }
  .fdx-task-grid { grid-template-columns: 1fr; }
  .fdx-steps { grid-template-columns: 1fr 1fr; }
  .fdx-steps::before { display: none; }
}
@media (max-width: 600px) {
  .fdx-steps { grid-template-columns: 1fr; }
}


/* ═══════════════════════════════════════════════════════════════
   CORE VALUES V2 — UNIFIED PILLARS  (cov-*)
   ═══════════════════════════════════════════════════════════════ */

/* Hero */
.cov-hero {
  position: relative; overflow: hidden; isolation: isolate;
  background: linear-gradient(140deg, #001122 0%, #004081 55%, #004081 100%);
  padding: calc(var(--nav-h) + 72px) 0 72px;
}
.cov-hero::before {
  content: '';
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 55% 60% at 90% 40%, rgba(102,197,197,.12) 0%, transparent 60%),
    radial-gradient(ellipse 30% 40% at 10% 80%, rgba(0,64,129,.2) 0%, transparent 60%);
  pointer-events: none;
}
.cov-hero-inner {
  position: relative; z-index: 1;
  max-width: var(--maxw); margin: 0 auto; padding: 0 40px;
}
.cov-hero-eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 11px; font-weight: 800; letter-spacing: .15em; text-transform: uppercase;
  color: var(--cyan); margin-bottom: 18px;
}
.cov-hero-h1 {
  font-family: var(--display);
  font-size: clamp(2.4rem, 4.5vw, 3.6rem); font-weight: 900;
  color: #F8F9FA; line-height: 1.1; letter-spacing: -.025em; margin: 0 0 16px;
}
.cov-hero-sub {
  font-size: 15.5px; line-height: 1.75; color: rgba(248,249,250,.58);
  max-width: 540px; margin: 0 0 36px;
}
.cov-nav {
  display: flex; gap: 8px; flex-wrap: wrap;
}
.cov-nav-chip {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 8px 16px; border-radius: 99px;
  background: rgba(248,249,250,.07); border: 1px solid rgba(248,249,250,.12);
  font-size: 13px; font-weight: 600; color: rgba(248,249,250,.7);
  text-decoration: none; transition: background .18s, color .18s, border-color .18s;
}
.cov-nav-chip:hover { background: rgba(248,249,250,.14); color: #F8F9FA; border-color: rgba(248,249,250,.25); }
.cov-nav-chip-num {
  font-size: 10px; font-weight: 900; font-family: var(--display);
  color: rgba(248,249,250,.3);
}

/* Values list */
.cov-list {
  background: var(--bg);
}
.cov-item {
  border-bottom: 1px solid var(--line);
}
.cov-item-inner {
  max-width: var(--maxw); margin: 0 auto; padding: 60px 40px;
  display: grid; grid-template-columns: 200px 1fr; gap: 52px; align-items: start;
}
/* Alternating background */
.cov-item:nth-child(even) { background: var(--surface); }

/* Left column: number + icon */
.cov-item-aside {
  display: flex; flex-direction: column; align-items: flex-start; gap: 16px;
}
.cov-item-num {
  font-family: var(--display);
  font-size: clamp(4rem, 7vw, 5.5rem); font-weight: 900;
  line-height: 1; letter-spacing: -.04em;
  color: var(--item-accent, #66C5C5);
  opacity: .18;
}
.cov-item-icon {
  width: 52px; height: 52px; border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--item-accent, #66C5C5) 12%, transparent);
  color: var(--item-accent, #66C5C5);
  margin-top: -16px;
}
.cov-item-badge {
  font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  padding: 4px 12px; border-radius: 99px;
  background: color-mix(in srgb, var(--item-accent, #66C5C5) 10%, transparent);
  color: var(--item-accent-dark, #004081);
  border: 1px solid color-mix(in srgb, var(--item-accent, #66C5C5) 25%, transparent);
}

/* Right column: content */
.cov-item-body { padding-top: 8px; }
.cov-item-title {
  font-family: var(--display);
  font-size: clamp(1.5rem, 2.5vw, 2rem); font-weight: 900;
  color: var(--ink); margin: 0 0 8px; letter-spacing: -.02em; line-height: 1.2;
}
.cov-item-tagline {
  font-size: 15px; color: var(--muted); line-height: 1.7; margin: 0 0 28px;
  max-width: 580px;
}
.cov-points-row {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px;
}
.cov-point {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 16px;
  border-top: 2px solid var(--item-accent, #66C5C5);
  transition: box-shadow .2s, transform .2s;
}
.cov-point:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.cov-point-k {
  display: block; font-size: 11px; font-weight: 800;
  letter-spacing: .07em; text-transform: uppercase;
  color: var(--item-accent-dark, #004081); margin-bottom: 6px;
}
.cov-point-v { font-size: 13px; color: #505050; line-height: 1.6; }

/* Bottom CTA strip */
.cov-cta {
  background: linear-gradient(90deg, rgba(102,197,197,.06), rgba(0,64,129,.04));
  border-top: 1px solid rgba(102,197,197,.2);
  padding: 48px 40px;
}
.cov-cta-inner {
  max-width: var(--maxw); margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
}
.cov-cta-text h4 { font-size: 16px; font-weight: 700; color: var(--ink); margin: 0 0 4px; }
.cov-cta-text p  { font-size: 14px; color: var(--muted); margin: 0; }

/* Responsive */
@media (max-width: 860px) {
  .cov-item-inner { grid-template-columns: 1fr; gap: 24px; }
  .cov-item-aside { flex-direction: row; align-items: center; }
  .cov-item-num { font-size: 3rem; opacity: .25; }
  .cov-item-icon { margin-top: 0; }
  .cov-points-row { grid-template-columns: 1fr 1fr; }
  .cov-cta-inner { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 540px) {
  .cov-points-row { grid-template-columns: 1fr; }
  .cov-nav { gap: 6px; }
}

/* ============================================================
   FIRST DAY V4 — Horizontal Story / fd3-*
   ============================================================ */

/* --- Story wrapper --- */
.fd3-page { background: #F8F9FA; }

/* --- Welcome Band --- */
.fd3-welcome {
  background: linear-gradient(135deg, #004081 0%, #004081 55%, #66C5C5 100%);
  padding: 72px 24px 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.fd3-welcome::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23F8F9FA' fill-opacity='0.04'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.fd3-welcome-inner { position: relative; max-width: 640px; margin: 0 auto; }
.fd3-day-chip {
  display: inline-flex; align-items: center; gap: 8px;
  background: rgba(248,249,250,.15); border: 1px solid rgba(248,249,250,.3);
  color: #F8F9FA; border-radius: 99px;
  padding: 6px 18px; font-size: .8rem; font-weight: 600;
  letter-spacing: .1em; text-transform: uppercase; margin-bottom: 20px;
}
.fd3-day-chip-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: #66C5C5;
  animation: fd3pulse 1.6s ease-in-out infinite;
}
@keyframes fd3pulse {
  0%,100% { opacity:1; transform:scale(1); }
  50% { opacity:.4; transform:scale(1.4); }
}
.fd3-welcome h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 800; color: #F8F9FA; line-height: 1.15; margin-bottom: 16px;
}
.fd3-welcome h1 em { font-style: normal; color: #D0D6DF; }
.fd3-welcome-sub {
  font-size: 1.05rem; color: rgba(248,249,250,.75);
  max-width: 480px; margin: 0 auto 32px; line-height: 1.7;
}
.fd3-scroll-hint {
  display: inline-flex; align-items: center; gap: 10px;
  color: rgba(248,249,250,.6); font-size: .85rem; cursor: pointer;
  border: 1px solid rgba(248,249,250,.25); border-radius: 99px;
  padding: 10px 22px; transition: background .2s;
}
.fd3-scroll-hint:hover { background: rgba(248,249,250,.1); }
.fd3-scroll-hint svg { animation: fd3slide 1.4s ease-in-out infinite; }
@keyframes fd3slide {
  0%,100% { transform:translateX(0); } 50% { transform:translateX(6px); }
}

/* --- Story Strip --- */
.fd3-strip-outer {
  padding: 0;
  position: relative;
}
/* Side fade overlays */
