.fd5-strip-outer { position: relative; }
.fd5-strip-outer::before, .fd5-strip-outer::after {
  content: ''; position: absolute; top: 0; bottom: 40px; width: 100px; z-index: 2; pointer-events: none;
}
.fd5-strip-outer::before { left: 0; background: linear-gradient(to right,#F8F9FA,transparent); }
.fd5-strip-outer::after  { right: 0; background: linear-gradient(to left,#F8F9FA,transparent); }

.fd5-strip {
  display: flex; gap: 18px;
  overflow-x: auto; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
  padding: 24px 100px 40px;
  scrollbar-width: none; perspective: 1200px;
