/* Panel */
.fd5-card {
  flex: 0 0 300px; scroll-snap-align: center;
  background: #F8F9FA; border-radius: 20px;
  border: 1.5px solid #F8F9FA;
  padding: 28px 24px 24px; position: relative; overflow: hidden;
  cursor: pointer;
