.fd5-eyebrow { font-size: .72rem; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--cyan,#66C5C5); margin-bottom: 8px; }
.fd5-section-h { font-size: 1.6rem; font-weight: 800; color: #004081; margin-bottom: 6px; }
.fd5-section-p { color: #707070; margin-bottom: 36px; line-height: 1.7; }

/* ══════════════════════════════════════════════
   ACHIEVEMENT STAMPS (replaces checklist)
══════════════════════════════════════════════ */
.fd5-achieve { background: #F8F9FA; border-top: 1px solid #F8F9FA; padding: 64px 24px 80px; }
.fd5-achieve-inner { max-width: 860px; margin: 0 auto; }
.fd5-achieve-grid {
  display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; margin-top: 36px;
}
@media(max-width:680px){ .fd5-achieve-grid{ grid-template-columns: repeat(2,1fr); } }

.fd5-ach {
  background: #F8F9FA; border: 1.5px solid #F8F9FA;
  border-radius: 16px; padding: 24px 20px;
  cursor: pointer; position: relative; overflow: hidden;
  transition: transform .2s, box-shadow .2s, border-color .2s;
  user-select: none;
  text-align: center;
}
.fd5-ach:hover { transform: translateY(-3px); box-shadow: 0 8px 28px rgba(0,64,129,.09); border-color: #D0D6DF; }
.fd5-ach.fd5-ach--done {
  border-color: var(--ach-c,#66C5C5);
  background: color-mix(in srgb, var(--ach-c,#66C5C5) 6%, #F8F9FA);
}
/* Stamp overlay */
.fd5-ach-stamp {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  pointer-events: none;
}
.fd5-ach-stamp-ring {
  width: 64px; height: 64px; border-radius: 50%;
  border: 3px solid var(--ach-c,#66C5C5);
  display: flex; align-items: center; justify-content: center;
  transform: scale(0) rotate(-15deg);
  opacity: 0;
  transition: transform .35s cubic-bezier(0.25, 1, 0.5, 1), opacity .2s;
}
.fd5-ach--done .fd5-ach-stamp-ring {
  transform: scale(1) rotate(-15deg);
  opacity: 1;
}
.fd5-ach-stamp-check {
  color: var(--ach-c,#66C5C5); font-size: 1.6rem; font-weight: 900; line-height: 1;
}
.fd5-ach-icon {
  font-size: 2rem; margin-bottom: 10px; display: block;
  transition: opacity .2s;
}
.fd5-ach--done .fd5-ach-icon { opacity: .2; }
.fd5-ach-label {
  font-size: .85rem; font-weight: 700; color: #004081; line-height: 1.4;
  transition: opacity .2s;
}
.fd5-ach--done .fd5-ach-label { opacity: .35; }
.fd5-ach-sub {
  font-size: .72rem; color: #707070; margin-top: 4px;
  transition: opacity .2s;
}
.fd5-ach--done .fd5-ach-sub { opacity: .3; }

/* Progress row */
.fd5-ach-prog-row {
  display: flex; align-items: center; gap: 16px; margin-top: 28px;
}
.fd5-ach-prog-bar {
  flex: 1; height: 8px; background: #F8F9FA; border-radius: 99px; overflow: hidden;
}
.fd5-ach-prog-fill {
  height: 100%;
  background: linear-gradient(90deg,#66C5C5,#004081);
  border-radius: 99px; width: 0%;
  transition: width .5s cubic-bezier(.4,0,.2,1);
}
.fd5-ach-prog-txt {
  font-size: .82rem; font-weight: 700; color: #004081; white-space: nowrap;
}
.fd5-ach-complete-msg {
  text-align: center; padding: 16px;
  font-weight: 700; color: var(--cyan,#66C5C5);
  font-size: .95rem; display: none; margin-top: 12px;
  animation: fd5pop .4s cubic-bezier(0.25, 1, 0.5, 1);
}
@keyframes fd5pop { from{transform:scale(.7);opacity:0} to{transform:scale(1);opacity:1} }

/* ============================================================
   FIRST DAY V5 — fd4-* (3D strip, rail, circular checklist)
   ============================================================ */

/* ── Hero ── */
.fd4-hero {
  min-height: 88vh;
  background: #001122;
  display: flex; align-items: center; justify-content: center;
  position: relative; overflow: hidden; text-align: center;
  padding: 80px 24px;
}
/* Floating orbs */
.fd4-orb {
  position: absolute; border-radius: 50%;
  filter: blur(72px); pointer-events: none;
}
.fd4-orb-1 { width:480px;height:480px; background:rgba(102,197,197,.22); top:-100px; left:-120px;
  animation: fd4float1 9s ease-in-out infinite; }
.fd4-orb-2 { width:320px;height:320px; background:rgba(0,64,129,.45); bottom:-80px; right:-60px;
  animation: fd4float2 11s ease-in-out infinite; }
.fd4-orb-3 { width:200px;height:200px; background:rgba(146,158,180,.3); top:40%; left:55%;
  animation: fd4float1 7s ease-in-out infinite reverse; }
@keyframes fd4float1 { 0%,100%{transform:translate(0,0)} 50%{transform:translate(30px,-40px)} }
@keyframes fd4float2 { 0%,100%{transform:translate(0,0)} 50%{transform:translate(-25px,30px)} }

/* Dot-grid overlay */
.fd4-hero::before {
  content:''; position:absolute; inset:0;
  background-image: radial-gradient(rgba(248,249,250,.07) 1px, transparent 1px);
  background-size: 32px 32px; pointer-events:none;
}

.fd4-hero-inner { position:relative; z-index:1; max-width:700px; }

.fd4-hero-kicker {
  display:inline-flex; align-items:center; gap:9px;
  border:1px solid rgba(102,197,197,.35); border-radius:99px;
  padding:7px 20px; margin-bottom:28px;
  font-size:.78rem; font-weight:700; letter-spacing:.12em; text-transform:uppercase;
  color:rgba(248,249,250,.7);
  background: rgba(102,197,197,.08);
}
.fd4-kicker-dot {
  width:8px; height:8px; border-radius:50%; background:#66C5C5;
  animation: fd4pulse 1.8s ease-in-out infinite;
}
@keyframes fd4pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.3;transform:scale(1.5)} }

.fd4-hero-h1 {
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 900; line-height: 1.1;
  color: #F8F9FA; margin-bottom: 20px;
  letter-spacing: -.02em;
}
.fd4-hero-h1 .fd4-grad {
  background: linear-gradient(90deg, #66C5C5 0%, #D0D6DF 50%, #F8F9FA 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}

.fd4-hero-sub {
  font-size: 1.05rem; color: rgba(248,249,250,.55);
  max-width: 500px; margin: 0 auto 40px; line-height: 1.75;
}

.fd4-hero-cta {
  display: inline-flex; align-items: center; gap: 10px;
  background: linear-gradient(135deg,#66C5C5,#586782);
  color: #F8F9FA; padding: 15px 34px; border-radius: 99px;
  font-weight: 700; font-size: .95rem; text-decoration: none;
  box-shadow: 0 8px 32px rgba(102,197,197,.35);
  transition: transform .2s, box-shadow .2s;
}
.fd4-hero-cta:hover { transform: translateY(-3px); box-shadow: 0 14px 40px rgba(102,197,197,.45); }
.fd4-hero-cta svg { animation: fd4slide 1.5s ease-in-out infinite; }
@keyframes fd4slide { 0%,100%{transform:translateX(0)} 50%{transform:translateX(5px)} }

/* scroll down indicator */
.fd4-scroll-down {
  position: absolute; bottom: 32px; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  color: rgba(248,249,250,.3); font-size: .72rem; letter-spacing: .1em; text-transform: uppercase;
  animation: fd4bob 2s ease-in-out infinite;
}
@keyframes fd4bob { 0%,100%{transform:translateX(-50%) translateY(0)} 50%{transform:translateX(-50%) translateY(6px)} }

/* ── Strip Section ── */
.fd4-strip-section {
  background: #F8F9FA;
  padding: 72px 0 48px;
}
.fd4-strip-hd {
  text-align: center; padding: 0 24px; margin-bottom: 48px;
}
.fd4-strip-eyebrow {
  font-size: .72rem; font-weight: 700; letter-spacing: .15em;
  text-transform: uppercase; color: var(--cyan,#66C5C5); margin-bottom: 10px;
  display: block;
}
.fd4-strip-title {
  font-size: 1.75rem; font-weight: 800; color: #004081; margin-bottom: 8px;
}
.fd4-strip-sub { color: #707070; font-size: .95rem; }

/* Rail + cards container */
.fd4-rail-wrap {
  position: relative;
  overflow: hidden;
}
/* The horizontal scrollable area */
.fd4-scroll {
  display: flex; gap: 0;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 16px 80px 48px;
  scrollbar-width: none;
  cursor: grab;
}
.fd4-scroll:active { cursor: grabbing; }
.fd4-scroll::-webkit-scrollbar { display: none; }

/* Rail line — absolutely positioned below the step nodes */
.fd4-rail-line {
  position: absolute;
  top: 60px; /* aligns with node center */
  left: 80px; right: 80px; height: 2px;
  background: linear-gradient(90deg,
    transparent 0%,
    #D0D6DF 8%,
    #D0D6DF 92%,
    transparent 100%);
  pointer-events: none;
  z-index: 0;
}

/* ── Story Card ── */
.fd4-card {
  flex: 0 0 280px;
  scroll-snap-align: center;
  position: relative;
  padding: 0 12px;
  z-index: 1;
  /* stagger entrance */
  opacity: 0; transform: translateY(40px);
  transition: opacity .5s ease, transform .5s ease;
}
.fd4-card.fd4-visible { opacity: 1; transform: translateY(0); }

/* The visual card box */
.fd4-card-box {
  background: #F8F9FA;
  border-radius: 20px;
  border: 1.5px solid #F8F9FA;
  padding: 28px 24px 24px;
  box-shadow: 0 2px 12px rgba(0,64,129,.05);
  transform-style: preserve-3d;
  transition: box-shadow .3s, border-color .3s;
  will-change: transform;
  position: relative; overflow: hidden;
}
.fd4-card-box::before {
  content:''; position:absolute; inset:0; border-radius: 18px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--card-accent,#66C5C5) 6%, transparent), transparent 60%);
  pointer-events: none;
}
.fd4-card-box:hover {
  border-color: var(--card-accent,#66C5C5);
  box-shadow: 0 20px 50px rgba(0,64,129,.16),
              0 0 0 3px color-mix(in srgb, var(--card-accent,#66C5C5) 18%, transparent);
}

/* Node circle on top */
.fd4-node {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--card-accent,#66C5C5);
  color: #F8F9FA; font-weight: 800; font-size: .9rem;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 20px;
  box-shadow: 0 4px 16px color-mix(in srgb, var(--card-accent,#66C5C5) 45%, transparent);
  position: relative; z-index: 1;
}

.fd4-card-icon {
  width: 52px; height: 52px; border-radius: 14px; margin: 0 0 16px;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--card-accent,#66C5C5) 12%, transparent);
  color: var(--card-accent,#66C5C5);
}
.fd4-card h3 {
  font-size: 1rem; font-weight: 700; color: #004081; margin-bottom: 8px;
}
.fd4-card-desc {
  font-size: .85rem; color: #707070; line-height: 1.65; margin-bottom: 16px;
}
.fd4-card-tags {
  display: flex; flex-wrap: wrap; gap: 5px;
}
.fd4-card-tag {
  font-size: .7rem; font-weight: 600; padding: 3px 9px; border-radius: 99px;
  background: color-mix(in srgb, var(--card-accent,#66C5C5) 10%, transparent);
  color: var(--card-accent,#66C5C5);
  border: 1px solid color-mix(in srgb, var(--card-accent,#66C5C5) 25%, transparent);
}

/* Dots nav */
.fd4-dots {
  display: flex; justify-content: center; gap: 8px; padding: 4px 0 0;
}
.fd4-dot {
  width: 8px; height: 8px; border-radius: 99px;
  background: #D0D6DF; border: none; cursor: pointer;
  transition: width .25s, background .25s; padding: 0;
}
.fd4-dot.on { width: 28px; background: var(--cyan,#66C5C5); }

/* ── Mission Cards ── */
.fd4-mission {
  background: #F8F9FA; border-top: 1px solid #F8F9FA;
  padding: 64px 24px;
}
.fd4-mission-inner { max-width: 860px; margin: 0 auto; }
.fd4-sec-label { font-size:.72rem; font-weight:700; letter-spacing:.15em; text-transform:uppercase; color:var(--cyan,#66C5C5); margin-bottom:10px; display:block; }
.fd4-sec-title { font-size:1.75rem; font-weight:800; color:#004081; margin-bottom:8px; }
.fd4-sec-sub { color:#707070; margin-bottom:36px; line-height:1.7; }
.fd4-mcards { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
@media(max-width:640px){ .fd4-mcards{grid-template-columns:1fr;} }
.fd4-mc {
  border-radius:18px; border:1.5px solid #F8F9FA; overflow:hidden;
  transition: box-shadow .25s, border-color .25s, transform .25s;
}
.fd4-mc:hover { box-shadow:0 12px 36px rgba(0,64,129,.1); border-color:var(--mc-accent,#66C5C5); transform:translateY(-4px); }
.fd4-mc-head {
  padding:22px 22px 18px;
  background: color-mix(in srgb, var(--mc-accent,#66C5C5) 7%, #F8F9FA);
  border-bottom:1px solid color-mix(in srgb, var(--mc-accent,#66C5C5) 18%, transparent);
  display:flex; align-items:center; gap:14px;
}
.fd4-mc-ico {
  width:44px; height:44px; border-radius:12px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background: color-mix(in srgb, var(--mc-accent,#66C5C5) 14%, transparent);
  color:var(--mc-accent,#66C5C5);
}
.fd4-mc-num { font-size:.68rem; font-weight:700; letter-spacing:.12em; color:var(--mc-accent,#66C5C5); margin-bottom:3px; }
.fd4-mc-title { font-size:1rem; font-weight:700; color:#004081; }
.fd4-mc-body { padding:18px 22px 20px; }
.fd4-mc-desc { font-size:.88rem; color:#707070; line-height:1.65; margin-bottom:16px; }
.fd4-mc-steps { display:flex; gap:0; margin-bottom:16px; }
.fd4-mc-step { flex:1; text-align:center; font-size:.75rem; color:#707070; position:relative; }
.fd4-mc-step::after { content:'→'; position:absolute; right:-8px; top:10px; color:#D0D6DF; }
.fd4-mc-step:last-child::after { display:none; }
.fd4-mc-step-ico {
  width:34px; height:34px; border-radius:50%; margin:0 auto 5px;
  display:flex; align-items:center; justify-content:center; font-size:.95rem;
  background: color-mix(in srgb, var(--mc-accent,#66C5C5) 10%, transparent);
}
.fd4-mc-cta {
  display:flex; align-items:center; justify-content:space-between;
  background: color-mix(in srgb, var(--mc-accent,#66C5C5) 9%, transparent);
  border-radius:10px; padding:11px 15px;
  color:var(--mc-accent,#66C5C5); font-weight:600; font-size:.85rem;
  text-decoration:none; transition:background .2s;
}
.fd4-mc-cta:hover { background: color-mix(in srgb, var(--mc-accent,#66C5C5) 18%, transparent); }

/* ── Circular Checklist ── */
.fd4-ring-section {
  background: linear-gradient(160deg, #001122 0%, #001122 60%, #001122 100%);
  padding: 80px 24px;
  position: relative; overflow: hidden;
}
.fd4-ring-section::before {
  content:''; position:absolute; inset:0;
  background-image: radial-gradient(rgba(102,197,197,.07) 1px, transparent 1px);
  background-size: 28px 28px;
}
.fd4-ring-inner {
  max-width: 900px; margin: 0 auto; position: relative; z-index: 1;
  display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
}
@media(max-width:700px){ .fd4-ring-inner{grid-template-columns:1fr; text-align:center;} }

/* Ring side */
.fd4-ring-side { display:flex; flex-direction:column; align-items:center; }
.fd4-ring-svg { width:200px; height:200px; }
.fd4-ring-bg { fill:none; stroke:rgba(248,249,250,.08); stroke-width:14; }
.fd4-ring-fg {
  fill:none; stroke:#66C5C5; stroke-width:14;
  stroke-linecap:round;
  stroke-dasharray: 565; /* 2π×90 */
  stroke-dashoffset: 565;
  transform: rotate(-90deg); transform-origin: 50% 50%;
  transition: stroke-dashoffset .6s cubic-bezier(.4,0,.2,1);
}
.fd4-ring-text { font-size:2.2rem; font-weight:900; fill:#F8F9FA; text-anchor:middle; dominant-baseline:central; }
.fd4-ring-sub-text { font-size:.75rem; fill:rgba(248,249,250,.4); text-anchor:middle; }
.fd4-ring-label { color:rgba(248,249,250,.45); font-size:.82rem; margin-top:14px; }

/* List side */
.fd4-ring-section .fd4-sec-label { color:#66C5C5; }
.fd4-ring-section .fd4-sec-title { color:#F8F9FA; }
.fd4-ring-section .fd4-sec-sub { color:rgba(248,249,250,.5); margin-bottom:24px; }
.fd4-cl { list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:8px; }
.fd4-cl-item {
  display:flex; align-items:center; gap:12px;
  background:rgba(248,249,250,.05); border:1px solid rgba(248,249,250,.08);
  border-radius:12px; padding:12px 16px; cursor:pointer;
  transition:background .2s, border-color .2s, transform .15s;
}
.fd4-cl-item:hover { background:rgba(248,249,250,.09); transform:translateX(4px); }
.fd4-cl-item.done { background:rgba(102,197,197,.1); border-color:rgba(102,197,197,.3); }
.fd4-cl-item.done .fd4-cl-box { background:#66C5C5; border-color:#66C5C5; }
.fd4-cl-item.done .fd4-cl-box::after { opacity:1; transform:rotate(45deg) scale(1); }
.fd4-cl-item.done .fd4-cl-lbl { opacity:.45; text-decoration:line-through; }
.fd4-cl-box {
  width:20px; height:20px; border-radius:6px; flex-shrink:0;
  border:2px solid rgba(248,249,250,.25); position:relative;
  transition:background .2s, border-color .2s;
}
.fd4-cl-box::after {
  content:''; position:absolute; top:2px; left:6px;
  width:5px; height:9px;
  border:2px solid #F8F9FA; border-top:0; border-left:0;
  opacity:0; transform:rotate(45deg) scale(.6);
  transition: opacity .15s, transform .2s;
}
.fd4-cl-lbl { color:#F8F9FA; font-size:.88rem; font-weight:500; transition:opacity .2s; }

/* Confetti burst (js-driven) */
.fd4-confetti-piece {
  position:fixed; width:8px; height:8px; border-radius:2px;
  pointer-events:none; z-index:9999;
  animation: fd4fall var(--dur,1.2s) ease-in forwards;
}
@keyframes fd4fall {
  0%   { opacity:1; transform:translate(0,0) rotate(0deg) scale(1); }
  100% { opacity:0; transform:translate(var(--tx,0),var(--ty,120px)) rotate(var(--rot,360deg)) scale(.4); }
}

/* ============================================================
   FIRST DAY V5 — fd5-*
   Dynamic hero · Timeless story strip · Achievement cards
   ============================================================ */

/* ── Page shell ── */
.fd5 { background: #F8F9FA; }

/* ══════════════════════════════════════════════
   HERO — animated blobs, big typographic split
   ══════════════════════════════════════════════ */
.fd5-hero {
  position: relative; overflow: hidden;
  min-height: 92vh;
  display: flex; align-items: center;
  background: #001122;
  padding: 80px 24px;
}

/* animated mesh gradient */
.fd5-hero::before {
  content: '';
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 20% 40%, rgba(0,64,129,.55) 0%, transparent 65%),
    radial-gradient(ellipse 60% 50% at 80% 70%, rgba(102,197,197,.3) 0%, transparent 60%),
    radial-gradient(ellipse 50% 40% at 60% 10%, rgba(88,103,130,.25) 0%, transparent 55%);
  animation: fd5mesh 8s ease-in-out infinite alternate;
}
@keyframes fd5mesh {
  0%   { opacity: 1; transform: scale(1) translateX(0); }
  50%  { opacity: .85; transform: scale(1.04) translateX(-1%); }
  100% { opacity: 1; transform: scale(1) translateX(1%); }
}

/* floating blobs */
.fd5-blob {
  position: absolute; border-radius: 50%; pointer-events: none; will-change: transform;
}
.fd5-blob-1 {
  width: 480px; height: 480px;
  background: radial-gradient(circle, rgba(102,197,197,.18) 0%, transparent 70%);
  top: -120px; right: -80px;
  animation: fd5float1 7s ease-in-out infinite;
}
.fd5-blob-2 {
  width: 320px; height: 320px;
  background: radial-gradient(circle, rgba(0,64,129,.35) 0%, transparent 70%);
  bottom: -60px; left: 5%;
  animation: fd5float2 9s ease-in-out infinite;
}
.fd5-blob-3 {
  width: 180px; height: 180px;
  background: radial-gradient(circle, rgba(102,197,197,.22) 0%, transparent 70%);
  top: 30%; left: 48%;
  animation: fd5float3 6s ease-in-out infinite;
}
@keyframes fd5float1 { 0%,100%{transform:translate(0,0) scale(1)} 50%{transform:translate(-30px,25px) scale(1.06)} }
@keyframes fd5float2 { 0%,100%{transform:translate(0,0) scale(1)} 50%{transform:translate(20px,-30px) scale(1.04)} }
@keyframes fd5float3 { 0%,100%{transform:translate(0,0)} 33%{transform:translate(18px,-12px)} 66%{transform:translate(-10px,20px)} }

/* dots grid pattern */
.fd5-hero::after {
  content: '';
  position: absolute; inset: 0; pointer-events: none;
  background-image: radial-gradient(circle, rgba(248,249,250,.06) 1px, transparent 1px);
  background-size: 32px 32px;
}

.fd5-hero-inner {
  position: relative; z-index: 2;
  max-width: 1160px; margin: 0 auto; width: 100%;
  display: grid; grid-template-columns: 1fr 420px; gap: 64px; align-items: center;
}
@media(max-width:900px){ .fd5-hero-inner{ grid-template-columns:1fr; gap:40px; } }

/* Left copy */
.fd5-kicker {
  display: inline-flex; align-items: center; gap: 10px;
  background: rgba(102,197,197,.12); border: 1px solid rgba(102,197,197,.3);
  border-radius: 99px; padding: 6px 16px 6px 10px;
  color: #D0D6DF; font-size: .78rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase;
  margin-bottom: 28px;
  animation: fd5fadein .6s ease both;
}
.fd5-kicker-dot {
  width: 8px; height: 8px; border-radius: 50%; background: #66C5C5;
  box-shadow: 0 0 0 0 rgba(102,197,197,.5);
  animation: fd5ping 1.8s ease-in-out infinite;
}
@keyframes fd5ping {
  0%,100%{ box-shadow: 0 0 0 0 rgba(102,197,197,.5); }
  60%{ box-shadow: 0 0 0 8px rgba(102,197,197,0); }
}

.fd5-h1 {
  font-size: clamp(2.6rem, 5.5vw, 4.2rem);
  font-weight: 900; line-height: 1.08; color: #F8F9FA;
  margin-bottom: 20px; letter-spacing: -.02em;
  animation: fd5fadein .6s .15s ease both;
}
.fd5-h1 .fd5-grad {
  background: linear-gradient(90deg, #66C5C5, #D0D6DF 40%, #F8F9FA 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}

.fd5-sub {
  font-size: 1.05rem; color: rgba(248,249,250,.65);
  line-height: 1.75; margin-bottom: 36px; max-width: 480px;
  animation: fd5fadein .6s .3s ease both;
}

.fd5-hero-ctas {
  display: flex; gap: 12px; flex-wrap: wrap;
  animation: fd5fadein .6s .45s ease both;
}
.fd5-btn-primary {
  display: inline-flex; align-items: center; gap: 8px;
  background: linear-gradient(135deg, #66C5C5, #586782);
  color: #F8F9FA; border: none; border-radius: 99px;
  padding: 14px 28px; font-size: .95rem; font-weight: 700;
  cursor: pointer; text-decoration: none;
  transition: transform .2s, box-shadow .2s;
  box-shadow: 0 4px 20px rgba(102,197,197,.35);
}
.fd5-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(102,197,197,.45); }
.fd5-btn-ghost {
  display: inline-flex; align-items: center; gap: 8px;
  background: rgba(248,249,250,.07); border: 1px solid rgba(248,249,250,.2);
  color: rgba(248,249,250,.8); border-radius: 99px;
  padding: 14px 28px; font-size: .95rem; font-weight: 600;
  cursor: pointer; text-decoration: none;
  transition: background .2s;
}
.fd5-btn-ghost:hover { background: rgba(248,249,250,.12); }

@keyframes fd5fadein {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Right — step preview card */
.fd5-preview-card {
  background: rgba(248,249,250,.06);
  backdrop-filter: blur(20px) saturate(1.4);
  -webkit-backdrop-filter: blur(20px) saturate(1.4);
  border: 1px solid rgba(248,249,250,.12);
  border-radius: 24px; padding: 28px;
  animation: fd5fadein .6s .5s ease both;
}
.fd5-preview-label {
  font-size: .7rem; letter-spacing: .14em; text-transform: uppercase;
  color: rgba(248,249,250,.45); margin-bottom: 18px; font-weight: 600;
}
.fd5-preview-steps { display: flex; flex-direction: column; gap: 10px; }
.fd5-pstep {
  display: flex; align-items: center; gap: 14px;
  background: rgba(248,249,250,.04); border-radius: 12px; padding: 12px 16px;
  border: 1px solid rgba(248,249,250,.07);
  transition: background .2s;
}
.fd5-pstep:hover { background: rgba(248,249,250,.08); }
.fd5-pstep-n {
  width: 28px; height: 28px; border-radius: 8px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: .75rem; font-weight: 800;
  background: rgba(102,197,197,.2); color: #66C5C5;
}
.fd5-pstep-text { color: rgba(248,249,250,.8); font-size: .88rem; font-weight: 500; }
.fd5-pstep-arrow { margin-left: auto; color: rgba(248,249,250,.25); font-size: .8rem; }
.fd5-pstep.active { background: rgba(102,197,197,.1); border-color: rgba(102,197,197,.25); }
.fd5-pstep.active .fd5-pstep-n { background: #66C5C5; color: #001122; }
.fd5-pstep.active .fd5-pstep-text { color: #F8F9FA; }
.fd5-pstep.active .fd5-pstep-arrow { color: #66C5C5; }

/* scroll indicator */
.fd5-scroll-ind {
  position: absolute; bottom: 32px; left: 50%; transform: translateX(-50%);
  z-index: 3; display: flex; flex-direction: column; align-items: center; gap: 6px;
  color: rgba(248,249,250,.35); font-size: .72rem; letter-spacing: .1em; text-transform: uppercase;
  animation: fd5fadein .6s .8s ease both;
}
.fd5-scroll-mouse {
  width: 22px; height: 34px; border: 2px solid rgba(248,249,250,.2); border-radius: 11px;
  position: relative;
}
.fd5-scroll-mouse::after {
  content: '';
  position: absolute; top: 5px; left: 50%; transform: translateX(-50%);
  width: 3px; height: 6px; background: rgba(248,249,250,.4); border-radius: 2px;
  animation: fd5scroll 1.6s ease-in-out infinite;
}
@keyframes fd5scroll { 0%,100%{opacity:1;top:5px} 50%{opacity:.3;top:14px} }

/* ══════════════════════════════════════════════
   STORY STRIP V5 — no times, tilt on hover
   ══════════════════════════════════════════════ */
.fd5-strip-section { padding: 64px 0 48px; background: #F8F9FA; }
.fd5-strip-hd {
  text-align: center; margin-bottom: 40px; padding: 0 24px;
}
.fd5-strip-eyebrow {
  font-size: .72rem; letter-spacing: .16em; text-transform: uppercase;
  color: var(--cyan,#66C5C5); font-weight: 700; margin-bottom: 8px;
}
.fd5-strip-title {
  font-size: 1.6rem; font-weight: 800; color: #004081;
}

.fd5-strip-wrap { position: relative; }
.fd5-strip-wrap::before, .fd5-strip-wrap::after {
  content: ''; position: absolute; top:0; bottom:0; width:60px; z-index:2; pointer-events:none;
}
.fd5-strip-wrap::before { left:0; background:linear-gradient(to right,#F8F9FA,transparent); }
.fd5-strip-wrap::after  { right:0; background:linear-gradient(to left,#F8F9FA,transparent); }

.fd5-strip {
  display: flex; gap: 16px;
  overflow-x: auto; scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 16px 72px 24px;
  scrollbar-width: none;
}
.fd5-strip::-webkit-scrollbar { display: none; }

/* Individual panel */
.fd5-spanel {
  flex: 0 0 300px; scroll-snap-align: center;
  border-radius: 22px; padding: 0;
  overflow: hidden;
  cursor: pointer;
  transition: transform .3s cubic-bezier(0.25, 1, 0.5, 1), box-shadow .3s ease;
  box-shadow: 0 2px 16px rgba(0,17,34,.07);
  border: 1.5px solid rgba(248,249,250,.8);
  background: #F8F9FA;
  position: relative;
}
.fd5-spanel:hover {
  transform: translateY(-10px) rotate(-0.8deg);
  box-shadow: 0 24px 48px rgba(0,17,34,.15);
}
.fd5-spanel:nth-child(even):hover { transform: translateY(-10px) rotate(0.8deg); }

/* Coloured top band */
.fd5-spanel-band {
  height: 6px;
  background: var(--sp-accent, #66C5C5);
}

/* Panel number watermark */
.fd5-spanel-watermark {
  position: absolute; top: 8px; right: 14px;
  font-size: 5.5rem; font-weight: 900; line-height: 1;
  color: var(--sp-accent, #66C5C5); opacity: .07;
  pointer-events: none; user-select: none;
  font-variant-numeric: tabular-nums;
}

.fd5-spanel-body { padding: 24px 22px 20px; }

.fd5-spanel-step {
  display: inline-flex; align-items: center; gap: 6px;
  background: color-mix(in srgb, var(--sp-accent,#66C5C5) 12%, transparent);
  color: var(--sp-accent-dark, #586782);
  border-radius: 99px; padding: 4px 12px;
  font-size: .72rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  margin-bottom: 16px;
}

.fd5-spanel-icon {
  width: 52px; height: 52px; border-radius: 14px; margin-bottom: 16px;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--sp-accent,#66C5C5) 10%, transparent);
  color: var(--sp-accent-dark, #586782);
}

.fd5-spanel h3 { font-size: 1.05rem; font-weight: 700; color: #004081; margin-bottom: 8px; }
.fd5-spanel-desc { font-size: .86rem; color: #707070; line-height: 1.6; margin-bottom: 16px; }

/* Expandable detail */
.fd5-spanel-more {
  max-height: 0; overflow: hidden;
  transition: max-height .38s cubic-bezier(.4,0,.2,1);
}
.fd5-spanel--open .fd5-spanel-more { max-height: 200px; }

.fd5-spanel-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 12px; }
.fd5-spanel-tag {
  font-size: .7rem; font-weight: 600;
  padding: 3px 9px; border-radius: 99px;
  background: #F8F9FA; color: #004081;
}
.fd5-spanel-link {
  display: flex; align-items: center; gap: 5px;
  font-size: .82rem; font-weight: 600;
  color: var(--sp-accent-dark, #586782);
  text-decoration: none; border-top: 1px solid #F8F9FA; padding-top: 12px;
}

/* Tap hint */
.fd5-spanel-tap {
  display: flex; align-items: center; justify-content: space-between;
  font-size: .76rem; color: #929EB4; padding-top: 4px;
}
.fd5-spanel-tap svg { transition: transform .25s; }
.fd5-spanel--open .fd5-spanel-tap svg { transform: rotate(180deg); }

/* Dots */
.fd5-dots {
  display: flex; justify-content: center; gap: 7px; padding: 4px 0 0;
}
.fd5-dot {
  width: 7px; height: 7px; border-radius: 99px;
  background: #D0D6DF; border: none; cursor: pointer;
  transition: all .25s;
}
.fd5-dot.on { width: 22px; background: #66C5C5; }

/* ══════════════════════════════════════════════
   MISSION CARDS (unchanged style, small polish)
   ══════════════════════════════════════════════ */
.fd5-tasks { background: #F8F9FA; border-top: 1px solid #F8F9FA; padding: 64px 24px; }
.fd5-tasks-inner { max-width: 880px; margin: 0 auto; }
.fd5-sec-eye { font-size: .72rem; letter-spacing: .15em; text-transform: uppercase; color: #66C5C5; font-weight: 700; margin-bottom: 8px; }
.fd5-sec-h   { font-size: 1.7rem; font-weight: 800; color: #004081; margin-bottom: 6px; }
.fd5-sec-sub { color: #707070; margin-bottom: 36px; line-height: 1.7; }
.fd5-tcards  { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
@media(max-width:680px){ .fd5-tcards{ grid-template-columns:1fr; } }

.fd5-tcard { border-radius: 18px; border: 1.5px solid #F8F9FA; overflow: hidden; transition: box-shadow .2s, border-color .2s; }
.fd5-tcard:hover { box-shadow: 0 8px 32px rgba(0,64,129,.1); border-color: var(--tc-accent); }
.fd5-tcard-top {
  padding: 22px 22px 18px;
  background: color-mix(in srgb, var(--tc-accent) 8%, #F8F9FA);
  border-bottom: 1.5px solid color-mix(in srgb, var(--tc-accent) 18%, transparent);
  display: flex; gap: 14px; align-items: flex-start;
}
.fd5-tcard-ico {
  width: 46px; height: 46px; border-radius: 12px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--tc-accent) 14%, transparent);
  color: var(--tc-accent);
}
.fd5-tcard-label { font-size: .68rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--tc-accent); margin-bottom: 3px; }
.fd5-tcard-title { font-size: 1rem; font-weight: 700; color: #004081; margin-bottom: 4px; }
.fd5-tcard-badge { display: inline-block; font-size: .68rem; font-weight: 700; padding: 2px 10px; border-radius: 99px; background: var(--tc-accent); color: #F8F9FA; }
.fd5-tcard-body { padding: 18px 22px 22px; }
.fd5-tcard-desc { font-size: .88rem; color: #707070; line-height: 1.65; margin-bottom: 16px; }
.fd5-tcard-flow { display: flex; gap: 0; margin-bottom: 16px; }
.fd5-tcard-fstep { flex:1; text-align:center; font-size:.76rem; color:#707070; position:relative; }
.fd5-tcard-fstep::after { content:'→'; position:absolute; right:-6px; top:11px; color:#D0D6DF; font-size:.85rem; }
.fd5-tcard-fstep:last-child::after { display:none; }
.fd5-tcard-ficon {
  width: 34px; height: 34px; border-radius: 50%; margin: 0 auto 5px;
  display: flex; align-items: center; justify-content: center;
  font-size: .95rem;
  background: color-mix(in srgb, var(--tc-accent) 10%, transparent);
}
.fd5-tcard-cta {
  display: flex; align-items: center; justify-content: space-between;
  background: color-mix(in srgb, var(--tc-accent) 8%, transparent);
  border-radius: 10px; padding: 11px 15px;
  text-decoration: none; color: var(--tc-accent);
  font-weight: 600; font-size: .86rem; transition: background .2s;
}
.fd5-tcard-cta:hover { background: color-mix(in srgb, var(--tc-accent) 16%, transparent); }

/* ══════════════════════════════════════════════
   ACHIEVEMENT UNLOCK — replaces plain checklist
   ══════════════════════════════════════════════ */
.fd5-achieve { padding: 64px 24px; background: #F8F9FA; border-top: 1px solid #F8F9FA; }
.fd5-achieve-inner { max-width: 900px; margin: 0 auto; }

/* Progress header */
.fd5-ach-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 32px; flex-wrap: wrap; gap: 16px;
}
.fd5-ach-prog-ring-wrap { position: relative; width: 72px; height: 72px; }
.fd5-ach-ring-svg { transform: rotate(-90deg); }
.fd5-ach-ring-bg { fill: none; stroke: #F8F9FA; stroke-width: 6; }
.fd5-ach-ring-fill { fill: none; stroke: #66C5C5; stroke-width: 6; stroke-linecap: round;
  stroke-dasharray: 188; stroke-dashoffset: 188;
  transition: stroke-dashoffset .5s cubic-bezier(.4,0,.2,1); }
.fd5-ach-ring-pct {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-size: .8rem; font-weight: 800; color: #004081;
}

/* Achievement card grid */
.fd5-ach-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
@media(max-width:720px){ .fd5-ach-grid{ grid-template-columns: repeat(2,1fr); } }
@media(max-width:480px){ .fd5-ach-grid{ grid-template-columns: 1fr; } }

.fd5-ach-card {
  border-radius: 16px; border: 1.5px solid #F8F9FA;
  background: #F8F9FA; padding: 20px 18px 18px;
  cursor: pointer; transition: all .25s;
  position: relative; overflow: hidden; user-select: none;
}
.fd5-ach-card::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--ach-color,#66C5C5) 0%, transparent 70%);
  opacity: 0; transition: opacity .3s;
}
.fd5-ach-card:hover { transform: translateY(-3px); box-shadow: 0 8px 24px rgba(0,64,129,.1); }
.fd5-ach-card.done {
  border-color: var(--ach-color,#66C5C5);
  background: color-mix(in srgb, var(--ach-color,#66C5C5) 6%, #F8F9FA);
}
.fd5-ach-card.done::before { opacity: .04; }
.fd5-ach-card.done .fd5-ach-icon-wrap { background: var(--ach-color,#66C5C5); color: #F8F9FA; }
.fd5-ach-card.done .fd5-ach-check { opacity: 1; transform: scale(1); }
.fd5-ach-card.done .fd5-ach-name { color: #004081; }

.fd5-ach-card-top { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 12px; }
.fd5-ach-icon-wrap {
  width: 42px; height: 42px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--ach-color,#66C5C5) 12%, #F8F9FA);
  color: var(--ach-color-dark, #586782);
  transition: all .25s;
}
.fd5-ach-check {
  width: 22px; height: 22px; border-radius: 50%;
  background: var(--ach-color,#66C5C5);
  display: flex; align-items: center; justify-content: center;
  opacity: 0; transform: scale(0.4);
  transition: all .3s cubic-bezier(0.25, 1, 0.5, 1);
}
.fd5-ach-check svg { stroke: #F8F9FA; }

.fd5-ach-name { font-size: .9rem; font-weight: 700; color: #707070; margin-bottom: 4px; transition: color .2s; }
.fd5-ach-hint { font-size: .76rem; color: #929EB4; line-height: 1.4; }

/* Pop animation on unlock */
/* duplicate fd5pop removed */
/* @keyframes fd5pop scale-bounce v2 */
}
.fd5-ach-card.popping { animation: fd5pop .35s ease; }

/* ============================================================
   FIRST DAY V6 — fd6-*
   Editorial split hero · Chapter spreads · Passport stamps
   ============================================================ */

/* ── Root ── */
.fd6 { background:#F8F9FA; }

/* ══════════════════════════════════════════════
   HERO — 50/50 split screen
   ══════════════════════════════════════════════ */
.fd6-hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 100vh;
}
@media(max-width:820px){ .fd6-hero{ grid-template-columns:1fr; min-height:auto; } }

/* LEFT — black typographic side */
.fd6-hero-l {
  background: #001122;
  padding: 64px 56px;
  display: flex; flex-direction: column; justify-content: space-between;
  position: relative; overflow: hidden;
}
.fd6-hero-l::after {
  content: 'DAY\A01';
  white-space: pre;
  position: absolute;
  bottom: -40px; right: -20px;
  font-size: 18vw; font-weight: 900; line-height: .85;
  color: rgba(248,249,250,.03);
  pointer-events: none; user-select: none;
  letter-spacing: -.04em;
}
@media(max-width:820px){ .fd6-hero-l::after{ font-size:34vw; } }

.fd6-hero-l-top {}
.fd6-eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  color: #66C5C5; font-size: .72rem; font-weight: 700;
  letter-spacing: .16em; text-transform: uppercase; margin-bottom: 32px;
}
.fd6-eyebrow-line {
  width: 28px; height: 2px; background: #66C5C5; border-radius: 2px;
}

.fd6-hero-h {
  font-size: clamp(3rem, 6vw, 5.5rem);
  font-weight: 900; line-height: 1.0; letter-spacing: -.03em;
  color: #F8F9FA; margin-bottom: 28px;
}
.fd6-hero-h em { font-style: normal; color: #66C5C5; }

.fd6-hero-body {
  font-size: 1rem; color: rgba(248,249,250,.5);
  line-height: 1.75; max-width: 380px; margin-bottom: 40px;
}

.fd6-hero-btns { display: flex; gap: 12px; flex-wrap: wrap; }
.fd6-btn-c {
  display: inline-flex; align-items: center; gap: 8px;
  background: #66C5C5; color: #001122;
  border-radius: 99px; padding: 13px 26px;
  font-size: .9rem; font-weight: 800; text-decoration: none;
  transition: background .2s, transform .2s;
}
.fd6-btn-c:hover { background: #66C5C5; transform: translateY(-1px); }
.fd6-btn-outline {
  display: inline-flex; align-items: center; gap: 8px;
  border: 1.5px solid rgba(248,249,250,.2); color: rgba(248,249,250,.7);
  border-radius: 99px; padding: 13px 26px;
  font-size: .9rem; font-weight: 600; text-decoration: none;
  transition: border-color .2s, color .2s;
}
.fd6-btn-outline:hover { border-color: rgba(248,249,250,.5); color: #F8F9FA; }

.fd6-hero-l-bottom {
  display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
}
.fd6-stat {
  padding-right: 20px;
  border-right: 1px solid rgba(248,249,250,.1);
}
.fd6-stat:last-child { border: none; }
.fd6-stat-n { font-size: 1.6rem; font-weight: 900; color: #F8F9FA; line-height: 1; }
.fd6-stat-l { font-size: .72rem; color: rgba(248,249,250,.4); letter-spacing: .06em; margin-top: 2px; }

/* RIGHT — vivid gradient + chapter previews */
.fd6-hero-r {
  background: linear-gradient(145deg, #004081 0%, #004081 40%, #004081 75%, #66C5C5 130%);
  padding: 64px 48px;
  display: flex; flex-direction: column; justify-content: center;
  position: relative; overflow: hidden;
}
/* geometric shapes */
.fd6-hero-r::before {
  content: '';
  position: absolute; width: 420px; height: 420px; border-radius: 50%;
  border: 60px solid rgba(248,249,250,.06);
  top: -120px; right: -140px;
}
.fd6-hero-r::after {
  content: '';
  position: absolute; width: 260px; height: 260px; border-radius: 50%;
  border: 40px solid rgba(248,249,250,.05);
  bottom: -80px; left: -60px;
}

.fd6-chapter-list {
  position: relative; z-index: 1;
  display: flex; flex-direction: column; gap: 0;
}
.fd6-chap-row {
  display: flex; align-items: center; gap: 20px;
  padding: 18px 0;
  border-bottom: 1px solid rgba(248,249,250,.1);
  cursor: pointer;
  transition: background .2s;
  border-radius: 8px; padding-left: 8px; padding-right: 8px;
  margin: 0 -8px;
}
.fd6-chap-row:hover { background: rgba(248,249,250,.06); }
.fd6-chap-row:last-child { border-bottom: none; }
.fd6-chap-n {
  font-size: .7rem; font-weight: 800; letter-spacing: .1em;
  color: rgba(248,249,250,.35); min-width: 28px; flex-shrink: 0;
}
.fd6-chap-ico {
  width: 38px; height: 38px; flex-shrink: 0; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(248,249,250,.1); color: rgba(248,249,250,.85);
}
.fd6-chap-txt { flex: 1; }
.fd6-chap-title { font-size: .9rem; font-weight: 700; color: #F8F9FA; margin-bottom: 2px; }
.fd6-chap-sub   { font-size: .75rem; color: rgba(248,249,250,.45); }
.fd6-chap-arr   { color: rgba(248,249,250,.25); font-size: .9rem; flex-shrink: 0; }
.fd6-chap-row:hover .fd6-chap-arr { color: #66C5C5; }

/* ══════════════════════════════════════════════
   CHAPTER SECTIONS — full-width story beats
   ══════════════════════════════════════════════ */
.fd6-chapters { background: #F8F9FA; }

.fd6-chapter {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 0;
  min-height: 300px;
  border-bottom: 1px solid #F8F9FA;
  position: relative; overflow: hidden;
}
@media(max-width:680px){ .fd6-chapter{ grid-template-columns: 1fr; } }

/* Alternate tint on even */
.fd6-chapter:nth-child(even) { background: #F8F9FA; }

/* Left accent column */
.fd6-chap-aside {
  background: var(--ch-accent, #66C5C5);
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  padding: 40px 20px; gap: 16px; position: relative; overflow: hidden;
}
.fd6-chap-aside::after {
  content: '';
  position: absolute; width: 200px; height: 200px; border-radius: 50%;
  background: rgba(248,249,250,.1);
  bottom: -80px; right: -60px;
}
.fd6-chap-big-n {
  font-size: 5rem; font-weight: 900; line-height: 1;
  color: rgba(248,249,250,.25); letter-spacing: -.04em;
}
.fd6-chap-aside-icon {
  width: 56px; height: 56px; border-radius: 16px;
  background: rgba(248,249,250,.2);
  display: flex; align-items: center; justify-content: center;
  color: #F8F9FA; position: relative; z-index: 1;
}

/* Right body */
.fd6-chap-body {
  padding: 48px 56px 48px 48px;
  display: flex; flex-direction: column; justify-content: center;
}
@media(max-width:820px){ .fd6-chap-body{ padding: 32px 24px; } }

.fd6-chap-eyebrow {
  font-size: .68rem; letter-spacing: .16em; text-transform: uppercase;
  color: var(--ch-accent-dark, #586782); font-weight: 700; margin-bottom: 10px;
}
.fd6-chap-h {
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 800; color: #001122; line-height: 1.2; margin-bottom: 12px;
}
.fd6-chap-p {
  font-size: .95rem; color: #586782; line-height: 1.75; margin-bottom: 24px;
  max-width: 560px;
}
.fd6-chap-tags { display: flex; flex-wrap: wrap; gap: 7px; margin-bottom: 20px; }
.fd6-chap-tag {
  font-size: .72rem; font-weight: 600; padding: 4px 12px; border-radius: 99px;
  background: color-mix(in srgb, var(--ch-accent,#66C5C5) 10%, #F8F9FA);
  color: var(--ch-accent-dark, #586782);
  border: 1px solid color-mix(in srgb, var(--ch-accent,#66C5C5) 20%, transparent);
}
.fd6-chap-link {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--ch-accent-dark, #586782); font-weight: 700; font-size: .88rem;
  text-decoration: none; width: fit-content;
}
.fd6-chap-link::after { content: '→'; transition: transform .2s; }
.fd6-chap-link:hover::after { transform: translateX(4px); }

/* ══════════════════════════════════════════════
   MUST DO BAND
   ══════════════════════════════════════════════ */
.fd6-mustdo {
  background: #001122; padding: 72px 24px;
}
.fd6-mustdo-inner { max-width: 940px; margin: 0 auto; }
.fd6-mustdo-hd {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 36px; gap: 20px; flex-wrap: wrap;
}
.fd6-mustdo-eye {
  font-size: .7rem; letter-spacing: .18em; text-transform: uppercase;
  color: #66C5C5; font-weight: 700; margin-bottom: 6px;
}
.fd6-mustdo-h { font-size: 1.9rem; font-weight: 900; color: #F8F9FA; }

.fd6-task-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
@media(max-width:680px){ .fd6-task-pair{ grid-template-columns:1fr; } }

.fd6-task {
  background: rgba(248,249,250,.05);
  border: 1px solid rgba(248,249,250,.1);
  border-radius: 20px; padding: 28px;
  transition: border-color .2s, background .2s;
}
.fd6-task:hover { border-color: var(--t-accent,#66C5C5); background: rgba(248,249,250,.08); }
.fd6-task-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.fd6-task-ico {
  width: 46px; height: 46px; border-radius: 13px;
  background: color-mix(in srgb, var(--t-accent,#66C5C5) 15%, transparent);
  color: var(--t-accent,#66C5C5);
  display: flex; align-items: center; justify-content: center;
}
.fd6-task-badge {
  font-size: .68rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  padding: 4px 12px; border-radius: 99px;
  background: var(--t-accent,#66C5C5); color: #001122;
}
.fd6-task-h { font-size: 1.05rem; font-weight: 800; color: #F8F9FA; margin-bottom: 8px; }
.fd6-task-p { font-size: .86rem; color: rgba(248,249,250,.45); line-height: 1.6; margin-bottom: 20px; }
.fd6-task-steps {
  display: flex; gap: 0; margin-bottom: 20px;
}
.fd6-task-step { flex:1; text-align:center; position:relative; font-size:.74rem; color:rgba(248,249,250,.4); }
.fd6-task-step::after { content:'→'; position:absolute; right:-6px; top:11px; color:rgba(248,249,250,.2); }
.fd6-task-step:last-child::after { display:none; }
.fd6-task-step-ico {
  width:34px; height:34px; border-radius:50%; margin:0 auto 5px;
  background:rgba(248,249,250,.06); display:flex; align-items:center; justify-content:center; font-size:.9rem;
}
.fd6-task-cta {
  display: flex; align-items: center; justify-content: space-between;
  padding: 11px 16px; border-radius: 10px;
  background: color-mix(in srgb, var(--t-accent,#66C5C5) 12%, transparent);
  color: var(--t-accent,#66C5C5); font-weight: 700; font-size: .86rem;
  text-decoration: none; transition: background .2s;
}
.fd6-task-cta:hover { background: color-mix(in srgb, var(--t-accent,#66C5C5) 22%, transparent); }

/* ══════════════════════════════════════════════
   PASSPORT STAMPS — achievement section
   ══════════════════════════════════════════════ */
.fd6-passport { background: #F8F9FA; padding: 72px 24px; border-top: 1px solid #F8F9FA; }
.fd6-passport-inner { max-width: 900px; margin: 0 auto; }
.fd6-passport-hd { text-align: center; margin-bottom: 48px; }
.fd6-passport-eye {
  font-size: .72rem; letter-spacing: .16em; text-transform: uppercase;
  color: #66C5C5; font-weight: 700; margin-bottom: 8px;
}
.fd6-passport-h { font-size: 1.75rem; font-weight: 900; color: #001122; margin-bottom: 6px; }
.fd6-passport-sub { color: #707070; font-size: .95rem; }

.fd6-stamps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
@media(max-width:700px){ .fd6-stamps{ grid-template-columns: repeat(2,1fr); } }
@media(max-width:440px){ .fd6-stamps{ grid-template-columns: 1fr; } }

.fd6-stamp {
  aspect-ratio: 1 / 1.05;
  border-radius: 16px;
  border: 2.5px dashed #D0D6DF;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  gap: 10px; padding: 20px;
  cursor: pointer; user-select: none;
  position: relative; overflow: hidden;
  transition: border-color .2s, transform .2s, box-shadow .2s;
  background: #F8F9FA;
}
.fd6-stamp:hover { transform: rotate(-1.5deg) scale(1.03); box-shadow: 0 8px 28px rgba(0,64,129,.1); }
.fd6-stamp:nth-child(even):hover { transform: rotate(1.5deg) scale(1.03); }

/* Stamp outer ring (not yet collected) */
.fd6-stamp-ring {
  width: 72px; height: 72px; border-radius: 50%;
  border: 3px solid #D0D6DF;
  display: flex; align-items: center; justify-content: center;
  color: #D0D6DF; transition: all .3s;
}

.fd6-stamp-name { font-size: .82rem; font-weight: 700; color: #929EB4; text-align: center; transition: color .2s; }
.fd6-stamp-sub  { font-size: .68rem; color: #929EB4; text-align: center; line-height: 1.4; }

/* Collected state */
.fd6-stamp.stamped {
  border-color: var(--st-color, #66C5C5);
  border-style: solid;
  background: color-mix(in srgb, var(--st-color,#66C5C5) 6%, #F8F9FA);
}
.fd6-stamp.stamped .fd6-stamp-ring {
  border-color: var(--st-color, #66C5C5);
  background: color-mix(in srgb, var(--st-color,#66C5C5) 12%, transparent);
  color: var(--st-color, #66C5C5);
}
.fd6-stamp.stamped .fd6-stamp-name { color: #001122; }
.fd6-stamp.stamped .fd6-stamp-sub  { color: #707070; }

/* STAMP ink diagonal text overlay */
.fd6-stamp-ink {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  opacity: 0; transition: opacity .3s;
  pointer-events: none;
}
.fd6-stamp-ink-text {
  font-size: 1.1rem; font-weight: 900; letter-spacing: .08em;
  color: var(--st-color,#66C5C5); opacity: .25;
  transform: rotate(-22deg); text-transform: uppercase;
  border: 3px solid var(--st-color,#66C5C5);
  padding: 3px 10px; border-radius: 4px; white-space: nowrap;
}
.fd6-stamp.stamped .fd6-stamp-ink { opacity: 1; }

/* stamp pop animation */
@keyframes fd6stampIn {
  0%   { transform: scale(1.4) rotate(-8deg); opacity: 0; }
  60%  { transform: scale(.93) rotate(2deg); opacity: 1; }
  100% { transform: scale(1) rotate(0deg); opacity: 1; }
}
.fd6-stamp.stamped { animation: fd6stampIn .4s cubic-bezier(0.25, 1, 0.5, 1) both; }

/* Progress bar below stamps */
.fd6-pass-prog {
  display: flex; align-items: center; gap: 14px; margin-top: 36px;
}
.fd6-pass-prog-bar {
  flex: 1; height: 8px; background: #F8F9FA; border-radius: 99px; overflow: hidden;
}
.fd6-pass-prog-fill {
  height: 100%;
  background: linear-gradient(90deg, #66C5C5, #586782);
  border-radius: 99px; width: 0%; transition: width .5s cubic-bezier(.4,0,.2,1);
}
.fd6-pass-prog-label { font-size: .82rem; font-weight: 700; color: #707070; white-space: nowrap; }

/* ============================================================
   FIRST DAY V5 — fd5-*
   ============================================================ */

/* --- Page base --- */
.fd5-page { background: #F8F9FA; }

/* ─── HERO ─────────────────────────────────────────────────── */
.fd5-hero {
  min-height: 88vh;
  display: flex; align-items: center;
  background: #F8F9FA;
  position: relative; overflow: hidden;
  padding: 80px 24px;
}
/* Animated gradient orbs */
.fd5-orb {
  position: absolute; border-radius: 50%;
  filter: blur(80px); pointer-events: none;
}
.fd5-orb-1 {
  width: 520px; height: 520px;
  background: radial-gradient(circle, rgba(102,197,197,.25) 0%, transparent 70%);
  top: -120px; right: -80px;
  animation: fd5float 7s ease-in-out infinite;
}
.fd5-orb-2 {
  width: 380px; height: 380px;
  background: radial-gradient(circle, rgba(0,64,129,.12) 0%, transparent 70%);
  bottom: -60px; left: 10%;
  animation: fd5float 9s ease-in-out infinite reverse;
}
.fd5-orb-3 {
  width: 240px; height: 240px;
  background: radial-gradient(circle, rgba(146,158,180,.18) 0%, transparent 70%);
  top: 30%; right: 25%;
  animation: fd5float 6s ease-in-out infinite 2s;
}
@keyframes fd5float {
  0%,100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-30px) scale(1.06); }
}

.fd5-hero-inner {
  max-width: 1100px; margin: 0 auto; width: 100%;
  display: grid; grid-template-columns: 1fr 420px; gap: 64px; align-items: center;
  position: relative; z-index: 1;
}
@media (max-width: 860px) {
  .fd5-hero-inner { grid-template-columns: 1fr; }
  .fd5-hero-card { display: none; }
}

/* Left copy */
.fd5-hero-eyebrow {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: .78rem; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: var(--cyan, #66C5C5);
  margin-bottom: 22px;
}
.fd5-hero-eyebrow-line {
  width: 32px; height: 2px;
  background: var(--cyan, #66C5C5);
}
.fd5-hero-h1 {
  font-size: clamp(2.4rem, 5.5vw, 3.6rem);
  font-weight: 900; color: #004081; line-height: 1.1;
  letter-spacing: -.02em; margin-bottom: 22px;
}
.fd5-hero-h1 .fd5-accent {
  background: linear-gradient(90deg, #66C5C5, #004081);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
/* Word-by-word reveal */
.fd5-hero-h1 .fd5-w {
  display: inline-block;
  opacity: 0; transform: translateY(24px);
  animation: fd5wordIn .5s cubic-bezier(0.25, 1, 0.5, 1) forwards;
}
@keyframes fd5wordIn {
  to { opacity:1; transform:translateY(0); }
}
.fd5-hero-sub {
  font-size: 1.05rem; color: #707070; line-height: 1.75;
  max-width: 480px; margin-bottom: 36px;
}
.fd5-hero-ctas { display: flex; gap: 14px; flex-wrap: wrap; }
.fd5-hero-cta-p {
  display: inline-flex; align-items: center; gap: 8px;
  background: linear-gradient(135deg, #66C5C5, #004081);
  color: #F8F9FA; border-radius: 12px; padding: 14px 28px;
  font-weight: 700; font-size: .95rem; text-decoration: none;
  box-shadow: 0 6px 24px rgba(0,64,129,.25);
  transition: transform .2s cubic-bezier(0.25, 1, 0.5, 1), box-shadow .2s;
}
.fd5-hero-cta-p:hover { transform: translateY(-3px) scale(1.03); box-shadow: 0 12px 32px rgba(0,64,129,.3); }
.fd5-hero-cta-g {
  display: inline-flex; align-items: center; gap: 8px;
  background: transparent; color: #004081; border-radius: 12px;
  padding: 14px 28px; font-weight: 600; font-size: .95rem;
  text-decoration: none; border: 2px solid #D0D6DF;
  transition: border-color .2s, background .2s, transform .2s cubic-bezier(0.25, 1, 0.5, 1);
}
.fd5-hero-cta-g:hover { border-color: #66C5C5; background: rgba(102,197,197,.06); transform: translateY(-2px); }

/* Right: floating card stack */
.fd5-hero-card {
  position: relative; height: 360px;
}
.fd5-hc {
  position: absolute; border-radius: 18px; padding: 22px 24px;
  box-shadow: 0 8px 32px rgba(0,64,129,.12);
  transition: transform .3s ease;
}
.fd5-hc-main {
  background: linear-gradient(135deg, #004081, #004081);
  color: #F8F9FA; width: 280px; top: 30px; left: 50%; transform: translateX(-50%);
  animation: fd5cardFloat 5s ease-in-out infinite;
  z-index: 3;
}
@keyframes fd5cardFloat {
  0%,100% { transform: translateX(-50%) translateY(0) rotate(-1deg); }
  50% { transform: translateX(-50%) translateY(-12px) rotate(1deg); }
}
.fd5-hc-back1 {
  background: #F8F9FA; border: 1.5px solid #F8F9FA;
  width: 260px; top: 60px; left: calc(50% - 130px + 40px);
  transform: rotate(6deg); z-index: 2;
  animation: fd5cardFloat2 6s ease-in-out infinite 1s;
}
@keyframes fd5cardFloat2 {
  0%,100% { transform: rotate(6deg) translateY(0); }
  50% { transform: rotate(4deg) translateY(-8px); }
}
.fd5-hc-back2 {
  background: #F8F9FA; border: 1.5px solid #F8F9FA;
  width: 240px; top: 80px; left: calc(50% - 120px - 36px);
  transform: rotate(-7deg); z-index: 1;
  animation: fd5cardFloat3 7s ease-in-out infinite .5s;
}
@keyframes fd5cardFloat3 {
  0%,100% { transform: rotate(-7deg) translateY(0); }
  50% { transform: rotate(-5deg) translateY(-10px); }
}
.fd5-hc-step {
  font-size: .68rem; letter-spacing: .1em; text-transform: uppercase;
  opacity: .7; margin-bottom: 10px;
}
.fd5-hc-title { font-size: 1rem; font-weight: 700; margin-bottom: 6px; }
.fd5-hc-sub { font-size: .82rem; opacity: .75; }
.fd5-hc-badge {
  display: inline-block; margin-top: 12px;
  font-size: .7rem; font-weight: 700;
  background: rgba(248,249,250,.2); border-radius: 99px;
  padding: 3px 12px;
}

/* ─── STRIP SECTION ────────────────────────────────────────── */
.fd5-strip-section {
  padding: 64px 0 48px;
  position: relative;
}
.fd5-strip-hd {
  max-width: 1100px; margin: 0 auto;
  padding: 0 24px 36px;
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: 16px;
}
.fd5-strip-label {
  font-size: .75rem; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: #66C5C5; margin-bottom: 6px;
}
.fd5-strip-title { font-size: 1.6rem; font-weight: 800; color: #004081; }
.fd5-strip-nav { display: flex; gap: 8px; }
.fd5-snav-btn {
  width: 40px; height: 40px; border-radius: 10px; border: 2px solid #D0D6DF;
  background: #F8F9FA; color: #004081; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: all .2s cubic-bezier(0.25, 1, 0.5, 1);
}
.fd5-snav-btn:hover { border-color: #66C5C5; transform: scale(1.1); background: rgba(102,197,197,.08); }

/* Scroll container */
.fd5-strip-outer { position: relative; }
.fd5-strip-outer::before, .fd5-strip-outer::after {
  content: ''; position: absolute; top: 0; bottom: 0; width: 72px; z-index: 2; pointer-events: none;
}
.fd5-strip-outer::before { left: 0; background: linear-gradient(to right, #F8F9FA, transparent); }
.fd5-strip-outer::after  { right: 0; background: linear-gradient(to left,  #F8F9FA, transparent); }
.fd5-strip {
  display: flex; gap: 18px;
  overflow-x: auto; scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 16px 80px 24px;
  scrollbar-width: none;
}
.fd5-strip::-webkit-scrollbar { display: none; }

/* Progress connector line */
.fd5-connector {
  position: absolute; top: 88px; left: 0; right: 0; height: 2px; z-index: 0; pointer-events: none;
  background: repeating-linear-gradient(90deg, #D0D6DF 0, #D0D6DF 8px, transparent 8px, transparent 20px);
}

/* ─── PANEL ─────────────────────────────────────────────────── */
.fd5-panel {
  flex: 0 0 300px; scroll-snap-align: center;
  background: #F8F9FA; border-radius: 20px;
  border: 2px solid transparent;
  padding: 28px 24px 24px;
  position: relative; overflow: hidden;
  cursor: pointer;
  box-shadow: 0 2px 14px rgba(0,64,129,.06);
  /* 3D tilt via JS */
  transform-style: preserve-3d;
  transition: box-shadow .3s, border-color .3s;
  will-change: transform;
}
/* Shimmer on hover */
.fd5-panel::before {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(105deg, transparent 40%, rgba(248,249,250,.6) 50%, transparent 60%);
  transform: translateX(-100%);
  transition: transform .5s ease;
  pointer-events: none; z-index: 0;
}
.fd5-panel:hover::before { transform: translateX(100%); }
.fd5-panel:hover {
  box-shadow: 0 20px 48px rgba(0,64,129,.15);
  border-color: var(--p-accent, #66C5C5);
}
/* Glow ring */
.fd5-panel::after {
  content: '';
  position: absolute; inset: -2px; border-radius: 22px;
  background: linear-gradient(135deg, var(--p-accent,#66C5C5), transparent);
  opacity: 0; transition: opacity .3s; z-index: -1;
  pointer-events: none;
}
.fd5-panel:hover::after { opacity: .15; }

/* Step chip replacing time */
.fd5-panel-step {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: .72rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
  color: var(--p-accent-dark, #586782);
  background: color-mix(in srgb, var(--p-accent,#66C5C5) 12%, transparent);
  border-radius: 99px; padding: 4px 12px; margin-bottom: 18px;
}
.fd5-panel-step-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--p-accent, #66C5C5);
}
.fd5-panel-num {
  position: absolute; top: -4px; right: 14px;
  font-size: 6.5rem; font-weight: 900; line-height: 1;
  color: var(--p-accent, #66C5C5); opacity: .06;
  pointer-events: none; user-select: none;
}
.fd5-panel-icon {
  width: 56px; height: 56px; border-radius: 14px; margin-bottom: 16px;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--p-accent,#66C5C5) 12%, transparent);
  color: var(--p-accent-dark, #586782);
  transition: transform .3s cubic-bezier(0.25, 1, 0.5, 1);
  position: relative; z-index: 1;
}
.fd5-panel:hover .fd5-panel-icon { transform: scale(1.12) rotate(-4deg); }
.fd5-panel h3 {
  font-size: 1.1rem; font-weight: 700; color: #004081;
  margin-bottom: 8px; position: relative; z-index: 1;
}
.fd5-panel-desc {
  font-size: .88rem; color: #707070; line-height: 1.65;
  margin-bottom: 18px; position: relative; z-index: 1;
}
/* Expandable detail */
.fd5-panel-expand {
  display: flex; align-items: center; gap: 6px;
  font-size: .78rem; font-weight: 600; color: var(--p-accent-dark,#586782);
  cursor: pointer; position: relative; z-index: 1;
  border: none; background: none; padding: 0;
}
.fd5-panel-expand svg { transition: transform .25s cubic-bezier(0.25, 1, 0.5, 1); }
.fd5-panel--open .fd5-panel-expand svg { transform: rotate(180deg); }
.fd5-panel-detail {
