}
.fd5-dot.active { width: 26px; background: #66C5C5; }

/* ─── ACHIEVEMENT CHECKLIST ─────────────────────────────────── */
.fd5-achieve {
  background: #F8F9FA;
  border-top: 1px solid #F8F9FA;
  padding: 72px 24px;
}
.fd5-achieve-inner { max-width: 960px; margin: 0 auto; }
.fd5-achieve-hd { text-align: center; margin-bottom: 48px; }
.fd5-achieve-label {
  font-size: .75rem; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: #66C5C5; margin-bottom: 10px;
}
.fd5-achieve-title { font-size: 1.75rem; font-weight: 800; color: #004081; margin-bottom: 10px; }
.fd5-achieve-sub { color: #707070; }
.fd5-achieve-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 36px;
}
@media (max-width: 700px) { .fd5-achieve-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 480px) { .fd5-achieve-grid { grid-template-columns: 1fr; } }

.fd5-ach {
  border-radius: 16px;
  border: 2px solid #F8F9FA;
  padding: 22px 20px;
  cursor: pointer;
  position: relative; overflow: hidden;
  transition: border-color .25s, background .25s, transform .3s cubic-bezier(0.25, 1, 0.5, 1), box-shadow .25s;
  background: #F8F9FA;
}
.fd5-ach:hover { transform: translateY(-4px); box-shadow: 0 10px 32px rgba(0,64,129,.1); }
.fd5-ach.done {
  border-color: var(--ach-accent, #66C5C5);
  background: color-mix(in srgb, var(--ach-accent,#66C5C5) 6%, #F8F9FA);
}
.fd5-ach.done .fd5-ach-check { background: var(--ach-accent,#66C5C5); border-color: var(--ach-accent,#66C5C5); }
.fd5-ach.done .fd5-ach-check::after { opacity: 1; transform: scale(1); }
.fd5-ach.done .fd5-ach-icon { color: var(--ach-accent,#66C5C5); }
.fd5-ach.done .fd5-ach-label { color: var(--ach-accent-dark, #586782); }
/* Pop animation when checked */
.fd5-ach.popping { animation: fd5pop .4s cubic-bezier(0.25, 1, 0.5, 1); }
/* duplicate fd5pop removed */
.fd5-ach-top {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px;
}
.fd5-ach-icon { font-size: 1.6rem; transition: transform .3s cubic-bezier(0.25, 1, 0.5, 1), color .2s; }
.fd5-ach.done .fd5-ach-icon { transform: scale(1.15) rotate(-8deg); }
.fd5-ach-check {
  width: 24px; height: 24px; border-radius: 50%;
  border: 2px solid #D0D6DF;
  flex-shrink: 0; position: relative;
  transition: all .25s cubic-bezier(0.25, 1, 0.5, 1);
}
.fd5-ach-check::after {
  content: '';
  position: absolute; top: 4px; left: 7px;
  width: 6px; height: 10px;
  border: 2px solid #F8F9FA; border-top: 0; border-left: 0;
  transform: rotate(45deg) scale(0);
  opacity: 0; transition: all .2s cubic-bezier(0.25, 1, 0.5, 1);
}
.fd5-ach-label {
  font-size: .88rem; font-weight: 600; color: #004081;
  line-height: 1.4; transition: color .2s;
}
.fd5-ach-sub {
  font-size: .75rem; color: #929EB4; margin-top: 4px;
}

/* Overall progress bar */
.fd5-prog-wrap {
  display: flex; align-items: center; gap: 16px;
  background: #F8F9FA; border-radius: 16px; padding: 20px 24px;
}
.fd5-prog-bar {
  flex: 1; height: 8px; background: #F8F9FA; border-radius: 99px; overflow: hidden;
}
.fd5-prog-fill {
  height: 100%; border-radius: 99px;
  background: linear-gradient(90deg, #66C5C5, #004081);
