}
.fd5-prog-label { font-size: .88rem; font-weight: 700; color: #004081; white-space: nowrap; }

/* Celebration overlay */
.fd5-celebrate {
  position: fixed; inset: 0; z-index: 9999;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,17,34,.55); backdrop-filter: blur(4px);
  opacity: 0; pointer-events: none;
  transition: opacity .3s;
}
.fd5-celebrate.show { opacity: 1; pointer-events: all; }
.fd5-celebrate-card {
  background: #F8F9FA; border-radius: 24px; padding: 48px 40px; text-align: center;
  max-width: 340px; transform: scale(.85);
  transition: transform .4s cubic-bezier(0.25, 1, 0.5, 1);
  box-shadow: 0 24px 64px rgba(0,64,129,.2);
}
.fd5-celebrate.show .fd5-celebrate-card { transform: scale(1); }
.fd5-celebrate-emoji { font-size: 3.5rem; margin-bottom: 16px; display: block; }
.fd5-celebrate-title { font-size: 1.5rem; font-weight: 800; color: #004081; margin-bottom: 8px; }
.fd5-celebrate-sub { color: #707070; line-height: 1.6; margin-bottom: 24px; }
.fd5-celebrate-btn {
  background: linear-gradient(135deg, #66C5C5, #004081);
  color: #F8F9FA; border: none; border-radius: 12px;
  padding: 12px 28px; font-weight: 700; cursor: pointer; font-size: .95rem;
}

/* ============================================================
   FIRST DAY V5 — Editorial Hero + 3D Tilt Story Strip / fd4-*
   ============================================================ */

/* ── Hero ─────────────────────────────────────────────────── */
.fd4-hero {
  background: #F8F9FA;
  border-bottom: 1px solid #F8F9FA;
  padding: 80px 24px 72px;
  overflow: hidden;
  position: relative;
}
/* Subtle background grid */
.fd4-hero::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(102,197,197,.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(102,197,197,.06) 1px, transparent 1px);
