  pointer-events: none;
}
.fd4-hero-inner {
  position: relative;
  max-width: 1080px; margin: 0 auto;
  display: grid; grid-template-columns: 1fr auto;
  gap: 48px; align-items: center;
}
@media (max-width: 680px) {
