}
.fd4-hero-eyebrow {
  font-size: .72rem; letter-spacing: .18em; text-transform: uppercase;
  font-weight: 700; color: var(--cyan, #66C5C5); margin-bottom: 20px;
  display: flex; align-items: center; gap: 10px;
}
.fd4-hero-eyebrow::before {
  content: '';
  display: block; width: 24px; height: 2px;
  background: var(--cyan, #66C5C5);
}
.fd4-hero-h1 {
  font-size: clamp(2.4rem, 5vw, 3.6rem);
  font-weight: 900; line-height: 1.1; color: #001122;
  margin-bottom: 20px; letter-spacing: -.02em;
}
.fd4-hero-h1 em {
  font-style: normal;
  background: linear-gradient(90deg, #586782, #66C5C5);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.fd4-hero-sub {
  font-size: 1.05rem; color: #707070;
  line-height: 1.75; max-width: 480px; margin-bottom: 36px;
}
.fd4-hero-cta {
  display: inline-flex; align-items: center; gap: 10px;
  background: #001122; color: #F8F9FA;
  padding: 14px 28px; border-radius: 99px;
  font-weight: 600; font-size: .92rem; text-decoration: none;
  transition: background .2s, transform .2s;
}
.fd4-hero-cta:hover { background: #004081; transform: translateY(-2px); }
/* Aside — step counter art */
.fd4-hero-aside {
  display: flex; flex-direction: column; align-items: center; gap: 0;
  background: #F8F9FA; border: 1.5px solid #F8F9FA;
  border-radius: 20px; padding: 32px 40px; text-align: center;
}
.fd4-hero-aside-num {
  font-size: 5rem; font-weight: 900; line-height: 1;
