}

/* ── Strip Section ───────────────────────────────────────── */
.fd4-strip-section {
  background: #F8F9FA;
  padding: 64px 0 48px;
}
.fd4-strip-hd {
  max-width: 1080px; margin: 0 auto 40px; padding: 0 40px;
  display: flex; align-items: flex-end; justify-content: space-between; gap: 24px;
}
.fd4-strip-hd-left {}
.fd4-strip-eyebrow {
  font-size: .72rem; letter-spacing: .18em; text-transform: uppercase;
  font-weight: 700; color: var(--cyan, #66C5C5); margin-bottom: 8px;
}
.fd4-strip-title {
  font-size: 1.5rem; font-weight: 800; color: #001122;
}
.fd4-strip-nav {
  display: flex; gap: 8px;
}
.fd4-strip-nav-btn {
  width: 40px; height: 40px; border-radius: 50%;
  border: 1.5px solid #D0D6DF; background: #F8F9FA;
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  color: #004081; transition: all .2s;
}
.fd4-strip-nav-btn:hover { border-color: var(--cyan,#66C5C5); background: var(--cyan,#66C5C5); color: #F8F9FA; }

/* Outer with side fade */
.fd4-strip-outer { position: relative; }
.fd4-strip-outer::before, .fd4-strip-outer::after {
  content: ''; position: absolute; top: 0; bottom: 0; width: 100px; z-index: 3; pointer-events: none;
}
.fd4-strip-outer::before { left: 0; background: linear-gradient(to right, #F8F9FA 30%, transparent); }
.fd4-strip-outer::after  { right: 0; background: linear-gradient(to left, #F8F9FA 30%, transparent); }

.fd4-strip {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 32px 120px 40px;
  scrollbar-width: none;
  perspective: 1200px;
}
.fd4-strip::-webkit-scrollbar { display: none; }

/* ── Story Card ──────────────────────────────────────────── */
.fd4-card {
  flex: 0 0 300px;
  scroll-snap-align: center;
  border-radius: 22px;
  background: #F8F9FA;
  border: 1.5px solid #F8F9FA;
  padding: 28px 24px 24px;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  /* 3D tilt transform — set by JS */
  transform-style: preserve-3d;
  transform: scale(.94) translateZ(0);
  transition:
    transform .35s cubic-bezier(0.25, 1, 0.5, 1),
    box-shadow .35s ease,
    border-color .35s ease;
  will-change: transform;
  box-shadow: 0 2px 8px rgba(0,64,129,.06);
}
/* Center/active card is larger */
.fd4-card.fd4-card--center {
  transform: scale(1.04) translateZ(0);
  box-shadow: 0 20px 60px rgba(0,64,129,.18);
  border-color: var(--card-accent, #66C5C5);
  z-index: 2;
}
/* Glow ring for center card */
.fd4-card.fd4-card--center::after {
  content: '';
  position: absolute; inset: -2px;
  border-radius: 24px;
  background: transparent;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--card-accent,#66C5C5) 40%, transparent),
              0 0 40px color-mix(in srgb, var(--card-accent,#66C5C5) 20%, transparent);
  pointer-events: none;
}
/* Blurred non-center when center is active */
.fd4-strip.has-center .fd4-card:not(.fd4-card--center) {
  filter: brightness(.92);
  transform: scale(.92) translateZ(0);
}
/* Step number watermark */
.fd4-card-watermark {
  position: absolute; bottom: -12px; right: 8px;
  font-size: 8rem; font-weight: 900; line-height: 1;
  color: var(--card-accent, #66C5C5);
  opacity: .06; user-select: none; pointer-events: none;
}
/* Step badge */
.fd4-card-step {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px; border-radius: 50%;
  background: color-mix(in srgb, var(--card-accent,#66C5C5) 15%, transparent);
  color: var(--card-accent-dark, #586782);
  font-size: .72rem; font-weight: 800; letter-spacing: .04em;
  margin-bottom: 18px;
}
.fd4-card-icon {
  width: 52px; height: 52px; border-radius: 14px; margin-bottom: 16px;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--card-accent,#66C5C5) 10%, transparent);
  color: var(--card-accent-dark, #586782);
  transition: background .2s;
}
.fd4-card--center .fd4-card-icon {
  background: color-mix(in srgb, var(--card-accent,#66C5C5) 20%, transparent);
}
.fd4-card-title {
  font-size: 1rem; font-weight: 700; color: #001122; margin-bottom: 8px; line-height: 1.3;
}
.fd4-card-desc {
  font-size: .85rem; color: #707070; line-height: 1.65;
}
/* Tags shown only on center card */
.fd4-card-tags {
  display: flex; flex-wrap: wrap; gap: 6px; margin-top: 14px;
  max-height: 0; overflow: hidden;
  transition: max-height .35s ease;
}
.fd4-card--center .fd4-card-tags { max-height: 60px; }
.fd4-card-tag {
  font-size: .7rem; font-weight: 600; padding: 3px 10px; border-radius: 99px;
  background: color-mix(in srgb, var(--card-accent,#66C5C5) 10%, transparent);
  color: var(--card-accent-dark, #586782);
}
/* Link shown only on center */
.fd4-card-link {
  display: flex; align-items: center; gap: 6px;
  font-size: .82rem; font-weight: 600;
  color: var(--card-accent-dark, #586782);
  text-decoration: none; margin-top: 14px;
  max-height: 0; overflow: hidden; opacity: 0;
  transition: max-height .35s ease, opacity .3s ease;
}
.fd4-card--center .fd4-card-link { max-height: 40px; opacity: 1; }

/* ── Dots ────────────────────────────────────────────────── */
.fd4-dots {
  display: flex; justify-content: center; gap: 6px; padding-bottom: 8px;
}
.fd4-dot {
  height: 4px; border-radius: 99px;
  background: #D0D6DF; border: none; padding: 0; cursor: pointer;
  width: 20px; transition: all .25s;
}
.fd4-dot.active { width: 36px; background: var(--cyan, #66C5C5); }

/* ── Mission Cards ───────────────────────────────────────── */
.fd4-mission {
  background: #F8F9FA;
  border-top: 1px solid #F8F9FA;
