.fd4-mission-eyebrow::before { content:''; display:block; width:24px; height:2px; background:var(--cyan,#66C5C5); }
.fd4-mission-title { font-size: 1.75rem; font-weight: 800; color: #001122; margin-bottom: 8px; }
.fd4-mission-sub { color: #707070; margin-bottom: 44px; line-height: 1.7; }
.fd4-mcards2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
@media (max-width:680px){ .fd4-mcards2 { grid-template-columns:1fr; } }

.fd4-mc {
