/* ============================================================
   FIRST DAY V5 — fd4-*
   Playful hero + step-strip with 3-D tilt + scale focus
   ============================================================ */

/* ── Page shell ── */
.fd4 { background: #F8F9FA; }

/* ══════════════════════════════════════
   HERO
══════════════════════════════════════ */
.fd4-hero {
  position: relative;
  min-height: 88vh;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
  background: linear-gradient(150deg, #F8F9FA 0%, #F8F9FA 40%, #F8F9FA 100%);
}

/* Floating bubbles */
.fd4-bubble {
  position: absolute;
  border-radius: 50%;
  opacity: .55;
  filter: blur(0px);
  pointer-events: none;
  animation: fd4float var(--dur, 8s) ease-in-out infinite;
  animation-delay: var(--delay, 0s);
}
@keyframes fd4float {
  0%,100% { transform: translateY(0) rotate(0deg) scale(1); }
  33%      { transform: translateY(-22px) rotate(8deg) scale(1.04); }
  66%      { transform: translateY(12px) rotate(-5deg) scale(.97); }
}
/* Floating icon chips */
.fd4-floater {
  position: absolute;
  display: flex; align-items: center; justify-content: center;
  border-radius: 18px;
  background: #F8F9FA;
  box-shadow: 0 8px 32px rgba(0,64,129,.10), 0 1px 4px rgba(0,64,129,.06);
  animation: fd4chip var(--dur,9s) ease-in-out infinite;
  animation-delay: var(--delay,0s);
  pointer-events: none;
}
@keyframes fd4chip {
  0%,100% { transform: translateY(0) rotate(var(--rot,0deg)); }
  50%      { transform: translateY(-18px) rotate(calc(var(--rot,0deg) + 4deg)); }
}

/* Hero content */
.fd4-hero-content {
  position: relative; z-index: 2;
  text-align: center;
  max-width: 660px;
  padding: 0 24px;
}
.fd4-hero-kicker {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: .78rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  color: #586782;
  background: rgba(102,197,197,.15);
  border: 1px solid rgba(102,197,197,.4);
  border-radius: 99px; padding: 6px 16px; margin-bottom: 24px;
}
.fd4-kicker-pulse {
  width: 7px; height: 7px; border-radius: 50%;
  background: #66C5C5;
  animation: fd4kpulse 1.8s ease-in-out infinite;
}
@keyframes fd4kpulse {
  0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.3;transform:scale(1.5)}
}
.fd4-hero-h1 {
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 900; line-height: 1.1;
  color: #004081; margin-bottom: 20px;
  letter-spacing: -.02em;
}
.fd4-hero-h1 .fd4-grad {
  background: linear-gradient(120deg, #586782 0%, #66C5C5 50%, #004081 100%);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
  background-clip: text;
}
.fd4-hero-sub {
  font-size: 1.05rem; color: #586782; line-height: 1.75;
  max-width: 480px; margin: 0 auto 36px;
}
.fd4-hero-ctas {
  display: flex; gap: 12px; justify-content: center; flex-wrap: wrap;
}
.fd4-btn-main {
  display: inline-flex; align-items: center; gap: 8px;
  background: linear-gradient(135deg,#004081,#586782);
  color: #F8F9FA; padding: 14px 28px; border-radius: 99px;
  font-weight: 700; font-size: .95rem; text-decoration: none;
  box-shadow: 0 8px 24px rgba(0,64,129,.25);
  transition: transform .2s, box-shadow .2s;
}
.fd4-btn-main:hover { transform: translateY(-2px); box-shadow: 0 14px 32px rgba(0,64,129,.32); }
.fd4-btn-ghost {
  display: inline-flex; align-items: center; gap: 8px;
  color: #586782; padding: 14px 28px; border-radius: 99px;
  font-weight: 600; font-size: .95rem; text-decoration: none;
  border: 1.5px solid rgba(88,103,130,.35);
  transition: background .2s, border-color .2s;
}
.fd4-btn-ghost:hover { background: rgba(88,103,130,.08); border-color: #586782; }

/* Scroll indicator */
.fd4-scroll-arrow {
  position: absolute; bottom: 32px; left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  color: #929EB4; font-size: .75rem; font-weight: 600; letter-spacing: .08em; text-transform: uppercase;
  animation: fd4bounce 2s ease-in-out infinite;
  z-index: 2;
}
@keyframes fd4bounce {
  0%,100%{transform:translateX(-50%) translateY(0)} 50%{transform:translateX(-50%) translateY(8px)}
}

/* ══════════════════════════════════════
   STEP STRIP
══════════════════════════════════════ */
.fd4-strip-section {
  background: #F8F9FA;
  padding: 64px 0 48px;
}
.fd4-strip-hd {
  text-align: center;
  padding: 0 24px;
  margin-bottom: 48px;
}
.fd4-strip-eyebrow {
  font-size: .72rem; font-weight: 700; letter-spacing: .18em; text-transform: uppercase;
  color: #66C5C5; display: block; margin-bottom: 10px;
}
.fd4-strip-title {
  font-size: 1.7rem; font-weight: 800; color: #004081; margin-bottom: 8px;
}
.fd4-strip-sub { color: #707070; font-size: .95rem; }

/* Progress connector above strip */
.fd4-prog-connector {
  display: flex; align-items: center;
  max-width: 900px; margin: 0 auto 0;
  padding: 0 80px 24px;
  position: relative;
}
.fd4-prog-node {
  width: 28px; height: 28px; border-radius: 50%; flex-shrink: 0;
  border: 2.5px solid #D0D6DF;
  background: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
  font-size: .65rem; font-weight: 800; color: #D0D6DF;
  cursor: pointer;
  transition: all .25s; z-index: 1; position: relative;
}
.fd4-prog-node.active {
  border-color: #66C5C5; background: #66C5C5; color: #F8F9FA;
  box-shadow: 0 0 0 5px rgba(102,197,197,.2);
}
.fd4-prog-node.done {
  border-color: #66C5C5; background: #66C5C5; color: #F8F9FA;
}
.fd4-prog-line {
  flex: 1; height: 2px; background: #D0D6DF; position: relative; overflow: hidden;
}
.fd4-prog-line-fill {
  position: absolute; inset-y: 0; left: 0;
  width: 0%; background: #66C5C5;
  transition: width .5s ease;
}

/* Strip scroll container */
.fd4-strip-scroll-outer {
  position: relative;
}
.fd4-strip-scroll-outer::before,
.fd4-strip-scroll-outer::after {
  content: '';
  position: absolute; top: 0; bottom: 40px; width: 100px; z-index: 2; pointer-events: none;
}
.fd4-strip-scroll-outer::before { left:0; background:linear-gradient(to right, #F8F9FA 0%, transparent 100%); }
.fd4-strip-scroll-outer::after  { right:0; background:linear-gradient(to left,  #F8F9FA 0%, transparent 100%); }

.fd4-strip {
  display: flex; gap: 18px;
  overflow-x: auto; scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: 20px 100px 40px;
  scrollbar-width: none;
  perspective: 1000px;
}
.fd4-strip::-webkit-scrollbar { display: none; }

/* Individual step card */
.fd4-step-card {
  flex: 0 0 300px;
  scroll-snap-align: center;
  background: #F8F9FA;
  border-radius: 22px;
  border: 1.5px solid #D0D6DF;
  padding: 28px 24px 24px;
  position: relative;
  overflow: hidden;
  cursor: pointer;
  transform-origin: center bottom;
  transition: transform .35s cubic-bezier(0.25, 1, 0.5, 1),
              box-shadow .3s ease,
              filter .3s ease,
              border-color .3s;
  transform: scale(.93) translateY(8px);
  filter: saturate(.65) brightness(.97);
  box-shadow: 0 2px 8px rgba(0,17,34,.06);
  will-change: transform;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
}
.fd4-step-card.fd4-active {
  transform: scale(1.03) translateY(-4px);
  filter: saturate(1) brightness(1);
  box-shadow: 0 20px 56px rgba(0,64,129,.14), 0 0 0 2px var(--sc-accent,#66C5C5);
  border-color: var(--sc-accent,#66C5C5);
  z-index: 3;
}
.fd4-step-card:hover:not(.fd4-active) {
  transform: scale(.97) translateY(2px);
  filter: saturate(.85) brightness(.99);
  box-shadow: 0 10px 28px rgba(0,64,129,.1);
}

/* Watermark step number */
.fd4-sc-watermark {
  position: absolute; bottom: -14px; right: 8px;
  font-size: 8rem; font-weight: 900; line-height: 1;
  color: var(--sc-accent, #66C5C5); opacity: .07;
  pointer-events: none; user-select: none;
}
/* Step badge */
.fd4-sc-badge {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: .7rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase;
  color: var(--sc-accent-dark, #586782);
  background: color-mix(in srgb, var(--sc-accent,#66C5C5) 13%, transparent);
  border-radius: 99px; padding: 4px 12px; margin-bottom: 18px;
}
/* Icon */
.fd4-sc-icon {
  width: 56px; height: 56px; border-radius: 16px; margin-bottom: 16px;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--sc-accent,#66C5C5) 12%, transparent);
  color: var(--sc-accent-dark,#586782);
  transition: transform .25s;
}
.fd4-active .fd4-sc-icon { transform: scale(1.1); }
.fd4-sc-title {
  font-size: 1.05rem; font-weight: 800; color: #004081; margin-bottom: 8px;
}
.fd4-sc-desc {
  font-size: .88rem; color: #707070; line-height: 1.65;
}
/* Expand on active */
.fd4-sc-extra {
  max-height: 0; overflow: hidden;
  transition: max-height .4s cubic-bezier(.4,0,.2,1), opacity .3s;
  opacity: 0;
}
.fd4-active .fd4-sc-extra { max-height: 200px; opacity: 1; }
.fd4-sc-tags {
  display: flex; flex-wrap: wrap; gap: 6px;
  margin-top: 16px; padding-top: 16px;
  border-top: 1px solid #F8F9FA;
}
.fd4-sc-tag {
  font-size: .72rem; font-weight: 600;
  padding: 3px 10px; border-radius: 99px;
  background: #F8F9FA; color: #505050;
}
.fd4-sc-link {
  display: inline-flex; align-items: center; gap: 5px;
  margin-top: 12px; color: var(--sc-accent-dark,#586782);
  font-size: .82rem; font-weight: 700; text-decoration: none;
}
.fd4-sc-link:hover { text-decoration: underline; }

/* ══════════════════════════════════════
   MISSION TASKS (kept, but cleaner)
══════════════════════════════════════ */
.fd4-tasks {
  background: #F8F9FA;
  border-top: 1px solid #D0D6DF;
  padding: 72px 24px;
}
.fd4-tasks-inner { max-width: 840px; margin: 0 auto; }
.fd4-tasks-eyebrow {
  font-size: .72rem; font-weight: 700; letter-spacing: .18em; text-transform: uppercase;
  color: #66C5C5; display: block; margin-bottom: 10px;
}
.fd4-tasks-title { font-size: 1.7rem; font-weight: 800; color: #004081; margin-bottom: 8px; }
.fd4-tasks-sub { color: #707070; margin-bottom: 44px; }
.fd4-tasks-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
@media(max-width:640px){ .fd4-tasks-grid { grid-template-columns:1fr; } }

.fd4-tcard {
  border-radius: 20px;
  border: 1.5px solid #D0D6DF;
  overflow: hidden;
  transition: transform .2s, box-shadow .2s;
}
.fd4-tcard:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(0,64,129,.12); }
.fd4-tcard-top {
  padding: 24px 24px 18px;
  background: color-mix(in srgb, var(--tc-accent) 8%, #F8F9FA);
  border-bottom: 1.5px solid color-mix(in srgb, var(--tc-accent) 20%, transparent);
  display: flex; align-items: center; gap: 14px;
}
.fd4-tcard-icon {
  width: 46px; height: 46px; border-radius: 13px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  background: color-mix(in srgb, var(--tc-accent) 15%, transparent);
  color: var(--tc-accent);
}
.fd4-tcard-label {
  font-size: .68rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase;
  color: var(--tc-accent); margin-bottom: 3px;
}
.fd4-tcard-name { font-size: 1rem; font-weight: 800; color: #004081; }
.fd4-tcard-urgency {
  margin-left: auto; font-size: .68rem; font-weight: 700;
  background: var(--tc-accent); color: #F8F9FA;
  padding: 3px 10px; border-radius: 99px; flex-shrink: 0;
}
.fd4-tcard-body { padding: 20px 24px 22px; }
.fd4-tcard-desc { font-size: .88rem; color: #707070; line-height: 1.65; margin-bottom: 18px; }
.fd4-tcard-steps {
  display: flex; gap: 4px; margin-bottom: 20px;
}
.fd4-tcard-step {
  flex: 1; text-align: center; font-size: .72rem; color: #929EB4; position: relative;
}
.fd4-tcard-step::after {
  content: '›'; position: absolute; right: -4px; top: 10px;
  color: #D0D6DF; font-size: 1rem; line-height: 1;
}
.fd4-tcard-step:last-child::after { display: none; }
.fd4-tcard-step-ico {
  width: 34px; height: 34px; border-radius: 50%;
  background: color-mix(in srgb, var(--tc-accent) 11%, transparent);
  color: var(--tc-accent);
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 5px; font-size: .95rem;
}
.fd4-tcard-cta {
  display: flex; align-items: center; justify-content: space-between;
  background: color-mix(in srgb, var(--tc-accent) 9%, transparent);
  border-radius: 10px; padding: 11px 15px;
  color: var(--tc-accent); font-weight: 700; font-size: .85rem;
  text-decoration: none; transition: background .15s;
}
.fd4-tcard-cta:hover { background: color-mix(in srgb, var(--tc-accent) 18%, transparent); }

/* ============================================================
   FIRST DAY V6 — fd5-*
   Morphing blob hero · Flip cards · Unlock · XP bar
   ============================================================ */
.fd5 { background:#F8F9FA; }

/* ── HERO ── */
.fd5-hero {
  position:relative; min-height:100vh;
  display:flex; align-items:center; justify-content:center;
  overflow:hidden;
  background: linear-gradient(160deg,#F8F9FA 0%,#F8F9FA 45%,#F8F9FA 100%);
}
/* canvas behind everything */
.fd5-canvas {
  position:absolute; inset:0; width:100%; height:100%;
  pointer-events:none; z-index:0;
}
/* morphing blobs */
.fd5-blob {
  position:absolute; border-radius:50%; pointer-events:none;
  animation: fd5morph var(--bd,12s) ease-in-out infinite;
  animation-delay: var(--bdelay,0s);
  filter: blur(var(--bblur,50px));
  opacity: var(--bop,.45);
}
@keyframes fd5morph {
  0%  {border-radius:60% 40% 55% 45%/65% 35% 65% 35%;transform:rotate(0) scale(1);}
  25% {border-radius:40% 60% 45% 55%/35% 65% 35% 65%;transform:rotate(10deg) scale(1.06);}
  50% {border-radius:55% 45% 60% 40%/55% 45% 55% 45%;transform:rotate(0) scale(.94);}
  75% {border-radius:45% 55% 40% 60%/45% 55% 45% 55%;transform:rotate(-8deg) scale(1.03);}
  100%{border-radius:60% 40% 55% 45%/65% 35% 65% 35%;transform:rotate(0) scale(1);}
}
/* floating icon chips */
.fd5-chip {
  position:absolute; border-radius:16px; background:#F8F9FA;
  box-shadow:0 8px 28px rgba(0,64,129,.10),0 1px 4px rgba(0,64,129,.07);
  display:flex; align-items:center; justify-content:center;
  animation:fd5chip var(--cd,9s) ease-in-out infinite;
  animation-delay:var(--cdelay,0s); pointer-events:none;
}
@keyframes fd5chip {
  0%,100%{transform:translateY(0) rotate(var(--crot,0deg));}
  50%{transform:translateY(-16px) rotate(calc(var(--crot,0deg) + 5deg));}
}
/* hero text */
.fd5-hero-inner {
  position:relative; z-index:2; text-align:center;
  max-width:640px; padding:0 24px;
}
.fd5-hero-kicker {
  display:inline-flex; align-items:center; gap:8px;
  font-size:.76rem; font-weight:800; letter-spacing:.15em; text-transform:uppercase;
  color:#586782; background:rgba(102,197,197,.15);
  border:1px solid rgba(102,197,197,.45); border-radius:99px;
  padding:7px 18px; margin-bottom:24px;
}
.fd5-kpulse {
  width:7px; height:7px; border-radius:50%; background:#66C5C5;
  animation:fd5kp 1.8s ease-in-out infinite;
}
@keyframes fd5kp{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.25;transform:scale(1.6)}}
.fd5-hero-h1 {
  font-size:clamp(2.6rem,6.5vw,4.2rem); font-weight:900;
  line-height:1.08; letter-spacing:-.025em; color:#001122; margin-bottom:20px;
}
.fd5-grad {
  background:linear-gradient(110deg,#004081 0%,#66C5C5 50%,#586782 100%);
  -webkit-background-clip:text; -webkit-text-fill-color:transparent;
  background-clip:text;
  background-size:200%; animation:fd5gradshift 4s ease-in-out infinite alternate;
}
@keyframes fd5gradshift{0%{background-position:0% 50%}100%{background-position:100% 50%}}
.fd5-hero-sub {
  font-size:1.05rem; color:#586782; line-height:1.8;
  max-width:460px; margin:0 auto 36px;
}
.fd5-hero-ctas { display:flex; gap:12px; justify-content:center; flex-wrap:wrap; }
.fd5-btn-p {
  display:inline-flex; align-items:center; gap:8px;
  background:linear-gradient(135deg,#004081,#586782);
  color:#F8F9FA; padding:14px 30px; border-radius:99px;
  font-weight:700; font-size:.95rem; text-decoration:none;
  box-shadow:0 10px 28px rgba(0,64,129,.28);
  transition:transform .2s,box-shadow .2s;
}
.fd5-btn-p:hover{transform:translateY(-3px);box-shadow:0 16px 36px rgba(0,64,129,.36);}
.fd5-btn-s {
  display:inline-flex; align-items:center; gap:8px;
  color:#586782; padding:14px 28px; border-radius:99px;
  font-weight:600; font-size:.95rem; text-decoration:none;
  border:1.5px solid rgba(88,103,130,.35);
  transition:background .2s,border-color .2s;
}
.fd5-btn-s:hover{background:rgba(88,103,130,.08);border-color:#586782;}
.fd5-scroll-cue {
  position:absolute; bottom:28px; left:50%; transform:translateX(-50%);
  display:flex; flex-direction:column; align-items:center; gap:5px;
  color:#929EB4; font-size:.72rem; font-weight:700; letter-spacing:.1em; text-transform:uppercase;
  z-index:2; animation:fd5cue 2s ease-in-out infinite;
}
@keyframes fd5cue{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(8px)}}

/* ── XP BAR ── */
.fd5-xp-wrap {
  background:#F8F9FA; border-bottom:1px solid #D0D6DF;
  padding:16px 24px; position:sticky; top:0; z-index:10;
  display:flex; align-items:center; gap:16px; max-width:100%;
}
.fd5-xp-label {
  font-size:.78rem; font-weight:800; color:#004081;
  white-space:nowrap; flex-shrink:0;
}
.fd5-xp-bar {
  flex:1; height:8px; background:#D0D6DF; border-radius:99px; overflow:hidden;
}
.fd5-xp-fill {
  height:100%; width:0%;
  background:linear-gradient(90deg,#66C5C5,#586782);
  border-radius:99px; transition:width .5s cubic-bezier(0.25, 1, 0.5, 1);
}
.fd5-xp-score {
  font-size:.82rem; font-weight:800; color:#586782; flex-shrink:0;
  min-width:44px; text-align:right;
}
.fd5-xp-complete {
  font-size:.75rem; font-weight:700; color:#004081;
  background:#D0D6DF; padding:3px 12px; border-radius:99px;
  display:none; flex-shrink:0;
}

/* ── STRIP SECTION ── */
.fd5-strip-section { background:#F8F9FA; padding:56px 0 48px; }
.fd5-strip-hd { text-align:center; padding:0 24px; margin-bottom:40px; }
.fd5-strip-eyebrow {
  font-size:.72rem; font-weight:800; letter-spacing:.18em; text-transform:uppercase;
  color:#66C5C5; display:block; margin-bottom:10px;
}
.fd5-strip-title { font-size:1.65rem; font-weight:800; color:#001122; margin-bottom:8px; }
.fd5-strip-hint { color:#707070; font-size:.9rem; }

/* ── SCROLL TRACK ── */
.fd5-track-outer { position:relative; }
.fd5-track-outer::before,.fd5-track-outer::after {
  content:''; position:absolute; top:0; bottom:60px; width:100px; z-index:2; pointer-events:none;
}
.fd5-track-outer::before{left:0;background:linear-gradient(to right,#F8F9FA,transparent);}
.fd5-track-outer::after {right:0;background:linear-gradient(to left,#F8F9FA,transparent);}
.fd5-track {
  display:flex; gap:20px; overflow-x:auto;
  scroll-snap-type:x mandatory; -webkit-overflow-scrolling:touch;
  padding:16px 100px 48px; scrollbar-width:none; perspective:1200px;
}
.fd5-track::-webkit-scrollbar{display:none;}

/* ── CARD WRAPPER (for flip + lock) ── */
.fd5-cw {
  flex:0 0 288px; scroll-snap-align:center;
  perspective:1200px; cursor:pointer;
  position:relative;
}
/* lock overlay */
.fd5-lock {
  position:absolute; inset:0; z-index:10; border-radius:22px;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:8px;
  background:rgba(248,249,250,.82); backdrop-filter:blur(3px);
  border:1.5px solid #D0D6DF;
  transition:opacity .4s,transform .4s;
}
.fd5-lock-icon { font-size:1.8rem; }
.fd5-lock-text { font-size:.78rem; font-weight:700; color:#707070; }
.fd5-cw.fd5-unlocked .fd5-lock { opacity:0; pointer-events:none; transform:scale(1.08); }
/* unlock pop animation */
@keyframes fd5unlock {
  0%  {transform:scale(1.15);box-shadow:0 0 0 0 rgba(102,197,197,.4);}
  60% {transform:scale(1);box-shadow:0 0 0 18px rgba(102,197,197,0);}
  100%{transform:scale(1);}
}
.fd5-cw.fd5-just-unlocked {animation:fd5unlock .55s ease-out forwards;}

/* ── FLIP CARD ── */
.fd5-card {
  width:100%; height:380px; position:relative;
  transform-style:preserve-3d;
  transition:transform .55s cubic-bezier(.4,0,.2,1), box-shadow .3s;
  border-radius:22px;
}
.fd5-card.fd5-flipped { transform:rotateY(180deg); }
.fd5-cw.fd5-done .fd5-card { box-shadow:0 0 0 2.5px #66C5C5; }

.fd5-face {
  position:absolute; inset:0; border-radius:22px;
  backface-visibility:hidden; -webkit-backface-visibility:hidden;
  overflow:hidden;
}
/* FRONT */
.fd5-front {
  background:#F8F9FA; border:1.5px solid #D0D6DF;
  padding:26px 22px 20px; display:flex; flex-direction:column;
  box-shadow:0 4px 16px rgba(0,64,129,.07);
}
/* active card lift */
.fd5-cw.fd5-active .fd5-front {
  border-color:var(--ca,#66C5C5);
  box-shadow:0 18px 48px rgba(0,64,129,.14), 0 0 0 2px var(--ca,#66C5C5);
}
.fd5-front-wm {
  position:absolute; bottom:-14px; right:8px;
  font-size:7rem; font-weight:900; line-height:1;
  color:var(--ca,#66C5C5); opacity:.07;
  pointer-events:none; user-select:none;
}
.fd5-front-badge {
  display:inline-flex; align-items:center; gap:5px;
  font-size:.68rem; font-weight:800; letter-spacing:.12em; text-transform:uppercase;
  color:var(--cad,#586782); background:color-mix(in srgb,var(--ca,#66C5C5) 13%,transparent);
  border-radius:99px; padding:4px 12px; margin-bottom:16px; align-self:flex-start;
}
/* done checkmark badge */
