}
.fd5-flip-btn:hover{background:color-mix(in srgb,var(--ca,#66C5C5) 22%,transparent);transform:translateX(2px);}

/* BACK */
.fd5-back {
  background:linear-gradient(145deg,var(--ca,#66C5C5) 0%,var(--cad,#586782) 100%);
  transform:rotateY(180deg);
  padding:28px 22px 22px; display:flex; flex-direction:column;
  color:#F8F9FA;
}
.fd5-back-label {
  font-size:.68rem; font-weight:800; letter-spacing:.14em; text-transform:uppercase;
  color:rgba(248,249,250,.6); margin-bottom:10px;
}
.fd5-back-tip {
  font-size:.92rem; line-height:1.7; color:rgba(248,249,250,.92); flex:1;
}
.fd5-back-tip strong { color:#F8F9FA; font-weight:800; }
.fd5-back-actions { display:flex; flex-direction:column; gap:8px; margin-top:16px; }
.fd5-back-done {
  background:#F8F9FA; color:var(--cad,#586782);
  border:none; border-radius:10px; padding:11px 16px;
  font-size:.82rem; font-weight:800; cursor:pointer;
  display:flex; align-items:center; justify-content:center; gap:6px;
  transition:transform .15s,box-shadow .15s;
}
.fd5-back-done:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(0,17,34,.15);}
.fd5-back-done:disabled{opacity:.55;cursor:default;transform:none;}
.fd5-back-flip {
  background:rgba(248,249,250,.18); color:#F8F9FA;
  border:none; border-radius:10px; padding:9px 16px;
  font-size:.78rem; font-weight:700; cursor:pointer;
  transition:background .15s;
}
.fd5-back-flip:hover{background:rgba(248,249,250,.28);}

/* active scale effect via JS class */
.fd5-cw.fd5-active {
  z-index:4;
}
.fd5-cw.fd5-active .fd5-card {
  transform:scale(1.04) translateY(-6px);
}
.fd5-cw:not(.fd5-active):not(.fd5-unlocked-pending) .fd5-card {
  transform:scale(.93) translateY(6px);
  filter:saturate(.6) brightness(.97);
}
/* keep done cards at normal scale */
.fd5-cw.fd5-done:not(.fd5-active) .fd5-card { filter:none; }

/* ── DOT NAV ── */
.fd5-dots {
  display:flex; justify-content:center; gap:8px; padding:0 0 40px;
}
.fd5-dot {
  width:8px; height:8px; border-radius:99px;
  background:#D0D6DF; border:none; cursor:pointer; padding:0;
  transition:all .2s;
}
.fd5-dot.on { width:24px; background:#66C5C5; }
.fd5-dot.done-dot { background:#66C5C5; width:8px; }

/* ── TASK SECTION ── */
.fd5-tasks { background:#F8F9FA; border-top:1px solid #D0D6DF; padding:72px 24px; }
.fd5-tasks-inner { max-width:840px; margin:0 auto; }
.fd5-tasks-ey { font-size:.72rem; font-weight:800; letter-spacing:.18em; text-transform:uppercase; color:#66C5C5; display:block; margin-bottom:10px; }
.fd5-tasks-h { font-size:1.65rem; font-weight:800; color:#001122; margin-bottom:8px; }
.fd5-tasks-sub { color:#707070; margin-bottom:44px; }
.fd5-tgrid { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
@media(max-width:640px){.fd5-tgrid{grid-template-columns:1fr;}}
