}
.fd5-tc:hover{transform:translateY(-4px);box-shadow:0 16px 40px rgba(0,64,129,.1);}
.fd5-tc-top {
  padding:22px 22px 16px;
  background:color-mix(in srgb,var(--ta) 8%,#F8F9FA);
  border-bottom:1.5px solid color-mix(in srgb,var(--ta) 20%,transparent);
  display:flex; align-items:center; gap:14px;
}
.fd5-tc-ico {
  width:44px; height:44px; border-radius:12px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:color-mix(in srgb,var(--ta) 15%,transparent); color:var(--ta);
}
