.fd5-tc-name { font-size:.98rem; font-weight:800; color:#001122; }
.fd5-tc-urg { margin-left:auto; font-size:.65rem; font-weight:700; background:var(--ta); color:#F8F9FA; padding:3px 9px; border-radius:99px; flex-shrink:0; }
.fd5-tc-body { padding:18px 22px 22px; }
.fd5-tc-desc { font-size:.87rem; color:#707070; line-height:1.65; margin-bottom:16px; }
.fd5-tc-steps { display:flex; gap:4px; margin-bottom:18px; }
.fd5-tc-step { flex:1; text-align:center; font-size:.7rem; color:#929EB4; position:relative; }
.fd5-tc-step::after { content:'›'; position:absolute; right:-4px; top:9px; color:#D0D6DF; font-size:1rem; }
.fd5-tc-step:last-child::after{display:none;}
.fd5-tc-step-i {
  width:32px; height:32px; border-radius:50%; margin:0 auto 4px;
  background:color-mix(in srgb,var(--ta) 11%,transparent); color:var(--ta);
  display:flex; align-items:center; justify-content:center; font-size:.88rem;
}
.fd5-tc-cta {
  display:flex; align-items:center; justify-content:space-between;
