  text-decoration:none; color:var(--ta); font-weight:700; font-size:.84rem;
  transition:background .15s;
}
.fd5-tc-cta:hover{background:color-mix(in srgb,var(--ta) 18%,transparent);}

/* ============================================================
   FIRST DAY V7 — fd6-*
   Scroll-reveal narrative · 4 rich step sections
   ============================================================ */
.fd6 { background:#F8F9FA; }

/* ── Scroll reveal base ── */
.fd6-reveal {
  opacity:0; transform:translateY(36px);
  transition:opacity .7s ease, transform .7s ease;
}
.fd6-reveal.fd6-visible { opacity:1; transform:translateY(0); }
.fd6-reveal-left {
  opacity:0; transform:translateX(-40px);
  transition:opacity .7s ease, transform .7s ease;
}
.fd6-reveal-left.fd6-visible { opacity:1; transform:translateX(0); }
.fd6-reveal-right {
  opacity:0; transform:translateX(40px);
  transition:opacity .7s ease, transform .7s ease;
}
.fd6-reveal-right.fd6-visible { opacity:1; transform:translateX(0); }
[data-fd6delay="1"]  { transition-delay:.1s; }
[data-fd6delay="2"]  { transition-delay:.2s; }
[data-fd6delay="3"]  { transition-delay:.35s; }
[data-fd6delay="4"]  { transition-delay:.5s; }

/* ── Journey wrapper (sticky nav + steps) ── */
.fd6-journey {
  display:flex; align-items:flex-start;
  max-width:1160px; margin:0 auto;
  padding:80px 24px 80px;
  gap:60px;
}
/* Sticky side nav */
.fd6-sidenav {
  flex:0 0 180px;
  position:sticky; top:96px;
  display:flex; flex-direction:column; align-items:center; gap:0;
}
.fd6-sidenav-line {
  position:absolute; top:16px; bottom:16px; left:50%;
  width:2px; background:#D0D6DF; transform:translateX(-50%);
  z-index:0;
}
.fd6-sidenav-fill {
  position:absolute; top:16px; left:50%;
  width:2px; background:linear-gradient(to bottom,#66C5C5,#586782);
  transform:translateX(-50%);
  height:0%; transition:height .4s ease;
  z-index:0;
}
.fd6-sn-item {
  position:relative; z-index:1;
  display:flex; flex-direction:column; align-items:center; gap:6px;
  padding:12px 0; cursor:pointer; width:100%;
  transition:color .25s;
}
.fd6-sn-node {
  width:32px; height:32px; border-radius:50%;
  border:2.5px solid #D0D6DF; background:#F8F9FA;
  display:flex; align-items:center; justify-content:center;
  font-size:.72rem; font-weight:800; color:#929EB4;
  transition:all .3s cubic-bezier(0.25, 1, 0.5, 1);
}
.fd6-sn-item.active .fd6-sn-node {
  border-color:#66C5C5; background:#66C5C5; color:#F8F9FA;
  box-shadow:0 0 0 5px rgba(102,197,197,.18);
  transform:scale(1.12);
}
.fd6-sn-label {
  font-size:.68rem; font-weight:700; color:#929EB4; text-align:center; line-height:1.3;
  transition:color .25s;
}
.fd6-sn-item.active .fd6-sn-label { color:#586782; }

/* Hide sidenav on narrow screens */
@media(max-width:860px){ .fd6-sidenav{display:none;} .fd6-journey{padding:48px 20px;} }

/* ── Step sections ── */
.fd6-steps-wrap { flex:1; display:flex; flex-direction:column; gap:0; min-width:0; }
.fd6-step {
  padding:72px 0;
  border-bottom:1px solid #F8F9FA;
}
.fd6-step:last-child { border-bottom:none; }

/* Step eyebrow */
.fd6-step-eye {
  display:inline-flex; align-items:center; gap:8px;
  font-size:.72rem; font-weight:800; letter-spacing:.16em; text-transform:uppercase;
  border-radius:99px; padding:5px 14px; margin-bottom:20px;
}
.fd6-step-num-big {
  position:absolute; top:-8px; right:0;
  font-size:9rem; font-weight:900; line-height:1; letter-spacing:-.04em;
  opacity:.045; pointer-events:none; user-select:none;
  color:var(--step-col,#66C5C5);
}
.fd6-step-head { position:relative; margin-bottom:36px; }
.fd6-step-title {
  font-size:clamp(1.6rem,3vw,2.2rem); font-weight:900;
  color:#001122; letter-spacing:-.02em; margin-bottom:12px; line-height:1.2;
}
.fd6-step-lead { font-size:1rem; color:#586782; line-height:1.75; max-width:560px; }

/* ── Layout variants ── */

/* Step 1: Two-col — text left, highlight card right */
.fd6-l-split { display:grid; grid-template-columns:1fr 1fr; gap:32px; align-items:start; }
@media(max-width:680px){ .fd6-l-split{grid-template-columns:1fr;} }

/* Step 2: Full-width visual strip */
.fd6-l-visual { display:flex; flex-direction:column; gap:28px; }

/* Step 3: Card grid */
.fd6-l-cards { display:grid; grid-template-columns:repeat(3,1fr); gap:16px; }
@media(max-width:640px){ .fd6-l-cards{grid-template-columns:1fr 1fr;} }
@media(max-width:400px){ .fd6-l-cards{grid-template-columns:1fr;} }

