  display:flex; gap:6px; align-items:center; margin-bottom:4px;
}
.fd6-mock-dot { width:10px; height:10px; border-radius:50%; }
.fd6-mock-row {
  height:10px; border-radius:6px; background:rgba(248,249,250,.1);
}
.fd6-mock-row.wide { width:70%; }
.fd6-mock-row.medium { width:50%; }
.fd6-mock-row.short { width:30%; }
.fd6-mock-row.accent { background:rgba(102,197,197,.4); width:40%; }
.fd6-mock-block {
  display:grid; grid-template-columns:1fr 1fr 1fr; gap:8px; margin-top:4px;
}
.fd6-mock-cell {
  height:48px; border-radius:8px; background:rgba(248,249,250,.07);
}
.fd6-mock-cell.hi { background:rgba(102,197,197,.2); }
/* Person cards */
.fd6-person {
  background:#F8F9FA; border-radius:16px; border:1.5px solid #F8F9FA;
  padding:20px 16px; text-align:center;
}
