  background:color-mix(in srgb,var(--step-col,#66C5C5) 13%,transparent);
}
.fd6-person-role { font-size:.68rem; font-weight:800; letter-spacing:.1em; text-transform:uppercase; color:var(--step-col,#66C5C5); margin-bottom:4px; }
.fd6-person-name { font-size:.88rem; font-weight:700; color:#001122; margin-bottom:8px; }
.fd6-person-ask {
  font-size:.76rem; color:#586782; line-height:1.5;
  background:color-mix(in srgb,var(--step-col,#66C5C5) 7%,transparent);
