/* ============================================================
   FIRST DAY V8 — fd8-*   (replaces fd6 + fixes render bug)
   ============================================================ */
.fd8 { background:#F8F9FA; }

/* ── Compact header ── */
.fd8-header {
  background: linear-gradient(135deg,#004081 0%,#004081 60%,#586782 100%);
  padding: 64px 24px 72px;
  position: relative; overflow: hidden;
}
.fd8-header::after {
  content: '';
  position: absolute; bottom: -1px; left: 0; right: 0; height: 48px;
  background: #F8F9FA;
  clip-path: ellipse(55% 100% at 50% 100%);
}
/* decorative rings */
.fd8-ring {
  position: absolute; border-radius: 50%; border: 1px solid rgba(248,249,250,.07);
  pointer-events: none;
}
.fd8-header-inner {
  max-width: 760px; margin: 0 auto; position: relative; z-index: 1;
  display: grid; grid-template-columns: 1fr auto; gap: 32px; align-items: center;
}
@media(max-width:640px){ .fd8-header-inner{grid-template-columns:1fr;} }
.fd8-header-kicker {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: .72rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  color: rgba(248,249,250,.65); margin-bottom: 16px;
}
.fd8-kpulse {
  width: 7px; height: 7px; border-radius: 50%;
  background: #66C5C5;
  animation: fd8kp 1.8s ease-in-out infinite;
}
@keyframes fd8kp{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.3;transform:scale(1.5)}}
.fd8-header h1 {
  font-size: clamp(1.9rem,4vw,2.8rem); font-weight: 900;
  color: #F8F9FA; line-height: 1.15; letter-spacing: -.02em; margin-bottom: 14px;
}
.fd8-header h1 span { color: #66C5C5; }
.fd8-header-sub { font-size: .95rem; color: rgba(248,249,250,.68); line-height: 1.7; }
/* Step pills on the right */
.fd8-step-pills {
  display: flex; flex-direction: column; gap: 10px; flex-shrink: 0;
}
.fd8-pill {
  display: flex; align-items: center; gap: 10px;
  background: rgba(248,249,250,.1); border: 1px solid rgba(248,249,250,.15);
  border-radius: 10px; padding: 10px 16px; cursor: pointer;
  transition: background .2s; text-decoration: none;
  color: rgba(248,249,250,.85); font-size: .82rem; font-weight: 600;
  white-space: nowrap;
}
.fd8-pill:hover { background: rgba(248,249,250,.18); }
.fd8-pill-n {
  width: 22px; height: 22px; border-radius: 50%; background: rgba(248,249,250,.15);
  display: flex; align-items: center; justify-content: center;
  font-size: .65rem; font-weight: 800; color: #F8F9FA; flex-shrink: 0;
}
.fd8-pill.current .fd8-pill-n { background: #66C5C5; }

/* ── Journey body ── */
.fd8-body {
  max-width: 980px; margin: 0 auto;
  padding: 0 24px 80px;
}

/* ── Each step block ── */
.fd8-step {
  padding: 64px 0;
  border-bottom: 1px solid #D0D6DF;
}
.fd8-step:last-child { border-bottom: none; }

.fd8-step-label {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: .7rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  border-radius: 99px; padding: 5px 14px; margin-bottom: 18px;
}
.fd8-step-h {
  font-size: clamp(1.5rem,3vw,2rem); font-weight: 900;
  color: #001122; letter-spacing: -.02em; margin-bottom: 12px;
}
.fd8-step-lead {
  font-size: .97rem; color: #586782; line-height: 1.75;
  max-width: 600px; margin-bottom: 36px;
}

/* Content grid — 2 cols */
.fd8-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
@media(max-width:640px){ .fd8-2col{grid-template-columns:1fr;} }
/* Content grid — 3 cols */
.fd8-3col { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; }
@media(max-width:620px){ .fd8-3col{grid-template-columns:1fr;} }
/* Content grid — 4 cols */
.fd8-4col { display: grid; grid-template-columns: repeat(4,1fr); gap: 14px; }
@media(max-width:680px){ .fd8-4col{grid-template-columns:1fr 1fr;} }

/* ── Card / Box components ── */
.fd8-card {
  background: #F8F9FA; border: 1.5px solid #D0D6DF;
  border-radius: 16px; padding: 22px 20px; position: relative; overflow: hidden;
}
.fd8-card-accent { /* top color bar */
  position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: var(--ac, #66C5C5);
}
.fd8-card-h { font-size: .78rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--ac,#66C5C5); margin-bottom: 14px; }
.fd8-bullets { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 11px; }
.fd8-bullet { display: flex; gap: 11px; align-items: flex-start; font-size: .88rem; color: #505050; line-height: 1.6; }
.fd8-bullet-icon { width: 20px; height: 20px; border-radius: 50%; flex-shrink: 0; margin-top: 1px;
  background: color-mix(in srgb,var(--ac,#66C5C5) 14%,transparent);
  color: var(--ac,#66C5C5); display: flex; align-items: center; justify-content: center; font-size: .75rem; }
.fd8-bullet strong { color: #001122; }

.fd8-quote {
  border-left: 3px solid var(--ac,#66C5C5);
  padding: 14px 18px;
  background: color-mix(in srgb,var(--ac,#66C5C5) 7%,transparent);
  border-radius: 0 12px 12px 0;
  font-size: .92rem; color: #505050; font-style: italic; line-height: 1.7;
}

/* Mini step tile */
