  background: #F8F9FA; border: 1.5px solid #D0D6DF; border-radius: 14px;
  padding: 18px 14px; text-align: center;
}
.fd8-tile-n { font-size: 1.8rem; font-weight: 900; color: var(--ac,#66C5C5); opacity: .2; line-height: 1; margin-bottom: 8px; }
.fd8-tile-icon { font-size: 1.4rem; margin-bottom: 8px; display: block; }
.fd8-tile-name { font-size: .8rem; font-weight: 700; color: #001122; margin-bottom: 4px; }
.fd8-tile-sub { font-size: .72rem; color: #929EB4; line-height: 1.5; }

/* Dark mockup */
.fd8-mock {
  background: linear-gradient(135deg,#001122,#001122);
  border-radius: 14px; padding: 18px; display: flex; flex-direction: column; gap: 9px;
  box-shadow: 0 18px 48px rgba(0,17,34,.22);
}
.fd8-mock-bar { display: flex; gap: 5px; align-items: center; margin-bottom: 4px; }
.fd8-mock-dot { width: 9px; height: 9px; border-radius: 50%; }
.fd8-mock-line { height: 9px; border-radius: 5px; background: rgba(248,249,250,.1); }
