.fd8-mock-line.w30 { width: 30%; } .fd8-mock-line.acc { background: rgba(102,197,197,.38); width: 45%; }
.fd8-mock-grid { display: grid; grid-template-columns:1fr 1fr 1fr; gap: 7px; margin-top: 4px; }
.fd8-mock-cell { height: 44px; border-radius: 7px; background: rgba(248,249,250,.07); }
.fd8-mock-cell.hi { background: rgba(102,197,197,.22); }

/* Person card */
.fd8-person {
  background: #F8F9FA; border: 1.5px solid #D0D6DF;
  border-radius: 16px; padding: 20px 16px; text-align: center;
}
.fd8-person-av {
  width: 50px; height: 50px; border-radius: 50%; margin: 0 auto 12px;
  background: color-mix(in srgb,var(--ac,#66C5C5) 13%,transparent);
  display: flex; align-items: center; justify-content: center; font-size: 1.5rem;
}
.fd8-person-role { font-size: .65rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--ac,#66C5C5); margin-bottom: 4px; }
.fd8-person-name { font-size: .86rem; font-weight: 700; color: #001122; margin-bottom: 10px; }
.fd8-person-ask { font-size: .75rem; color: #586782; line-height: 1.55; background: color-mix(in srgb,var(--ac,#66C5C5) 8%,transparent); border-radius: 9px; padding: 8px 10px; }

/* Timesheet rows */
.fd8-ts { display: flex; flex-direction: column; gap: 10px; }
.fd8-ts-row {
  display: grid; grid-template-columns: 140px 1fr auto; gap: 14px; align-items: center;
  background: #F8F9FA; border: 1.5px solid #D0D6DF; border-radius: 13px; padding: 14px 18px;
}
