.fd8-ts-lbl { font-size: .75rem; font-weight: 700; color: #929EB4; text-transform: uppercase; letter-spacing: .07em; }
.fd8-ts-val { font-size: .88rem; color: #001122; font-weight: 600; }
.fd8-ts-tag { font-size: .68rem; font-weight: 700; padding: 3px 10px; border-radius: 99px;
  background: color-mix(in srgb,var(--ac,#66C5C5) 13%,transparent); color: var(--ac,#66C5C5); white-space:nowrap; }
.fd8-ts-row.warn { border-color: #FFCC00; }
.fd8-ts-row.warn .fd8-ts-tag { background:#F8F9FA; color:#F3554F; }

/* CTA link row */
.fd8-cta-link {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--ac,#66C5C5); color: #F8F9FA;
  padding: 12px 24px; border-radius: 99px;
  font-weight: 700; font-size: .88rem; text-decoration: none;
  box-shadow: 0 6px 20px color-mix(in srgb,var(--ac,#66C5C5) 40%,transparent);
  transition: transform .2s, box-shadow .2s;
}
.fd8-cta-link:hover { transform: translateY(-2px); box-shadow: 0 10px 28px color-mix(in srgb,var(--ac,#66C5C5) 50%,transparent); }

/* ── Task cards section ── */
