  background: #F8F9FA; border-top: 1px solid #D0D6DF; padding: 72px 24px;
}
.fd8-tasks-inner { max-width: 840px; margin: 0 auto; }
.fd8-tasks-ey { font-size:.7rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:#66C5C5;display:block;margin-bottom:10px; }
.fd8-tasks-h { font-size:1.6rem;font-weight:900;color:#001122;margin-bottom:8px; }
.fd8-tasks-sub { color:#586782;margin-bottom:40px; }
.fd8-tgrid { display:grid;grid-template-columns:1fr 1fr;gap:20px; }
@media(max-width:580px){ .fd8-tgrid{grid-template-columns:1fr;} }
.fd8-tc { border-radius:18px;border:1.5px solid #D0D6DF;overflow:hidden;transition:transform .2s,box-shadow .2s; }
.fd8-tc:hover { transform:translateY(-4px);box-shadow:0 14px 36px rgba(0,64,129,.1); }
.fd8-tc-top { padding:20px 20px 14px;background:color-mix(in srgb,var(--ta) 8%,#F8F9FA);border-bottom:1.5px solid color-mix(in srgb,var(--ta) 18%,transparent);display:flex;align-items:center;gap:13px; }
.fd8-tc-ico { width:42px;height:42px;border-radius:11px;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:color-mix(in srgb,var(--ta) 15%,transparent);color:var(--ta); }
.fd8-tc-lbl { font-size:.63rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--ta);margin-bottom:2px; }
.fd8-tc-name { font-size:.95rem;font-weight:800;color:#001122; }
.fd8-tc-urg { margin-left:auto;font-size:.63rem;font-weight:700;background:var(--ta);color:#F8F9FA;padding:3px 9px;border-radius:99px;flex-shrink:0; }
.fd8-tc-body { padding:16px 20px 20px; }
.fd8-tc-desc { font-size:.86rem;color:#586782;line-height:1.65;margin-bottom:14px; }
.fd8-tc-steps { display:flex;gap:4px;margin-bottom:16px; }
.fd8-tc-s { flex:1;text-align:center;font-size:.68rem;color:#929EB4;position:relative; }
.fd8-tc-s::after { content:'›';position:absolute;right:-4px;top:8px;color:#D0D6DF;font-size:.95rem; }
.fd8-tc-s:last-child::after{display:none;}
.fd8-tc-si { width:30px;height:30px;border-radius:50%;margin:0 auto 4px;background:color-mix(in srgb,var(--ta) 10%,transparent);color:var(--ta);display:flex;align-items:center;justify-content:center;font-size:.82rem; }
.fd8-tc-cta { display:flex;align-items:center;justify-content:space-between;background:color-mix(in srgb,var(--ta) 9%,transparent);border-radius:9px;padding:10px 13px;text-decoration:none;color:var(--ta);font-weight:700;font-size:.82rem;transition:background .15s; }
.fd8-tc-cta:hover{background:color-mix(in srgb,var(--ta) 17%,transparent);}

/* ── Scroll-in animation (JS-driven, safe) ── */
.fd8-ani {
  /* visible by default; JS adds fd8-hidden before observing */
  transition: opacity .65s ease, transform .65s ease;
}
.fd8-ani.fd8-hidden { opacity: 0; transform: translateY(30px); }
.fd8-ani.fd8-hidden.fd8-from-left { transform: translateX(-30px); }
.fd8-ani.fd8-hidden.fd8-from-right { transform: translateX(30px); }
[data-d="1"].fd8-hidden ~ [data-d] { transition-delay: 0s; }
.fd8-ani { transition-delay: var(--d, 0s); }

