/* ============================================================
   FIRST DAY V10 — fda-*
   No hero · CSS-only animations · Tab-based step panel
   ============================================================ */

/* ── Load keyframes (no JS needed) ── */
@keyframes fdaUp  { from{opacity:0;transform:translateY(22px)} to{opacity:1;transform:none} }
@keyframes fdaLeft{ from{opacity:0;transform:translateX(-24px)} to{opacity:1;transform:none} }
@keyframes fdaFade{ from{opacity:0} to{opacity:1} }

/* ── Page title bar ── */
.fda-titlebar {
  background: #F8F9FA;
  border-bottom: 1px solid #F8F9FA;
  padding: 40px 24px 36px;
}
.fda-titlebar-inner { max-width: 940px; margin: 0 auto; }
.fda-tb-kicker {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: .7rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  color: #586782; background: rgba(102,197,197,.12);
  border-radius: 99px; padding: 5px 14px; margin-bottom: 14px;
  animation: fdaFade .4s ease both;
}
.fda-tb-pulse { width: 7px; height: 7px; border-radius: 50%; background: #66C5C5; animation: fd9kp 1.8s ease-in-out infinite; }
.fda-titlebar h1 {
  font-size: clamp(1.7rem,3.5vw,2.4rem); font-weight: 900;
  color: #001122; letter-spacing: -.02em; margin-bottom: 10px;
  animation: fdaUp .5s .05s ease both;
}
.fda-titlebar h1 em { font-style: normal; color: #586782; }
.fda-tb-sub {
  font-size: .93rem; color: #586782; line-height: 1.7; max-width: 540px;
  animation: fdaUp .5s .12s ease both;
}

/* ── Page body ── */
.fda-body { background: #F8F9FA; }
.fda-inner { max-width: 940px; margin: 0 auto; padding: 48px 24px 80px; }

/* ── TASK CARDS ── */
.fda-tasks-head {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 18px;
  animation: fdaFade .4s .18s ease both;
}
.fda-tasks-badge {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: .7rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase;
  color: #F3554F; background: #F8F9FA; border-radius: 99px; padding: 5px 14px;
}
.fda-tasks-note { font-size: .82rem; color: #929EB4; }

.fda-tgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 48px; }
@media(max-width:580px){ .fda-tgrid{grid-template-columns:1fr;} }

.fda-tc {
  background: #F8F9FA; border-radius: 18px; overflow: hidden;
  border: 1.5px solid #D0D6DF;
  box-shadow: 0 3px 18px rgba(0,64,129,.07);
  transition: transform .2s, box-shadow .2s;
}
.fda-tc:nth-child(1) { animation: fdaUp .5s .22s ease both; }
.fda-tc:nth-child(2) { animation: fdaUp .5s .34s ease both; }
.fda-tc:hover { transform: translateY(-4px); box-shadow: 0 12px 36px rgba(0,64,129,.12); }
.fda-tc-top {
  padding: 20px 20px 14px;
  background: color-mix(in srgb,var(--ta) 9%,#F8F9FA);
  border-bottom: 1.5px solid color-mix(in srgb,var(--ta) 18%,transparent);
  display: flex; align-items: center; gap: 12px;
}
.fda-tc-ico { width: 44px; height: 44px; border-radius: 12px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; background: color-mix(in srgb,var(--ta) 15%,transparent); color: var(--ta); }
.fda-tc-lbl { font-size: .62rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--ta); margin-bottom: 2px; }
.fda-tc-name { font-size: .96rem; font-weight: 800; color: #001122; }
.fda-tc-urg { margin-left: auto; font-size: .62rem; font-weight: 800; background: var(--ta); color: #F8F9FA; padding: 4px 10px; border-radius: 99px; flex-shrink: 0; }
.fda-tc-body { padding: 16px 20px 20px; }
.fda-tc-desc { font-size: .86rem; color: #586782; line-height: 1.65; margin-bottom: 14px; }
.fda-tc-steps { display: flex; gap: 4px; margin-bottom: 16px; }
.fda-tc-s { flex: 1; text-align: center; font-size: .67rem; color: #929EB4; position: relative; }
.fda-tc-s::after { content: '›'; position: absolute; right: -3px; top: 8px; color: #D0D6DF; font-size: .9rem; }
.fda-tc-s:last-child::after { display: none; }
.fda-tc-si { width: 30px; height: 30px; border-radius: 50%; margin: 0 auto 4px; background: color-mix(in srgb,var(--ta) 11%,transparent); color: var(--ta); display: flex; align-items: center; justify-content: center; font-size: .82rem; }
.fda-tc-cta { display: flex; align-items: center; justify-content: space-between; background: color-mix(in srgb,var(--ta) 9%,transparent); border-radius: 9px; padding: 10px 13px; text-decoration: none; color: var(--ta); font-weight: 700; font-size: .82rem; transition: background .15s; }
.fda-tc-cta:hover { background: color-mix(in srgb,var(--ta) 18%,transparent); }

/* ── STEP TAB NAV ── */
.fda-step-section { animation: fdaUp .5s .4s ease both; }
.fda-section-label {
  font-size: .7rem; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  color: #929EB4; display: block; margin-bottom: 16px;
}
.fda-tabs {
  display: grid; grid-template-columns: repeat(4,1fr); gap: 8px;
  margin-bottom: 0;
}
@media(max-width:620px){ .fda-tabs{grid-template-columns:1fr 1fr;} }

.fda-tab {
  border: 1.5px solid #D0D6DF;
  border-radius: 14px; padding: 14px 12px;
  background: #F8F9FA; cursor: pointer;
  text-align: left; transition: border-color .2s, box-shadow .2s, background .2s;
  position: relative; overflow: hidden;
  /* bottom border becomes the active indicator */
  border-bottom-width: 3px;
}
.fda-tab:hover { border-color: var(--tc); box-shadow: 0 4px 16px rgba(0,64,129,.08); }
.fda-tab.active {
  border-color: var(--tc);
  border-bottom-color: var(--tc);
  background: color-mix(in srgb,var(--tc) 6%,#F8F9FA);
  box-shadow: 0 4px 20px rgba(0,64,129,.1);
}
.fda-tab-num {
  font-size: .62rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  color: var(--tc); margin-bottom: 6px;
}
.fda-tab-name { font-size: .88rem; font-weight: 800; color: #001122; line-height: 1.25; }
.fda-tab-sub { font-size: .72rem; color: #929EB4; margin-top: 3px; }
/* active dot */
.fda-tab.active::after {
  content: '';
  position: absolute; bottom: 0; left: 0; right: 0; height: 3px;
  background: var(--tc);
}

/* ── STEP PANEL ── */
.fda-panel-wrap {
  margin-top: -1px;
  border: 1.5px solid #D0D6DF; border-radius: 0 0 18px 18px;
  background: #F8F9FA; overflow: hidden;
}
.fda-panel { display: none; padding: 36px 32px; }
.fda-panel.active { display: block; animation: fdaFade .3s ease; }

/* Panel internals */
.fda-panel-h { font-size: 1.3rem; font-weight: 900; color: #001122; margin-bottom: 8px; letter-spacing: -.01em; }
.fda-panel-lead { font-size: .92rem; color: #586782; line-height: 1.75; max-width: 560px; margin-bottom: 28px; }
.fda-p2col { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
@media(max-width:580px){ .fda-p2col{grid-template-columns:1fr;} }
.fda-p3col { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; }
@media(max-width:580px){ .fda-p3col{grid-template-columns:1fr;} }
.fda-p4col { display: grid; grid-template-columns: repeat(4,1fr); gap: 12px; }
@media(max-width:640px){ .fda-p4col{grid-template-columns:1fr 1fr;} }

.fda-pcard {
  background: #F8F9FA; border: 1px solid #F8F9FA; border-radius: 13px;
  padding: 18px 16px; position: relative; overflow: hidden;
}
.fda-pcard-bar { position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--pc,#66C5C5); }
.fda-pcard-h { font-size: .65rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; color: var(--pc,#66C5C5); margin-bottom: 11px; }
.fda-bullets { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 9px; }
.fda-bullet { display: flex; gap: 9px; align-items: flex-start; font-size: .86rem; color: #505050; line-height: 1.6; }
.fda-bico { width: 19px; height: 19px; border-radius: 50%; flex-shrink: 0; margin-top: 1px; background: color-mix(in srgb,var(--pc,#66C5C5) 14%,transparent); color: var(--pc,#66C5C5); display: flex; align-items: center; justify-content: center; font-size: .72rem; }
.fda-bullet strong { color: #001122; }
.fda-quote { border-left: 3px solid var(--pc,#66C5C5); padding: 12px 15px; background: color-mix(in srgb,var(--pc,#66C5C5) 7%,transparent); border-radius: 0 10px 10px 0; font-size: .88rem; color: #505050; font-style: italic; line-height: 1.7; }

/* Metro tile */
.fda-tile { background: #F8F9FA; border: 1px solid #F8F9FA; border-radius: 12px; padding: 14px 10px; text-align: center; }
.fda-tile-n { font-size: 1.4rem; font-weight: 900; color: var(--pc,#929EB4); opacity: .2; line-height: 1; margin-bottom: 6px; }
.fda-tile-i { font-size: 1.2rem; margin-bottom: 6px; display: block; }
.fda-tile-name { font-size: .76rem; font-weight: 700; color: #001122; margin-bottom: 2px; }
.fda-tile-sub { font-size: .69rem; color: #929EB4; line-height: 1.4; }

/* Dark mock */
.fda-mock { background: linear-gradient(135deg,#001122,#001122); border-radius: 12px; padding: 14px; display: flex; flex-direction: column; gap: 7px; box-shadow: 0 14px 40px rgba(0,17,34,.2); }
.fda-mock-bar { display: flex; gap: 5px; align-items: center; margin-bottom: 3px; }
.fda-mock-dot { width: 8px; height: 8px; border-radius: 50%; }
.fda-mock-ln { height: 7px; border-radius: 4px; background: rgba(248,249,250,.1); }
.fda-mock-ln.w70{width:70%}.fda-mock-ln.w50{width:50%}.fda-mock-ln.w30{width:30%}.fda-mock-ln.acc{background:rgba(102,197,197,.4);width:40%}
.fda-mock-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 5px; margin-top: 3px; }
.fda-mock-cell { height: 36px; border-radius: 6px; background: rgba(248,249,250,.07); }
.fda-mock-cell.hi { background: rgba(102,197,197,.22); }

/* Person */
.fda-person { background: #F8F9FA; border: 1px solid #F8F9FA; border-radius: 13px; padding: 16px 12px; text-align: center; }
.fda-person-av { width: 44px; height: 44px; border-radius: 50%; margin: 0 auto 10px; background: color-mix(in srgb,var(--pc,#F3554F) 13%,transparent); display: flex; align-items: center; justify-content: center; font-size: 1.35rem; }
.fda-person-role { font-size: .6rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--pc,#F3554F); margin-bottom: 2px; }
.fda-person-name { font-size: .82rem; font-weight: 700; color: #001122; margin-bottom: 8px; }
.fda-person-ask { font-size: .72rem; color: #586782; line-height: 1.5; background: color-mix(in srgb,var(--pc,#F3554F) 7%,transparent); border-radius: 7px; padding: 7px 9px; }

/* Timesheet rows */
.fda-ts { display: flex; flex-direction: column; gap: 8px; }
.fda-ts-row { display: grid; grid-template-columns: 120px 1fr auto; gap: 12px; align-items: center; background: #F8F9FA; border: 1px solid #F8F9FA; border-radius: 11px; padding: 12px 15px; }
@media(max-width:500px){ .fda-ts-row{grid-template-columns:1fr;} }
.fda-ts-lbl { font-size: .7rem; font-weight: 700; color: #929EB4; text-transform: uppercase; letter-spacing: .07em; }
.fda-ts-val { font-size: .85rem; color: #001122; font-weight: 600; }
.fda-ts-tag { font-size: .63rem; font-weight: 700; padding: 3px 8px; border-radius: 99px; background: color-mix(in srgb,var(--pc,#FFCC00) 13%,transparent); color: var(--pc,#FFCC00); white-space: nowrap; }
.fda-ts-row.warn { border-color: #FFCC00; background: #F8F9FA; }
.fda-ts-row.warn .fda-ts-tag { background: #F8F9FA; color: #F3554F; }

.fda-cta-btn { display: inline-flex; align-items: center; gap: 7px; background: var(--pc,#FFCC00); color: #F8F9FA; padding: 11px 20px; border-radius: 99px; font-weight: 700; font-size: .84rem; text-decoration: none; box-shadow: 0 5px 16px color-mix(in srgb,var(--pc,#FFCC00) 36%,transparent); transition: transform .18s, box-shadow .18s; }
.fda-cta-btn:hover { transform: translateY(-2px); box-shadow: 0 9px 24px color-mix(in srgb,var(--pc,#FFCC00) 48%,transparent); }

/* Tab nav rounded top corners */
.fda-tab:first-child { border-radius: 14px 14px 0 0; }
/* full nav tab row connects to panel */
.fda-tabs { border-radius: 14px 14px 0 0; }
.fda-tab { border-radius: 0; }
.fda-tab:first-child { border-radius: 14px 0 0 0; }
.fda-tab:last-child { border-radius: 0 14px 0 0; }
/* remove inner borders between tabs */
.fda-tab + .fda-tab { border-left-width: 0; }
@media(max-width:620px){
  .fda-tab + .fda-tab { border-left-width: 1.5px; }
  .fda-tab:first-child { border-radius: 14px 0 0 0; }
  .fda-tab:nth-child(2) { border-radius: 0 14px 0 0; }
  .fda-tab:nth-child(3) { border-radius: 0; }
  .fda-tab:nth-child(4) { border-radius: 0; }
}

/* ══════════════════════════════════════════════════════
   fdb-* — First Day V11  (scroll-reveal step cards)
   ══════════════════════════════════════════════════════ */

/* reveal base */
.fdb-reveal { opacity:0; transform:translateY(44px); transition:opacity .7s cubic-bezier(.22,1,.36,1), transform .7s cubic-bezier(.22,1,.36,1); }
