/* ── Day 1 hero (redesigned split layout) ───────────────────────── */
.fdc-hero {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 0;
  padding: calc(var(--nav-h) + 28px) clamp(20px,5vw,64px) 40px;
  overflow: hidden;
  background: #001122;
  isolation: isolate;
  min-height: 260px;
}
/* subtle diagonal stripe texture */
.fdc-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(
      -55deg,
      rgba(102,197,197,.018) 0px,
      rgba(102,197,197,.018) 1px,
      transparent 1px,
      transparent 32px
    );
  pointer-events: none;
}
/* teal glow behind right side */
.fdc-hero::after {
  content: '';
  position: absolute;
  right: 0; top: 0; bottom: 0;
  width: 55%;
  background: radial-gradient(ellipse 80% 100% at 90% 50%,
    rgba(102,197,197,.13) 0%,
    rgba(0,64,129,.08) 50%,
    transparent 75%);
  pointer-events: none;
}
.fdc-hero-noise {
  position: absolute;
  inset: 0;
  opacity: .025;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 256px 256px;
  pointer-events: none;
}

/* left col */
.fdc-hero-left {
  position: relative;
  z-index: 2;
  max-width: 520px;
}
.fdc-hero-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px 5px 8px;
  border-radius: 100px;
  background: rgba(102,197,197,.1);
  border: 1px solid rgba(102,197,197,.22);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: rgba(102,197,197,.9);
  margin-bottom: 18px;
}
.fdc-hero-pip {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #66C5C5;
  box-shadow: 0 0 6px rgba(102,197,197,.8);
  animation: heroPip 2.4s ease-in-out infinite;
  flex-shrink: 0;
}
@keyframes heroPip { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.4;transform:scale(1.7)} }

.fdc-hero-h1 {
  font-size: clamp(1.9rem, 4.8vw, 3rem);
  font-weight: 900;
  color: #F8F9FA;
  line-height: 1.12;
  letter-spacing: -.03em;
  margin: 0 0 14px;
}
