@media(max-width:480px){ .fdc-ts-row{ grid-template-columns:1fr; gap:4px; } }
.fdc-ts-lbl { font-size:.63rem; font-weight:700; color:#929EB4; text-transform:uppercase; letter-spacing:.07em; }
.fdc-ts-val { font-size:.82rem; color:#001122; font-weight:600; }
.fdc-ts-tag {
  font-size:.6rem; font-weight:700; padding:3px 8px; border-radius:99px;
  background:color-mix(in srgb,var(--sc,#FFCC00) 13%,transparent); color:var(--sc,#FFCC00); white-space:nowrap;
}
.fdc-ts-row.warn { border-color:#FFCC00; background:#F8F9FA; }
.fdc-ts-row.warn .fdc-ts-tag { background:#F8F9FA; color:#F3554F; }

/* quote */
.fdc-quote {
  border-left:4px solid var(--sc,#66C5C5);
  background:color-mix(in srgb,var(--sc,#66C5C5) 5%,transparent);
  border-radius:0 10px 10px 0; padding:12px 15px; margin-top:14px;
  font-size:.8rem; color:#505050; line-height:1.6; font-style:italic;
}
.fdc-quote cite { display:block; font-style:normal; font-size:.68rem; font-weight:700; color:var(--sc,#66C5C5); margin-top:4px; }

/* cta */
.fdc-step-cta { margin-top:14px; display:flex; gap:9px; flex-wrap:wrap; }
.fdc-cta-btn {
  display:inline-flex; align-items:center; gap:6px; color:#F8F9FA;
  background:var(--sc,#FFCC00); padding:10px 18px; border-radius:99px;
  font-size:.76rem; font-weight:700; text-decoration:none;
  box-shadow:0 4px 14px color-mix(in srgb,var(--sc,#FFCC00) 32%,transparent);
  transition:transform .18s, box-shadow .18s;
}
.fdc-cta-btn:hover { transform:translateY(-2px); box-shadow:0 8px 22px color-mix(in srgb,var(--sc,#FFCC00) 44%,transparent); }
.fdc-cta-ghost {
  display:inline-flex; align-items:center; gap:6px; color:var(--sc,#FFCC00);
  border:1.5px solid color-mix(in srgb,var(--sc,#FFCC00) 30%,transparent);
  padding:9px 16px; border-radius:99px;
  font-size:.76rem; font-weight:700; text-decoration:none; transition:background .16s,border-color .16s;
}
.fdc-cta-ghost:hover { background:color-mix(in srgb,var(--sc,#FFCC00) 8%,transparent); border-color:var(--sc,#FFCC00); }

/* ── fdc section header (enhanced) ── */
.fdc-section-head {
  display:flex; align-items:center; gap:12px; margin:40px 0 16px;
}
.fdc-section-icon {
  width:34px; height:34px; border-radius:10px; flex-shrink:0;
  background:color-mix(in srgb,var(--ic,#66C5C5) 13%,transparent);
  display:flex; align-items:center; justify-content:center; font-size:1rem;
}
.fdc-section-text { flex:1; }
.fdc-section-title {
  font-size:.7rem; font-weight:800; letter-spacing:.12em; text-transform:uppercase;
  color:var(--ic,#66C5C5); margin:0 0 1px;
}
.fdc-section-desc { font-size:.75rem; color:#929EB4; margin:0; }
.fdc-section-line { flex:1; height:1.5px; background:linear-gradient(to right,#D0D6DF,transparent); border-radius:99px; }

/* ── discover cards ── */
.fdc-discover-wrap { margin-top:48px; }
.fdc-discover-intro {
  background:linear-gradient(135deg,#001122 0%,#001122 100%);
  border-radius:18px 18px 0 0; padding:24px 24px 20px;
  position:relative; overflow:hidden;
}
.fdc-discover-intro-bg {
  position:absolute; right:-20px; top:-20px;
  font-size:6rem; font-weight:900; letter-spacing:-.06em;
  color:rgba(248,249,250,.04); line-height:1; user-select:none;
}
.fdc-discover-eyebrow {
  font-size:.6rem; font-weight:800; letter-spacing:.14em; text-transform:uppercase;
  color:#66C5C5; margin-bottom:8px;
}
.fdc-discover-title { font-size:1.1rem; font-weight:800; color:#F8F9FA; margin:0 0 6px; }
.fdc-discover-sub { font-size:.8rem; color:rgba(248,249,250,.55); margin:0; line-height:1.55; }

.fdc-discover-grid {
  display:grid; grid-template-columns:1fr 1fr; gap:2px;
  background:#D0D6DF; border-radius:0 0 18px 18px; overflow:hidden;
}
@media(max-width:480px){ .fdc-discover-grid{ grid-template-columns:1fr; } }

.fdc-discover-card {
  background:#F8F9FA; padding:18px 18px 16px;
  display:flex; flex-direction:column; gap:8px;
  text-decoration:none; cursor:pointer;
  transition:background .18s;
  position:relative;
}
.fdc-discover-card:hover { background:#F8F9FA; }
.fdc-discover-card:last-child:nth-child(odd) { grid-column:span 2; }
@media(max-width:480px){ .fdc-discover-card:last-child:nth-child(odd){ grid-column:span 1; } }
.fdc-discover-card-ico {
  width:36px; height:36px; border-radius:10px; flex-shrink:0;
  background:color-mix(in srgb,var(--dc,#66C5C5) 12%,transparent);
  display:flex; align-items:center; justify-content:center; font-size:1rem;
}
.fdc-discover-card-title { font-size:.88rem; font-weight:800; color:#001122; }
.fdc-discover-card-desc { font-size:.74rem; color:#586782; line-height:1.5; flex:1; }
.fdc-discover-card-cta {
  display:inline-flex; align-items:center; gap:5px;
  font-size:.68rem; font-weight:700; color:var(--dc,#66C5C5);
  margin-top:2px;
}
.fdc-discover-card-arrow {
  display:flex; align-items:center; justify-content:center;
  width:24px; height:24px; border-radius:99px;
  background:color-mix(in srgb,var(--dc,#66C5C5) 12%,transparent);
  color:var(--dc,#66C5C5); transition:transform .18s, background .18s;
}
.fdc-discover-card:hover .fdc-discover-card-arrow { transform:translateX(3px); background:color-mix(in srgb,var(--dc,#66C5C5) 22%,transparent); }

/* ── fdc section blocks (V12 fix) ── */
.fdc-section-block {
  background:#F8F9FA;
  border-radius:20px;
  border:1.5px solid #F8F9FA;
  box-shadow:0 2px 16px rgba(0,17,34,.04);
  margin-bottom:20px;
  overflow:hidden;
}
.fdc-section-block-header {
  display:flex; align-items:center; gap:13px;
  padding:18px 22px 16px;
  border-bottom:1.5px solid #F8F9FA;
  background:color-mix(in srgb,var(--bic,#66C5C5) 4%,#F8F9FA);
}
.fdc-section-block-ico {
  width:38px; height:38px; border-radius:11px; flex-shrink:0;
  background:color-mix(in srgb,var(--bic,#66C5C5) 14%,transparent);
  display:flex; align-items:center; justify-content:center; font-size:1.1rem;
}
.fdc-section-block-title {
  font-size:.78rem; font-weight:800; letter-spacing:.08em; text-transform:uppercase;
  color:var(--bic,#66C5C5); margin:0 0 2px;
}
.fdc-section-block-desc { font-size:.78rem; color:#586782; margin:0; }
.fdc-section-block-body { padding:20px 22px 22px; }

/* step inside block — remove card box, use simpler styling */
.fdc-step-inline {
  padding:16px 0; border-bottom:1.5px solid #F8F9FA;
}
.fdc-step-inline:last-child { border-bottom:none; padding-bottom:0; }
.fdc-step-inline-head {
  display:flex; align-items:center; gap:12px; margin-bottom:12px;
}
.fdc-step-inline-n {
  width:36px; height:36px; border-radius:10px; flex-shrink:0;
  background:color-mix(in srgb,var(--sc,#66C5C5) 13%,transparent);
  display:flex; align-items:center; justify-content:center;
  font-size:.85rem; font-weight:900; color:var(--sc,#66C5C5);
  opacity:0; transform:scale(.5);
  transition:opacity .4s cubic-bezier(0.25, 1, 0.5, 1) .2s, transform .4s cubic-bezier(0.25, 1, 0.5, 1) .2s;
}
.fdb-vis .fdc-step-inline-n { opacity:1; transform:none; }
.fdc-step-inline-tag {
  font-size:.56rem; font-weight:800; letter-spacing:.1em; text-transform:uppercase;
  color:var(--sc,#66C5C5); background:color-mix(in srgb,var(--sc,#66C5C5) 10%,transparent);
  padding:2px 8px; border-radius:99px;
}
.fdc-step-inline-title { font-size:.95rem; font-weight:800; color:#001122; margin:0 0 2px; }
.fdc-step-inline-sub { font-size:.76rem; color:#586782; margin:0; line-height:1.5; }
.fdc-step-inline-bar {
  height:3px; background:var(--sc,#66C5C5); border-radius:99px;
  transform-origin:left; transform:scaleX(0);
  transition:transform .8s cubic-bezier(.22,1,.36,1) .3s;
  margin-bottom:14px;
}
.fdb-vis .fdc-step-inline-bar { transform:scaleX(1); }

/* ══════════════════════════════════════════════════════
   hmdk-* — Home Dark Version
   ══════════════════════════════════════════════════════ */
.hmdk-page { background:#001122; min-height:100vh; color:#F8F9FA; }

/* ── hero ── */
.hmdk-hero {
  position:relative; overflow:hidden;
  padding:52px 24px 48px; max-width:740px; margin:0 auto;
}
.hmdk-hero-glow {
  position:absolute; width:400px; height:400px; border-radius:50%;
  background:radial-gradient(circle, rgba(102,197,197,.18) 0%, transparent 70%);
  right:-100px; top:-80px; pointer-events:none;
}
.hmdk-hero-glow2 {
  position:absolute; width:300px; height:300px; border-radius:50%;
  background:radial-gradient(circle, rgba(146,158,180,.1) 0%, transparent 70%);
  left:-80px; bottom:-60px; pointer-events:none;
}
.hmdk-kicker {
  display:inline-flex; align-items:center; gap:8px; margin-bottom:14px;
  font-size:.63rem; font-weight:800; letter-spacing:.15em; text-transform:uppercase; color:#66C5C5;
}
.hmdk-kicker-dot { width:6px; height:6px; border-radius:50%; background:#66C5C5; animation:fdcPulse 2.2s ease-in-out infinite; }
.hmdk-h1 { font-size:clamp(2rem,6vw,3rem); font-weight:900; line-height:1.1; margin:0 0 14px; color:#F8F9FA; }
.hmdk-h1 em { font-style:normal; color:#66C5C5; }
.hmdk-sub { font-size:.9rem; color:rgba(248,249,250,.55); line-height:1.7; margin:0 0 28px; max-width:480px; }
.hmdk-cta-row { display:flex; gap:12px; flex-wrap:wrap; }
.hmdk-cta-primary {
  display:inline-flex; align-items:center; gap:8px;
  background:#66C5C5; color:#001122;
  padding:13px 22px; border-radius:99px;
  font-size:.84rem; font-weight:800; text-decoration:none;
  box-shadow:0 6px 24px rgba(102,197,197,.35);
  transition:transform .18s, box-shadow .18s;
}
.hmdk-cta-primary:hover { transform:translateY(-2px); box-shadow:0 10px 32px rgba(102,197,197,.45); }
.hmdk-cta-ghost {
  display:inline-flex; align-items:center; gap:8px;
  border:1.5px solid rgba(248,249,250,.2); color:rgba(248,249,250,.8);
  padding:12px 20px; border-radius:99px;
  font-size:.84rem; font-weight:700; text-decoration:none;
  transition:border-color .18s, background .18s;
}
.hmdk-cta-ghost:hover { border-color:rgba(248,249,250,.5); background:rgba(248,249,250,.06); }

/* stats strip */
.hmdk-stats {
  display:flex; gap:0; border-top:1px solid rgba(248,249,250,.08);
  border-bottom:1px solid rgba(248,249,250,.08);
  margin:0; padding:0;
  max-width:740px; margin:0 auto;
}
.hmdk-stat {
  flex:1; padding:18px 0; text-align:center;
  border-right:1px solid rgba(248,249,250,.08);
}
.hmdk-stat:last-child { border-right:none; }
.hmdk-stat-n { display:block; font-size:1.5rem; font-weight:900; color:#66C5C5; line-height:1; }
.hmdk-stat-l { display:block; font-size:.65rem; color:rgba(248,249,250,.4); font-weight:600; letter-spacing:.06em; margin-top:3px; }

/* ── scroll menu label ── */
.hmdk-menu-label {
  max-width:740px; margin:40px auto 0; padding:0 24px;
  font-size:.63rem; font-weight:800; letter-spacing:.14em; text-transform:uppercase;
  color:rgba(248,249,250,.35); display:flex; align-items:center; gap:10px;
}
.hmdk-menu-label::after { content:''; flex:1; height:1px; background:rgba(248,249,250,.08); }

/* ── horizontal scroll strip ── */
.hmdk-scroll-wrap {
  overflow-x:auto; padding:16px 24px 24px;
  scrollbar-width:none; -ms-overflow-style:none;
  /* push start/end to align with page content */
  scroll-padding-left:24px;
}
.hmdk-scroll-wrap::-webkit-scrollbar { display:none; }
.hmdk-scroll-track {
  display:flex; gap:13px;
  width:max-content; padding-right:24px;
}

.hmdk-card {
  width:220px; flex-shrink:0;
  background:rgba(248,249,250,.05);
  border:1.5px solid rgba(248,249,250,.09);
  border-radius:18px; padding:20px;
  text-decoration:none; display:flex; flex-direction:column; gap:10px;
  transition:background .2s, border-color .2s, transform .2s;
  cursor:pointer;
}
.hmdk-card:hover {
  background:rgba(248,249,250,.09);
  border-color:color-mix(in srgb,var(--cc,#66C5C5) 50%,transparent);
  transform:translateY(-3px);
}
.hmdk-card-top { display:flex; align-items:center; justify-content:space-between; }
.hmdk-card-num {
  font-size:.6rem; font-weight:800; letter-spacing:.1em;
  color:rgba(248,249,250,.25);
}
.hmdk-card-ico {
  width:36px; height:36px; border-radius:10px; flex-shrink:0;
  background:color-mix(in srgb,var(--cc,#66C5C5) 16%,transparent);
  display:flex; align-items:center; justify-content:center; font-size:1.1rem;
}
.hmdk-card-title { font-size:.92rem; font-weight:800; color:#F8F9FA; }
.hmdk-card-desc { font-size:.74rem; color:rgba(248,249,250,.45); line-height:1.5; flex:1; }
.hmdk-card-cta {
  display:inline-flex; align-items:center; gap:5px;
  font-size:.68rem; font-weight:700; color:var(--cc,#66C5C5);
  margin-top:auto;
}
.hmdk-card-arr {
  display:flex; align-items:center; justify-content:center;
  width:20px; height:20px; border-radius:50%;
  background:color-mix(in srgb,var(--cc,#66C5C5) 15%,transparent);
  transition:transform .18s;
}
.hmdk-card:hover .hmdk-card-arr { transform:translateX(3px); }
/* Day 1 highlight card */
.hmdk-card.hmdk-card-featured {
  background:linear-gradient(135deg, rgba(102,197,197,.18) 0%, rgba(102,197,197,.06) 100%);
  border-color:rgba(102,197,197,.35);
}

/* ── quick links dark ── */
.hmdk-quick {
  max-width:740px; margin:32px auto 0; padding:0 24px 60px;
}
.hmdk-quick-label {
  font-size:.63rem; font-weight:800; letter-spacing:.14em; text-transform:uppercase;
  color:rgba(248,249,250,.35); margin-bottom:12px; display:flex; align-items:center; gap:10px;
}
.hmdk-quick-label::after { content:''; flex:1; height:1px; background:rgba(248,249,250,.08); }
.hmdk-quick-grid { display:grid; grid-template-columns:1fr 1fr; gap:8px; }
@media(max-width:480px){ .hmdk-quick-grid{ grid-template-columns:1fr; } }
.hmdk-quick-row {
  display:flex; align-items:center; gap:10px;
  background:rgba(248,249,250,.04); border:1px solid rgba(248,249,250,.08);
  border-radius:12px; padding:12px 14px; text-decoration:none;
  transition:background .16s, border-color .16s;
}
.hmdk-quick-row:hover { background:rgba(248,249,250,.08); border-color:rgba(248,249,250,.18); }
.hmdk-quick-ico { font-size:1rem; flex-shrink:0; }
.hmdk-quick-lbl { font-size:.8rem; font-weight:600; color:rgba(248,249,250,.75); flex:1; }
.hmdk-quick-arr { font-size:.7rem; color:rgba(248,249,250,.3); }

/* ─────────────── WIFI V3 (wf2-*) ─────────────── */
.wf2-tabs {
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
}
.wf2-tab {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 20px;
  border-radius: var(--radius);
  border: 2px solid var(--line);
  background: var(--bg);
  cursor: pointer;
  transition: all .2s;
  text-align: left;
}
.wf2-tab.is-active {
  border-color: var(--cyan);
  background: rgba(102,197,197,0.06);
}
.wf2-tab:hover:not(.is-active) { background: var(--surface); }
.wf2-tab-dot {
  width: 12px; height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}
.wf2-dot-staff { background: var(--cyan); box-shadow: 0 0 0 4px rgba(102,197,197,0.18); }
.wf2-dot-guest { background: #FFCC00; box-shadow: 0 0 0 4px rgba(255,204,0,0.18); }
.wf2-tab-label { display: flex; flex-direction: column; gap: 1px; }
.wf2-tab-title { font-size: 14px; font-weight: 700; color: var(--ink); }
.wf2-tab-sub { font-size: 11px; color: var(--muted); font-weight: 500; }
.wf2-tab.is-active .wf2-tab-title { color: var(--cyan); }

/* Panels */
.wf2-panel {
  border-radius: var(--radius);
  border: 1px solid var(--line);
  overflow: hidden;
  margin-bottom: 32px;
}
.wf2-panel[hidden] { display: none; }
.wf2-panel-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 24px;
  background: var(--cyan);
  color: #F8F9FA;
}
.wf2-panel-guest .wf2-panel-header { background: #FFCC00; }
.wf2-panel-hbadge {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .1em;
  background: rgba(248,249,250,0.2);
  padding: 3px 10px;
  border-radius: 100px;
  white-space: nowrap;
}
.wf2-panel-hdesc { font-size: 13px; opacity: .9; }

.wf2-panel-body {
  display: grid;
  grid-template-columns: 180px 1fr;
  gap: 32px;
  padding: 28px 28px 24px;
  align-items: start;
}
.wf2-qr-col { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.wf2-qr-frame {
  width: 160px; height: 160px;
  border-radius: 14px;
  border: 2px solid var(--line);
  background: #F8F9FA;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
  padding: 8px;
}
.wf2-qr { width: 100%; height: 100%; }
.wf2-qr svg { width: 100%; height: auto; }
.wf2-qr-cap { font-size: 11.5px; color: var(--muted); text-align: center; line-height: 1.4; }

.wf2-info-col { display: flex; flex-direction: column; gap: 16px; }
.wf2-cred-row { display: flex; flex-direction: column; gap: 6px; }
.wf2-cred-label { font-size: 11px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.wf2-cred-val {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 9px 12px;
}
.wf2-cred-val code {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
  flex: 1;
  background: none;
  border: none;
  padding: 0;
}
.wf2-copy {
  width: 28px; height: 28px;
  border-radius: 7px;
  border: 1px solid var(--line);
  background: var(--bg);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  color: var(--muted);
  flex-shrink: 0;
  transition: all .15s;
}
.wf2-copy:hover { background: var(--ink); color: #F8F9FA; border-color: var(--ink); }
.wf2-copy.is-copied { background: #66C5C5; color: #F8F9FA; border-color: #66C5C5; }
.wf2-connect-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 20px;
  border-radius: var(--radius-sm);
  background: var(--cyan);
  color: #F8F9FA;
  font-size: 13px;
  font-weight: 700;
  border: none;
  cursor: pointer;
  transition: opacity .15s;
  align-self: flex-start;
  margin-top: 4px;
}
.wf2-connect-btn:hover { opacity: .85; }
.wf2-connect-guest { background: #FFCC00; }

/* How to Connect */
.wf2-how { margin-top: 8px; }
.wf2-how-title {
  font-size: 1rem;
  font-weight: 800;
  color: var(--ink);
  margin: 0 0 20px;
  display: flex;
  align-items: center;
  gap: 10px;
  letter-spacing: -0.01em;
}
.wf2-steps { display: flex; flex-direction: column; gap: 0; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.wf2-step {
  display: grid;
  grid-template-columns: 48px 1fr;
  align-items: center;
  border-bottom: 1px solid var(--line);
  background: var(--bg);
  transition: background .15s;
}
.wf2-step:last-child { border-bottom: none; }
.wf2-step:hover { background: var(--surface); }
.wf2-step-num {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  align-self: stretch;
  font-size: 13px;
  font-weight: 900;
  color: var(--cyan);
  background: rgba(102,197,197,0.07);
  border-right: 1px solid var(--line);
  letter-spacing: -0.03em;
  font-family: var(--display);
}
.wf2-step-content {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
}
.wf2-step-icon {
  width: 40px; height: 40px;
  border-radius: 10px;
