/* ─────────────── FIRST DAY V12+ — Section Division & Icon Bullets ─────────────── */
.fdc-section-header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 0 24px;
}
.fdc-section-badge {
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--muted);
  background: var(--surface);
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 100px;
  white-space: nowrap;
}
.fdc-section-title {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: -0.01em;
}

.fdc-section-sep {
  margin: 40px 0 36px;
  position: relative;
}
.fdc-section-sep-line {
  height: 1px;
