  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 12px;
}

/* Discover eyebrow with SVG */
.fdc-discover-eyebrow {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
