/* ─────────────── WIFI V4 (wn-*) ─────────────── */
.wn-selector {
  display: flex;
  gap: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 20px;
}
.wn-sel-btn {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  background: var(--surface);
  border: none;
  cursor: pointer;
  transition: background .15s;
  border-right: 1px solid var(--line);
  text-align: left;
}
.wn-sel-btn:last-child { border-right: none; }
.wn-sel-btn.wn-sel-active { background: var(--bg); }
.wn-sel-btn:hover:not(.wn-sel-active) { background: var(--surface-2, var(--surface)); }
.wn-sel-pip {
  position: relative;
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--cyan);
  flex-shrink: 0;
  box-shadow: 0 0 0 3px rgba(102,197,197,.2);
}
.wn-pip-guest { background: #929EB4; box-shadow: 0 0 0 3px rgba(146,158,180,.2); }
.wn-sel-active .wn-sel-pip::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 2px solid rgba(102,197,197,.5);
  animation: pipPulse 2s ease-out infinite;
  pointer-events: none;
}
@keyframes pipPulse { 0% { transform: scale(1); opacity: .6; } 100% { transform: scale(1.7); opacity: 0; } }
.wn-sel-info { display: flex; flex-direction: column; gap: 1px; }
.wn-sel-title { font-size: 13.5px; font-weight: 700; color: var(--ink); }
.wn-sel-ssid { font-size: 11px; color: var(--muted); font-family: monospace; }
.wn-sel-active .wn-sel-title { color: var(--cyan); }

/* Panel */
.wn-panel {
  background: #001122;
  border-radius: var(--radius);
  border: 1px solid rgba(102,197,197,.18);
  overflow: hidden;
  margin-bottom: 28px;
}
.wn-panel[hidden] { display: none; }
.wn-panel-guest { border-color: rgba(146,158,180,.2); }
.wn-main {
  display: grid;
  grid-template-columns: 200px 1fr;
  min-height: 220px;
}
.wn-qr-side {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 24px;
  background: rgba(248,249,250,.03);
  border-right: 1px solid rgba(248,249,250,.08);
}
.wn-qr-box {
  width: 148px; height: 148px;
  background: #F8F9FA;
  border-radius: 10px;
  padding: 8px;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
  box-shadow: 0 0 0 2px rgba(102,197,197,.3);
}
.wn-qr-box-guest { box-shadow: 0 0 0 2px rgba(146,158,180,.3); }
.wn-qr { width: 100%; height: 100%; }
.wn-qr svg { width: 100%; height: auto; }
.wn-qr-tip { font-size: 11px; color: rgba(248,249,250,.55); text-align: center; line-height: 1.4; }

.wn-info-side {
  padding: 28px 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  justify-content: center;
}
.wn-network-badge {
  display: inline-flex;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: #001122;
  background: var(--cyan);
  padding: 3px 10px;
  border-radius: 4px;
  align-self: flex-start;
}
.wn-badge-guest { background: #929EB4; }
.wn-cred { display: flex; flex-direction: column; gap: 10px; }
.wn-cred-row { display: flex; flex-direction: column; gap: 5px; }
.wn-cred-k { font-size: 10.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: rgba(248,249,250,.55); }
.wn-cred-v {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(248,249,250,.06);
  border: 1px solid rgba(248,249,250,.1);
  border-radius: 8px;
  padding: 8px 12px;
}
.wn-cred-v code {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 15px;
  font-weight: 600;
  color: #F8F9FA;
  background: none;
  border: none;
  padding: 0;
  flex: 1;
  letter-spacing: .03em;
}
.wn-copy {
  width: 26px; height: 26px;
  border-radius: 6px;
  border: 1px solid rgba(248,249,250,.15);
  background: transparent;
  color: rgba(248,249,250,.5);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: all .15s;
}
.wn-copy:hover { background: var(--cyan); color: #001122; border-color: var(--cyan); }
.wn-copy.is-copied { background: #66C5C5; color: #F8F9FA; border-color: #66C5C5; }
.wn-connect-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: var(--cyan);
  color: #001122;
  font-size: 13px;
  font-weight: 800;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: opacity .15s;
  align-self: flex-start;
}
.wn-connect-btn:hover { opacity: .88; }
.wn-connect-guest { background: #929EB4; color: #F8F9FA; }
.wn-note { font-size: 11.5px; color: rgba(248,249,250,.5); margin: 0; line-height: 1.5; }

/* How to steps */
.wn-how { margin-top: 4px; }
.wn-how-label {
  font-size: 13px;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: .03em;
  margin-bottom: 12px;
  text-transform: uppercase;
  font-size: 10.5px;
  letter-spacing: .1em;
  color: var(--muted);
}
.wn-how-steps {
  display: flex;
  align-items: stretch;
  gap: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.wn-how-step {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  padding: 16px 18px;
  background: var(--bg);
  border-right: 1px solid var(--line);
}
.wn-how-step:last-child { border-right: none; }
.wn-how-n {
  font-family: var(--display);
  font-size: 1.6rem;
  font-weight: 900;
  color: var(--cyan);
  line-height: 1;
  letter-spacing: -0.04em;
  opacity: .35;
}
.wn-how-title { font-size: 13.5px; font-weight: 700; color: var(--ink); }
.wn-how-desc { font-size: 12.5px; color: var(--muted); line-height: 1.5; }
.wn-how-sep {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  flex-shrink: 0;
  font-size: 10px;
  font-weight: 800;
  color: var(--muted);
  letter-spacing: .08em;
  text-transform: uppercase;
  background: var(--surface);
  border-right: 1px solid var(--line);
  writing-mode: vertical-lr;
}

@media (max-width: 680px) {
  .wn-selector { flex-direction: column; }
  .wn-sel-btn { border-right: none; border-bottom: 1px solid var(--line); }
  .wn-sel-btn:last-child { border-bottom: none; }
  .wn-main { grid-template-columns: 1fr; }
  .wn-qr-side { border-right: none; border-bottom: 1px solid rgba(248,249,250,.08); flex-direction: row; justify-content: flex-start; }
  .wn-qr-box { width: 100px; height: 100px; flex-shrink: 0; }
  .wn-how-steps { flex-direction: column; }
  .wn-how-step { border-right: none; border-bottom: 1px solid var(--line); }
  .wn-how-step:last-child { border-bottom: none; }
  .wn-how-sep { width: 100%; height: 32px; writing-mode: horizontal-tb; }
}

/* ── Wi-Fi How-To V2 ─────────────────────────────────────────── */
.wn-how-v2 {
  margin-top: 36px;
  padding: 28px 28px 24px;
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(102,197,197,.08) 0%, rgba(0,64,128,.07) 100%);
