.phb-title {
  font-size: 32px;
  line-height: 1.2;
  margin-bottom: 8px;
}
.phb-title::after {
  margin-top: 8px;
}
.phb-lead {
  font-size: 14px;
  line-height: 1.6;
}
.section {
  padding: 56px 0;
}

/* Day 1 page: clearer sections */
.fdc-page {
  background: #F8F9FA;
}
.fdc-hero {
  min-height: 300px;
  background: linear-gradient(135deg, #001122 0%, #004081 58%, #586782 100%);
}
.fdc-hero::after {
  background: linear-gradient(90deg, transparent 0%, rgba(248,249,250,.08) 100%);
}
.fdc-hero-h1 {
  font-size: 54px;
  line-height: 1.12;
  letter-spacing: 0;
}
.fdc-hero-sub {
  font-size: 17px;
  max-width: 560px;
}
.fdc-hero-right {
  width: 260px;
  padding-left: 24px;
}
.fdc-day-card {
  width: 220px;
  min-height: 220px;
  border-radius: 22px;
  padding: 24px;
  background: rgba(248,249,250,.12);
  border: 1px solid rgba(248,249,250,.22);
  color: #F8F9FA;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 28px 70px rgba(0,17,34,.22);
}
.fdc-day-card-kicker {
  font-size: 13px;
  font-weight: 900;
  text-transform: uppercase;
  color: #D0D6DF;
}
.fdc-day-card strong {
  font-size: 38px;
  line-height: 1.05;
  color: #F8F9FA;
}
.fdc-day-card-list {
  display: grid;
  gap: 8px;
}
.fdc-day-card-list span {
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(248,249,250,.1);
  font-size: 13px;
  font-weight: 700;
}
.fdc-body {
  max-width: 980px;
  padding: 0 20px;
}
.fdc-band {
  margin: 28px 0;
  padding: 30px;
  border-radius: 24px;
  border: 1px solid rgba(0,64,129,.08);
}
.fdc-band-tasks {
  background: #F8F9FA;
  box-shadow: 0 18px 45px rgba(0,17,34,.08);
}
.fdc-band-timeline {
  background: #F8F9FA;
}
.fdc-band-more {
  background: #F8F9FA;
}
.fdc-section-header {
  align-items: flex-start;
  margin-bottom: 24px;
}
.fdc-section-title {
  font-size: 28px;
  line-height: 1.25;
  color: #001122;
  text-transform: none;
  letter-spacing: 0;
}
.fdc-section-copy {
  margin: 6px 0 0;
  color: #586782;
  font-size: 15px;
  line-height: 1.6;
}
.fdc-section-badge {
  margin-top: 4px;
  color: #004081;
  background: #F8F9FA;
  border-color: #D0D6DF;
}
.fdc-tgrid {
  gap: 18px;
}
.fdc-tc {
  border-radius: 16px;
  border-color: #D0D6DF;
}
.fdc-tc-inner {
  padding: 22px;
}
.fdc-tc-name {
  font-size: 21px;
  line-height: 1.25;
}
.fdc-tc-desc {
  font-size: 14px;
  line-height: 1.65;
}
.fdc-tc .fdc-steps-flow {
  margin: 18px 0 16px;
  background: #F8F9FA;
  border: 1px solid #D0D6DF;
  border-radius: 14px;
  padding: 14px;
  gap: 8px;
}
.fdc-tc .fdc-sf-step {
  min-width: 112px;
  background: #F8F9FA;
  border: 1px solid #F8F9FA;
  border-radius: 12px;
  padding: 10px 8px;
}
.fdc-tc .fdc-sf-text {
  color: #505050;
  font-size: 12px;
  max-width: 120px;
}
.fdc-tc .fdc-sf-arrow {
  color: #929EB4;
}
.fdc-step-title {
  font-size: 24px;
  line-height: 1.2;
}
.fdc-step-sub {
  font-size: 14px;
}
.fdc-bullet-text,
.fdc-quote,
.fdc-ts-val {
  font-size: 14px;
}

/* Wi-Fi: light, high-contrast panel with visible QR */
.wn-selector {
  border-radius: 12px;
  background: #F8F9FA;
  padding: 6px;
  border-color: #D0D6DF;
}
.wn-sel-btn {
  border: 0;
  border-radius: 8px;
  background: transparent;
}
.wn-sel-btn.wn-sel-active,
.wn-sel-btn.is-active {
  background: #F8F9FA;
  box-shadow: 0 8px 22px rgba(0,64,129,.08);
}
.wn-sel-btn.wn-sel-active .wn-sel-title,
.wn-sel-btn.is-active .wn-sel-title {
  color: #004081;
}
.wn-panel {
  background: #F8F9FA;
  border-color: #D0D6DF;
  border-radius: 16px;
  box-shadow: 0 18px 45px rgba(0,17,34,.08);
}
.wn-panel-guest {
  border-color: #D0D6DF;
}
.wn-main {
  grid-template-columns: 260px 1fr;
}
.wn-qr-side {
  background: #F8F9FA;
  border-right: 1px solid #D0D6DF;
}
.wn-panel-guest .wn-qr-side {
  background: #F8F9FA;
}
.wn-qr-box {
  width: 176px;
  height: 176px;
  border-radius: 16px;
  box-shadow: 0 0 0 1px #D0D6DF, 0 16px 32px rgba(0,17,34,.10);
}
.wn-qr svg {
  width: 100%;
  height: 100%;
  display: block;
}
.wn-qr-tip,
.wn-note {
  color: #586782;
}
.wn-info-side {
  gap: 18px;
}
.wn-network-badge {
  color: #004081;
  background: #F8F9FA;
}
.wn-badge-guest {
  color: #505050;
  background: #F8F9FA;
}
.wn-cred-k {
  color: #707070;
}
.wn-cred-v {
  background: #F8F9FA;
  border-color: #D0D6DF;
}
.wn-cred-v code {
  color: #001122;
}
.wn-copy {
  color: #586782;
  border-color: #D0D6DF;
  background: #F8F9FA;
}
.wn-copy:hover {
  background: #004081;
  color: #F8F9FA;
  border-color: #004081;
}
.wn-connect-btn {
  background: #004081;
  color: #F8F9FA;
}
.wn-connect-guest {
  background: #F3554F;
  color: #F8F9FA;
}
.wn-how-steps {
  border-radius: 14px;
}

/* Showcase: cleaner article cards */
.showcase-real-grid {
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
}
.show-real-card {
  min-height: 100%;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0,17,34,.06);
}
.show-real-card-facebook,
.show-real-card-medium {
  display: grid;
  grid-template-rows: auto 1fr;
}
.show-real-media-link {
  border-bottom: 0;
}
.slc-header {
  min-height: 150px;
  padding: 24px;
}
.slc-header-facebook {
  background: linear-gradient(135deg, #004081 0%, #586782 100%);
}
.slc-header-medium {
  background: linear-gradient(135deg, #001122 0%, #586782 100%);
}
.slc-headline {
  font-size: 19px;
  line-height: 1.35;
  -webkit-line-clamp: 3;
}
.slc-preview-strip {
  padding: 16px 24px;
  background: #F8F9FA;
}
.slc-preview-strip p {
  font-size: 14px;
  -webkit-line-clamp: 4;
}
.show-real-body {
  padding: 20px 24px 22px;
  display: flex;
  flex-direction: column;
}
.show-real-card h4 {
  font-size: 20px;
  line-height: 1.35;
}
.show-real-summary {
  font-size: 14px;
  line-height: 1.65;
}
.show-real-actions {
  margin-top: auto;
  padding-top: 18px;
}
.show-real-link {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 8px;
  background: #004081;
  color: #F8F9FA;
}
.show-real-link:hover {
  color: #F8F9FA;
  background: #004081;
}

@media (max-width: 780px) {
  .page-header {
    padding: 28px 0 20px;
  }
  .page-header h1,
  .phb-title {
    font-size: 28px;
  }
  .fdc-hero {
    grid-template-columns: 1fr;
    padding-top: calc(var(--nav-h) + 24px);
  }
  .fdc-hero-right {
    display: none;
  }
  .fdc-hero-h1 {
    font-size: 42px;
  }
  .fdc-band {
    padding: 22px 16px;
    border-radius: 18px;
  }
  .fdc-tgrid,
  .fdc-2col {
    grid-template-columns: 1fr;
  }
  .wn-main {
    grid-template-columns: 1fr;
  }
  .wn-qr-side {
    border-right: 0;
    border-bottom: 1px solid #D0D6DF;
  }
  .wn-how-steps {
    flex-direction: column;
  }
  .wn-how-step {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }
  .wn-how-sep {
    width: 100%;
    height: 32px;
    writing-mode: horizontal-tb;
  }
}

/* ════════════════════════════════════════════════════════════
   DAY 1 HERO V2 — editorial layout
   ════════════════════════════════════════════════════════════ */
.fdc-hero2 {
  position: relative;
  overflow: hidden;
  background: #001122;
  padding: calc(var(--nav-h) + 32px) 0 0;
  isolation: isolate;
}
.fdc-hero2::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(-50deg,
      rgba(102,197,197,.015) 0px, rgba(102,197,197,.015) 1px,
      transparent 1px, transparent 40px);
  pointer-events: none;
}
.fdc-hero2::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(102,197,197,.3), transparent);
}
/* giant background text */
.fdc-hero2-bg-text {
  position: absolute;
  right: -2%; top: 50%;
  transform: translateY(-54%);
  font-family: var(--display);
  font-size: clamp(8rem, 22vw, 18rem);
  font-weight: 900;
  line-height: .88;
  letter-spacing: -.06em;
  color: transparent;
  -webkit-text-stroke: 1.5px rgba(102,197,197,.09);
  text-stroke: 1.5px rgba(102,197,197,.09);
  pointer-events: none;
  user-select: none;
  white-space: nowrap;
}
.fdc-hero2-inner {
  position: relative;
  z-index: 2;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 clamp(20px, 5vw, 64px) 44px;
}
.fdc-hero2-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: rgba(102,197,197,.7);
  margin-bottom: 28px;
}
.fdc-hero2-pip {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #66C5C5;
  box-shadow: 0 0 8px rgba(102,197,197,.8);
  animation: heroPip 2.4s ease-in-out infinite;
  flex-shrink: 0;
}
.fdc-hero2-grid {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 40px;
  align-items: end;
}
.fdc-hero2-title-col {
  position: relative;
}
.fdc-hero2-num {
  font-family: var(--display);
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 900;
  color: transparent;
  -webkit-text-stroke: 1.5px rgba(102,197,197,.35);
  text-stroke: 1.5px rgba(102,197,197,.35);
  line-height: 1;
  letter-spacing: -.05em;
  margin-bottom: 8px;
}
.fdc-hero2-h1 {
  font-family: var(--display);
  font-size: clamp(2.4rem, 6vw, 4.2rem);
  font-weight: 900;
  color: #F8F9FA;
  line-height: 1.08;
  letter-spacing: -.03em;
  margin: 0 0 16px;
}
.fdc-hero2-h1 em { font-style: normal; color: #66C5C5; }
.fdc-hero2-sub {
  font-size: 15px;
  color: rgba(248,249,250,.45);
  line-height: 1.7;
  max-width: 460px;
}
/* agenda card */
.fdc-hero2-agenda {
  background: rgba(248,249,250,.04);
  border: 1px solid rgba(102,197,197,.18);
  border-radius: 16px;
  padding: 20px;
  backdrop-filter: blur(10px);
}
.fdc-hero2-agenda-head {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: rgba(102,197,197,.7);
  margin-bottom: 14px;
}
.fdc-hero2-agenda-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(248,249,250,.06);
}
.fdc-hero2-agenda-item:last-of-type { border-bottom: none; }
.fdc-hero2-agenda-n {
  width: 22px; height: 22px;
  border-radius: 50%;
  background: rgba(102,197,197,.15);
  border: 1px solid rgba(102,197,197,.3);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px;
  font-weight: 800;
  color: #66C5C5;
  flex-shrink: 0;
}
.fdc-hero2-agenda-title {
  font-size: 13px;
  font-weight: 700;
  color: rgba(248,249,250,.88);
  margin-bottom: 2px;
}
.fdc-hero2-agenda-sub {
  font-size: 11.5px;
  color: rgba(248,249,250,.4);
  line-height: 1.4;
}
.fdc-hero2-agenda-foot {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: rgba(102,197,197,.5);
  padding-top: 12px;
}
@media (max-width: 680px) {
  .fdc-hero2-grid { grid-template-columns: 1fr; }
  .fdc-hero2-agenda { display: none; }
  .fdc-hero2-bg-text { font-size: 30vw; opacity: .5; }
}

/* ── art-cover label ─────────────────────────────────────── */
.hmv3-art-cover-label {
  position: absolute;
  top: 14px; left: 16px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: rgba(248,249,250,.55);
}
/* override the old cover sizing */
.hmv3-art-cover-exp,
.hmv3-art-cover-blog {
  min-height: 110px;
}

/* ── art-card tag color variants ─────────────────────────── */
.hmv3-art-tag-exp  { color: #66C5C5; background: rgba(102,197,197,.12); border-color: rgba(102,197,197,.25); }
.hmv3-art-tag-blog { color: #66C5C5; background: rgba(102,197,197,.12); border-color: rgba(102,197,197,.25); }

/* ── fdc-tc HR note ──────────────────────────────────────── */
.fdc-tc-hr-note {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 12px;
  font-size: 12px;
  color: #586782;
  background: #F8F9FA;
  border: 1px solid #D0D6DF;
  border-radius: 8px;
  padding: 7px 12px;
}
.fdc-tc-hr-note svg { color: #66C5C5; flex-shrink: 0; }

/* ── page-hero-band spacing — proportionate per section ─── */
.page-hero-band[data-section="getting-started"] { padding-top: calc(var(--nav-h) + 24px); padding-bottom: 28px; }
.page-hero-band[data-section="policy"]           { padding-top: calc(var(--nav-h) + 24px); padding-bottom: 28px; }
.page-hero-band[data-section="resources"]        { padding-top: calc(var(--nav-h) + 24px); padding-bottom: 28px; }
.page-hero-band[data-section="company"]          { padding-top: calc(var(--nav-h) + 24px); padding-bottom: 28px; }

/* ── section bg dividers (resources, first-day body) ────── */
.ts-steps-visual {
  background: #F8F9FA;
  border-radius: 16px;
  padding: 28px 20px;
}
.hmv3-bento-wrap {
  background: #F8F9FA;
}
.hmv3-ql-wrap {
  background: #F8F9FA;
  border-top: 1px solid var(--line);
}

/* ── showcase card sizing fix ───────────────────────────── */
.show-real-grid {
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
}
.show-real-card {
  display: flex;
  flex-direction: column;
}
.show-real-card-facebook,
.show-real-card-medium {
  grid-template-rows: unset;
  display: flex;
  flex-direction: column;
}
.slc-header {
  min-height: 130px;
  flex-shrink: 0;
}
.slc-headline {
  font-size: 16px;
}
.show-real-body {
  flex: 1;
  display: flex;
  flex-direction: column;
}
.show-real-card h4 {
  font-size: 16px;
}


/* ════════════════════════════════════════════════════════════
   DAY 1 — fd3-* full redesign
   ════════════════════════════════════════════════════════════ */
.fd3-page { background: #F8F9FA; min-height: 100vh; }

/* ── HERO ── */
.fd3-hero {
  position: relative;
  background: #001122;
  overflow: hidden;
  isolation: isolate;
}
.fd3-hero-grid-bg {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(102,197,197,.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(102,197,197,.05) 1px, transparent 1px);
  background-size: 48px 48px;
  pointer-events: none;
}
.fd3-hero-glow {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 60% 80% at 85% 40%, rgba(102,197,197,.12) 0%, transparent 65%);
  pointer-events: none;
}
.fd3-hero-main {
  position: relative; z-index: 2;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 32px;
  padding: calc(var(--nav-h) + 36px) clamp(24px,6vw,80px) 44px;
  max-width: 1400px;
  margin: 0 auto;
}
.fd3-hero-eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 11px; font-weight: 800; letter-spacing: .14em;
  text-transform: uppercase; color: rgba(102,197,197,.75);
  margin-bottom: 20px;
}
.fd3-hero-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: #66C5C5; box-shadow: 0 0 8px rgba(102,197,197,.9);
  animation: fd3Pulse 2.4s ease-in-out infinite; flex-shrink: 0;
}
@keyframes fd3Pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.4;transform:scale(1.7)} }
.fd3-hero-h1 {
  display: flex; flex-direction: column; gap: 4px;
  font-family: var(--display); font-weight: 900;
  line-height: 1.05; letter-spacing: -.03em;
  margin: 0 0 18px;
}
.fd3-hero-h1-line1 {
  font-size: clamp(2rem, 4.5vw, 3.8rem);
  color: rgba(248,249,250,.55);
  font-weight: 700;
}
.fd3-hero-h1-line2 {
  font-size: clamp(2.8rem, 6.5vw, 5.2rem);
  color: #F8F9FA;
}
.fd3-hero-h1-line2 em { font-style: normal; color: #66C5C5; }
.fd3-hero-sub {
  font-size: 15px; color: rgba(248,249,250,.42);
  line-height: 1.7; max-width: 420px;
}
/* right: big number */
.fd3-hero-right {
  display: flex; flex-direction: column; align-items: center;
  gap: 0; padding-right: clamp(0px,2vw,24px);
}
.fd3-hero-tag {
  font-size: 10px; font-weight: 900; letter-spacing: .28em;
  text-transform: uppercase; color: rgba(102,197,197,.5);
  margin-bottom: -8px;
}
.fd3-hero-bignum {
  font-family: var(--display);
  font-size: clamp(6rem, 14vw, 12rem);
  font-weight: 900; line-height: 1; letter-spacing: -.07em;
  color: transparent;
  -webkit-text-stroke: 2px rgba(102,197,197,.22);
  text-stroke: 2px rgba(102,197,197,.22);
  user-select: none;
}
/* bottom anchor strip */
.fd3-hero-strip {
  position: relative; z-index: 2;
  display: flex; align-items: stretch;
  border-top: 1px solid rgba(248,249,250,.07);
  background: rgba(248,249,250,.03);
}
.fd3-strip-item {
  flex: 1; display: flex; align-items: center; gap: 14px;
  padding: 18px clamp(16px,3vw,36px);
  text-decoration: none; color: rgba(248,249,250,.55);
  transition: background .18s, color .15s;
  cursor: pointer;
}
.fd3-strip-item:hover { background: rgba(248,249,250,.05); color: rgba(248,249,250,.9); }
.fd3-strip-active { color: rgba(248,249,250,.85); }
.fd3-strip-n {
  font-family: var(--display); font-size: 1rem; font-weight: 900;
  color: #66C5C5; opacity: .7;
}
.fd3-strip-label { font-size: 13px; font-weight: 700; }
.fd3-strip-hint { font-size: 11px; color: rgba(248,249,250,.3); margin-left: auto; }
.fd3-strip-div { width: 1px; background: rgba(248,249,250,.07); flex-shrink: 0; }

@media (max-width: 640px) {
  .fd3-hero-main { grid-template-columns: 1fr; }
  .fd3-hero-right { display: none; }
  .fd3-strip-hint { display: none; }
}

/* ── SHARED SECTION SHELL ── */
.fd3-section {
  width: 100%;
  padding: 72px clamp(20px,5vw,64px) 80px;
}
/* Tighter top for sections following another section */
.fd3-sec-timeline {
  padding-top: 80px;
}
.fd3-sec-tasks {
  padding-top: 64px;
}
.fd3-sec-head {
  max-width: 1400px; margin: 0 auto 52px;
}
.fd3-sec-tag {
  display: inline-block;
  font-size: 10px; font-weight: 800; letter-spacing: .16em;
  text-transform: uppercase; color: #004081;
  background: #F8F9FA; border: 1px solid #D0D6DF;
  border-radius: 100px; padding: 4px 12px;
  margin-bottom: 12px;
}
.fd3-sec-tag-alt { color: #004081; background: rgba(0,64,129,0.07); border-color: rgba(0,64,129,0.16); }
.fd3-sec-tag-light { color: rgba(248,249,250,.6); background: rgba(248,249,250,.08); border-color: rgba(248,249,250,.15); }
.fd3-sec-title {
  font-family: var(--display);
  font-size: clamp(1.6rem, 3.5vw, 2.6rem);
  font-weight: 900; color: var(--ink);
  letter-spacing: -.02em; margin: 0 0 12px;
  text-wrap: balance;
}
.fd3-sec-sub { font-size: 15px; color: var(--muted); line-height: 1.7; max-width: 560px; margin: 0; text-wrap: pretty; }

/* ── SECTION 1: TASKS ── */
.fd3-sec-tasks { background: #F8F9FA; }
.fd3-task-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 1400px; margin: 0 auto;
}
.fd3-task-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 20px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 2px 8px rgba(0,64,129,0.05), 0 1px 2px rgba(0,17,34,0.03);
  transition: box-shadow .22s ease, transform .22s ease;
}
.fd3-task-card:hover {
  box-shadow: 0 8px 28px rgba(0,64,129,0.10), 0 2px 6px rgba(0,17,34,0.04);
  transform: translateY(-2px);
}
.fd3-task-body { padding: 28px; display: flex; flex-direction: column; gap: 16px; flex: 1; }
.fd3-task-header { display: flex; align-items: flex-start; gap: 14px; }
.fd3-task-ico {
  width: 44px; height: 44px; border-radius: 12px;
  background: rgba(102,197,197,0.08);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.fd3-task-num { font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; margin-bottom: 2px; }
.fd3-task-name { font-size: 18px; font-weight: 800; color: #001122; line-height: 1.2; }
.fd3-task-urgency {
  margin-left: auto; flex-shrink: 0;
  font-size: 10.5px; font-weight: 800; letter-spacing: .06em;
  border-radius: 100px; padding: 5px 11px;
}
.fd3-urg-now { background: #F8F9FA; color: #004081; border: 1px solid #D0D6DF; }
.fd3-urg-eod { background: #F8F9FA; color: #505050; border: 1px solid #D0D6DF; }
.fd3-task-desc { font-size: 14px; color: #586782; line-height: 1.65; margin: 0; }

/* ── flow (horizontal steps) ── */
.fd3-flow {
  display: flex;
  align-items: center;
  gap: 0;
  background: var(--surface-2);
  border-radius: 14px;
  padding: 16px 14px;
  overflow-x: auto;
}
.fd3-flow-step {
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  flex: 1; min-width: 80px; text-align: center;
  padding: 4px 6px;
}
.fd3-flow-icon {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: rgba(0,64,129,0.06);
  display: flex; align-items: center; justify-content: center;
  font-size: 22px; line-height: 1;
  color: #505050;
  flex-shrink: 0;
}
.fd3-flow-text {
  font-size: 11.5px; font-weight: 600; color: #505050;
  line-height: 1.4;
}
.fd3-flow-arrow { flex-shrink: 0; color: #929EB4; margin: 0 2px; }

.fd3-task-note {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 12.5px; color: #586782;
  background: var(--surface);
  border-radius: 8px; padding: 8px 13px;
}
.fd3-task-note svg { color: #66C5C5; flex-shrink: 0; }
.fd3-task-link {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; font-weight: 700; color: #004081;
  text-decoration: none; margin-top: auto;
  padding: 9px 16px;
  background: #F8F9FA; border: 1px solid #D0D6DF;
  border-radius: 8px; width: fit-content;
  transition: background .15s;
}
.fd3-task-link:hover { background: #D0D6DF; }

@media (max-width: 720px) {
  .fd3-task-grid { grid-template-columns: 1fr; }
  .fd3-flow { flex-wrap: wrap; }
  .fd3-flow-arrow { transform: rotate(90deg); }
}

/* ── SECTION 2: TIMELINE ── */
.fd3-sec-timeline { background: #F8F9FA; }
.fd3-tl {
  max-width: 1000px; margin: 0 auto;
  display: flex; flex-direction: column; gap: 0;
}
.fd3-tl-item {
  display: grid;
  grid-template-columns: 72px 1fr;
  gap: 0 20px;
  position: relative;
}
.fd3-tl-side {
  display: flex; flex-direction: column; align-items: center;
}
.fd3-tl-num {
  width: 52px; height: 52px; border-radius: 50%;
  background: var(--tl, #66C5C5);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--display); font-size: 1rem; font-weight: 900;
  color: #F8F9FA; flex-shrink: 0;
  box-shadow: 0 4px 16px rgba(0,17,34,.15);
}
.fd3-tl-line {
  width: 2px; flex: 1; min-height: 24px;
  background: linear-gradient(to bottom, var(--tl), transparent);
  margin: 4px 0;
}
.fd3-tl-card {
  background: #F8F9FA;
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 24px 26px;
  margin-bottom: 20px;
  box-shadow: 0 2px 12px rgba(0,64,129,0.06), 0 1px 3px rgba(0,17,34,0.03);
}
.fd3-tl-tag {
  font-size: 10px; font-weight: 800; letter-spacing: .14em;
  text-transform: uppercase; color: var(--tl, #66C5C5);
  margin-bottom: 6px;
}
.fd3-tl-title {
  font-size: 22px; font-weight: 800; color: #001122;
  margin-bottom: 8px; line-height: 1.2;
}
.fd3-tl-sub { font-size: 14px; color: #586782; line-height: 1.65; margin: 0 0 14px; }
.fd3-tl-pills {
  display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 16px;
}
.fd3-tl-pills span {
  font-size: 11.5px; font-weight: 600;
  padding: 4px 11px; border-radius: 100px;
  background: #F8F9FA; border: 1px solid #D0D6DF; color: #505050;
}
.fd3-tl-quote {
  font-size: 13px; font-style: italic; color: #929EB4;
  line-height: 1.6;
  padding: 10px 14px;
  background: rgba(0,64,129,0.03);
  border-radius: 8px;
  margin-top: 4px;
}
.fd3-tl-quote em { font-style: normal; font-weight: 700; color: #586782; }
/* persons */
.fd3-tl-persons { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 4px; }
.fd3-tl-person {
  display: flex; align-items: center; gap: 10px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px; padding: 10px 14px;
  flex: 1; min-width: 160px;
}
.fd3-tl-person-av {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--pc); opacity: .15;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0; position: relative;
}
.fd3-tl-person-av svg { position: absolute; color: var(--pc); opacity: 1; }
.fd3-tl-person-av { background: rgba(0,17,34,.05); }
.fd3-tl-person-role { font-size: 10px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--pc); }
.fd3-tl-person-tip { font-size: 12px; color: #586782; line-height: 1.4; margin-top: 2px; }
/* timesheet mini table */
.fd3-tl-ts { display: flex; flex-direction: column; gap: 6px; margin-bottom: 16px; }
.fd3-tl-ts-row {
  display: flex; gap: 12px; align-items: center;
  background: #F8F9FA; border: 1px solid #D0D6DF;
  border-radius: 8px; padding: 9px 14px;
}
.fd3-tl-ts-k { font-size: 12px; font-weight: 700; color: #505050; min-width: 140px; }
.fd3-tl-ts-v { font-size: 12.5px; color: #586782; }
.fd3-tl-ts-ok { color: #004081; font-weight: 700; }
.fd3-tl-ts-warn { border-color: #D0D6DF; background: #F8F9FA; }
.fd3-tl-ts-warn .fd3-tl-ts-k { color: #505050; }
.fd3-tl-ts-warn .fd3-tl-ts-v { color: #F3554F; font-weight: 700; }
.fd3-tl-cta {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 13px; font-weight: 700; color: #004081;
  background: #F8F9FA; border: 1px solid #D0D6DF;
  border-radius: 8px; padding: 9px 16px;
  text-decoration: none; transition: background .15s;
}
.fd3-tl-cta:hover { background: #D0D6DF; }

@media (max-width: 640px) {
  .fd3-tl-item { grid-template-columns: 48px 1fr; }
  .fd3-tl-num { width: 40px; height: 40px; font-size: .85rem; }
  .fd3-tl-persons { flex-direction: column; }
}

/* ── SECTION 3: HANDBOOK GRID ── */
.fd3-sec-more {
  background: #001122;
  padding-bottom: 64px;
}
.fd3-sec-more .fd3-sec-title { color: #F8F9FA; }
.fd3-sec-more .fd3-sec-sub { color: rgba(248,249,250,.45); }
.fd3-more-inner { max-width: 1400px; margin: 0 auto; }
.fd3-more-head { margin-bottom: 36px; }
.fd3-more-title {
  font-family: var(--display);
  font-size: clamp(1.8rem, 3.5vw, 2.8rem);
  font-weight: 900; color: #F8F9FA;
  letter-spacing: -.025em; margin: 0 0 10px;
}
.fd3-more-sub { font-size: 15px; color: rgba(248,249,250,.45); max-width: 480px; }
.fd3-more-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}
.fd3-more-card {
  background: rgba(248,249,250,.04);
  border: 1px solid rgba(248,249,250,.08);
  border-top: 3px solid var(--mc, #66C5C5);
  border-radius: 16px;
  padding: 24px 20px;
  text-decoration: none;
  display: flex; flex-direction: column; gap: 10px;
  transition: background .2s, transform .2s;
}
.fd3-more-card:hover {
  background: rgba(248,249,250,.08);
  transform: translateY(-3px);
}
.fd3-more-card-num {
  font-family: var(--display);
  font-size: 2.2rem; font-weight: 900;
  color: var(--mc, #66C5C5); opacity: .25;
  line-height: 1; letter-spacing: -.05em;
}
.fd3-more-card-ico { color: var(--mc, #66C5C5); }
.fd3-more-card-title { font-size: 15px; font-weight: 800; color: #F8F9FA; line-height: 1.3; }
.fd3-more-card-items {
  display: flex; flex-wrap: wrap; gap: 5px;
}
.fd3-more-card-items span {
  font-size: 10.5px; font-weight: 600;
  padding: 3px 9px; border-radius: 100px;
  background: rgba(248,249,250,.07);
  border: 1px solid rgba(248,249,250,.1);
  color: rgba(248,249,250,.55);
}
.fd3-more-card-cta {
  font-size: 12px; font-weight: 700;
  color: var(--mc, #66C5C5);
  margin-top: auto;
}
.fd3-more-home {
  text-align: center;
}
.fd3-more-home-btn {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 14px; font-weight: 700; color: rgba(248,249,250,.8);
  background: rgba(248,249,250,.07);
  border: 1px solid rgba(248,249,250,.14);
  border-radius: 100px; padding: 12px 28px;
  text-decoration: none; transition: background .2s;
}
.fd3-more-home-btn:hover { background: rgba(248,249,250,.12); color: #F8F9FA; }

@media (max-width: 860px) {
  .fd3-more-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .fd3-more-grid { grid-template-columns: 1fr; }
}


/* ════════════════════════════════════════════════════════════
   SHOWCASE — card sizing fix + Medium color
   ════════════════════════════════════════════════════════════ */

/* Grid: align cards to top so varying heights don't stretch */
.showcase-real-grid {
  align-items: start !important;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)) !important;
}

/* Card base — use flex column so body fills remaining space */
.show-real-card {
  display: flex !important;
  flex-direction: column !important;
  height: auto !important;
  min-height: unset !important;
}

/* Link-type cards (Facebook / Medium) */
.show-real-card-facebook,
.show-real-card-medium {
  display: flex !important;
  flex-direction: column !important;
  grid-template-rows: unset !important;
}

/* Header strip — fixed compact height, no overflow */
.slc-header {
  min-height: 110px !important;
  max-height: 160px !important;
  padding: 18px 20px !important;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 8px;
  overflow: hidden;
}
.slc-platform-row {
  position: absolute;
  top: 0;
  left: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  width: auto;
  min-width: 34px;
  height: 22px;
  margin-bottom: 0;
  padding: 0 8px;
  border: 1px solid rgba(248,249,250,.18);
  border-top: 0;
  border-left: 0;
  border-radius: 0 0 9px 0;
  background: rgba(0,17,34,.58);
  box-shadow: 0 7px 18px rgba(0,17,34,.18);
  backdrop-filter: blur(8px) saturate(1.05);
  -webkit-backdrop-filter: blur(8px) saturate(1.05);
  z-index: 2;
}
.slc-headline {
  font-size: 14.5px !important;
  line-height: 1.4 !important;
  color: #F8F9FA;
  font-weight: 700;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin: 0;
}

/* Preview strip — compact */
.slc-preview-strip {
  padding: 12px 20px !important;
  background: #F8F9FA !important;
  border-bottom: 1px solid #F8F9FA;
}
.slc-preview-strip p {
  font-size: 13px !important;
  line-height: 1.55 !important;
  color: #586782;
  display: -webkit-box;
  -webkit-line-clamp: 3 !important;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin: 0;
}

/* Body — flex:1 so it fills space */
.show-real-body {
  flex: 1 !important;
  padding: 16px 20px 18px !important;
  display: flex !important;
  flex-direction: column !important;
}
.show-real-card h4 {
  font-size: 14.5px !important;
  line-height: 1.4 !important;
  margin: 0 0 6px !important;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.show-real-summary {
  font-size: 12.5px !important;
  line-height: 1.55 !important;
}
.show-real-actions {
  margin-top: auto !important;
  padding-top: 12px !important;
}
.show-real-link {
  font-size: 12.5px !important;
  padding: 7px 13px !important;
  min-height: unset !important;
}

/* Medium: vibrant green — #586782 is Medium's actual brand color */
.slc-header-medium {
  background: linear-gradient(135deg, #004081 0%, #586782 100%) !important;
}

/* ════════════════════════════════════════════════════════════
   PAGE HEADER (phb) — proportionate spacing, no eyebrow icon
   ════════════════════════════════════════════════════════════ */
.page-hero-band {
  padding: calc(var(--nav-h) + 20px) 0 24px !important;
}
.phb-title {
  font-size: clamp(1.4rem, 3vw, 2.1rem) !important;
  margin-bottom: 8px !important;
}
.phb-title::after { display: none; } /* remove the decorative underline bar */
.phb-lead { font-size: 14px !important; }
.phb-eyebrow { margin-bottom: 8px !important; font-size: 9.5px !important; }
/* Remove the large decorative number — takes up too much visual space */
.phb-deco-num { display: none !important; }

/* ════════════════════════════════════════════════════════════
   SECTION BACKGROUND DIVIDERS — tasteful alternation
   (policy, resources pages)
   ════════════════════════════════════════════════════════════ */

/* Core Values / Policy pages */
.cv-section-divider { background: #F8F9FA; border-radius: 20px; padding: 36px; margin: 32px 0; }

/* Timesheet page: give the column grid a tinted bg */
.ts-col-grid-wrap {
  background: #F8F9FA;
  border-radius: 16px;
  padding: 24px;
  margin: 24px 0;
}

/* Resources page: alternate sections */
.section-inner > h2:not(:first-child) {
  padding-top: 36px;
  border-top: 1px solid var(--line);
  margin-top: 36px;
}

/* WiFi page strip */
.wn-panel { background: #F8F9FA !important; border-radius: 16px !important; border: 1px solid var(--line) !important; }
.wn-panel .wn-main { padding: 24px !important; }

@media (max-width: 640px) {
  .page-hero-band { padding: calc(var(--nav-h) + 14px) 0 18px !important; }
}


/* ════════════════════════════════════════════════════════════
   DAY 1 HERO — fd3-hero (mesh gradient editorial layout)
   ════════════════════════════════════════════════════════════ */
.fd3-page { overflow-x: hidden; }

.fd3-hero {
  position: relative;
  min-height: 92vh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background: #F8F9FA;
  overflow: hidden;
}

/* Mesh gradient orbs */
.fd3-hero-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.65;
  pointer-events: none;
}
.fd3-orb-1 {
  width: 580px; height: 580px;
  background: radial-gradient(circle, #66C5C5 0%, #D0D6DF 55%, transparent 100%);
  top: -150px; left: -100px;
}
.fd3-orb-2 {
  width: 440px; height: 440px;
  background: radial-gradient(circle, #66C5C5 0%, #D0D6DF 55%, transparent 100%);
  top: 20px; right: -80px;
  opacity: 0.7;
}
.fd3-orb-3 {
  width: 360px; height: 360px;
  background: radial-gradient(circle, #D0D6DF 0%, #D0D6DF 55%, transparent 100%);
  bottom: 100px; left: 40%;
  opacity: 0.55;
}

/* Subtle dot-grid overlay */
.fd3-hero-grid-bg {
  position: absolute; inset: 0;
  background-image: radial-gradient(circle, rgba(0,64,129,0.07) 1px, transparent 1px);
  background-size: 36px 36px;
  pointer-events: none;
}

/* Inner layout: side-label | content | deco-num */
.fd3-hero-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: end;
  gap: 0 32px;
  padding: 0 48px 80px;
  max-width: 1300px;
  margin: 0 auto;
  width: 100%;
  padding-top: calc(var(--nav-h, 64px) + 40px);
}

/* Vertical side label */
.fd3-hero-side-label {
  writing-mode: vertical-rl;
  text-orientation: mixed;
  transform: rotate(180deg);
  font-size: 9px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(0,64,129,0.25);
  align-self: stretch;
  display: flex;
  align-items: center;
  padding-bottom: 8px;
}

/* Content block */
.fd3-hero-content { padding-bottom: 8px; }

.fd3-hero-eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(0,64,129,0.5);
  margin-bottom: 20px;
}
.fd3-hero-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #66C5C5;
  flex-shrink: 0;
}

.fd3-hero-h1 {
  font-size: clamp(2.8rem, 6vw, 5.5rem);
  line-height: 1.08;
  letter-spacing: -0.03em;
  margin: 0 0 24px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.fd3-h1-muted {
  color: rgba(0,64,129,0.4);
  font-weight: 300;
  display: block;
}
.fd3-h1-bold {
  color: #001122;
  font-weight: 700;
  display: block;
}
.fd3-h1-bold em {
  font-style: normal;
  color: #004081;
}

.fd3-hero-sub {
  font-size: 14px;
  color: rgba(0,64,129,0.45);
  margin: 0 0 32px;
  letter-spacing: 0.02em;
}

/* Stat row */
.fd3-hero-stat-row {
  display: flex;
  align-items: center;
  gap: 24px;
}
.fd3-hero-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.fd3-hero-stat-n {
  font-size: 2rem;
  font-weight: 700;
  color: #001122;
  line-height: 1;
  letter-spacing: -0.04em;
}
.fd3-hero-stat-l {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(0,64,129,0.4);
}
.fd3-hero-stat-sep {
  width: 1px;
  height: 36px;
  background: rgba(0,64,129,0.12);
}

/* Decorative large number */
.fd3-hero-deconum {
  font-size: clamp(5rem, 12vw, 11rem);
  font-weight: 800;
  color: rgba(0,64,129,0.05);
  line-height: 1;
  letter-spacing: -0.06em;
  align-self: end;
  padding-bottom: 4px;
  white-space: nowrap;
  user-select: none;
}

/* Bottom anchor strip */
.fd3-hero-strip {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: stretch;
  border-top: 1px solid rgba(0,64,129,0.1);
  background: rgba(248,249,250,0.5);
