/* ════════════════════════════════════════════════════════════
   DAY 1 HERO v5 — animated, immersive, cinematic
   ════════════════════════════════════════════════════════════ */

/* Animated gradient shift */
@keyframes fd3GradShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes fd3OrbFloat1 {
  0%, 100% { transform: translate(0, 0) scale(1); }
  33%       { transform: translate(30px, -20px) scale(1.05); }
  66%       { transform: translate(-20px, 15px) scale(0.97); }
}
@keyframes fd3OrbFloat2 {
  0%, 100% { transform: translate(0, 0) scale(1); }
  40%       { transform: translate(-25px, 20px) scale(1.08); }
  70%       { transform: translate(15px, -10px) scale(0.95); }
}
@keyframes fd3OrbFloat3 {
  0%, 100% { transform: translate(0, 0); }
  50%       { transform: translate(20px, -25px); }
}
@keyframes fd3FadeUp {
  from { opacity: 0; transform: translateY(28px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes fd3PillIn {
  from { opacity: 0; transform: translateY(14px) scale(0.95); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes fd3Pulse {
  0%, 100% { box-shadow: 0 4px 20px rgba(102,197,197,0.35); }
  50%       { box-shadow: 0 6px 32px rgba(102,197,197,0.6), 0 0 0 6px rgba(102,197,197,0.08); }
}
@keyframes fd3WavePan {
  0%   { d: path("M0,40 C360,80 1080,0 1440,40 L1440,80 L0,80 Z"); }
  50%  { d: path("M0,20 C400,60 1000,10 1440,50 L1440,80 L0,80 Z"); }
  100% { d: path("M0,40 C360,80 1080,0 1440,40 L1440,80 L0,80 Z"); }
}
@keyframes fd3LineDrift {
  from { transform: translateX(-100%); opacity: 0; }
  10%  { opacity: 1; }
  90%  { opacity: 1; }
  to   { transform: translateX(110vw); opacity: 0; }
}
@keyframes fd3DotPop {
  0%   { opacity: 0; transform: scale(0); }
  60%  { opacity: 1; transform: scale(1.2); }
  100% { opacity: 0.4; transform: scale(1); }
}
@keyframes fd3GlowPulse {
  0%, 100% { opacity: 0.5; }
  50%       { opacity: 0.85; }
}

/* Override bg with animated gradient */
.fd3-hero-bg {
  background-size: 300% 300% !important;
  animation: fd3GradShift 12s ease infinite !important;
}

/* Floating orbs — use pseudo-elements on bg div */
.fd3-hero-bg::before {
  content: "";
  position: absolute;
  width: 500px; height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(102,197,197,0.28) 0%, transparent 65%);
  top: -100px; left: -80px;
  filter: blur(60px);
  animation: fd3OrbFloat1 14s ease-in-out infinite;
}
.fd3-hero-bg::after {
  content: "";
  position: absolute;
  width: 380px; height: 380px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0,64,129,0.32) 0%, transparent 65%);
  bottom: 40px; right: -60px;
  filter: blur(55px);
  animation: fd3OrbFloat2 18s ease-in-out infinite;
  opacity: 0.8;
}

/* Extra orb via a wrapper */
.fd3-hero::before {
  content: "";
  position: absolute;
  width: 280px; height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(102,197,197,0.18) 0%, transparent 70%);
  bottom: 120px; left: 42%;
  filter: blur(50px);
  animation: fd3OrbFloat3 22s ease-in-out infinite;
  z-index: 1;
  pointer-events: none;
}

/* Animated scan lines — subtle horizontal streaks */
.fd3-hero-center::before {
  content: "";
  position: absolute;
  top: 50%; left: -20%;
  width: 60%; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(102,197,197,0.4), transparent);
  animation: fd3LineDrift 8s ease-in-out infinite;
  animation-delay: 2s;
  pointer-events: none;
}
.fd3-hero-center::after {
  content: "";
  position: absolute;
  top: 62%; left: -30%;
  width: 45%; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(102,197,197,0.25), transparent);
  animation: fd3LineDrift 11s ease-in-out infinite;
  animation-delay: 5s;
  pointer-events: none;
}

/* Staggered text animation */
.fd3-hero-pill {
  animation: fd3PillIn 0.7s cubic-bezier(0.22, 1, 0.36, 1) both !important;
  animation-delay: 0.1s !important;
}
.fd3-hero-h1 {
  animation: fd3FadeUp 0.8s cubic-bezier(0.22, 1, 0.36, 1) both !important;
  animation-delay: 0.3s !important;
}
.fd3-hero-sub {
  animation: fd3FadeUp 0.8s cubic-bezier(0.22, 1, 0.36, 1) both !important;
  animation-delay: 0.55s !important;
}
.fd3-hero-cta {
  animation: fd3FadeUp 0.8s cubic-bezier(0.22, 1, 0.36, 1) both, fd3Pulse 3s ease-in-out 1.5s infinite !important;
  animation-delay: 0.75s, 1.5s !important;
}

/* EXZY text in headline — glowing cyan */
.fd3-hero-h1 span {
  position: relative;
  text-shadow: 0 0 40px rgba(102,197,197,0.35);
  animation: fd3GlowPulse 3s ease-in-out 1s infinite !important;
}

/* Enhanced wave animation */
.fd3-hero-wave {
  animation: none; /* wave shape is static, movement from gradient above */
}

/* Floating dot particles */
@keyframes fd3DotFloat {
  0%, 100% { transform: translateY(0) scale(1); opacity: 0.4; }
  50%       { transform: translateY(-18px) scale(1.15); opacity: 0.7; }
}
.fd3-dots {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}
.fd3-dot-p {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: var(--s);
  height: var(--s);
  border-radius: 50%;
  background: #66C5C5;
  opacity: 0.4;
  animation: fd3DotFloat var(--dur, 10s) ease-in-out var(--d, 0s) infinite;
  box-shadow: 0 0 8px rgba(102,197,197,0.6);
}

/* ════════════════════════════════════════════════════════════
   DAY 1 HERO v6 — bold split + floating cards
   ════════════════════════════════════════════════════════════ */

/* Animations */
@keyframes fd6OrbA {
  0%,100% { transform:translate(0,0) scale(1); }
  33%      { transform:translate(40px,-30px) scale(1.1); }
  66%      { transform:translate(-20px,20px) scale(0.93); }
}
@keyframes fd6OrbB {
  0%,100% { transform:translate(0,0); }
  50%      { transform:translate(-30px,25px) scale(1.07); }
}
@keyframes fd6OrbC {
  0%,100% { transform:translate(0,0) scale(1); }
  40%      { transform:translate(20px,-20px) scale(1.05); }
}
@keyframes fd6Float1 {
  0%,100% { transform:translateY(0) rotate(-3deg); }
  50%      { transform:translateY(-14px) rotate(-1deg); }
}
@keyframes fd6Float2 {
  0%,100% { transform:translateY(0) rotate(2deg); }
  50%      { transform:translateY(-20px) rotate(4deg); }
}
@keyframes fd6BadgeIn {
  0%,100% { transform:translateY(0) scale(1); }
  50%      { transform:translateY(-8px) scale(1.02); }
}
@keyframes fd6RingPulse {
  0%,100% { transform:scale(1); opacity:0.15; }
  50%      { transform:scale(1.06); opacity:0.28; }
}
@keyframes fd6SlideLeft {
  from { opacity:0; transform:translateX(-40px); }
  to   { opacity:1; transform:translateX(0); }
}
@keyframes fd6SlideRight {
  from { opacity:0; transform:translateX(40px); }
  to   { opacity:1; transform:translateX(0); }
}
@keyframes fd6FadeUp {
  from { opacity:0; transform:translateY(20px); }
  to   { opacity:1; transform:translateY(0); }
}
@keyframes fd6GradText {
  0%   { background-position:0% 50%; }
  50%  { background-position:100% 50%; }
  100% { background-position:0% 50%; }
}
@keyframes fd6GridScroll {
  from { background-position: 0 0; }
  to   { background-position: 40px 40px; }
}
@keyframes fd6DotBlink {
  0%,100% { opacity:1; }
  50%      { opacity:0.3; }
}

/* ── Hero shell ── */
.fd6-hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
  background: #001122;
}

/* ── Animated background ── */
.fd6-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.fd6-bg-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(102,197,197,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(102,197,197,0.06) 1px, transparent 1px);
  background-size: 40px 40px;
  animation: fd6GridScroll 8s linear infinite;
}
.fd6-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  pointer-events: none;
}
.fd6-orb-a {
  width: 550px; height: 550px;
  background: radial-gradient(circle, rgba(102,197,197,0.3) 0%, transparent 65%);
  top: -150px; left: -80px;
  animation: fd6OrbA 16s ease-in-out infinite;
}
.fd6-orb-b {
  width: 420px; height: 420px;
  background: radial-gradient(circle, rgba(0,64,129,0.35) 0%, transparent 65%);
  bottom: -60px; right: -60px;
  animation: fd6OrbB 20s ease-in-out infinite;
}
.fd6-orb-c {
  width: 280px; height: 280px;
  background: radial-gradient(circle, rgba(102,197,197,0.18) 0%, transparent 70%);
  top: 50%; left: 50%;
  animation: fd6OrbC 24s ease-in-out infinite;
}

/* ── Split inner ── */
.fd6-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 40px;
  max-width: 1280px;
  margin: 0 auto;
  width: 100%;
  padding: calc(var(--nav-h,64px) + 48px) 56px 100px;
}

/* ── LEFT ── */
.fd6-left {
  animation: fd6SlideLeft 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0.1s both;
}

.fd6-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 10.5px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(102,197,197,0.7);
  margin-bottom: 24px;
  padding: 6px 14px;
  border: 1px solid rgba(102,197,197,0.2);
  border-radius: 100px;
  background: rgba(102,197,197,0.06);
}
.fd6-tag-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #66C5C5;
  animation: fd6DotBlink 2s ease-in-out infinite;
}
.fd6-tag-sep { opacity: 0.4; }

.fd6-h1 {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0 0 24px;
  line-height: 1;
}
.fd6-h1-line {
  display: block;
  font-weight: 800;
  letter-spacing: -0.04em;
}
.fd6-h1-line1 {
  font-size: clamp(1.6rem, 3.2vw, 2.8rem);
  color: rgba(248,249,250,0.45);
  font-weight: 300;
  letter-spacing: -0.01em;
  margin-bottom: 4px;
  animation: fd6FadeUp 0.7s 0.3s both;
}
.fd6-h1-line2 {
  font-size: clamp(2.6rem, 5.5vw, 5rem);
  color: rgba(248,249,250,0.88);
  animation: fd6FadeUp 0.7s 0.45s both;
}
.fd6-h1-line3 {
  font-size: clamp(3.5rem, 8vw, 7.5rem);
  background: linear-gradient(135deg, #66C5C5 0%, #D0D6DF 30%, #66C5C5 60%, #66C5C5 100%);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: fd6FadeUp 0.7s 0.6s both, fd6GradText 5s ease 1s infinite;
  filter: drop-shadow(0 0 30px rgba(102,197,197,0.4));
}

.fd6-sub {
  font-size: 15px;
  color: rgba(248,249,250,0.45);
  line-height: 1.7;
  margin: 0 0 32px;
  animation: fd6FadeUp 0.7s 0.75s both;
}

.fd6-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 32px;
  animation: fd6FadeUp 0.7s 0.9s both;
}
.fd6-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 28px;
  border-radius: 100px;
  background: #66C5C5;
  color: #001122;
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  box-shadow: 0 0 0 0 rgba(102,197,197,0.5);
  animation: fd6Pulse 3s ease-in-out 2s infinite;
}
@keyframes fd6Pulse {
  0%,100% { box-shadow: 0 4px 20px rgba(102,197,197,0.3); }
  50%      { box-shadow: 0 4px 32px rgba(102,197,197,0.6), 0 0 0 8px rgba(102,197,197,0.07); }
}
.fd6-btn-primary:hover { background: #66C5C5; transform: translateY(-2px); }
.fd6-btn-ghost {
  font-size: 13.5px;
  color: rgba(248,249,250,0.5);
  text-decoration: none;
  border-bottom: 1px solid rgba(248,249,250,0.2);
  padding-bottom: 2px;
  transition: color 0.2s, border-color 0.2s;
}
.fd6-btn-ghost:hover { color: #66C5C5; border-color: #66C5C5; }

.fd6-chips {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  animation: fd6FadeUp 0.7s 1.05s both;
}
.fd6-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  color: rgba(248,249,250,0.4);
  border: 1px solid rgba(248,249,250,0.1);
  border-radius: 100px;
  padding: 5px 12px;
  background: rgba(248,249,250,0.04);
}
.fd6-chip svg { opacity: 0.6; stroke: #66C5C5; }

/* ── RIGHT: floating cards ── */
.fd6-right {
  display: flex;
  justify-content: center;
  align-items: center;
  animation: fd6SlideRight 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0.2s both;
}
.fd6-cards-wrap {
  position: relative;
  width: 360px;
  height: 420px;
}

/* Glow ring behind cards */
.fd6-ring {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%,-50%);
  width: 300px; height: 300px;
  border-radius: 50%;
  border: 1px solid rgba(102,197,197,0.2);
  animation: fd6RingPulse 4s ease-in-out infinite;
}
.fd6-ring::after {
  content: "";
  position: absolute;
  inset: 20px;
  border-radius: 50%;
  border: 1px solid rgba(102,197,197,0.1);
  animation: fd6RingPulse 4s ease-in-out 1s infinite;
}

/* Cards */
.fd6-card {
  position: absolute;
  width: 300px;
  border-radius: 16px;
  overflow: hidden;
  background: rgba(248,249,250,0.06);
  border: 1px solid rgba(248,249,250,0.1);
  backdrop-filter: blur(12px);
  box-shadow: 0 20px 60px rgba(0,17,34,0.4), 0 0 0 1px rgba(248,249,250,0.05);
  transition: transform 0.3s, box-shadow 0.3s;
}
.fd6-card:hover {
  box-shadow: 0 28px 70px rgba(0,17,34,0.5), 0 0 30px rgba(102,197,197,0.15);
}
.fd6-card-1 {
  top: 20px; left: 20px;
  animation: fd6Float1 7s ease-in-out infinite;
  z-index: 2;
}
.fd6-card-2 {
  bottom: 20px; right: 0;
  animation: fd6Float2 9s ease-in-out 1s infinite;
  z-index: 1;
}

.fd6-card-top {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  color: rgba(0,17,34,0.7);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.fd6-card-ico {
  width: 30px; height: 30px;
  border-radius: 8px;
  background: rgba(0,17,34,0.15);
  display: flex; align-items: center; justify-content: center;
  color: rgba(0,17,34,0.6);
  flex-shrink: 0;
}
.fd6-card-body { padding: 14px 16px 16px; }
.fd6-card-title {
  font-size: 13.5px;
  font-weight: 700;
  color: rgba(248,249,250,0.88);
  margin-bottom: 10px;
}
.fd6-card-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 6px;
  align-items: center;
  font-size: 11px;
  color: rgba(248,249,250,0.45);
  line-height: 1.5;
}
.fd6-card-steps span:not(:nth-child(even)) {
  background: rgba(248,249,250,0.06);
  border-radius: 6px;
  padding: 2px 7px;
}
.fd6-card-steps span:nth-child(even) { opacity: 0.3; font-size: 10px; }

/* Floating badge */
.fd6-badge {
  position: absolute;
  top: 50%; right: -20px;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(248,249,250,0.9);
  border-radius: 14px;
  padding: 10px 14px;
  box-shadow: 0 8px 30px rgba(0,17,34,0.25);
  animation: fd6BadgeIn 5s ease-in-out 0.5s infinite;
  z-index: 3;
  white-space: nowrap;
}
.fd6-badge-icon { font-size: 22px; }
.fd6-badge-label { font-size: 12px; font-weight: 700; color: #001122; }
.fd6-badge-sub   { font-size: 10.5px; color: #707070; margin-top: 1px; }

/* Wave */
.fd6-wave {
  position: absolute;
  bottom: -2px; left: 0; right: 0;
  z-index: 3;
  line-height: 0;
}
.fd6-wave svg { width: 100%; height: 80px; display: block; }

/* Responsive */
@media (max-width: 900px) {
  .fd6-inner {
    grid-template-columns: 1fr;
    padding: calc(var(--nav-h,64px)+32px) 28px 120px;
    text-align: center;
  }
  .fd6-right { display: none; }
  .fd6-tag, .fd6-actions, .fd6-chips { justify-content: center; }
  .fd6-h1-line3 { font-size: 4rem; }
}

/* ════════════════════════════════════════════════════════════
   DAY 1 HERO v7 — light blue-white gradient, fresh & airy
   ════════════════════════════════════════════════════════════ */

/* Keyframes */
@keyframes fd7BlobFloat {
  0%,100% { transform: translate(0,0) scale(1); }
  33%      { transform: translate(30px,-25px) scale(1.06); }
  66%      { transform: translate(-18px,18px) scale(0.96); }
}
@keyframes fd7BlobFloat2 {
  0%,100% { transform: translate(0,0) scale(1); }
  45%      { transform: translate(-28px,20px) scale(1.08); }
}
@keyframes fd7RingPulse {
  0%,100% { transform: scale(1); opacity:.25; }
  50%      { transform: scale(1.12); opacity:.5; }
}
@keyframes fd7Up {
  from { opacity:0; transform: translateY(24px); }
  to   { opacity:1; transform: translateY(0); }
}
@keyframes fd7DotBlink {
  0%,100% { opacity:1; } 50% { opacity:.3; }
}
@keyframes fd7ChipIn {
  from { opacity:0; transform: translateY(16px) scale(.97); }
  to   { opacity:1; transform: translateY(0) scale(1); }
}
@keyframes fd7CtaPulse {
  0%,100% { box-shadow: 0 4px 20px rgba(102,197,197,.28); }
  50%      { box-shadow: 0 6px 32px rgba(102,197,197,.55), 0 0 0 8px rgba(102,197,197,.07); }
}
@keyframes fd7AccentShimmer {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Shell */
.fd7-hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  background: linear-gradient(160deg, #F8F9FA 0%, #F8F9FA 45%, #D0D6DF 100%);
}

/* Soft background blobs */
.fd7-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
}
.fd7-blob-1 {
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(102,197,197,.22) 0%, transparent 65%);
  top: -180px; left: -100px;
  animation: fd7BlobFloat 16s ease-in-out infinite;
}
.fd7-blob-2 {
  width: 460px; height: 460px;
  background: radial-gradient(circle, rgba(0,64,129,.12) 0%, transparent 65%);
  top: -60px; right: -80px;
  animation: fd7BlobFloat2 20s ease-in-out infinite;
}
.fd7-blob-3 {
  width: 350px; height: 350px;
  background: radial-gradient(circle, rgba(102,197,197,.15) 0%, transparent 70%);
  bottom: 60px; left: 38%;
  animation: fd7BlobFloat 22s ease-in-out 3s infinite;
}

/* Decorative rings */
.fd7-deco-ring {
  position: absolute;
  border-radius: 50%;
  border: 1.5px solid rgba(102,197,197,.22);
  pointer-events: none;
}
.fd7-ring-1 {
  width: 520px; height: 520px;
  top: 50%; right: -180px;
  transform: translateY(-50%);
  animation: fd7RingPulse 6s ease-in-out infinite;
}
.fd7-ring-2 {
  width: 340px; height: 340px;
  top: 50%; right: -100px;
  transform: translateY(-50%);
  animation: fd7RingPulse 6s ease-in-out 1.5s infinite;
  border-color: rgba(102,197,197,.13);
}

/* Inner content */
.fd7-inner {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  max-width: 820px;
  width: 100%;
  padding: calc(var(--nav-h,64px) + 48px) 32px 90px;
}

/* Eyebrow */
.fd7-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 10.5px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: #66C5C5;
  margin-bottom: 28px;
  padding: 7px 18px;
  border: 1.5px solid rgba(102,197,197,.25);
  border-radius: 100px;
  background: rgba(102,197,197,.08);
  animation: fd7Up .7s cubic-bezier(0.22, 1, 0.36, 1) .1s both;
}
.fd7-eyebrow-dot {
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #66C5C5;
  animation: fd7DotBlink 2s ease-in-out infinite;
  flex-shrink: 0;
}

/* Headline */
.fd7-h1 {
  font-size: clamp(2.8rem, 6.5vw, 5.4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.04em;
  color: #001122;
  margin: 0 0 20px;
  animation: fd7Up .75s cubic-bezier(0.22, 1, 0.36, 1) .25s both;
}
.fd7-h1-accent {
  background: linear-gradient(135deg, #66C5C5 0%, #66C5C5 40%, #66C5C5 80%);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: fd7AccentShimmer 5s ease 1s infinite;
}

/* Subtitle */
.fd7-sub {
  font-size: 16px;
  color: rgba(0,17,34,.5);
  margin: 0 0 36px;
  line-height: 1.65;
  animation: fd7Up .7s .42s both;
}

/* CTA */
.fd7-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 34px;
  border-radius: 100px;
  background: #66C5C5;
  color: #F8F9FA;
  font-size: 14.5px;
  font-weight: 700;
  text-decoration: none;
  margin-bottom: 44px;
  box-shadow: 0 4px 20px rgba(102,197,197,.28);
  animation: fd7Up .7s .58s both, fd7CtaPulse 3s ease-in-out 2s infinite;
  transition: background .2s, transform .15s;
}
.fd7-cta:hover { background: #586782; transform: translateY(-2px); }

/* Task preview chips */
.fd7-task-row {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
  animation: fd7ChipIn .8s .75s both;
}
.fd7-task-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  border-radius: 16px;
  background: rgba(248,249,250,.75);
  backdrop-filter: blur(8px);
  border: 1.5px solid rgba(0,17,34,.06);
  box-shadow: 0 4px 20px rgba(0,64,129,.08);
  text-align: left;
  min-width: 220px;
  transition: transform .2s, box-shadow .2s;
}
.fd7-task-chip:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px rgba(0,64,129,.13);
}
.fd7-chip-num {
  font-size: 13px;
  font-weight: 800;
  width: 32px; height: 32px;
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  letter-spacing: -.02em;
}
.fd7-chip-cyan .fd7-chip-num { background: rgba(102,197,197,.18); color: #66C5C5; }
.fd7-chip-amber .fd7-chip-num { background: rgba(255,204,0,.15); color: #F3554F; }
.fd7-chip-text span {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: #001122;
  line-height: 1.3;
}
.fd7-chip-text small {
  display: block;
  font-size: 11px;
  color: rgba(0,17,34,.45);
  margin-top: 2px;
}

/* Wave bottom */
.fd7-wave {
  position: absolute;
  bottom: -2px; left: 0; right: 0;
  z-index: 3;
  line-height: 0;
}
.fd7-wave svg { width: 100%; height: 60px; display: block; }

@media (max-width: 640px) {
  .fd7-h1 { font-size: 2.6rem; }
