   HERO v7 ENRICH — more visual depth, texture, accents
   ════════════════════════════════════════════════════════════ */

/* Richer gradient base */
.fd7-hero {
  background: linear-gradient(150deg,
    #F8F9FA 0%,
    #D0D6DF 30%,
    #F8F9FA 65%,
    #F8F9FA 100%
  ) !important;
}

/* Dot-grid texture over background */
.fd7-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle, rgba(102,197,197,.13) 1.5px, transparent 1.5px);
  background-size: 28px 28px;
  pointer-events: none;
  z-index: 1;
}

/* Large watermark "DAY 01" behind content */
.fd7-hero::after {
  content: "DAY 01";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -52%);
  font-size: clamp(9rem, 22vw, 18rem);
  font-weight: 900;
  letter-spacing: -.06em;
  color: rgba(102,197,197,.05);
  white-space: nowrap;
  pointer-events: none;
  z-index: 1;
  user-select: none;
}

/* Blobs: more saturated */
.fd7-blob-1 {
  background: radial-gradient(circle, rgba(102,197,197,.35) 0%, transparent 65%) !important;
}
.fd7-blob-2 {
  background: radial-gradient(circle, rgba(0,64,129,.16) 0%, transparent 65%) !important;
}
.fd7-blob-3 {
  background: radial-gradient(circle, rgba(102,197,197,.22) 0%, transparent 70%) !important;
}

/* Diagonal accent lines */
.fd7-inner::before {
  content: "";
  position: absolute;
  top: 60px; left: -60px;
  width: 200px; height: 1.5px;
  background: linear-gradient(90deg, transparent, rgba(102,197,197,.4), transparent);
  transform: rotate(-12deg);
  pointer-events: none;
}
.fd7-inner::after {
  content: "";
  position: absolute;
  bottom: 110px; right: -40px;
