/* Headline: bigger, with underline accent on second line */
.fd7-h1 {
  font-size: clamp(3.2rem, 7.5vw, 6.2rem) !important;
  position: relative;
}

/* Decorative bracket left of headline */
.fd7-h1-accent {
  position: relative;
}
.fd7-h1-accent::after {
  content: "";
  position: absolute;
  bottom: 6px; left: 0; right: 0;
  height: 4px;
  border-radius: 2px;
  background: linear-gradient(90deg, #66C5C5, #66C5C5, #66C5C5);
  background-size: 200% 100%;
  animation: fd7AccentShimmer 3s ease infinite;
