/* Task chips: richer cards with top color bar */
.fd7-task-chip {
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 10px !important;
  padding: 0 !important;
  overflow: hidden !important;
  min-width: 240px !important;
