}
.fd7-chip-text span { font-size: 13.5px !important; }

/* Subtle corner deco on rings */
.fd7-ring-1 {
  right: -200px !important;
  opacity: .6;
}
.fd7-ring-2 {
  right: -120px !important;
  opacity: .4;
}

/* Eyebrow: more prominent */
.fd7-eyebrow {
  font-size: 11px !important;
  letter-spacing: .2em !important;
  background: rgba(102,197,197,.12) !important;
  border-color: rgba(102,197,197,.35) !important;
