}

/* CTA: richer */
.fd7-cta {
  font-size: 15px !important;
  padding: 15px 38px !important;
  box-shadow: 0 6px 28px rgba(102,197,197,.32), inset 0 1px 0 rgba(248,249,250,.25) !important;
