/* ════════════════════════════════════════════════════════════
   DAY 1 HERO v8 — split layout, vivid right panel, rich animations
   ════════════════════════════════════════════════════════════ */

@keyframes fd8BlobA  { 0%,100%{transform:translate(0,0) scale(1)} 40%{transform:translate(30px,-25px) scale(1.07)} 70%{transform:translate(-15px,18px) scale(.95)} }
@keyframes fd8BlobB  { 0%,100%{transform:translate(0,0)} 50%{transform:translate(-25px,20px) scale(1.06)} }
@keyframes fd8Float1 { 0%,100%{transform:translateY(0) rotate(-2deg)} 50%{transform:translateY(-14px) rotate(1deg)} }
@keyframes fd8Float2 { 0%,100%{transform:translateY(0) rotate(2deg)} 50%{transform:translateY(-20px) rotate(-1deg)} }
@keyframes fd8Badge  { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-8px)} }
@keyframes fd8TimeBadge { 0%,100%{transform:translateY(0) rotate(-4deg)} 50%{transform:translateY(-10px) rotate(-2deg)} }
@keyframes fd8DotFloat { 0%,100%{transform:translateY(0);opacity:.5} 50%{transform:translateY(-12px);opacity:.9} }
@keyframes fd8GlowPulse { 0%,100%{opacity:.35} 50%{opacity:.6} }
@keyframes fd8RingPop  { 0%,100%{transform:translate(-50%,-50%) scale(1);opacity:.15} 50%{transform:translate(-50%,-50%) scale(1.08);opacity:.28} }
@keyframes fd8SlideL   { from{opacity:0;transform:translateX(-36px)} to{opacity:1;transform:translateX(0)} }
@keyframes fd8SlideR   { from{opacity:0;transform:translateX(36px)} to{opacity:1;transform:translateX(0)} }
@keyframes fd8FadeUp   { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }
@keyframes fd8Dot      { 0%,100%{opacity:1} 50%{opacity:.25} }
@keyframes fd8Shimmer  { 0%,100%{background-position:0% 50%} 50%{background-position:100% 50%} }
@keyframes fd8CtaPulse { 0%,100%{box-shadow:0 4px 20px rgba(102,197,197,.3)} 50%{box-shadow:0 6px 32px rgba(102,197,197,.6),0 0 0 8px rgba(102,197,197,.07)} }
@keyframes fd8CircleRotate { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }

/* ── Shell ── */
.fd8-hero {
  position: relative;
  min-height: 92vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

/* ── BG ── */
.fd8-bg {
  position: absolute; inset: 0; z-index: 0;
  background: linear-gradient(145deg, #F8F9FA 0%, #D0D6DF 28%, #D0D6DF 58%, #F8F9FA 85%, #F8F9FA 100%);
}
.fd8-bg::before {
  content:"";
  position:absolute;inset:0;
  background-image: radial-gradient(circle,rgba(102,197,197,.14) 1.5px,transparent 1.5px);
  background-size: 26px 26px;
}
/* floating blobs on bg */
.fd8-bg::after {
  content:"";
  position:absolute;
  width:620px;height:620px;border-radius:50%;
  background:radial-gradient(circle,rgba(102,197,197,.32) 0%,transparent 60%);
  top:-200px;left:-120px;filter:blur(85px);
  animation: fd8BlobA 16s ease-in-out infinite;
}

/* second blob via hero::before */
.fd8-hero::before {
  content:"";
  position:absolute;
  width:480px;height:480px;border-radius:50%;
  background:radial-gradient(circle,rgba(102,197,197,.18) 0%,transparent 60%);
  top:-80px;right:30%;filter:blur(80px);z-index:0;
  animation: fd8BlobB 20s ease-in-out infinite;
  pointer-events:none;
}

/* Big decorative ring - right edge */
.fd8-circle-deco {
  position:absolute;
  width:700px;height:700px;border-radius:50%;
  right:-200px;top:50%;transform:translateY(-50%);
  border:1.5px solid rgba(102,197,197,.22);
  z-index:0;pointer-events:none;
  animation: fd8RingPop 7s ease-in-out infinite;
}
.fd8-circle-deco::before {
  content:"";position:absolute;inset:50px;border-radius:50%;
  border:1px solid rgba(102,197,197,.12);
}
.fd8-circle-deco::after {
  content:"";position:absolute;inset:120px;border-radius:50%;
  border:1px dashed rgba(102,197,197,.15);
  animation: fd8CircleRotate 30s linear infinite;
}

/* ── Split ── */
.fd8-split {
  position:relative;z-index:2;
  display:grid;
  grid-template-columns:1fr 1fr;
  align-items:center;
  gap:48px;
  max-width:1280px;
  margin:0 auto;
  width:100%;
  padding: calc(var(--nav-h,64px)+52px) 64px 100px;
}

/* ── LEFT ── */
.fd8-left { animation: fd8SlideL .9s cubic-bezier(0.22, 1, 0.36, 1) .1s both; }

.fd8-eyebrow {
  display:inline-flex;align-items:center;gap:8px;
  font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;
  color:#66C5C5;margin-bottom:22px;
  padding:6px 16px;border-radius:100px;
  border:1.5px solid rgba(102,197,197,.28);
  background:rgba(102,197,197,.09);
  animation: fd8FadeUp .6s .2s both;
}
.fd8-dot {
  width:7px;height:7px;border-radius:50%;background:#66C5C5;flex-shrink:0;
  animation: fd8Dot 2s ease-in-out infinite;
}

.fd8-h1 {
  display:flex;flex-direction:column;gap:2px;
  margin:0 0 20px;
}
.fd8-h1-light {
  font-size:clamp(1.5rem,3vw,2.4rem);
  font-weight:300;color:rgba(0,17,34,.45);
  letter-spacing:-.01em;
  animation: fd8FadeUp .7s .3s both;
}
.fd8-h1-bold {
  font-size:clamp(3rem,6.5vw,5.8rem);
  font-weight:900;color:#001122;
  line-height:1.05;letter-spacing:-.04em;
  animation: fd8FadeUp .7s .45s both;
}
.fd8-h1-bold em {
  font-style:normal;
  background:linear-gradient(120deg,#66C5C5 0%,#66C5C5 45%,#66C5C5 90%);
  background-size:250% 250%;
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
  animation: fd8Shimmer 4s ease 1s infinite;
}

.fd8-sub {
  font-size:15.5px;color:rgba(0,17,34,.5);
  line-height:1.75;margin:0 0 32px;
  animation: fd8FadeUp .7s .6s both;
}

.fd8-actions {
  display:flex;align-items:center;gap:14px;margin-bottom:36px;
  animation: fd8FadeUp .7s .75s both;
}
.fd8-cta-main {
  display:inline-flex;align-items:center;gap:8px;
  padding:13px 30px;border-radius:100px;
  background:#66C5C5;color:#F8F9FA;
  font-size:14px;font-weight:700;text-decoration:none;
  animation: fd8CtaPulse 3s ease-in-out 2s infinite;
  transition:background .2s,transform .15s;
}
.fd8-cta-main:hover{background:#586782;transform:translateY(-2px);}
.fd8-cta-ghost {
  font-size:13.5px;color:rgba(0,17,34,.5);
  text-decoration:none;border-bottom:1px solid rgba(0,17,34,.2);padding-bottom:1px;
  transition:color .2s,border-color .2s;
}
.fd8-cta-ghost:hover{color:#66C5C5;border-color:#66C5C5;}

.fd8-stats {
  display:flex;align-items:center;gap:20px;
  animation: fd8FadeUp .7s .9s both;
}
.fd8-stat { display:flex;flex-direction:column;gap:1px; }
.fd8-stat-n { font-size:2rem;font-weight:800;color:#001122;line-height:1;letter-spacing:-.04em; }
.fd8-stat-l { font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:rgba(0,17,34,.4); }
.fd8-stat-sep { width:1px;height:32px;background:rgba(0,17,34,.1); }

/* ── RIGHT ── */
.fd8-right {
  position:relative;height:460px;
  animation: fd8SlideR .9s cubic-bezier(0.22, 1, 0.36, 1) .2s both;
}

.fd8-glow-orb {
  position:absolute;top:50%;left:50%;
  transform:translate(-50%,-50%);
  width:340px;height:340px;border-radius:50%;
  background:radial-gradient(circle,rgba(102,197,197,.22) 0%,transparent 65%);
  filter:blur(30px);
  animation: fd8GlowPulse 4s ease-in-out infinite;
}

/* Task cards */
.fd8-vcard {
  position:absolute;
  width:300px;
  border-radius:18px;
  background:#F8F9FA;
  box-shadow:0 16px 48px rgba(0,64,129,.12),0 2px 8px rgba(0,17,34,.06);
  overflow:hidden;
  transition:box-shadow .3s;
}
.fd8-vcard:hover { box-shadow:0 24px 60px rgba(0,64,129,.18); }
.fd8-vcard-1 { top:30px;left:10px; animation:fd8Float1 7s ease-in-out infinite; }
.fd8-vcard-2 { bottom:20px;right:0; animation:fd8Float2 9s ease-in-out 1.2s infinite; }

.fd8-vcard-bar { height:4px;width:100%; }
.fd8-vcard-body { padding:16px 18px 14px; display:flex; flex-direction:column; gap:6px; }
.fd8-vcard-label { font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase; }
.fd8-vcard-title { font-size:14px;font-weight:700;color:#001122; }
.fd8-vcard-steps { display:flex;align-items:center;gap:5px;font-size:18px;padding-top:4px; }
.fd8-step-arrow { font-size:11px;color:rgba(0,17,34,.3); }
.fd8-vcard-check {
  position:absolute;top:14px;right:16px;
  width:26px;height:26px;border-radius:50%;
  background:rgba(102,197,197,.12);color:#66C5C5;
  font-size:13px;display:flex;align-items:center;justify-content:center;font-weight:900;
}

/* Floating badges */
.fd8-badge {
  position:absolute;top:40%;right:-24px;
  display:flex;align-items:center;gap:10px;
  background:#F8F9FA;border-radius:14px;padding:10px 14px;
  box-shadow:0 8px 28px rgba(0,64,129,.14);
  animation:fd8Badge 5s ease-in-out .5s infinite;
  white-space:nowrap;z-index:3;
}
.fd8-badge-emoji { font-size:22px; }
.fd8-badge-title { font-size:12px;font-weight:800;color:#001122; }
.fd8-badge-sub   { font-size:10.5px;color:#707070;margin-top:1px; }

.fd8-time-badge {
  position:absolute;top:10px;right:60px;
  display:inline-flex;align-items:center;gap:5px;
  background:rgba(102,197,197,.12);color:#66C5C5;
  border:1.5px solid rgba(102,197,197,.25);
  border-radius:100px;padding:5px 12px;font-size:12px;font-weight:600;
  animation:fd8TimeBadge 6s ease-in-out 1s infinite;
}

/* Floating dots */
.fd8-fdot {
  position:absolute;border-radius:50%;background:#66C5C5;
  box-shadow:0 0 10px rgba(102,197,197,.6);
}
.fd8-fdot-1 { width:10px;height:10px;top:60px;right:30px;  animation:fd8DotFloat 6s ease-in-out infinite; opacity:.6; }
.fd8-fdot-2 { width:7px; height:7px; bottom:70px;left:20px;animation:fd8DotFloat 8s ease-in-out 1s infinite;opacity:.5;background:#66C5C5; }
.fd8-fdot-3 { width:13px;height:13px;bottom:130px;right:50px;animation:fd8DotFloat 7s ease-in-out 2s infinite;opacity:.4; }

/* Wave */
.fd8-wave { position:absolute;bottom:-2px;left:0;right:0;z-index:3;line-height:0; }
.fd8-wave svg { width:100%;height:60px;display:block; }

/* Responsive */
@media (max-width:960px) {
  .fd8-split { grid-template-columns:1fr;padding:calc(var(--nav-h,64px)+32px) 28px 120px; }
  .fd8-right { display:none; }
  .fd8-h1-bold { font-size:3.2rem; }
}

