/* =========================================================
   HOME + FIRST DAY SOFTENING / ANIMATION PASS
   Compact heroes, rounder frames, purposeful motion
   ========================================================= */

@keyframes welcomeSceneSettle {
  0% { opacity: 0; transform: translateY(22px) scale(.96); filter: blur(8px); }
  70% { opacity: 1; filter: blur(0); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}

@keyframes welcomeObjectDrift {
  0%, 100% { transform: translate3d(0,0,0) rotate(var(--r, 0deg)); }
  50% { transform: translate3d(0,-9px,0) rotate(calc(var(--r, 0deg) + .8deg)); }
}

@keyframes softPop {
  from { opacity: 0; transform: translateY(16px) scale(.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes pathBreathe {
  0%, 100% { opacity: .42; transform: scale(1); }
  50% { opacity: .72; transform: scale(1.035); }
}

.welcome-hero {
  min-height: min(820px, calc(100vh - var(--nav-h))) !important;
  border-radius: 0 0 28px 28px;
}

