  min-height: min(820px, calc(100vh - var(--nav-h))) !important;
  padding-top: clamp(34px, 5vw, 74px) !important;
  padding-bottom: clamp(36px, 5vw, 68px) !important;
  grid-template-columns: minmax(0, .86fr) minmax(360px, .9fr) !important;
}

.welcome-copy h1 {
  max-width: 11.6ch !important;
  font-size: clamp(2.65rem, 6.2vw, 4.95rem) !important;
  line-height: 1.2 !important;
}

