  max-width: 520px !important;
  margin-top: 18px !important;
}

.welcome-actions {
  margin-top: 28px !important;
}

.welcome-primary {
  min-height: 52px !important;
  padding-inline: 26px !important;
  border-radius: 999px !important;
  transition:
    transform .18s var(--ease-out-quart),
    box-shadow .22s ease,
    background .18s ease,
    filter .18s ease !important;
}

.welcome-primary:hover {
  box-shadow: 0 14px 28px rgba(0,64,129,.24) !important;
  filter: saturate(1.08);
}

.welcome-primary:active {
  transform: translateY(0) scale(.97) !important;
}

.welcome-scene {
  max-width: 640px;
  justify-self: end;
  animation: welcomeSceneSettle .82s var(--ease-out-expo) .08s both, welcomeFloat 8s ease-in-out 1.1s infinite !important;
  filter: drop-shadow(0 22px 42px rgba(0,64,129,.08));
}

.welcome-scene svg > g {
  transform-box: fill-box;
  transform-origin: center;
}

.welcome-scene svg > g:nth-of-type(1) { --r: 0deg; animation: welcomeObjectDrift 7.2s ease-in-out 1.3s infinite; }
.welcome-scene svg > g:nth-of-type(2) { --r: -6deg; animation: welcomeObjectDrift 6.6s ease-in-out 1.6s infinite; }
.welcome-scene svg > g:nth-of-type(3) { --r: 8deg; animation: welcomeObjectDrift 7.8s ease-in-out 1.8s infinite; }
.welcome-scene svg > g:nth-of-type(4) { --r: -4deg; animation: welcomeObjectDrift 6.9s ease-in-out 1.5s infinite; }
.welcome-scene svg > g:nth-of-type(5) { --r: 7deg; animation: welcomeObjectDrift 8.4s ease-in-out 1.7s infinite; }

