.fdw-cta:hover {
  box-shadow: 0 14px 30px rgba(0,64,129,.22) !important;
}

.fdw-cta:active {
  transform: translateY(0) scale(.97) !important;
}

.fd3-task-card {
  overflow: hidden !important;
  animation: softPop .58s var(--ease-out-quint) both;
}

.fd3-task-card:nth-child(2) { animation-delay: .1s; }

.fd3-card-graphic {
  width: 300px !important;
  height: 330px !important;
  right: -70px !important;
  bottom: -76px !important;
  opacity: .22 !important;
  filter: saturate(.8) contrast(.95) blur(.2px) !important;
}

.fd3-task-card:hover .fd3-card-graphic {
  opacity: .34 !important;
  transform: translateY(-4px) rotate(-1deg);
}

.fd3-flow {
  border-radius: 20px !important;
}

.fd3-flow-icon {
  font-size: 22px !important;
  width: 46px !important;
  height: 46px !important;
  border-radius: 18px !important;
  background: rgba(248,249,250,.82) !important;
  color: inherit !important;
  box-shadow: 0 8px 18px rgba(0,64,129,.08);
  transition: transform .2s var(--ease-out-quart), box-shadow .2s ease;
}

.fd3-flow-step:hover .fd3-flow-icon {
  transform: translateY(-3px) scale(1.04);
  box-shadow: 0 12px 24px rgba(0,64,129,.12);
}

.fd3-flow-step .fd3-flow-icon::before,
.fd3-flow-step:nth-of-type(1) .fd3-flow-icon::before,
.fd3-flow-step:nth-of-type(2) .fd3-flow-icon::before,
.fd3-flow-step:nth-of-type(3) .fd3-flow-icon::before {
  content: none !important;
}

.fd3-tl {
  position: relative;
  padding-left: 8px;
}

.fd3-tl::before {
  content: "";
  position: absolute;
  top: 18px;
  bottom: 22px;
  left: 28px;
