/* =========================================================
   FD5-HERO — Clean two-column first-day hero
   Replaces the broken full-bleed fdw-hero system entirely
   ========================================================= */

.fd5-hero {
  min-height: 88vh;
  background: linear-gradient(105deg,
    #001122 0%,
    #004081 28%,
    #004081 55%,
    #66C5C5 80%,
    #66C5C5 100%);
  display: flex;
  align-items: center;
  overflow: hidden;
  position: relative;
}

.fd5-inner {
  max-width: 1240px;
  margin: 0 auto;
  width: 100%;
  padding: clamp(80px, 11vw, 140px) clamp(24px, 5vw, 60px);
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: clamp(40px, 7vw, 100px);
  align-items: center;
}

/* ── Left: text ── */
.fd5-copy {
  display: flex;
  flex-direction: column;
}

.fd5-tag {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: .10em;
  text-transform: uppercase;
  color: rgba(208,214,223,.88);
  margin: 0 0 28px;
}

.fd5-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #66C5C5;
  box-shadow: 0 0 0 4px rgba(102,197,197,.22);
  flex-shrink: 0;
}

.fd5-h1 {
  margin: 0 0 22px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.fd5-sub {
  font-family: var(--thai);
  font-size: clamp(1.35rem, 2.5vw, 1.9rem);
  font-weight: 300;
  color: rgba(208,214,223,.44);
  letter-spacing: -.01em;
  line-height: 1.8;
}

.fd5-main {
  font-family: var(--thai);
  font-size: clamp(4.2rem, 9.5vw, 8rem);
  font-weight: 900;
  color: #F8F9FA;
  line-height: .95;
  letter-spacing: -.04em;
}

.fd5-place {
  font-family: var(--thai);
  font-size: clamp(1.5rem, 2.8vw, 2.4rem);
  font-weight: 400;
  color: rgba(208,214,223,.52);
  letter-spacing: -.01em;
  line-height: 1.55;
}

.fd5-place em {
  font-style: normal;
  font-weight: 800;
  color: #D0D6DF;
}

.fd5-lead {
  font-family: var(--thai);
  font-size: clamp(0.94rem, 1.5vw, 1.05rem);
  line-height: 1.9;
  color: rgba(208,214,223,.68);
  margin: 0 0 36px;
  max-width: 44ch;
}

.fd5-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: #F8F9FA;
  color: #004081;
  padding: 14px 30px;
  border-radius: 100px;
  font-family: var(--thai);
  font-weight: 700;
  font-size: 15px;
  text-decoration: none;
  width: fit-content;
  box-shadow: 0 8px 28px rgba(0,17,34,.22);
