}

.fd5-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 36px rgba(0,17,34,.30);
  background: #F8F9FA;
}

/* ── Right: visual ── */
.fd5-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.fd5-visual svg {
  width: 100%;
  max-width: 520px;
  height: auto;
  overflow: visible;
}

/* fdw-hero is the active first-day hero — keep visible */
.fd3-page .fdw-hero { display: flex !important; }

@media (max-width: 900px) {
  .fd5-inner {
    grid-template-columns: 1fr;
    gap: 48px;
    padding-top: 80px;
    padding-bottom: 60px;
