/* =========================================================
   VISUAL EFFECTS — Animations, blobs, tilt, shimmer, glow
   ========================================================= */

/* ── ANIMATED GRADIENT BACKGROUND ── */
@keyframes gradShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.welcome-hero {
  background-size: 300% 300% !important;
  animation: gradShift 14s ease infinite !important;
}

.fd5-hero {
  background-size: 300% 300% !important;
  animation: gradShift 16s ease infinite !important;
}

/* ── ANIMATED BACKGROUND BLOBS ── */
@keyframes blobA {
  0%, 100% { transform: translate(0, 0) scale(1) rotate(0deg); }
  33%       { transform: translate(40px,-30px) scale(1.12) rotate(8deg); }
  66%       { transform: translate(-28px, 22px) scale(.93) rotate(-6deg); }
}
@keyframes blobB {
  0%, 100% { transform: translate(0, 0) scale(1) rotate(0deg); }
  40%       { transform: translate(-36px, 24px) scale(1.08) rotate(-10deg); }
  70%       { transform: translate(26px,-20px) scale(.96) rotate(5deg); }
}

/* Blobs via ::before and ::after on hero wrappers */
.welcome-hero::before {
  content: "";
  position: absolute;
  width: 500px; height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(102,197,197,.18) 0%, transparent 70%);
  top: -100px; right: -80px;
  animation: blobA 12s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}

/* Second blob via fd5-hero structural approach */
.fd5-hero::before {
  content: "";
  position: absolute;
  width: 560px; height: 420px;
  border-radius: 60% 40% 50% 60% / 50% 60% 40% 50%;
  background: radial-gradient(ellipse, rgba(102,197,197,.16) 0%, transparent 70%);
  top: -60px; right: -40px;
  animation: blobA 14s ease-in-out infinite;
  pointer-events: none;
}
.fd5-hero::after {
  content: "";
  position: absolute;
  width: 400px; height: 400px;
  border-radius: 50% 60% 40% 50% / 60% 40% 60% 40%;
  background: radial-gradient(ellipse, rgba(0,64,129,.10) 0%, transparent 70%);
  bottom: -60px; left: -40px;
  animation: blobB 17s ease-in-out infinite;
  pointer-events: none;
}

/* ── SHIMMER ON BUTTONS ── */
@keyframes shimmerBtn {
  0%   { left: -120%; }
  100% { left: 160%; }
}

.welcome-primary,
.fd5-cta {
  position: relative;
  overflow: hidden;
}
.welcome-primary::before,
.fd5-cta::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0;
  left: -120%;
  width: 60%;
  background: linear-gradient(90deg, transparent, rgba(248,249,250,.28), transparent);
  transform: skewX(-18deg);
  animation: shimmerBtn 3.2s ease-in-out infinite 1.5s;
}

/* ── GLOW EFFECT on teal accents ── */
@keyframes glowPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(102,197,197,.35); }
  50%       { box-shadow: 0 0 22px 6px rgba(102,197,197,.18); }
}

.fd5-dot { animation: pulseDot 2.4s ease-in-out infinite, glowPulse 2.4s ease-in-out infinite !important; }

/* ── 3D TILT HOVER ON PATH CARDS ── */
.welcome-path-piece {
  transform-style: preserve-3d;
  will-change: transform;
  transition: transform .2s var(--ease-out-quart), box-shadow .2s ease !important;
}

/* ── MORE FLOAT VARIATION FOR SATELLITE CARDS ── */
.hv-hub {
  animation: fd5FadeUp .7s var(--ease-out-quint) .08s both;
}

/* ── ANIMATED UNDERLINE on section headings ── */
@keyframes underlineGrow {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

.welcome-section-head h2::after,
.fd3-sec-title::after {
  content: "";
  display: block;
  height: 3px;
  width: 56px;
  background: linear-gradient(90deg, #66C5C5, #004081);
  border-radius: 2px;
  margin-top: 12px;
  transform-origin: left;
  transform: scaleX(0);
  transition: transform .6s var(--ease-out-quint);
}

.fdb-vis .welcome-section-head h2::after,
.fdb-vis .fd3-sec-title::after {
  transform: scaleX(1);
}

/* ── MORE DRAMATIC SECTION REVEALS ── */
.fdb-reveal {
  opacity: 0 !important;
  transform: translateY(36px) !important;
  transition: opacity .65s var(--ease-out-quint), transform .65s var(--ease-out-quint) !important;
}
.fdb-reveal.fdb-vis {
  opacity: 1 !important;
  transform: translateY(0) !important;
}

/* ── PATH PIECE LABELS with pulse dot ── */
.piece-label::before {
  content: "";
  display: inline-block;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: currentColor;
  margin-right: 8px;
  vertical-align: middle;
  animation: pulseDot 2s ease-in-out infinite;
}

/* ── OFFICE SCENE ANIMATIONS on fd5-visual ── */
/* (steamRise defined below with the correct rise-and-fade keyframe) */

/* ── CTA ARROW BOUNCE ── */
@keyframes arrowBounce {
  0%, 100% { transform: translateX(0); }
  50%       { transform: translateX(4px); }
}
.welcome-primary:hover svg,
.fd5-cta:hover svg {
  animation: arrowBounce .5s ease-in-out infinite;
}

/* ── CARD ENTRANCE from opacity scale ── */
@keyframes cardIn {
  from { opacity: 0; transform: scale(.92) translateY(20px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

.fd3-task-card { animation: cardIn .55s var(--ease-out-quint) var(--delay,0s) both; }

@media (prefers-reduced-motion: reduce) {
  .welcome-hero, .fd5-hero {
    animation: none !important;
    background-size: 100% 100% !important;
  }
  .welcome-hero::before, .fd5-hero::before, .fd5-hero::after { animation: none !important; }
  .welcome-primary::before, .fd5-cta::before { animation: none !important; }
  .fd5-dot { animation: none !important; }
  .piece-label::before { animation: none !important; }
  .fd3-task-card { animation: none !important; opacity: 1 !important; transform: none !important; }
}

/* ── PARTICLE FLOAT (used by JS) ── */
@keyframes particleFloat {
  0%, 100% { transform: translateY(0) translateX(0) scale(1); opacity: .7; }
  25%       { transform: translateY(-24px) translateX(12px) scale(1.2); opacity: 1; }
  50%       { transform: translateY(-44px) translateX(-8px) scale(.85); opacity: .5; }
  75%       { transform: translateY(-28px) translateX(18px) scale(1.1); opacity: .8; }
}

/* ── OFFICE SCENE: steam animation on mug ── */
.fd5-visual path[stroke="rgba(146,158,180,.42)"],
.fd5-visual path[stroke="rgba(146,158,180,.35)"],
.fd5-visual path[stroke="rgba(146,158,180,.30)"] {
  animation: steamRise 2.8s ease-in-out infinite;
}

/* ── BORDER GRADIENT ANIMATION on fd5-cta ── */
@keyframes borderSpin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ── WELCOME PATH BOARD: hide the dashed SVG path behind — let hover colors speak ── */
.welcome-path-board::before { opacity: .45 !important; }

@media (prefers-reduced-motion: reduce) {
  .welcome-hero, .fd5-hero { animation: none !important; background-size: 100% !important; }
  .welcome-hero::before, .fd5-hero::before, .fd5-hero::after { display: none !important; }
  .welcome-primary::before, .fd5-cta::before { display: none !important; }
  span[style*="particleFloat"] { display: none !important; }
}

/* =========================================================
   /impeccable animate home
   One rehearsed entrance → scroll stagger → micro-interactions
   ========================================================= */

/* ── 1. EASING TOKENS (site-wide) ── */
:root {
  --ease-out-quart: cubic-bezier(0.25, 1, 0.5, 1);
  --ease-out-quint: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out-expo:  cubic-bezier(0.16, 1, 0.3, 1);
}

/* ── 2. HERO ENTRANCE CHOREOGRAPHY ── */

/* Remove the block-level animation from welcome-copy so children stagger */
.welcome-copy { animation: none !important; opacity: 1 !important; }

/* Shared child entrance keyframe */
@keyframes heroChildIn {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Stagger: kicker → h1 → lead → CTA */
.welcome-kicker  { animation: heroChildIn .5s var(--ease-out-quint) .08s both; }
.welcome-copy h1 { animation: heroChildIn .6s var(--ease-out-quint) .20s both; }
.welcome-lead    { animation: heroChildIn .5s var(--ease-out-quint) .36s both; }
.welcome-actions { animation: heroChildIn .5s var(--ease-out-quint) .50s both; }

/* Hub card: enters slightly ahead of satellites */
.hv-hub { animation: hubEnter .55s var(--ease-out-quint) .38s both !important; }

@keyframes hubEnter {
  from { opacity: 0; transform: scale(.94) translateY(12px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

/* ── 3. SATELLITE ENTRANCE → then float ── */

/* Keyframe for entrance only */
@keyframes satEnter {
  from { opacity: 0; transform: scale(.78) translateY(18px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

/* Multi-animation: entrance (.45s) + infinite float (begins after entrance) */
.hv-sat-1 {
  animation:
    satEnter .45s var(--ease-out-quint) .55s both,
    hvFloatA 5.2s 1.05s ease-in-out infinite !important;
}
.hv-sat-2 {
  animation:
    satEnter .45s var(--ease-out-quint) .70s both,
    hvFloatB 5.8s 1.20s ease-in-out infinite !important;
}
.hv-sat-3 {
  animation:
    satEnter .45s var(--ease-out-quint) .82s both,
    hvFloatC 4.9s 1.32s ease-in-out infinite !important;
}
.hv-sat-4 {
  animation:
    satEnter .45s var(--ease-out-quint) .94s both,
    hvFloatA 6.1s 1.44s ease-in-out infinite !important;
}

/* ── 4. CONNECTING LINES: soft reveal with blur ── */

@keyframes linesReveal {
  from { opacity: 0; filter: blur(3px); }
  to   { opacity: .38; filter: blur(0); }
}

.hn-lines {
  animation: linesReveal .7s var(--ease-out-quint) .88s both;
}

/* ── 5. HUB PROGRESS BAR: fill animation ── */

@keyframes progFill {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

.hn-prog {
  transform-box: fill-box;
  transform-origin: left center;
  animation: progFill 1.4s var(--ease-out-expo) 1.2s both;
}

/* ── 6. SCROLL-STAGGER: path pieces + object cards ── */

/* Use CSS custom property --rd (reveal-delay) from inline style */
.fdb-reveal {
  transition-delay: var(--rd, 0ms) !important;
}

/* Override: path pieces need scale + translateY (not just translateY) */
.welcome-path-piece.fdb-reveal {
  opacity: 0 !important;
  transform: translateY(28px) scale(.97) !important;
}
.welcome-path-piece.fdb-reveal.fdb-vis {
  opacity: 1 !important;
  transform: translateY(0) scale(1) !important;
  transition: opacity .6s var(--ease-out-quint) var(--rd, 0ms),
              transform .6s var(--ease-out-quint) var(--rd, 0ms) !important;
}

/* Object cards: slide up with stagger */
.welcome-object-list a.fdb-reveal {
  opacity: 0 !important;
  transform: translateY(22px) !important;
}
.welcome-object-list a.fdb-reveal.fdb-vis {
  opacity: 1 !important;
  transform: translateY(0) !important;
  transition: opacity .55s var(--ease-out-quint) var(--rd, 0ms),
              transform .55s var(--ease-out-quint) var(--rd, 0ms) !important;
}

/* ── 7. MICRO-INTERACTIONS ── */

/* CTA active press: quick scale-down tactile feedback */
.welcome-primary:active,
.fd5-cta:active {
  transform: scale(.95) !important;
  transition: transform .08s ease !important;
}

/* Path piece hover: lift already has tilt from JS, add glow */
.welcome-path-piece:focus-visible {
  outline: 3px solid rgba(102,197,197,.60);
  outline-offset: 4px;
}

/* Object cards: colour-matched glow on focus */
.welcome-object-list a:focus-visible {
  outline: 3px solid #66C5C5;
  outline-offset: 4px;
  border-radius: 22px;
}

/* Kicker pulse dot animation (defined in pulseDot keyframe already) */
.welcome-kicker span {
  animation: pulseDot 2.4s ease-in-out 1s infinite !important;
}

/* Nav: smooth box-shadow on scroll (already has .scrolled class applied by JS) */
.navbar { transition: box-shadow .25s ease, border-color .25s ease, background .25s ease; }

/* ── 8. PREFERS-REDUCED-MOTION — full coverage ── */

@media (prefers-reduced-motion: reduce) {
  /* Hero children: instant reveal, no motion */
  .welcome-kicker,
  .welcome-copy h1,
  .welcome-lead,
  .welcome-actions {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  /* Hub and satellites */
  .hv-hub,
  .hv-sat-1,
  .hv-sat-2,
  .hv-sat-3,
  .hv-sat-4 {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }

  /* Lines and progress */
  .hn-lines { animation: none !important; opacity: .38 !important; }
  .hn-prog  { animation: none !important; transform: none !important; }

  /* Scroll reveals: show immediately */
  .welcome-path-piece.fdb-reveal,
  .welcome-object-list a.fdb-reveal {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }

  /* Kicker pulse */
  .welcome-kicker span { animation: none !important; }
}

/* =========================================================
   /impeccable animate first-day
   Hero stagger → office scene settles in → living scene →
   task + timeline scroll-stagger
   ========================================================= */

/* ── 1. HERO TEXT — stagger every child independently ── */

/* Drop the block-level slide so children can own their timing */
.fd5-copy { animation: none !important; opacity: 1 !important; }

@keyframes fd5ChildIn {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* "วันแรก" (fd5-main) gets a distinct scale entrance — it's the hero word */
@keyframes fd5MainIn {
  from { opacity: 0; transform: translateY(22px) scale(.94); }
  to   { opacity: 1; transform: translateY(0)  scale(1); }
}

.fd5-tag   { animation: fd5ChildIn .50s var(--ease-out-quint) .06s  both; }
.fd5-sub   { animation: fd5ChildIn .50s var(--ease-out-quint) .18s  both; }
.fd5-main  { animation: fd5MainIn  .62s var(--ease-out-quint) .28s  both; }
.fd5-place { animation: fd5ChildIn .50s var(--ease-out-quint) .42s  both; }
.fd5-lead  { animation: fd5ChildIn .48s var(--ease-out-quint) .56s  both; }
.fd5-cta   { animation: fd5ChildIn .48s var(--ease-out-quint) .68s  both; }

/* Visual column: refined entrance — scale from .97 as it slides in */
.fd5-visual {
  animation: fd5VisIn .72s var(--ease-out-quint) .22s both !important;
}

@keyframes fd5VisIn {
  from { opacity: 0; transform: translateX(30px) scale(.97); }
  to   { opacity: 1; transform: translateX(0)    scale(1); }
}

/* ── 2. OFFICE SCENE: elements settle onto the desk ── */

/* Shared settle keyframe */
@keyframes deskSettle {
  from { opacity: 0; transform: translateY(14px) scale(.88); }
  60%  { opacity: 1; transform: translateY(-3px)  scale(1.02); }
  to   { opacity: 1; transform: translateY(0)      scale(1); }
}

/* Plant: settles from slightly above, delayed after visual enters */
.fd5-plant {
  transform-box: fill-box;
  transform-origin: bottom center;
  animation: deskSettle .55s var(--ease-out-quint) .50s both;
}

/* Mug: arrives after laptop */
.fd5-mug {
  animation: deskSettle .50s var(--ease-out-quint) .80s both;
}

/* Badge: settles from slightly higher */
.fd5-badge {
  transform-box: fill-box;
  transform-origin: center;
  animation: deskSettle .45s var(--ease-out-quint) 1.00s both;
}

/* Post-it: settles last */
.fd5-postit {
  transform-box: fill-box;
  transform-origin: center;
  animation: deskSettle .45s var(--ease-out-quint) 1.12s both;
}

/* Chip: pops in + then bobs */
@keyframes chipPop {
  from { opacity: 0; transform: scale(.6) translateY(10px); }
  70%  { opacity: 1; transform: scale(1.08) translateY(-4px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

.fd5-chip {
  animation:
    chipPop   .50s var(--ease-out-quint) 1.20s both,
    chipBob   4.4s 1.80s ease-in-out infinite;
}

@keyframes chipBob {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(-7px); }
}

/* ── 3. LIVING SCENE — continuous micro-animations ── */

/* Plant: very gentle sway, organic rhythm */
@keyframes plantSway {
  0%, 100% { transform: rotate(0deg); }
  30%       { transform: rotate(-2.5deg); }
  70%       { transform: rotate(1.8deg); }
}

.fd5-plant {
  animation:
    deskSettle .55s var(--ease-out-quint) .50s both,
    plantSway  7s   1.20s ease-in-out infinite;
}

/* Coffee steam: each wisp rises independently */
@keyframes steamRise {
  0%   { opacity: 0; transform: translateY(0) scaleX(1); }
  25%  { opacity: .50; }
  80%  { opacity: .28; transform: translateY(-16px) scaleX(.65); }
  100% { opacity: 0;   transform: translateY(-22px) scaleX(.4); }
}

.fd5-steam {
  transform-box: fill-box;
  transform-origin: center bottom;
  animation: steamRise 3.2s var(--sd, 0s) ease-in-out infinite;
}

/* ── 4. TASK CARDS — fix conflict with fdb-reveal, proper stagger ── */

/* Remove the animation that fires before scroll; let fdb-reveal own it */
.fd3-task-card {
  animation: none !important;
}

/* Richer task-card reveal: scale + rise (the fdb-reveal transition handles timing) */
.fd3-task-card.fdb-reveal {
  opacity: 0 !important;
  transform: translateY(28px) scale(.96) !important;
}
.fd3-task-card.fdb-reveal.fdb-vis {
  opacity: 1 !important;
  transform: translateY(0) scale(1) !important;
  transition:
    opacity .58s var(--ease-out-quint) var(--rd, 0ms),
    transform .58s var(--ease-out-quint) var(--rd, 0ms) !important;
}

/* ── 5. TIMELINE ITEMS — proper scroll stagger via --rd ── */

/* Override old nth-child animation-delay approach */
.fd3-tl-item { animation: none !important; }

.fd3-tl-item.fdb-reveal {
  opacity: 0 !important;
  transform: translateX(-18px) !important;
}
.fd3-tl-item.fdb-reveal.fdb-vis {
  opacity: 1 !important;
  transform: translateX(0) !important;
  transition:
    opacity .55s var(--ease-out-quint) var(--rd, 0ms),
    transform .55s var(--ease-out-quint) var(--rd, 0ms) !important;
}

/* ── 6. SECTION HEAD REVEALS ── */

/* fd3 section headings: slide up with blur-in */
.fd3-sec-head.fdb-reveal {
  opacity: 0 !important;
  transform: translateY(20px) !important;
  filter: blur(3px) !important;
}
.fd3-sec-head.fdb-reveal.fdb-vis {
  opacity: 1 !important;
  transform: translateY(0) !important;
  filter: blur(0) !important;
  transition:
    opacity  .60s var(--ease-out-quint),
    transform .60s var(--ease-out-quint),
    filter   .60s var(--ease-out-quint) !important;
}

/* ── 7. CTA MICRO-INTERACTION ── */

.fd5-cta:active {
  transform: scale(.95) !important;
  transition: transform .07s ease !important;
}

/* Arrow nudge on hover */
.fd5-cta:hover svg {
  animation: arrowBounce .5s ease-in-out infinite;
}

/* ── 8. prefers-reduced-motion — full first-day coverage ── */

@media (prefers-reduced-motion: reduce) {
  /* Hero text: instant reveal */
  .fd5-tag, .fd5-sub, .fd5-main, .fd5-place, .fd5-lead, .fd5-cta {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .fd5-visual { animation: none !important; opacity: 1 !important; transform: none !important; }

  /* Office scene */
  .fd5-plant, .fd5-mug, .fd5-badge, .fd5-postit, .fd5-chip {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
  .fd5-steam { animation: none !important; }

  /* Task cards */
  .fd3-task-card.fdb-reveal,
  .fd3-tl-item.fdb-reveal,
  .fd3-sec-head.fdb-reveal {
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
    transition: none !important;
  }

  /* CTA */
  .fd5-cta:active { transform: none !important; }
  .fd5-cta:hover svg { animation: none !important; }
}

/* =========================================================
   /impeccable optimize + colorize first-day
   ========================================================= */

/* ── OPTIMIZE: perf hints ── */

/* gradShift animates background-position — declare intent */
.fd5-hero {
  will-change: background-position;
}

/* Bound section repaint — fd3 sections are independent scroll regions */
.fd3-sec-tasks,
.fd3-sec-timeline {
  contain: layout style;
}

/* ── COLORIZE: Committed teal strategy activated across fd3 sections ── */

/* ── TASK SECTION: Subtle teal wash — not dead white ── */
.fd3-sec-tasks {
  background:
    radial-gradient(ellipse 60% 50% at 92% 8%, rgba(102,197,197,.07), transparent 50%),
    linear-gradient(180deg, #F8F9FA 0%, #F8F9FA 60%) !important;
}

/* Calendar card — teal identity */
.fd3-task-card--cal {
  background:
    radial-gradient(ellipse 70% 60% at 105% 96%, rgba(102,197,197,.22), transparent 44%),
    linear-gradient(145deg, #F8F9FA 0%, #F8F9FA 100%) !important;
  border-color: rgba(102,197,197,.24) !important;
}

/* Timesheet card — navy identity */
.fd3-task-card--ts {
  background:
    radial-gradient(ellipse 70% 60% at 105% 96%, rgba(0,64,129,.14), transparent 44%),
    linear-gradient(145deg, #F8F9FA 0%, #F8F9FA 100%) !important;
  border-color: rgba(0,64,129,.18) !important;
}

/* ── TIMELINE SECTION: stronger brand presence ── */
.fd3-sec-timeline {
  background:
    radial-gradient(ellipse 65% 55% at 88% 10%, rgba(102,197,197,.10), transparent 48%),
    radial-gradient(ellipse 45% 40% at 8% 88%, rgba(0,64,129,.06), transparent 44%),
    linear-gradient(180deg, #F8F9FA 0%, #F8F9FA 50%, #F8F9FA 100%) !important;
}

/* Timeline number badges: absorb --tl with a bolder treatment */
.fd3-tl-num {
  color: var(--tl, #66C5C5) !important;
  font-weight: 800 !important;
  border: 2px solid var(--tl, #66C5C5) !important;
  border-radius: 50% !important;
  width: 40px !important;
  height: 40px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: color-mix(in srgb, var(--tl, #66C5C5) 10%, #F8F9FA) !important;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--tl, #66C5C5) 14%, transparent) !important;
  font-size: 14px !important;
}

/* Timeline line: branded colour instead of gray */
.fd3-tl-line {
  background: linear-gradient(180deg, var(--tl, #66C5C5) 0%, rgba(0,64,129,.18) 100%) !important;
  opacity: .45 !important;
}

/* Timeline cards: top accent strip (full-width — not a side stripe) */
.fd3-tl-card {
  border-top: 3px solid var(--tl, #66C5C5) !important;
  border-radius: 0 0 20px 20px !important;  /* keep existing bottom radius, flat top where stripe is */
}

/* Subtle card tint from --tl */
.fd3-tl-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: color-mix(in srgb, var(--tl, #66C5C5) 5%, transparent);
  pointer-events: none;
}
.fd3-tl-card { position: relative; overflow: hidden; }

/* Timeline tags: use --tl color */
.fd3-tl-tag {
  color: var(--tl, #66C5C5) !important;
  font-weight: 700 !important;
  font-size: 11px !important;
  letter-spacing: .06em !important;
  text-transform: uppercase !important;
}

/* Timeline pills: tinted from --tl */
.fd3-tl-pills span {
  background: color-mix(in srgb, var(--tl, #66C5C5) 14%, #F8F9FA) !important;
  color: color-mix(in srgb, var(--tl, #66C5C5) 70%, #001122) !important;
  border: 1px solid color-mix(in srgb, var(--tl, #66C5C5) 28%, transparent) !important;
  border-radius: 999px !important;
  padding: 3px 12px !important;
  font-size: 12px !important;
  font-weight: 600 !important;
}

/* ── ORIENTATION MAP: each step gets a teal wash + coloured icon box ── */
.fd3-orient-step {
  background:
    radial-gradient(ellipse 80% 60% at 50% 0%, rgba(102,197,197,.12), transparent 60%),
    rgba(248,249,250,.88) !important;
