:root {
  --exzy-cyan: #66C5C5;
  --exzy-cyan-deep: #586782;
  --exzy-navy: #004081;
  --exzy-ink: #001122;
  --exzy-muted: #505050;
  --exzy-soft: #F8F9FA;
  --exzy-line: #D0D6DF;
}

.ex-home-hero {
  position: relative;
  overflow: hidden;
  min-height: calc(88svh - var(--nav-h));
  background:
    linear-gradient(90deg, rgba(0,64,129,.05) 1px, transparent 1px),
    linear-gradient(180deg, rgba(0,64,129,.05) 1px, transparent 1px),
    radial-gradient(circle at 82% 18%, rgba(102,197,197,.24), transparent 31%),
    radial-gradient(circle at 14% 78%, rgba(0,64,129,.09), transparent 32%),
    linear-gradient(145deg, #F8F9FA 0%, #F8F9FA 55%, #F8F9FA 100%);
  background-size:
    42px 42px,
    42px 42px,
    auto,
    auto,
    auto;
}

.ex-home-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 86px;
  background: linear-gradient(180deg, transparent, #F8F9FA);
  pointer-events: none;
}

.ex-home-hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1260px;
  min-height: calc(88svh - var(--nav-h));
  margin: 0 auto;
  padding: clamp(64px, 8vw, 112px) 28px 76px;
  display: grid;
  grid-template-columns: minmax(0, .92fr) minmax(430px, 1.08fr);
  align-items: center;
  gap: clamp(36px, 6vw, 82px);
}

.ex-home-copy {
  max-width: 650px;
}

.ex-home-kicker,
.ex-day-chapter {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 18px;
  color: var(--exzy-navy);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.ex-home-kicker span,
.ex-day-chapter span {
  width: 36px;
  height: 3px;
  border-radius: 99px;
  background: var(--exzy-cyan);
}

.ex-home-copy h1,
.ex-day-hero-inner h1 {
  margin: 0;
  color: #001122;
  font-size: clamp(2.7rem, 5.2vw, 5.2rem);
  line-height: 1.12;
  letter-spacing: -.03em;
  text-wrap: balance;
}

.ex-home-lead,
.ex-day-hero-inner p {
  margin: 24px 0 0;
  max-width: 610px;
  color: var(--exzy-muted);
  font-size: clamp(1rem, 1.4vw, 1.12rem);
  line-height: 1.85;
  text-wrap: pretty;
}

.ex-home-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  margin-top: 34px;
}

.ex-home-primary,
.ex-home-secondary,
.ex-day-cta,
.ex-inline-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: fit-content;
  border-radius: 999px;
  font-weight: 700;
  transition: transform .22s var(--ease-out-quart), box-shadow .22s var(--ease-out-quart), background .22s ease;
}

.ex-home-primary,
.ex-day-cta {
  position: relative;
  overflow: hidden;
  padding: 14px 24px;
  color: #F8F9FA;
  background: linear-gradient(135deg, #66C5C5 0%, #004080 100%);
  box-shadow: 0 14px 30px rgba(0,64,128,.22);
}

.ex-home-primary::after,
.ex-day-cta::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 55%;
  height: 100%;
  background: linear-gradient(105deg, transparent 20%, rgba(255,255,255,.32) 50%, transparent 80%);
  transform: translateX(-140%);
  animation: btn-shimmer 3.2s ease-in-out infinite;
  pointer-events: none;
}

@keyframes btn-shimmer {
  0%   { transform: translateX(-140%); }
  35%  { transform: translateX(260%); }
  100% { transform: translateX(260%); }
}

.ex-home-primary:hover,
.ex-day-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 36px rgba(0,64,129,.25);
}

.ex-home-secondary {
  padding: 14px 24px;
  color: var(--exzy-navy);
  background: rgba(248,249,250,.58);
  border: 1px solid rgba(0,64,129,.16);
}

.ex-home-secondary:hover {
  background: rgba(102,197,197,.13);
}

.ex-binder-scene {
  position: relative;
  min-height: 580px;
  display: grid;
  place-items: center;
  perspective: 1200px;
}

.ex-binder-scene::before {
  content: "";
  position: absolute;
  inset: 14% 5% 5% 15%;
  border-radius: 999px;
  background: rgba(102,197,197,.18);
  filter: blur(28px);
}

.ex-binder-stack {
  position: relative;
  width: min(100%, 530px);
  aspect-ratio: 1 / 1.08;
  transform: rotate(-4deg);
  animation: ex-binder-float 7s ease-in-out infinite;
}

.ex-binder-cover,
.ex-binder-page,
.ex-binder-tab {
  position: absolute;
  box-shadow: 0 18px 42px rgba(0,64,129,.12);
}

.ex-binder-cover {
  inset: 10% 8% 7% 9%;
  padding: clamp(26px, 4vw, 38px);
  color: #F8F9FA;
  border-radius: 22px 28px 28px 22px;
  background:
    linear-gradient(90deg, rgba(0,17,34,.20) 0 11%, transparent 11%),
    radial-gradient(circle at 86% 18%, rgba(102,197,197,.36), transparent 29%),
    linear-gradient(145deg, #004081 0%, #001122 100%);
  overflow: hidden;
  z-index: 6;
}

.ex-binder-cover::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
