/* ==========================================================
   First-day page refinements
   ========================================================== */

/* 1. Grid alignment: section heads inside task/road sections
      match the 1160px content grids below them            */
.ex-day-tasks .ex-section-head,
.ex-day-road  .ex-section-head {
  max-width: 1160px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: clamp(32px, 4vw, 52px);
}

/* 2. Grid alignment: ex-day-more inner → same 1160px column */
/* 3. ex-day-more: keep copy column top-aligned so the button
      never overlaps the map column                         */
.ex-day-more-inner {
  max-width: 1160px !important;
  align-items: start !important;
}

/* 4. Section boundary: smooth blend instead of a colour cut */
.ex-day-road {
  background: linear-gradient(
    180deg,
    #F8F9FA 0%,
    #F8F9FA 28%,
    #F8F9FA 55%,
    #F8F9FA 100%
  ) !important;
}
.ex-day-road::before {
  inset: 0 0 auto !important;
  height: 72px !important;
  background: linear-gradient(180deg, rgba(248,249,250,.95), transparent) !important;
  opacity: 1 !important;
  transform: none !important;
}

/* 5. Roadmap float animations — subtle per-card lift so the
      winding shape is alive from the first render           */
@keyframes ex-float-1 {
  0%, 100% { transform: translateY(74px)  rotate(-1.2deg); }
  50%       { transform: translateY(70px)  rotate(-1.2deg); }
}
@keyframes ex-float-2 {
  0%, 100% { transform: translateY(0px)   rotate(1deg); }
  50%       { transform: translateY(-4px)  rotate(1deg); }
}
@keyframes ex-float-3 {
  0%, 100% { transform: translateY(82px)  rotate(-.7deg); }
  50%       { transform: translateY(78px)  rotate(-.7deg); }
}
@keyframes ex-float-4 {
  0%, 100% { transform: translateY(18px)  rotate(1.1deg); }
  50%       { transform: translateY(14px)  rotate(1.1deg); }
}

.ex-info-stop-1 { animation: ex-float-1 5.1s ease-in-out infinite; }
.ex-info-stop-2 { animation: ex-float-2 6.2s ease-in-out infinite  .9s; }
.ex-info-stop-3 { animation: ex-float-3 5.6s ease-in-out infinite 1.5s; }
.ex-info-stop-4 { animation: ex-float-4 6.7s ease-in-out infinite  .3s; }

/* 6. Hover: smooth lift that keeps the card's natural tilt —
      previously snapped rotation to 0deg causing a jolt    */
.ex-info-stop:hover,
.ex-info-stop.is-scroll-focus {
  animation: none !important;
  transform: translateY(calc(var(--road-y, 0px) - 7px)) rotate(var(--road-r, 0deg)) scale(1.01) !important;
  box-shadow: 0 20px 38px rgba(0,64,129,.13) !important;
  transition:
    transform .32s var(--ease-out-quart),
    box-shadow .26s ease !important;
}

/* 7. Disable float animations below the 2-col breakpoint   */
@media (max-width: 1180px) {
  .ex-info-stop-1,
  .ex-info-stop-2,
  .ex-info-stop-3,
  .ex-info-stop-4 { animation: none !important; }
}

@media (prefers-reduced-motion: reduce) {
  .ex-info-stop-1,
  .ex-info-stop-2,
  .ex-info-stop-3,
  .ex-info-stop-4 { animation: none !important; }
}

/* =========================================================
   OFFICE SCENE + FOLDER CARDS — Home redesign per CI + refs
   ========================================================= */

/* ── Office scene replaces binder ── */
.ex-office-scene {
  position: relative;
  min-height: 520px;
  display: grid;
  place-items: center;
  overflow: visible;
}

.ex-office-scene svg {
  width: 100%;
  max-width: 620px;
  height: auto;
  filter: drop-shadow(0 24px 48px rgba(0,17,34,.14));
  border-radius: 18px;
  overflow: hidden;
}

/* ── FOLDER SECTION ── */
.ex-folders-section {
  padding: clamp(72px, 9vw, 116px) clamp(20px, 5vw, 60px);
  background:
    linear-gradient(180deg, #F8F9FA 0%, #F8F9FA 28%, #F8F9FA 100%);
  position: relative;
  overflow: clip;
}

.ex-folders-section::before {
  content: "";
  position: absolute;
  inset: 24px clamp(20px, 7vw, 84px) auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(102,197,197,.72), transparent);
  opacity: .48;
  pointer-events: none;
}

.ex-folders-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.ex-folders-section .ex-home-section-intro {
  max-width: 720px;
  margin: 0 auto 56px;
  text-align: center;
}

/* ── FOLDER GRID ── */
.ex-folder-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 34px 24px;
  align-items: stretch;
}

/* ── INDIVIDUAL FOLDER ── */
.ex-folder {
  position: relative;
  padding-top: 24px;
  cursor: pointer;
  user-select: none;
  outline: none;
  isolation: isolate;
  --folder-front: #F8F9FA;
  --folder-paper: #F8F9FA;
}

/* Folder tab (the protruding label at top-left) */
.ex-folder-tab {
  position: absolute;
  top: 0;
  left: 0;
  padding: 5px 18px 5px 14px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: #F8F9FA;
  border-radius: 8px 8px 0 0;
  clip-path: polygon(0 0, 88% 0, 100% 100%, 0% 100%);
  box-shadow: 0 8px 18px rgba(0,64,129,.08);
  transition: transform .24s var(--ease-out-quart), filter .24s ease;
  z-index: 4;
}

/* Folder body */
.ex-folder-body {
  position: relative;
  z-index: 3;
  padding: 24px 22px 22px;
  min-height: 190px;
  border-radius: 0 14px 14px 14px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--folder-accent, #66C5C5) 8%, #F8F9FA), #F8F9FA 48%);
  border: 1.5px solid var(--folder-border, rgba(0,64,129,.12));
  box-shadow: 0 1px 2px rgba(0,64,129,.04), 0 1px 1px rgba(0,17,34,.02);
  transition:
    transform .28s var(--ease-out-quint),
    box-shadow .28s var(--ease-out-quart),
    border-color .2s ease;
}

.ex-folder-body::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 46px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--folder-border, rgba(0,64,129,.12)), transparent);
  opacity: .76;
}

.ex-folder:hover .ex-folder-body,
.ex-folder:focus-within .ex-folder-body,
.ex-folder:focus .ex-folder-body {
  transform: translateY(-5px) rotateX(2deg);
  box-shadow: 0 12px 28px rgba(0,64,129,.12), 0 3px 8px rgba(0,64,129,.05);
  border-color: var(--folder-accent, #66C5C5);
}

.ex-folder:focus-visible .ex-folder-body {
  box-shadow:
    0 0 0 4px rgba(102,197,197,.18),
    0 12px 28px rgba(0,64,129,.12);
}

.ex-folder-icon {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  margin-bottom: 16px;
  color: #F8F9FA;
  background: var(--folder-accent, #66C5C5);
  transition: transform .3s var(--ease-out-quint);
}

.ex-folder:hover .ex-folder-icon,
.ex-folder:focus-within .ex-folder-icon,
.ex-folder:focus .ex-folder-icon {
  transform: translateY(-2px) rotate(-3deg);
}

.ex-folder:hover .ex-folder-tab,
.ex-folder:focus-within .ex-folder-tab,
.ex-folder:focus .ex-folder-tab {
  transform: translateY(-3px);
  filter: brightness(1.04);
}

.ex-folder-body h3 {
  margin: 0 0 8px;
  font-size: 16px;
  font-weight: 800;
  color: #001122;
  line-height: 1.3;
}

.ex-folder-body p {
  margin: 0;
  font-size: 13px;
  color: #586782;
  line-height: 1.6;
}

/* Documents that fan out on hover */
.ex-folder-docs {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 0;
  overflow: hidden;
  margin: 0 12px;
  padding: 0 4px;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-10px);
  transition:
    max-height .38s var(--ease-out-quint),
    margin .28s var(--ease-out-quart),
    opacity .28s var(--ease-out-quint),
    transform .32s var(--ease-out-quint);
}

.ex-folder:hover .ex-folder-docs,
.ex-folder:focus-within .ex-folder-docs,
.ex-folder:focus .ex-folder-docs {
  max-height: 190px;
  margin-top: 12px;
  padding-bottom: 2px;
  opacity: 1;
  transform: translateY(0);
  pointer-events: all;
}

.ex-folder-doc {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 38px;
  padding: 9px 12px;
  background:
    linear-gradient(180deg, #F8F9FA 0%, color-mix(in srgb, var(--folder-accent, #66C5C5) 5%, #F8F9FA) 100%);
  border: 1px solid var(--folder-border, rgba(0,64,129,.14));
  border-radius: 10px;
  font-size: 13px;
  font-weight: 700;
  color: #004081;
  text-decoration: none;
  box-shadow: 0 4px 12px rgba(0,64,129,.05);
  transform-origin: 50% 0;
  transition:
    background .16s ease,
    color .16s ease,
    border-color .16s ease,
    transform .22s var(--ease-out-quart),
    box-shadow .22s var(--ease-out-quart);
}

.ex-folder-doc span {
  width: 26px;
  height: 22px;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  background: color-mix(in srgb, var(--folder-accent, #66C5C5) 14%, #F8F9FA);
  color: var(--folder-accent, #004081);
  font-size: 10px;
  font-weight: 800;
}

.ex-folder-doc:hover {
  background: var(--folder-accent, #66C5C5);
  color: #F8F9FA;
  border-color: transparent;
  transform: translateY(-2px);
  box-shadow: 0 8px 18px rgba(0,64,129,.12);
}

.ex-folder-doc:hover span {
  background: rgba(248,249,250,.18);
  color: #F8F9FA;
}

.ex-folder-doc:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 4px rgba(102,197,197,.18),
    0 8px 18px rgba(0,64,129,.12);
}

/* Staggered doc reveal */
.ex-folder .ex-folder-doc:nth-child(1) { transform: translateY(-12px) rotate(-1.4deg); }
.ex-folder .ex-folder-doc:nth-child(2) { transform: translateY(-18px) rotate(1.1deg); }
.ex-folder .ex-folder-doc:nth-child(3) { transform: translateY(-24px) rotate(-.7deg); }

.ex-folder:hover .ex-folder-doc:nth-child(1),
.ex-folder:focus-within .ex-folder-doc:nth-child(1),
.ex-folder:focus .ex-folder-doc:nth-child(1) {
  transform: translateY(0) rotate(-1.2deg);
  transition-delay: .00s;
}

.ex-folder:hover .ex-folder-doc:nth-child(2),
.ex-folder:focus-within .ex-folder-doc:nth-child(2),
.ex-folder:focus .ex-folder-doc:nth-child(2) {
  transform: translateY(0) rotate(.8deg);
  transition-delay: .045s;
}

.ex-folder:hover .ex-folder-doc:nth-child(3),
.ex-folder:focus-within .ex-folder-doc:nth-child(3),
.ex-folder:focus .ex-folder-doc:nth-child(3) {
  transform: translateY(0) rotate(-.4deg);
  transition-delay: .09s;
}

/* ── FOLDER COLOUR THEMES ── */
.ex-folder--cyan  { --folder-accent: #66C5C5; --folder-border: rgba(102,197,197,.25); }
.ex-folder--cyan  .ex-folder-tab { background: #66C5C5; }

.ex-folder--navy  { --folder-accent: #004081; --folder-border: rgba(0,64,129,.22); }
.ex-folder--navy  .ex-folder-tab { background: #004081; }

.ex-folder--slate { --folder-accent: #586782; --folder-border: rgba(88,103,130,.20); }
.ex-folder--slate .ex-folder-tab { background: #586782; }

.ex-folder--teal  { --folder-accent: #929EB4; --folder-border: rgba(146,158,180,.22); }
.ex-folder--teal  .ex-folder-tab { background: #929EB4; }

.ex-folder--warm  { --folder-accent: #4A7FC1; --folder-border: rgba(74,127,193,.22); }
.ex-folder--warm  .ex-folder-tab { background: #4A7FC1; }

/* ── MOBILE: stack folders ── */
@media (max-width: 980px) {
  .ex-folder-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 30px 22px;
  }
}

@media (max-width: 768px) {
  .ex-folder-grid {
    grid-template-columns: 1fr 1fr;
    gap: 26px 20px;
  }

  .ex-folder .ex-folder-docs {
    max-height: none;
    margin-top: 12px;
    padding-bottom: 2px;
    opacity: 1;
    transform: none;
    pointer-events: all;
  }

  .ex-folder .ex-folder-doc {
    transform: none !important;
  }
}

@media (max-width: 480px) {
  .ex-folder-grid { grid-template-columns: 1fr; }

  .ex-folders-section .ex-home-section-intro {
    text-align: left;
    margin-bottom: 34px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ex-folder-body,
  .ex-folder-docs,
  .ex-folder-doc,
  .ex-folder-icon { transition: none !important; }

  .ex-folder,
  .ex-folder-body,
  .ex-folder-docs,
  .ex-folder-doc,
  .ex-folder-icon,
  .ex-folder-tab {
    transform: none !important;
  }
}

