/* ── ZIGZAG ROADMAP ── */

.ex-zigzag-road {
  position: relative;
  max-width: 860px;
  margin: 52px auto 0;
  padding: 24px 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Vertical spine line */
.ex-zigzag-spine {
  position: absolute;
  left: 50%;
  top: 32px;
  bottom: 32px;
  width: 3px;
  transform: translateX(-50%);
  background: linear-gradient(180deg, #66C5C5, #004081 60%, #004081);
  border-radius: 99px;
  opacity: .22;
}

/* Each step */
.ex-zig-item {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 0;
  padding: 28px 0;
}

/* The connector dot at the spine */
.ex-zig-connector {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 32px;
}

.ex-zig-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--stop, #66C5C5);
  border: 3px solid #F8F9FA;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--stop, #66C5C5) 28%, transparent),
              0 6px 18px color-mix(in srgb, var(--stop, #66C5C5) 35%, transparent);
  transition: transform .3s var(--ease-out-quint), box-shadow .3s ease;
}

.ex-zig-item:hover .ex-zig-dot {
  transform: scale(1.4);
}

/* Card */
.ex-zig-card {
  position: relative;
  background: #F8F9FA;
  border: 1.5px solid color-mix(in srgb, var(--stop, #66C5C5) 22%, #F8F9FA);
  border-radius: 20px;
  padding: 28px 26px 24px;
  box-shadow: 0 6px 24px rgba(0,17,34,.08);
  transition: transform .28s var(--ease-out-quint), box-shadow .28s ease;
}

.ex-zig-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 16px 40px rgba(0,17,34,.14);
}

/* Left item: card in col 1, connector in col 2, empty col 3 */
.ex-zig-left .ex-zig-card { grid-column: 1; }
.ex-zig-left .ex-zig-connector { grid-column: 2; }
.ex-zig-left > :nth-child(3) { display: none; } /* no spacer needed in flex */

/* Right item: empty col 1, connector in col 2, card in col 3 */
.ex-zig-right .ex-zig-connector { grid-column: 2; order: 2; }
.ex-zig-right .ex-zig-card { grid-column: 3; order: 3; }

/* Step pin badge */
.ex-zig-pin {
  position: absolute;
  top: -18px;
  left: 20px;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: var(--stop, #66C5C5);
  color: #F8F9FA;
  font-size: 13px;
  font-weight: 900;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 6px 18px color-mix(in srgb, var(--stop, #66C5C5) 40%, transparent);
}

/* Step icon */
.ex-zig-icon {
  display: flex;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  align-items: center;
  justify-content: center;
  color: var(--stop, #66C5C5);
  background: color-mix(in srgb, var(--stop, #66C5C5) 12%, #F8F9FA);
  margin-bottom: 14px;
  margin-top: 8px;
}

.ex-zig-card h3 {
  margin: 0 0 10px;
  font-size: 17px;
  font-weight: 800;
  color: #001122;
}

.ex-zig-card p {
  margin: 0 0 14px;
  font-size: 14px;
  color: #586782;
  line-height: 1.7;
}

/* Tag chips */
.ex-zig-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ex-zig-tags span {
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--stop, #66C5C5) 12%, #F8F9FA);
  color: color-mix(in srgb, var(--stop, #66C5C5) 80%, #001122);
}

/* Inline link in last card */
.ex-zig-link {
  display: inline-block;
  margin-top: 6px;
  font-size: 13px;
  font-weight: 700;
  color: var(--stop, #66C5C5);
  text-decoration: none;
  transition: gap .15s ease;
}
.ex-zig-link:hover { text-decoration: underline; }

/* Scroll reveal for zigzag items */
.ex-zig-left.fdb-reveal  { opacity: 0; transform: translateX(-24px); }
.ex-zig-right.fdb-reveal { opacity: 0; transform: translateX(24px); }
.ex-zig-left.fdb-reveal.fdb-vis,
.ex-zig-right.fdb-reveal.fdb-vis {
  opacity: 1;
  transform: translateX(0);
  transition: opacity .6s var(--ease-out-quint) var(--rd, 0ms),
              transform .6s var(--ease-out-quint) var(--rd, 0ms);
}

/* ── EX-DAY-MORE: full redesign ── */

.ex-day-more {
  background:
    radial-gradient(ellipse 55% 60% at 92% 14%, rgba(102,197,197,.14), transparent 48%),
